CREATE OR ALTER PROCEDURE DBO.SPQ_HCA_COL
	@JSON NVARCHAR(MAX),
	@CONSECUTIVO_HCA_ORIGEN VARCHAR(20) = NULL
	,@CONSECUTIVOCIT_ORIGEN VARCHAR(20) = NULL
	WITH ENCRYPTION
AS
DECLARE @TBLERRORES            TABLE (ERROR VARCHAR(MAX))
DECLARE @PARAMETROS            NVARCHAR(MAX)	   ,@MODELO        VARCHAR(100)	    ,@METODO             VARCHAR(100)	,@GRUPO             VARCHAR(8)      ,@SEDE             VARCHAR(5)
	    ,@USUARIO               VARCHAR(20)		    ,@MARCO         VARCHAR(100)	,@FILTRO             VARCHAR(250)	,@ORDEN             VARCHAR(100)    ,@PAGINA           INT				,@FILASXPAG       INT
	    ,@DEFCOLUMNS            BIT			        ,@NOADMISION    VARCHAR(16)	    ,@CONSECUTIVO        VARCHAR(13)	,@UNICO             INT				,@SQL              NVARCHAR(MAX)	,@DESCRIPCION     VARCHAR(MAX)
	    ,@PARAM                 NVARCHAR(500)		,@FECHAHCA      DATETIME		,@CNSWEB             VARCHAR(100)	,@CLASE             VARCHAR(10)     ,@PREFIJO          VARCHAR(20)		,@CLASEPLANTILLA  VARCHAR(8)
	    ,@AMBITO                VARCHAR(2)			,@DAALTA        INT = 0			,@ITEMRED            INT            ,@IDAFILIADO        VARCHAR(20)     ,@TIPODX           VARCHAR(20)		,@IDDX            VARCHAR(10)
	    ,@IDMEDICO              VARCHAR(20)		    ,@PROCEDENCIA   VARCHAR(10)	    ,@SYS_COMPUTERNAME   VARCHAR(200)   ,@IDAREA            VARCHAR(20)     ,@CCOSTO           VARCHAR(20)
	    ,@AUX                   NVARCHAR(MAX)		,@CNSHCAAP      VARCHAR(20)	    ,@ANTECEDENTE        VARCHAR(MAX)	,@CNSTGANTOP        VARCHAR(20)	    ,@CNSTGANT         VARCHAR(20)		,@CNSTGANTOP2        VARCHAR(50) ,@NUMERICO        VARCHAR(20)
	    ,@FECHAHCAAP            DATETIME		    ,@FECHA         DATETIME		,@MPLDL              NVARCHAR(MAX)	,@CAMPO             VARCHAR(12)     ,@TIPO_CAMPO       VARCHAR(50)	    ,@ALFANUMERICO    VARCHAR(MAX), @STATUS_ALERGIA VARCHAR(25)
	    ,@SECUENCIA             SMALLINT		    ,@VALOR         VARCHAR(MAX)	,@VALORLISTA         VARCHAR(256)	,@AUX1              INT				,@CHECKM           VARCHAR(10)		,@VALORLISTAHCADL VARCHAR(256)
	    ,@CONSECUTIVOCIT        VARCHAR(13)         ,@IDPLAN        VARCHAR(20)	    ,@IDPLAN_HADM        VARCHAR(20)	,@CODOMS            VARCHAR(150)	,@CONSECUTIVOS     VARCHAR(8000)    ,@CONSECUTIVOHCA  VARCHAR(20)
		,@TOTAL                 DECIMAL(14, 2)	    ,@IDEMEDICA     VARCHAR(4)		,@INTERPRETACION     VARCHAR(200)   ,@ITEMHCSEGD        INT		        ,@HCADCP           NVARCHAR(MAX)	,@DIASPRORROGA    INT
		,@MATRIZ                NVARCHAR(MAX)
	    ,@NOMBREAFI             VARCHAR(120)	    ,@IDTERCERO     VARCHAR(20)	    ,@PASASEGCOV         INT = 0		,@EDITAFECHA        TINYINT		    ,@FECHA_1          VARCHAR(20)		,@HORA_1          VARCHAR(10)
	    ,@RENGLON               VARCHAR(100)		,@ESCALA        VARCHAR(20)	    ,@IDESC              INT			,@PROT_ACTUAL       INT		        ,@C0010            INT				,@C0020           INT
	    ,@C0030                 INT					,@C0040         INT				,@C0050              INT			,@C0060             INT			    ,@C0070            INT				,@C0080           INT
	    ,@C0090                 INT					,@C0100         INT				,@C0110              INT			,@C0120             INT			    ,@C0130            INT				,@C0140           INT
	    ,@C0150                 INT					,@C0160         INT				,@C0170              INT			,@C0180             INT			    ,@C0190            INT				,@C0200           INT
	    ,@C0210                 INT					,@C0220         INT				,@C0230              INT			,@C0240             INT			    ,@C0250            INT				,@C0260           INT
	    ,@C0270                 INT					,@C0280         INT				,@C0290              INT			,@C0300             INT			    ,@C0310            INT				,@C0320           INT
	    ,@C0330                 INT					,@C0340         INT				,@C0350              INT			,@C0360             INT			    ,@C0370            INT				,@C0380           INT
	    ,@C0390                 INT					,@C0400         INT				,@C0410              INT			,@C0420             INT			    ,@C0430            INT				,@C0440           INT
	    ,@C0450                 INT					,@C0460         INT				,@C0470              INT			,@C0480             INT			    ,@C0490            INT				,@AA              DECIMAL(14, 2)
	    ,@C0500                 INT					,@C0510         INT				,@C0520              INT			,@C0530             INT			    ,@C0540            INT				,@C0550           INT
	    ,@C0560                 INT					,@C0570         INT				,@C0580              INT			,@C0590             INT			    ,@C0600            INT				,@C0610           INT
	    ,@C0620                 INT					,@C0630         INT				,@C0640              INT			,@C0650             INT			    ,@C0660            INT				,@C0670           INT
	    ,@C0680                 INT					,@C0690         INT				,@C0700              INT			,@C0710             INT			    ,@C0720            INT				,@C0730           INT
	    ,@C0740                 INT					,@C0750         INT				,@C0760              INT			,@C0770             INT			    ,@C0780            INT				,@C0790           INT
	    ,@C0800                 INT					,@RIAS          VARCHAR(100)    ,@AIEPI              NVARCHAR(MAX)  ,@M0000             VARCHAR(500)    ,@M0010            VARCHAR(500)     ,@M0020           VARCHAR(500)
        ,@M0030                 VARCHAR(500)        ,@M0040         VARCHAR(500)    ,@M0050              VARCHAR(500)   ,@M0060             VARCHAR(500)    ,@M0070            VARCHAR(500)     ,@M0080           VARCHAR(500)
        ,@M0090                 VARCHAR(500)        ,@M0100         VARCHAR(500)    ,@D0000              DECIMAL(14,2)  ,@D0010             DECIMAL(14,2)   ,@OBSERVACION      VARCHAR(500)	    ,@IDGESTION       INT
        ,@SEGMENTO              NVARCHAR(255) = NULL
	    ,@ID                    VARCHAR(100)		,@FECHAGLU      DATE			,@AD                 DECIMAL(14,2)	,@DD                DECIMAL(14, 2)  ,@NOTACNSORI       VARCHAR(13)
	    ,@DA                    DECIMAL(14,2)	    ,@AC            DECIMAL(14,2)	,@DC                 DECIMAL(14,2)	,@OTRO              DECIMAL(14, 2)  ,@IDTERCEROGESTION VARCHAR(20)      ,@IDEMEDICAX      VARCHAR(4)
	    ,@PROT_IDPESPECIAL      VARCHAR(5)          ,@PROT_ID       INT				,@PROT_JUSTIFICACION VARCHAR(1000)  ,@CLASEORDENX       VARCHAR(10)     ,@IDMEDICO_AUX     VARCHAR(20)      ,@ANEXOAUTO       SMALLINT = 0
	    ,@PROT_FECHA            DATETIME		    ,@PROT_PROCESO  SMALLINT		,@IDGESTOR_NA        INT = 0		,@DOCUMENTOID       VARCHAR(100)
	    ,@IDPESPECIAL           VARCHAR(5)	        ,@CNSRPDX       VARCHAR(20)	    ,@IDAFILIADO_OTRO    VARCHAR(20)    ,@IDPLANGESTION     VARCHAR(6)
	    ,@CODUNG                VARCHAR(5)			,@IDAFIPROT     VARCHAR(20)	    ,@IDAFILIADOX        VARCHAR(20)	,@IDMEDICOX         VARCHAR(12)
	    ,@IDPESPECIALX          VARCHAR(5)	        ,@CODOM_GESTION VARCHAR(20)	    ,@IDSERVICIO_PROT    VARCHAR(20)    ,@IDSERVICIOGESTION VARCHAR(20)
	    ,@IDMEDICO_ESPECIALISTA VARCHAR(20)		    ,@CNS_AUX       VARCHAR(20)	    ,@COMPANIA           VARCHAR(20)    ,@NIT               VARCHAR(20)
	    ,@ID_HCATD              INT				    ,@MEMO          VARCHAR(MAX)	,@ENEPICRISIS        SMALLINT		,@IDPROVEEDOR       VARCHAR(20)
	    ,@IDIMAGEN              VARCHAR(100)		,@ANCHOIMG		 INT			,@ALTOIMG	         INT			,@ESCALAX	        FLOAT           ,@ESCALAY	        FLOAT
		,@IDPUNTO		        VARCHAR(20)  	    ,@XPOS		    INT				,@YPOS		         INT			,@COLOR		        VARCHAR(20)     ,@FORMA		        VARCHAR(20)
		,@IMGSERIE              VARCHAR(20)  	    ,@TITULOMAPA    VARCHAR(20)  	,@TAMANO             INT			,@ESNOTAACLARATORIA BIT			    ,@RTA_JSON          NVARCHAR(MAX)
DECLARE @IDMEDICOALTA VARCHAR(20), @DXINGRESO VARCHAR(6), @DXEGRESO VARCHAR(6),  @DESTINO VARCHAR(2), @ESTADOPSALIDA VARCHAR(2)
		,@FECHAALTA VARCHAR(15), @HORASUSPENDE VARCHAR(15), @CCOSTO_ALTA VARCHAR(10), @DXSALIDA1 VARCHAR(6)
		,@DXSALIDA2 VARCHAR(6), @DXSALIDA3 VARCHAR(6), @CAUSABMUERTE VARCHAR(6), @ACTADEFUNCION VARCHAR(30)
		,@TIENEOM SMALLINT	, @NOCOPIAOM SMALLINT, @AUDITORIA BIT, @USUARIO_AUX VARCHAR(12)
DECLARE @CORREGIMIENTO          VARCHAR(20)         ,@PROVEEDOR_FAR VARCHAR(1000)   ,@PROVEEDOR_FAR_DF  VARCHAR(1000)   ,@PROVEEDOR_EXA     VARCHAR(1000)   , @PROVEEDOR_APO VARCHAR(1000)
        ,@IDSERVICIO VARCHAR(20), @ESTANCIA VARCHAR(20), @MENSAJE_ALERTA nVARCHAR(MAX)
        ,@CMD VARCHAR(MAX), @CNSLOG VARCHAR(20), @CLASE_PLANTILLA_EVOLUCION VARCHAR(20)= dbo.FNK_VALORVARIABLE('HCPLANTILLARED')
        ,@CONSECUTIVOCIT_NEW VARCHAR(20), @IDSEDE_PARAMETRO VARCHAR(10), @IDSERVICIOPYM VARCHAR(20), @IDPLAN_MPE VARCHAR(20), @FECHA_AUX_1 DATETIME, @EXISTE_CIT BIT
        ,@FINALIDAD_MPE VARCHAR(10), @CAUSAEXTERNA_MPE VARCHAR(20)
        ,@IXCOUNTRY VARCHAR(20)=DBO.FNK_VALORVARIABLE('IXCOUNTRY') ,@NUEVA_HCA BIT = 0 ,@HUBO_CAMBIOS_OM BIT = 0 ,@CITACONTROL NVARCHAR(max), @VIRTUAL BIT, @TELEFONOAVISO VARCHAR(20)
        ,@IDAPLIM INT, @ESTADO_ANTERIOR VARCHAR(50), @DETALLE_APLIMG VARCHAR(3000) ,@VALUE INT  ,@LABEL VARCHAR(100) ,@NECPAL BIT = 0 ,@EXISTE BIT = 0 ,@PART BIT=0
        ,@JSON_COMMAND NVARCHAR(MAX) ,@IDDXING VARCHAR(10) , @IDMEDICOING VARCHAR(12) ,@TIPOCAMBIO VARCHAR(1), @CODOM VARCHAR(10) ,@CONSECUTIVOHCAING_EXARIA  VARCHAR(13)
        ,@IDAFIFAM1_ECO	NVARCHAR(100) ,@TRABAJO NVARCHAR(100),@AMIGOS NVARCHAR(100),@EDUCACION NVARCHAR(100),@RELIGION NVARCHAR(100),@RECREACION NVARCHAR(100)
        ,@SALUD NVARCHAR(100),@TRANSPORTE NVARCHAR(100) ,@ID1_ECO INT ,@CONSECUTIVOHCAING_ECO VARCHAR(13) ,@FECHAINSERTAECO DATE
        ,@IDAFILIADO_AFR	VARCHAR(20), @IDAFIFAM1_AFR	NVARCHAR(100) ,@IDAFIFAM2_AFR NVARCHAR(100) ,@TIPORELACION_AFR	VARCHAR(20) ,@X1_AFR	decimal(20,14)
        ,@X2_AFR	decimal(20,14) ,@Y1_AFR	decimal(20,14) ,@Y2_AFR	decimal(20,14) , @ID1_AFR INT  ,@ID2_AFR INT ,@REGAFIFAM INT ,@I INT = 1, @I_TO INT, @CANT INT = 0
        ,@CICLO INT ,@DIA_ACTUAL INT ,@CICLO_ACTUAL INT ,@ULTIMO_CICLO INT ,@ULTIMO_DIA_CICLO INT ,@_IDSERVICIO VARCHAR(20)
        ,@CNSTGANTCUR VARCHAR(20),@TIPOANT VARCHAR(100), @NOMBREANT VARCHAR(100) ,@CNSHCAAPD NVARCHAR(100) ,@CNSHCAAPCUR NVARCHAR(100) ,@FECHAING DATE ,@CNSHCAANT VARCHAR(13) ,@ANTECEDENTECUR  NVARCHAR(MAX) ,@ORDENCUR INT
        ,@TGANTJson NVARCHAR(MAX) ,@CANT_ANT_FALTANTES INT ,@DX1 VARCHAR(20), @DX2 VARCHAR(20), @DX3 VARCHAR(20), @DX4 VARCHAR(20)
        ,@ITEM INT = 0, @CURRENTCNS VARCHAR(20)='' ,@IDPLAN_NUEVAHCA VARCHAR(20), @IDMADSEGUI VARCHAR(20), @IDSERVICIOS_UNIRS VARCHAR(120)
        ,@ID_HCATD_AUD_MPL INT
        ,@MOTIVOCITA VARCHAR(100)   , @NOPRESUPUESTO VARCHAR(20), @IDAUT VARCHAR(20), @NO_ITEM INT,    @MAX_NO_ITEM INT, @CANTIDAD INT
        ,@CAUSAEXTERNA VARCHAR(100), @FINALIDADCONSULTA VARCHAR(100), @NEWIDEMEDICA VARCHAR(4) , @ID_CITSITEDS INT, @NOPRESUPUESTO_NUEVO VARCHAR(20)
        ,@FDESDE DATETIME, @FHASTA DATETIME, @GSERVICIOS VARCHAR(20), @MODALIDAD VARCHAR(20), @RETROACTIVA VARCHAR(20)
        ,@TIPOINCAPACIDAD VARCHAR(20), @DIASINCAPACIDAD INT, @JSON_IME NVARCHAR(MAX), @SYNC_MDX BIT = 0
DECLARE @DBNAME_DOCU VARCHAR(200),@USA_DOCU_BD VARCHAR(2), @IDMEDICO_GEN VARCHAR(20), @IDMEDICO_CIT VARCHAR(20), @CNSALR VARCHAR(20)
DECLARE @IDALERTA_ESCAUTO VARCHAR(20)=DBO.FNK_VALORVARIABLE('IDALERTA_ESCAUTO')
DECLARE @IDPLAN_NEW VARCHAR(6), @TOPICO_SELECCIONADOS VARCHAR(20)
DECLARE @FAM_PRIMER_NOMBRE VARCHAR(100), @FAM_SEGUNDO_NOMBRE VARCHAR(100),@PAC_CIE VARCHAR(20), @PAC_CIEVERSION VARCHAR(100) 
       ,@FAM_PRIMER_APELLIDO VARCHAR(100), @FAM_SEGUNDO_APELLIDO VARCHAR(100)
       ,@FAM_GENERO VARCHAR(20), @FAM_CIE VARCHAR(20), @FAM_PARENTESCO VARCHAR(20), @FAM_STATUS VARCHAR(20), @FAM_CIEVERSION VARCHAR(100)
DECLARE @ANTECEDENTE_ALER VARCHAR(MAX), @TIPO_ALERGIA_ALER VARCHAR(50), @STATUS_ALERGIA_ALER VARCHAR(50), @NOMBRE_ANTECEDENTE_ALER VARCHAR(200), @DESC_TIPO_ALERGIA_ALER VARCHAR(100), @MENSAJE_ALERTA_ALER VARCHAR(500)
DECLARE @IDPESPECIAL_CITA VARCHAR(20), @HABCAMA VARCHAR(10), @TIPOADM VARCHAR(2), @CERRADA SMALLINT
DECLARE @PROCEDENCIACIT VARCHAR(20), @PROP_PROCEDENCIA VARCHAR(20) , @CIT_PROCEDENCIA VARCHAR(20)
DECLARE @PROT_MOTIVO VARCHAR(5)
DECLARE @CNSOMSOLI VARCHAR(20)
DECLARE @ES_ATENCION_MOR BIT = 0, @IDPE_ATENCION VARCHAR(20), @IDPESPECIAL_CIT_ACT VARCHAR(20), @CLASEORDEN_CIT_ACT VARCHAR(10)
DECLARE @TIENE_HCA_PREVIA BIT = 0, @PROCEDENCIA_CIT_ACT VARCHAR(20), @NO_CREAR_CITA BIT = 0
DECLARE @FECHACONFIRMACION DATETIME, @FECHASINTOMAS DATETIME, @DXANT VARCHAR(5), @FECHASANT DATETIME, @FECHACANT DATETIME
DECLARE @IDTERCERO_SOAT VARCHAR(20) = NULL;
DECLARE @IDPLAN_SOAT VARCHAR(6) = NULL;

-- VARIABLES NUEVAS PARA CONTROL DE DEADLOCKS
DECLARE @RetryCount INT = 0;
DECLARE @MaxRetries INT = 3;
DECLARE @Success BIT = 0;
DECLARE @ERROR_MSG NVARCHAR(MAX);
DECLARE @STEP NVARCHAR(200) = 'INIT';

BEGIN
	SET NOCOUNT ON;
	--SET XACT_ABORT ON;
	SET DATEFORMAT dmy;

	-- Validaciones de entrada
	-- IF @JSON IS NULL OR LTRIM(RTRIM(@JSON)) = ''
	-- BEGIN
	-- 	RAISERROR('SPQ_HCA_COL: @JSON no puede ser NULL ni vacío.', 16, 1);
	-- 	RETURN;
	-- END
	-- IF ISJSON(@JSON) <> 1
	-- BEGIN
	-- 	RAISERROR('SPQ_HCA_COL: @JSON no es un JSON válido.', 16, 1);
	-- 	RETURN;
	-- END

	SELECT *
	INTO #JSON
	FROM OPENJSON(@json) WITH (
			MODELO  VARCHAR(100) '$.MODELO'
			,METODO  VARCHAR(100) '$.METODO'
			,CNSWEB  VARCHAR(100) '$.CNSWEB'
			,RIAS    VARCHAR(100) '$.RIAS'
			,USUARIO VARCHAR(100) '$.USUARIO'
			,DEFCOLUMNS BIT '$.DEFCOLUMNS'
			,PARAMETROS NVARCHAR(MAX) AS JSON
	);

	IF NOT EXISTS (SELECT 1 FROM #JSON)
	BEGIN
		RAISERROR('SPQ_HCA_COL: No se pudo parsear el JSON root (MODELO/METODO/PARAMETROS).', 16, 1);
		RETURN;
	END

	SELECT @MODELO = MODELO ,@METODO = METODO ,@PARAMETROS = PARAMETROS ,@DEFCOLUMNS = DEFCOLUMNS ,@USUARIO = USUARIO ,@CNSWEB = CNSWEB ,@RIAS = RIAS
	FROM #JSON;

	--IF COALESCE(@METODO, '') = '' OR COALESCE(@PARAMETROS, '') = ''
	--BEGIN
	--	RAISERROR('SPQ_HCA_COL: METODO y PARAMETROS son obligatorios.', 16, 1);
	--	RETURN;
	--END
	--IF ISJSON(@PARAMETROS) <> 1
	--BEGIN
	--	RAISERROR('SPQ_HCA_COL: PARAMETROS no es un JSON válido.', 16, 1);
	--	RETURN;
	--END

	-- CNSWEB is required for HCA traceability; recover it from PARAMETROS or generate one as last fallback.
	IF COALESCE(@CNSWEB, '') = ''
		SELECT @CNSWEB = NULLIF(LTRIM(RTRIM(JSON_VALUE(@PARAMETROS, '$.CNSWEB'))), '')

	IF @METODO = 'DILIGENCIAR'
	BEGIN
		

		SELECT @GRUPO = DBO.FNK_DESCIFRAR(GRUPO), @IDMEDICO = IDMEDICO ,@SYS_COMPUTERNAME = SYS_COMPUTERNAME
		FROM USUSU WITH (NOLOCK)
		WHERE USUARIO = @USUARIO
		SELECT @SEDE = IDSEDE, @COMPANIA=COMPANIA FROM UBEQ WITH (NOLOCK) WHERE SYS_ComputerName = @SYS_COMPUTERNAME
        SELECT @NIT = NIT FROM TER WITH (NOLOCK) WHERE IDTERCERO = dbo.FNK_VALORVARIABLE('IDTERCEROINSTALADO')

		SELECT @NOADMISION          = NOADMISION        ,@CONSECUTIVOCIT    = COALESCE(@CONSECUTIVOCIT_ORIGEN, CONSECUTIVOCIT)
                ,@CONSECUTIVOHCA    = CONSECUTIVOHCA    ,@EDITAFECHA        = EDITAFECHA
				,@FECHA_1	        = FECHA             ,@HORA_1            = HORA
				,@PROCEDENCIA	    = PROCEDENCIA       ,@IDAFILIADO	    = IDAFILIADO
				,@IDPESPECIAL	    = IDPESPECIAL       ,@DAALTA		    = DAALTA
                ,@CLASEPLANTILLA    = CLASEPLANTILLA    ,@CITACONTROL       = CITACONTROL
                ,@IDDX              = IDDX              
                ,@CAUSAEXTERNA      = CAUSAEXTERNA      ,@FINALIDADCONSULTA = FINALIDADCONSULTA
                ,@IDPLAN_NEW        = IDPLAN_NEW        ,@PROT_IDPESPECIAL  = PROT_IDPESPECIAL
                ,@TOPICO_SELECCIONADOS = TOPICO_SELECCIONADOS, @NEWIDEMEDICA = IDEMEDICA, @PROP_PROCEDENCIA = PROP_PROCEDENCIA, @CIT_PROCEDENCIA = CIT_PROCEDENCIA
                ,@CNSOMSOLI = CNSOMSOLI
		FROM OPENJSON(@PARAMETROS) WITH (
				 NOADMISION          VARCHAR(20) '$.NOADMISION'
                ,CONSECUTIVOCIT     VARCHAR(20) '$.CONSECUTIVOCIT'
				,CONSECUTIVOHCA     VARCHAR(20) '$.CONSECUTIVOHCA'
				,PROCEDENCIA        VARCHAR(20) '$.PROCEDENCIA'
				,FECHA			    VARCHAR(20) '$.FECHA'
				,HORA			    VARCHAR(10) '$.HORA'
				,EDITAFECHA	        TINYINT     '$.EDITAFECHA'
				,IDAFILIADO		    VARCHAR(20) '$.IDAFILIADO'
				,IDPESPECIAL        VARCHAR(20) '$.IDPESPECIAL'
				,IDEMEDICA          VARCHAR(4) '$.IDEMEDICA'
				,DAALTA             BIT			'$.DAALTA'
				,CLASEPLANTILLA     VARCHAR(20) '$.CLASEPLANTILLA'
				,IDDX               VARCHAR(20) '$.IDDX'
				,CAUSAEXTERNA       VARCHAR(20) '$.CAUSAEXTERNA'
				,FINALIDADCONSULTA  VARCHAR(20) '$.FINALIDADCONSULTA'
				,IDPLAN_NEW         VARCHAR(20) '$.IDPLAN_NEW'
            ,PROT_IDPESPECIAL   VARCHAR(5)  '$.PROT_IDPESPECIAL'
            ,TOPICO_SELECCIONADOS   VARCHAR(20)  '$.TOPICO_SELECCIONADOS'
            ,PROP_PROCEDENCIA   VARCHAR(20)  '$.PROP_PROCEDENCIA'
            ,CIT_PROCEDENCIA   VARCHAR(20)  '$.CIT_PROCEDENCIA'
            ,CNSOMSOLI          VARCHAR(20)  '$.CNSOMSOLI'
            ,CITACONTROL        NVARCHAR(MAX) AS JSON
		)

		IF DBO.FNK_VALORVARIABLE('TOMAR_SEDE_AFI') = 'SI'
		BEGIN
			IF ((@PROCEDENCIA = 'IPS' AND EXISTS(SELECT 1 FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT AND FECHALLEGA IS NULL AND COALESCE(MODALIDAD, '') = 'Virtual'))
				OR @PROCEDENCIA = 'URGENCIA'
			)
			BEGIN
				SELECT @SEDE = IDSEDE 
				FROM AFI 
				WHERE IDAFILIADO = @IDAFILIADO;
			END
		END

		IF COALESCE(@CNSWEB, '') = '' AND COALESCE(@CONSECUTIVOHCA, '') <> ''
			SELECT @CNSWEB = NULLIF(LTRIM(RTRIM(CNSWEB)), '') FROM HCA WHERE CONSECUTIVO = @CONSECUTIVOHCA

		IF COALESCE(@CNSWEB, '') = ''
			SELECT @CNSWEB = CONVERT(VARCHAR(100), NEWID())

		-- Variables de configuracion (evitar llamadas repetidas a FNK_VALORVARIABLE)
		DECLARE @HCPLANTILLAEPI VARCHAR(20) = DBO.FNK_VALORVARIABLE('HCPLANTILLAEPI')
			   ,@MINTOSMAXSINEPI VARCHAR(20) = DBO.FNK_VALORVARIABLE('MINTOSMAXSINEPI')
			   ,@VALIDA_EPIANTESALTA VARCHAR(2) = DBO.FNK_VALORVARIABLE('VALIDA_EPIANTESALTA')
			   ,@PERMITE_ALTASINEPI VARCHAR(2) = DBO.FNK_VALORVARIABLE('PERMITE_ALTASINEPI')
			   ,@FECHA_ACTUAL_DIL_HC VARCHAR(2) = DBO.FNK_VALORVARIABLE('FECHA_ACTUAL_DIL_HC')
			   ,@MDX_X_MPE VARCHAR(2) = DBO.FNK_VALORVARIABLE('MDX_X_MPE')
			   ,@VALIDAR_SER_PROT VARCHAR(2) = DBO.FNK_VALORVARIABLE('VALIDAR_SER_PROT')
			   ,@VALIDAR_HCA_GUARDAR VARCHAR(2) = DBO.FNK_VALORVARIABLE('VALIDAR_HCA_GUARDAR')
			   ,@MIN_CARACTER_PROT INT = TRY_CAST(DBO.FNK_VALORVARIABLE('MIN_CARACTER_PROT') AS INT)
			   ,@DENEGAR_INTERCONS VARCHAR(2) = DBO.FNK_VALORVARIABLE('DENEGAR_INTERCONS')
			   ,@CODOM_INTERCONSULTA_CFG VARCHAR(10) = DBO.FNK_VALORVARIABLE('OMCODINTERCONSULTA')
			   ,@IDPESPECIAL_CIT VARCHAR(20)
			   ,@DX_INVALIDOS VARCHAR(MAX)
			   ,@DESCESPECIAL VARCHAR(200)


        IF COALESCE(@CONSECUTIVOHCA,'')=''
			SET @NUEVA_HCA = 1
        ELSE
			SET @NUEVA_HCA = 0

		-- Nota enfermeria nueva: no reutilizar consecutivo de HC medica (evita sobrescribir ingreso)
		IF @NUEVA_HCA = 0
			AND COALESCE(@CONSECUTIVOHCA, '') <> ''
			AND EXISTS (SELECT 1 FROM MPL WITH (NOLOCK) WHERE CLASEPLANTILLA = @CLASEPLANTILLA AND CLASE = 'NE')
			AND EXISTS (SELECT 1 FROM HCA WITH (NOLOCK) WHERE CONSECUTIVO = @CONSECUTIVOHCA AND COALESCE(CLASE, '') <> 'NE')
		BEGIN
			SET @CONSECUTIVOHCA = NULL
			SET @NUEVA_HCA = 1
		END

		IF @PROCEDENCIA='IPS'
		BEGIN
		    IF COALESCE(@CONSECUTIVOCIT,'')<>'' AND EXISTS (SELECT 1 FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT)
		    BEGIN
			    IF @IDAFILIADO<>(SELECT TOP 1 IDAFILIADO FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT)
				    SELECT @IDAFILIADO=IDAFILIADO FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT

		    END

		    SELECT @IDMEDICO_GEN = IDMEDICO_GEN, @IDMEDICO_CIT = IDMEDICO, @PROCEDENCIACIT=PROCEDENCIA, @CLASEORDENX=CLASEORDEN
            FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT
            
		    IF COALESCE(@NOADMISION, '') = ''
		    BEGIN
			    SELECT TOP 1 @NOADMISION = NOADMISION FROM HTRAT INNER JOIN HTRATDD ON HTRATDD.IDHTRAT = HTRAT.ID WHERE CONSECUTIVOCIT=@CONSECUTIVOCIT
		    END
		END
        -- Evitar la duplicacion de HCA si se intenta registrar dos veces.
		IF @NUEVA_HCA=1 AND EXISTS (
			SELECT CONSECUTIVO
			FROM   HCA
			WHERE  @CNSWEB IS NOT NULL
			AND    CNSWEB  = @CNSWEB
			AND	   CLASEPLANTILLA = @CLASEPLANTILLA
		)
			AND @CONSECUTIVO_HCA_ORIGEN IS NULL
		BEGIN
			SELECT 'OK' AS OK, CONSECUTIVO
			FROM   HCA
			WHERE  @CNSWEB IS NOT NULL
			AND    CNSWEB  = @CNSWEB
			AND	   CLASEPLANTILLA = @CLASEPLANTILLA
			--ROLLBACK TRANSACTION
			RETURN
		END

		-- Evitar HCA duplicada por cita + plantilla (consulta externa / IPS)
		IF @VALIDAR_HCA_GUARDAR = 'SI'
			AND @NUEVA_HCA = 1
			AND COALESCE(@CONSECUTIVOCIT, '') <> ''
			AND EXISTS (
				SELECT 1
				FROM HCA WITH (NOLOCK)
				INNER JOIN CIT WITH (NOLOCK) ON CIT.CONSECUTIVO = HCA.CONSECUTIVOCIT
				WHERE HCA.CLASEPLANTILLA = @CLASEPLANTILLA
					AND HCA.CONSECUTIVOCIT = @CONSECUTIVOCIT
					AND HCA.PROCEDENCIA = 'IPS'
			)
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR = 'Ya existe una historia clínica con la misma plantilla para esta cita. No se puede continuar.'
			RETURN
		END

        BEGIN--QCORE10 ESCALAS
		    SELECT * INTO #HCAESCALAS
		    FROM OPENJSON(@PARAMETROS) WITH (
			    ESCALAS	NVARCHAR(MAX) AS JSON
		    )
		    SELECT @AUX = ESCALAS FROM #HCAESCALAS

		    SELECT * INTO #QESCALASTEMP
		    FROM OPENJSON(@AUX) WITH (
			    ID             VARCHAR(100)			'$.ID'
			    ,ESCALA        VARCHAR(20)			'$.ESCALA.value'
		    )
        END

        BEGIN--MDX
		    SELECT * INTO #HCAMDX
		    FROM OPENJSON(@PARAMETROS) WITH (
			    MDX NVARCHAR(MAX) AS JSON,
			    SYNC_MDX BIT '$.SYNC_MDX'
            )
            SELECT @AUX = MDX, @SYNC_MDX = COALESCE(SYNC_MDX, 0) FROM #HCAMDX

		    SELECT IDDX,TIPODX, FECHASINTOMAS, FECHACONFIRMACION
		    INTO #MDX
		    FROM OPENJSON(@AUX) WITH (
			    IDDX VARCHAR(10) '$.IDDX',
			    TIPODX VARCHAR(10) '$.TIPODX',
			    FECHASINTOMAS VARCHAR(12) '$.FECHASINTOMAS',
			    FECHACONFIRMACION VARCHAR(12) '$.FECHACONFIRMACION'
		    )
		    CREATE INDEX IX_MDX_IDDX ON #MDX(IDDX);
        END

		IF @MDX_X_MPE = 'SI' AND COALESCE(@CONSECUTIVOCIT, '') <> ''
		BEGIN
			SELECT @IDPESPECIAL_CIT = NULLIF(LTRIM(RTRIM(CIT.IDPESPECIAL)), '')
				,@DESCESPECIAL = MPE.DESCESPECIAL
			FROM CIT WITH (NOLOCK)
			LEFT JOIN MPE WITH (NOLOCK) ON MPE.IDPESPECIAL = CIT.IDPESPECIAL
			WHERE CIT.CONSECUTIVO = @CONSECUTIVOCIT

			IF COALESCE(@IDPESPECIAL_CIT, '') <> ''
				AND EXISTS (
					SELECT 1
					FROM TGEN WITH (NOLOCK)
					WHERE TABLA = 'MPE_MDX'
						AND CAMPO = @IDPESPECIAL_CIT
				)
			BEGIN
				SELECT @DX_INVALIDOS = STUFF((
						SELECT ', ' + D.IDDX + ' - ' + COALESCE(X.DESCRIPCION, '')
						FROM (
							SELECT IDDX FROM #MDX WHERE COALESCE(IDDX, '') <> ''
							UNION
							SELECT @IDDX WHERE COALESCE(@IDDX, '') <> ''
						) D
						LEFT JOIN MDX X WITH (NOLOCK) ON X.IDDX = D.IDDX
						WHERE NOT EXISTS (
								SELECT 1
								FROM TGEN T WITH (NOLOCK)
								WHERE T.TABLA = 'MPE_MDX'
									AND T.CAMPO = @IDPESPECIAL_CIT
									AND T.CODIGO = D.IDDX
							)
						FOR XML PATH('')
							,TYPE
						).value('.', 'VARCHAR(MAX)'), 1, 2, '')

				IF COALESCE(@DX_INVALIDOS, '') <> ''
					OR NOT EXISTS (
						SELECT 1 FROM #MDX WHERE COALESCE(IDDX, '') <> ''
						UNION ALL
						SELECT @IDDX WHERE COALESCE(@IDDX, '') <> ''
					)
				BEGIN
					SELECT 'KO' OK

					SELECT ERROR = 'El(los) diagnóstico(s) ' + COALESCE(@DX_INVALIDOS, '(ninguno)')
						+ ' no está(n) relacionado(s) al programa especial '
						+ COALESCE(@IDPESPECIAL_CIT, '')
						+ ' - ' + COALESCE(@DESCESPECIAL, '')
						+ '. No se puede continuar.'

					RETURN
				END
			END
		END

        IF (SELECT COALESCE(@RIAS,'') ) <> ''  --ES RIAS
        BEGIN
            IF @NUEVA_HCA=0  --ES EDICION
            BEGIN
                IF (SELECT COUNT(1) FROM TGEN WITH (NOLOCK) WHERE TABLA='ESCALAS' AND CAMPO=@CLASEPLANTILLA AND COALESCE(TGEN.VALOR1,0)>0
			        AND NOT EXISTS (SELECT 1 FROM #QESCALASTEMP A WHERE A.ESCALA=TGEN.CODIGO)
                    AND NOT EXISTS (SELECT 1 FROM QCORE10 WHERE QCORE10.IDAFILIADO=@IDAFILIADO AND QCORE10.ESCALA=TGEN.CODIGO AND QCORE10.CONSECUTIVOHCA=@CONSECUTIVOHCA)
		            )>0
		        BEGIN
			        SELECT 'KO' OK
			        SELECT ERROR = 'Las siguientes escalas son obligatorias, debe diligenciarlas para poder continuar' UNION ALL
			        SELECT CONCAT(CODIGO,' - ',DESCRIPCION)
			        FROM TGEN WITH (NOLOCK)
                    WHERE  TABLA='ESCALAS' AND CAMPO=@CLASEPLANTILLA AND COALESCE(TGEN.VALOR1,0)>0
				        AND    NOT EXISTS (SELECT 1 FROM #QESCALASTEMP A WHERE A.ESCALA=TGEN.CODIGO)
                        AND    NOT EXISTS (SELECT 1 FROM QCORE10 WHERE QCORE10.IDAFILIADO=@IDAFILIADO AND QCORE10.ESCALA=TGEN.CODIGO AND QCORE10.CONSECUTIVOHCA=@CONSECUTIVOHCA)
			        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
			        RETURN
		        END
            END
            ELSE
            BEGIN --ES INSERCION
            IF (SELECT COUNT(1) FROM TGEN WITH (NOLOCK) WHERE TABLA='ESCALAS' AND CAMPO=@CLASEPLANTILLA AND COALESCE(TGEN.VALOR1,0)>0
			        AND NOT EXISTS (SELECT 1 FROM #QESCALASTEMP A WHERE A.ESCALA=TGEN.CODIGO)
		        )>0
		        BEGIN
			        SELECT 'KO' OK
			        SELECT ERROR = 'Las siguientes escalas son obligatorias, debe diligenciarlas para poder continuar' UNION ALL
			        SELECT CODIGO+' - '+DESCRIPCION
			        FROM TGEN WITH (NOLOCK) WHERE TABLA='ESCALAS' AND CAMPO=@CLASEPLANTILLA AND COALESCE(TGEN.VALOR1,0)>0
				        AND NOT EXISTS (SELECT 1 FROM #QESCALASTEMP A WHERE A.ESCALA=TGEN.CODIGO)
			        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
			        RETURN
		        END
            END
        END
        ELSE
        BEGIN
            IF @NUEVA_HCA=1 /*SE VALIDA SOLO EN LA INSERCION, EDICION NO MANEJA ESCALAS*/
            BEGIN
		        IF (SELECT COUNT(1) FROM TGEN WITH (NOLOCK) WHERE TABLA='ESCALAS' AND CAMPO=@CLASEPLANTILLA AND COALESCE(TGEN.VALOR1,0)>0
			        AND NOT EXISTS (SELECT 1 FROM #QESCALASTEMP A WHERE A.ESCALA=TGEN.CODIGO)
			        AND NOT EXISTS (SELECT 1 FROM QCORE10 WHERE IDAFILIADO=@IDAFILIADO AND ESCALA=TGEN.CODIGO)
		        )>0
		        BEGIN
			        SELECT 'KO' OK
			        SELECT ERROR = 'Las siguientes escalas son obligatorias, debe diligenciarlas para poder continuar' UNION ALL
			        SELECT CODIGO+' - '+DESCRIPCION
			        FROM TGEN WITH (NOLOCK) WHERE TABLA='ESCALAS' AND CAMPO=@CLASEPLANTILLA AND COALESCE(TGEN.VALOR1,0)>0
				        AND NOT EXISTS (SELECT 1 FROM #QESCALASTEMP A WHERE A.ESCALA=TGEN.CODIGO)
				        AND NOT EXISTS (SELECT 1 FROM QCORE10 WHERE IDAFILIADO=@IDAFILIADO AND ESCALA=TGEN.CODIGO)
			        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
			        RETURN
		        END

                IF (
                    SELECT COUNT(1)
                    FROM TGEN
                    INNER JOIN TGEN C ON C.TABLA='ESCALAS' AND C.CAMPO=@CLASEPLANTILLA AND C.CODIGO=TGEN.CAMPO
                    INNER JOIN TGEN D ON D.TABLA='ESCALAS' AND D.CAMPO='NOMBRE' AND D.CODIGO=C.CODIGO
                    WHERE TGEN.TABLA='ESCALAS' AND TGEN.CODIGO IN (SELECT IDDX FROM #MDX UNION ALL SELECT @IDDX)
				        AND TGEN.VALOR2>0
                        AND ((COALESCE(TGEN.OBSERVACION,'')<>'' AND @CLASEPLANTILLA IN (SELECT ITEM FROM FNK_SPLIT1(TGEN.OBSERVACION,',',0,NULL)))
                                OR COALESCE(TGEN.OBSERVACION,'')=''
                            )
			            AND NOT EXISTS (SELECT 1 FROM #QESCALASTEMP A WHERE A.ESCALA=TGEN.CAMPO OR A.ESCALA=D.DATO5)
			            AND NOT EXISTS (
								        SELECT 1 FROM QCORE10
								        WHERE IDAFILIADO=@IDAFILIADO AND ESCALA=TGEN.CAMPO
								        AND (COALESCE(TGEN.VALOR1,0)=0 OR DATEDIFF(DAY, QCORE10.FECHAREG, GETDATE())<COALESCE(TGEN.VALOR1,0) )
                                        )
		        )>0
		        BEGIN
			        SELECT 'KO' OK
			        SELECT ERROR = 'Las siguientes escalas son obligatorias segun DX, debe diligenciarlas para poder continuar' UNION ALL
			        SELECT TGEN.CODIGO+' - '+TGEN.DESCRIPCION
			        FROM TGEN
                    WHERE TABLA='ESCALAS' AND CAMPO='NOMBRE' AND CODIGO IN (
                        SELECT TGEN.CAMPO
                        FROM TGEN
                            INNER JOIN TGEN C ON C.TABLA='ESCALAS' AND C.CAMPO=@CLASEPLANTILLA AND C.CODIGO=TGEN.CAMPO
                            INNER JOIN TGEN D ON D.TABLA='ESCALAS' AND D.CAMPO='NOMBRE' AND D.CODIGO=C.CODIGO
                        WHERE TGEN.TABLA='ESCALAS' AND TGEN.CODIGO IN (SELECT IDDX FROM #MDX UNION ALL SELECT @IDDX)
						    AND TGEN.VALOR2>0
                            AND ((COALESCE(TGEN.OBSERVACION,'')<>'' AND @CLASEPLANTILLA IN (SELECT ITEM FROM FNK_SPLIT1(TGEN.OBSERVACION,',',0,NULL)))
                                    OR COALESCE(TGEN.OBSERVACION,'')=''
                                )
						    AND NOT EXISTS (SELECT 1 FROM #QESCALASTEMP A WHERE A.ESCALA=TGEN.CAMPO OR A.ESCALA=D.DATO5)
						    AND NOT EXISTS (
										    SELECT 1 FROM QCORE10
										    WHERE IDAFILIADO=@IDAFILIADO AND ESCALA=TGEN.CAMPO
										    AND (COALESCE(TGEN.VALOR1,0)=0 OR DATEDIFF(DAY, QCORE10.FECHAREG, GETDATE())<COALESCE(TGEN.VALOR1,0) )
                                            AND (COALESCE(TGEN.OBSERVACION,'')='' OR (COALESCE(TGEN.OBSERVACION,'')<>'' AND @CLASEPLANTILLA IN (SELECT ITEM FROM FNK_SPLIT1(TGEN.OBSERVACION,',',0,NULL))) )
										    )
                    )
			        RETURN
		        END
            END
        END

		SELECT @CLASE=CLASE FROM MPL WHERE CLASEPLANTILLA=@CLASEPLANTILLA
		SET @STEP = 'BEGIN_TRAN';
		DECLARE @trancount int = @@TRANCOUNT;
		IF @trancount = 0
			BEGIN TRANSACTION
		ELSE
			SAVE TRANSACTION USP_SPQ_HCA_COL_V2

		BEGIN TRY
			IF NOT EXISTS(SELECT 1 FROM MED WHERE IDMEDICO=@IDMEDICO)
			BEGIN
				RAISERROR ('Su ficha de usuario no tiene vinculado un profesional. Contacte por favor con el departamento de tecnologia.' , 16, 1);
				IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
				RETURN
			END
			IF @CONSECUTIVO_HCA_ORIGEN IS NULL
			BEGIN
				IF @PROCEDENCIA = 'GESTION'
				BEGIN
					SET @IDGESTION = CAST(@CONSECUTIVOCIT AS INT)
					SET @CONSECUTIVOCIT = NULL

					IF COALESCE(@IDAFILIADO,'')=''
					BEGIN
						SELECT @IDAFILIADO = IDAFILIADO
						FROM AFIPROT
						WHERE ID = @IDGESTION
					END
				END
				IF @PROCEDENCIA IN ( 'GESTIONES' ,'AUDITEXT','GESTADVA', 'URGENCIA' ,'GESTSER')
				BEGIN
					SELECT @IDAFILIADO_OTRO = COALESCE(@IDAFILIADO, @CONSECUTIVOCIT)
					SELECT @CONSECUTIVOCIT  = NULL
					SELECT @IDAFIPROT       = JSON_VALUE(@PARAMETROS,'$.IDAFIPROT')
				END
				IF @PROCEDENCIA = 'SEGUI' AND @IDAFILIADO IS NULL AND JSON_VALUE(@PARAMETROS, '$.CONSECUTIVOCIT') IS NOT NULL
				BEGIN
					SELECT @IDAFILIADO = MAD.IDAFILIADO
					FROM MADSEGUI INNER JOIN MAD ON MAD.ID = MADSEGUI.IDMAD
					WHERE MADSEGUI.ITEM = JSON_VALUE(@PARAMETROS, '$.CONSECUTIVOCIT')
				END
				SELECT @FECHAHCA = COALESCE(TRY_CAST(JSON_VALUE(@PARAMETROS,'$.FECHA_DILIGENCIA') AS SMALLDATETIME),
					CONVERT(SMALLDATETIME,DBO.FNK_GETDATE()))

				IF @PROCEDENCIA='IPS' AND EXISTS(SELECT 1 FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT)
				BEGIN
					SELECT @IDPESPECIAL_CITA = IDPESPECIAL FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT

					IF EXISTS(SELECT 1 FROM CIT INNER JOIN TGEN T ON T.TABLA='AFI' AND T.CAMPO='TIPOATENCION' AND T.CODIGO=CIT.ATENCION
								WHERE CONSECUTIVO=@CONSECUTIVOCIT AND T.DATO2='EXTRAMURAL')
					BEGIN
						SELECT @FECHAHCA=CIT.FECHA FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT
					END
				END
			END
			IF @EDITAFECHA = 1 AND @HORA_1 IS NOT NULL
			BEGIN
				IF @FECHA_1 IS NULL OR LTRIM(RTRIM(@FECHA_1)) = ''
				BEGIN
					SET @FECHAHCA =
						DATEADD(
							MINUTE,
							DATEDIFF(MINUTE, '00:00', CAST(@HORA_1 AS TIME)),
							CAST(CAST(GETDATE() AS DATE) AS DATETIME)
						)
				END
				ELSE
				BEGIN
					SET @FECHAHCA =
						DATEADD(
							MINUTE,
							DATEDIFF(MINUTE, '00:00', CAST(@HORA_1 AS TIME)),
							CAST(CAST(@FECHA_1 AS DATE) AS DATETIME)
						)
				END

			END

			IF @CONSECUTIVO_HCA_ORIGEN IS NOT NULL AND @CONSECUTIVOCIT_ORIGEN IS NOT NULL
			BEGIN
				SELECT @IDAFILIADO = IDAFILIADO
				FROM CIT c
				WHERE c.CONSECUTIVO = @CONSECUTIVOCIT_ORIGEN

				SELECT @FECHAHCA = FECHA
				FROM HCA
				WHERE CONSECUTIVO = @CONSECUTIVO_HCA_ORIGEN
			END

			IF COALESCE(@CONSECUTIVOCIT,'')<>''
			BEGIN
				IF @PROCEDENCIA = 'IPS'
				BEGIN
                    IF EXISTS(SELECT 1 FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT AND COALESCE(IDPESPECIAL,'')='')
                        AND DBO.FNK_VALORVARIABLE('VALIDA_DX_PYM_MOR')='SI'
                        AND EXISTS (SELECT 1 FROM MDX WHERE IDDX IN(SELECT IDDX FROM #MDX UNION SELECT @IDDX) AND PYP=1)
                    BEGIN
					    SELECT @CMD=STUFF((SELECT '  Los siguientes diagnosticos son de PYP y esta atendiendo una cita de morbilidad: '+IDDX FROM MDX WHERE IDDX IN(SELECT IDDX FROM #MDX UNION SELECT @IDDX) AND PYP=1 FOR XML PATH('')),1,1,'')
                        BEGIN
						    RAISERROR (@CMD , 16, 1);
						    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
						    RETURN
                        END
                    END
					IF @CONSECUTIVO_HCA_ORIGEN IS NULL
					BEGIN
						-- EZERPA 10.04.2023, Validar que la cita que esta atendiendo exista en CIT
						IF @NUEVA_HCA=1
						BEGIN
							IF NOT EXISTS(SELECT 1 FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT)
							BEGIN

								IF(SELECT COUNT(1) FROM CIT WHERE IDAFILIADO=@IDAFILIADO AND IDMEDICO=@IDMEDICO AND CAST(FECHA AS DATE)=CAST(GETDATE() AS DATE))=1
								BEGIN
									SELECT TOP 1 @CONSECUTIVOCIT = CONSECUTIVO FROM CIT WHERE IDAFILIADO=@IDAFILIADO AND IDMEDICO=@IDMEDICO AND CAST(FECHA AS DATE)=CAST(GETDATE() AS DATE)

									IF EXISTS(SELECT 1 FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT)
									BEGIN
										SELECT @EXISTE = 1
									END
								END

								IF @EXISTE = 0
								BEGIN
									RAISERROR ('Al parecer la cita que esta intentando atender fue borrada. Si cree que esto es una irregularidad por favor contacte con el departamento de tecnologia.' , 16, 1);
									IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
									RETURN
								END
							END
						END
						-- PyP / Morbilidad: clonar UNA vez al cruzar tipo (PyM?Mor), aunque haya N HC del mismo tipo
						-- Máximo 2 citas: original + un clon. 1ª HC y editar nunca clonan.
						BEGIN
							DECLARE @IDPE_MOR VARCHAR(20), @FINALIDAD_MORB VARCHAR(20), @CAUSA_MORB VARCHAR(20), @IDPLAN_MORB VARCHAR(20)

							SET @ES_ATENCION_MOR = 0
							SET @IDPE_ATENCION = NULL
							SET @IDPESPECIAL_CIT_ACT = NULL
							SET @CLASEORDEN_CIT_ACT = NULL
							SET @PROCEDENCIA_CIT_ACT = NULL
							SET @TIENE_HCA_PREVIA = 0
							SET @NO_CREAR_CITA = 0

							SELECT @CLASEORDEN_CIT_ACT = NULLIF(LTRIM(RTRIM(CLASEORDEN)), '')
								,@IDPESPECIAL_CIT_ACT = NULLIF(LTRIM(RTRIM(IDPESPECIAL)), '')
								,@PROCEDENCIA_CIT_ACT = NULLIF(LTRIM(RTRIM(PROCEDENCIA)), '')
							FROM CIT WITH (NOLOCK)
							WHERE CONSECUTIVO = @CONSECUTIVOCIT

							-- Ya hay al menos 1 HC en esta cita (puede haber 10 PyM o 10 Mor). No es la 1ª.
							-- Solo HCA real; CONSECUTIVOHCA en CIT no cuenta (puede estar lleno antes de la 1ª HC)
							IF @NUEVA_HCA = 1
							AND (
								SELECT COUNT(1) FROM HCA WITH (NOLOCK)
								WHERE CONSECUTIVOCIT = @CONSECUTIVOCIT
								AND COALESCE(CLASE, '') <> 'NE'
							) >= 1
								SET @TIENE_HCA_PREVIA = 1

							-- Si plantilla es PyP y el front no mandó IDPESPECIAL, usar solo el de la cita (no inventar otro programa)
							IF NULLIF(LTRIM(RTRIM(@IDPESPECIAL)), '') IS NULL
								AND EXISTS(SELECT 1 FROM TGEN WITH (NOLOCK) WHERE TABLA = 'HC_PYP' AND CAMPO = @CLASEPLANTILLA)
							BEGIN
								IF COALESCE(@IDPESPECIAL_CIT_ACT, '') <> ''
									AND EXISTS(
										SELECT 1 FROM TGEN WITH (NOLOCK)
										WHERE TABLA = 'HC_PYP' AND CAMPO = @CLASEPLANTILLA AND CODIGO = @IDPESPECIAL_CIT_ACT
									)
									SET @IDPESPECIAL = @IDPESPECIAL_CIT_ACT
							END

							SET @IDPE_ATENCION = COALESCE(
								NULLIF(LTRIM(RTRIM(@IDPESPECIAL)), ''),
								@IDPESPECIAL_CIT_ACT
							)

							-- Clínica con HC_PYM_NOCITA=SI: TGEN.DATO1='NOCITA' en 2ª atención no clona
							IF @TIENE_HCA_PREVIA = 1
								AND DBO.FNK_VALORVARIABLE('HC_PYM_NOCITA') = 'SI'
								AND EXISTS(
									SELECT 1 FROM TGEN WITH (NOLOCK)
									WHERE CAMPO = @CLASEPLANTILLA
									AND UPPER(LTRIM(RTRIM(COALESCE(DATO1, '')))) = 'NOCITA'
									AND (
										(TABLA = 'HC_PYP' AND CODIGO = COALESCE(@IDPE_ATENCION, @IDPESPECIAL_CIT_ACT, CODIGO))
										OR TABLA = 'HC_MOR'
									)
								)
								SET @NO_CREAR_CITA = 1

							-- Clasificación: PyP (HC_PYP) tiene prioridad; morbilidad solo si plantilla mor o cita de programa sin plantilla PyP
							IF @IDPE_ATENCION IS NOT NULL
								AND EXISTS(
									SELECT 1 FROM TGEN WITH (NOLOCK)
									WHERE TABLA = 'HC_PYP' AND CAMPO = @CLASEPLANTILLA AND CODIGO = @IDPE_ATENCION
								)
								SET @ES_ATENCION_MOR = 0
							ELSE IF EXISTS(SELECT 1 FROM TGEN WITH (NOLOCK) WHERE TABLA = 'HC_MOR' AND CAMPO = @CLASEPLANTILLA)
								SET @ES_ATENCION_MOR = 1
							ELSE IF COALESCE(@IDPESPECIAL_CIT_ACT, '') <> ''
								SET @ES_ATENCION_MOR = 1

							IF @ES_ATENCION_MOR = 1
							BEGIN
							SELECT TOP 1 @IDPE_MOR = NULLIF(LTRIM(RTRIM(CODIGO)), '')
							FROM TGEN WITH (NOLOCK)
							WHERE TABLA = 'HC_MOR' AND CAMPO = @CLASEPLANTILLA

							SELECT @IDPLAN_MORB = NULLIF(LTRIM(RTRIM(IDPLAN_MORB)), '')
								,@FINALIDAD_MORB = NULLIF(LTRIM(RTRIM(CAST(FINALIDAD_MORB AS VARCHAR(20)))), '')
								,@CAUSA_MORB = NULLIF(LTRIM(RTRIM(CAST(CAUSA_EXTERNA_MORB AS VARCHAR(20)))), '')
							FROM MPE WITH (NOLOCK)
							WHERE IDPESPECIAL = COALESCE(@IDPESPECIAL_CIT_ACT, NULLIF(LTRIM(RTRIM(@IDPESPECIAL)), ''), @IDPE_MOR)

							IF @IDPLAN_MORB IS NOT NULL
							   AND NOT EXISTS(SELECT 1 FROM PLN WITH (NOLOCK) WHERE IDPLAN = @IDPLAN_MORB)
								SET @IDPLAN_MORB = NULL

							-- Cruce PyM?Mor: cita de programa original, ya hay HC, aún no existe clon (máx. 2 citas)
							IF @NUEVA_HCA = 1
								AND COALESCE(@IDPESPECIAL_CIT_ACT, '') <> ''
								AND UPPER(COALESCE(@PROCEDENCIA_CIT_ACT, '')) <> 'HCA'
								AND @TIENE_HCA_PREVIA = 1
								AND @NO_CREAR_CITA = 0
							BEGIN
								SELECT @IDSEDE_PARAMETRO = COALESCE(IDSEDEATENCION, IDSEDE)
								FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT

								SELECT TOP 1 @CONSECUTIVOCIT_NEW = CONSECUTIVO
								FROM CIT
								WHERE IDAFILIADO = @IDAFILIADO
								AND PROCEDENCIA = 'HCA'
								AND COALESCE(IDPESPECIAL, '') = ''
								AND COALESCE(CLASEORDEN, '') <> 'PyP'
								AND (
									CNSORIGINAL = @CONSECUTIVOCIT
									OR (
										CAST(@FECHAHCA AS DATE) = CAST(CIT.FECHA AS DATE)
										AND IDPLAN = COALESCE(@IDPLAN_MORB, IDPLAN)
									)
								)
								ORDER BY CASE WHEN CNSORIGINAL = @CONSECUTIVOCIT THEN 0 ELSE 1 END

								IF COALESCE(@CONSECUTIVOCIT_NEW, '') = ''
								BEGIN
									EXEC SPK_GENCONSECUTIVO @COMPANIA, @IDSEDE_PARAMETRO, '@CIT', @CONSECUTIVOCIT_NEW OUTPUT
									SELECT @CONSECUTIVOCIT_NEW = @IDSEDE_PARAMETRO + REPLACE(SPACE(10 - LEN(@CONSECUTIVOCIT_NEW)) + LTRIM(RTRIM(@CONSECUTIVOCIT_NEW)), SPACE(1), 0)

									SELECT * INTO #CIT_CLONE_MOR FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT

									BEGIN
										SELECT @FECHA_AUX_1 = DBO.FNK_GETDATE()
										SELECT @EXISTE_CIT = 1
										SELECT @FECHA_AUX_1 = FECHA FROM #CIT_CLONE_MOR

										WHILE @EXISTE_CIT = 1
										BEGIN
											SELECT @FECHA_AUX_1 = DATEADD(MINUTE, 1, @FECHA_AUX_1)
											IF NOT EXISTS(SELECT 1 FROM CIT WHERE FECHA = @FECHA_AUX_1 AND IDMEDICO = @IDMEDICO)
												SELECT @EXISTE_CIT = 0
										END
									END

									-- Clon de 2ª atención: IDPLAN / FINALIDAD / CAUSAEXTERNA desde MPE.*_MORB
									UPDATE #CIT_CLONE_MOR SET CONSECUTIVO = @CONSECUTIVOCIT_NEW
										,FECHA = @FECHA_AUX_1
										,IDPESPECIAL = NULL
										,CONSECUTIVOHCA = NULL
										,CUMPLIDA = 1
										,IDPLAN = COALESCE(@IDPLAN_MORB, IDPLAN)
										,CLASEORDEN = 'Normal'
										,PROCEDENCIA = 'HCA'
										,CNSORIGINAL = @CONSECUTIVOCIT
										,FINALIDAD = COALESCE(@FINALIDAD_MORB, FINALIDAD)
										,FINCONSULTA = COALESCE(@FINALIDAD_MORB, FINCONSULTA)
										,CAUSAEXTERNA = COALESCE(@CAUSA_MORB, CAUSAEXTERNA)
									WHERE 1 = 1

