													 SPD ,NORECIBOCAJA ,CLASEORDEN ,USUARIO ,NOADMISION ,GENPRESTACION ,FINCONSULTA ,CODCAJA ,FECHALLEGA ,USUARIOLLEGA ,OBSERVACIONES ,
													 NOAUTORIZACION ,IDSEDEORIGEN ,IDIPSSOLICITA ,IDMEDICOSOLICITA ,AUTORIZADOPOR ,FECHAAUTORIZACION ,CNSAFIAA ,TIPOCOPAGO ,PROCEDENCIA ,IDAREAH ,IDAREA ,
													 CCOSTO ,SUBCCOSTO ,NIVELATENCION ,FACTURADA ,N_FACTURA ,CNSFCT ,VFACTURAS ,FACTURABLE ,DESCUENTO ,TIPODTO ,MARCAFAC ,
