													 IDTERCEROCA ,FINALIDAD ,TIPOCAJA ,CONSECUTIVOHCA ,AQUIENCOBRO ,VALORPROV ,CODUNG ,CODPRG ,NOCITA ,REASIGNADA ,IDCONTRATO ,
