													 FECHAENVIOLAB ,ESTADOPREANALITICA ,USUNOPROCESA ,FECHANOPROCESA ,RAZONNOPROCESA ,ESPROGRAMAS ,URLVIDEOLLAMADA ,CANTIDADC ,IDFIRMAPTE ,IDFIRMARESP ,MODELOS ,
													 RCAMBIO ,CONFIRMADA ,ENUSO ,USUARIOENUSO ,NOPROGRAMACION ,CITAENSEDE ,CONDUCTOR ,RAZONMEDDIF ,NOASISTIO_IDCAUSAL ,NOASISTIO_OBSERVACION ,FECHACONFIRMA ,
													 USUCONFIRMA ,EXTRA ,TIME_EXTRA ,IDAUTSES ,RES_ONCO ,REQ_AUTORIZACION ,TIENE_LAB ,OBS_CONFIRMADO ,CNSHCA_CITACONTROL ,FIRMA_PACIENTE ,FIRMA_ACUDIENTE ,
													 CONSECUTIVOMAGP ,MARCA ,NFACTURA ,COPA_VAR_PORC ,TIPO_DESC_FAR ,COPA_VAR_EXA ,TIPO_DESC_EXA ,COPA_VAR_APOYO ,TIPO_DESC_APOYO ,COPA_VAR_INTERC ,TIPO_DESC_INTERC ,
													 COPAGO_FI_CON ,COPAGO_FI_FAR ,COPAGO_VA_FAR ,COPAGO_FI_EXA ,COPAGO_VA_EXA ,EMBARAZADA ,IDMAD ,TVALORACION ,CNSPAQ ,IDROL ,IDMEDICO_GEN ,
													 IDSEDCONS ,ITEM_DISMED_AGEN ,FVENCEAUTORIZACION ,AUTAUDITADO ,VALORCOPAGO_EXONERA ,EXONERACION ,TIPO_EXONERACION ,VALOR_UNITARIO_SIN_IGV ,VALOR_IGV_UNITARIO ,VALOR_UNITARIO_CON_IGV ,FIRMA_EXO_PX ,
													 IDAPLIM ,VALOR_COPAGO_UNIT_SIN_IGV ,VALOR_COPAGO_IGV_UNIT ,VALOR_COPAGO_TOTAL_SIN_IGV ,VALOR_COPAGO_TOTAL_CON_IGV ,RAZONCITA ,CAUSAEXTERNA ,BLOQUEADO ,IDMEDICO_GEN_RET ,ENFACT ,USUARIO_ENFACT ,
													 FECHA_ENFACT ,FACTURADA_TERCERO ,N_FACTURA_TERCERO ,IDAPLIMBLOQUEO ,USU_EXONERA ,OBS_EXONERA ,SIRAS
									FROM #CIT_CLONE_MOR

									-- 2ª atención: la HC nueva queda en la cita clonada
									IF COALESCE(@CONSECUTIVOCIT_NEW, '') <> ''
										SELECT @CONSECUTIVOCIT = @CONSECUTIVOCIT_NEW
								END
								-- 3ª+ : el clon ya existe ? no crear otra ni mover esta HC
							END
							ELSE IF UPPER(COALESCE(@PROCEDENCIA_CIT_ACT, '')) = 'HCA'
								AND COALESCE(@IDPESPECIAL_CIT_ACT, '') = ''
								AND (@IDPLAN_MORB IS NOT NULL OR @FINALIDAD_MORB IS NOT NULL OR @CAUSA_MORB IS NOT NULL)
							BEGIN
								-- Solo en cita ya clonada de morbilidad (2ª atención): asegurar MPE.*_MORB
								UPDATE CIT SET
									IDPLAN = COALESCE(@IDPLAN_MORB, IDPLAN),
									FINALIDAD = COALESCE(@FINALIDAD_MORB, NULLIF(LTRIM(RTRIM(@FINALIDADCONSULTA)), ''), FINALIDAD),
									FINCONSULTA = COALESCE(@FINALIDAD_MORB, NULLIF(LTRIM(RTRIM(@FINALIDADCONSULTA)), ''), FINCONSULTA),
									CAUSAEXTERNA = COALESCE(@CAUSA_MORB, NULLIF(LTRIM(RTRIM(@CAUSAEXTERNA)), ''), CAUSAEXTERNA)
								WHERE CONSECUTIVO = @CONSECUTIVOCIT
							END
							-- 1ª atención en cita original: no alterar IDPLAN/FINALIDAD/CAUSA
							END -- @ES_ATENCION_MOR
						END
						-- Atención PyP: actualizar cita de programa in situ; clonar solo en 2ª atención desde morbilidad
						IF COALESCE(@ES_ATENCION_MOR, 0) = 0
							AND @IDPE_ATENCION IS NOT NULL
							AND EXISTS(
								SELECT 1 FROM TGEN WITH (NOLOCK)
								WHERE TABLA = 'HC_PYP' AND CAMPO = @CLASEPLANTILLA AND CODIGO = @IDPE_ATENCION
							)
						BEGIN
							SET @IDPESPECIAL = @IDPE_ATENCION

							SELECT @IDPLAN_MPE = NULLIF(LTRIM(RTRIM(IDPLAN)), '')
								,@FINALIDAD_MPE = NULLIF(LTRIM(RTRIM(FINALIDAD)), '')
								,@CAUSAEXTERNA_MPE = NULLIF(LTRIM(RTRIM(CAUSA_EXTERNA)), '')
							FROM MPE WITH (NOLOCK) WHERE IDPESPECIAL = @IDPESPECIAL

							IF NOT EXISTS(SELECT 1 FROM PLN WITH (NOLOCK) WHERE IDPLAN = @IDPLAN_MPE)
								SET @IDPLAN_MPE = NULL

							SELECT @IDSERVICIOPYM = IDSERVICIOPYM FROM MPL WITH (NOLOCK) WHERE CLASEPLANTILLA = @CLASEPLANTILLA
							SELECT @IDSEDE_PARAMETRO = COALESCE(IDSEDEATENCION, IDSEDE) FROM CIT WITH (NOLOCK) WHERE CONSECUTIVO = @CONSECUTIVOCIT

							SET @CONSECUTIVOCIT_NEW = NULL

							-- Misma cita de programa: 1ª atención conserva datos originales; clon HCA aplica MPE
							IF COALESCE(@IDPESPECIAL_CIT_ACT, '') = @IDPESPECIAL
							BEGIN
								IF UPPER(COALESCE(@PROCEDENCIA_CIT_ACT, '')) = 'HCA'
								BEGIN
									UPDATE CIT SET
										IDPLAN = COALESCE(@IDPLAN_MPE, IDPLAN),
										FINALIDAD = COALESCE(@FINALIDAD_MPE, NULLIF(LTRIM(RTRIM(@FINALIDADCONSULTA)), ''), FINALIDAD),
										FINCONSULTA = COALESCE(@FINALIDAD_MPE, NULLIF(LTRIM(RTRIM(@FINALIDADCONSULTA)), ''), FINCONSULTA),
										CAUSAEXTERNA = COALESCE(@CAUSAEXTERNA_MPE, NULLIF(LTRIM(RTRIM(@CAUSAEXTERNA)), ''), CAUSAEXTERNA),
										CUMPLIDA = 1,
										IDSERVICIO = COALESCE(@IDSERVICIOPYM, IDSERVICIO)
									WHERE CONSECUTIVO = @CONSECUTIVOCIT
								END
								ELSE
								BEGIN
									-- Cita agenda original (1ª atención): no pisar IDPLAN/FINALIDAD/CAUSA
									UPDATE CIT SET CUMPLIDA = 1
									WHERE CONSECUTIVO = @CONSECUTIVOCIT
								END

								SET @CONSECUTIVOCIT_NEW = @CONSECUTIVOCIT
							END
							-- Cruce Mor?PyP: cita Normal original, ya hay HC, aún no existe clon (máx. 2 citas)
							ELSE IF @NUEVA_HCA = 1
								AND @TIENE_HCA_PREVIA = 1
								AND COALESCE(@IDPESPECIAL_CIT_ACT, '') = ''
								AND UPPER(COALESCE(@PROCEDENCIA_CIT_ACT, '')) <> 'HCA'
								AND @NO_CREAR_CITA = 0
							BEGIN
								SELECT TOP 1 @CONSECUTIVOCIT_NEW = CONSECUTIVO
								FROM CIT WITH (NOLOCK)
								WHERE IDAFILIADO = @IDAFILIADO
								AND CLASEORDEN = 'PyP'
								AND PROCEDENCIA = 'HCA'
								AND IDPESPECIAL = @IDPESPECIAL
								AND (
									CNSORIGINAL = @CONSECUTIVOCIT
									OR (
										CAST(@FECHAHCA AS DATE) = CAST(CIT.FECHA AS DATE)
										AND IDSERVICIO = COALESCE(@IDSERVICIOPYM, IDSERVICIO)
										AND IDPLAN = COALESCE(@IDPLAN_MPE, IDPLAN)
									)
								)
								ORDER BY CASE WHEN CNSORIGINAL = @CONSECUTIVOCIT THEN 0 ELSE 1 END

								IF COALESCE(@CONSECUTIVOCIT_NEW, '') = ''
								BEGIN
									EXEC SPK_GENCONSECUTIVO @COMPANIA, @IDSEDE_PARAMETRO, '@CIT', @CONSECUTIVOCIT_NEW OUTPUT
									SELECT @CONSECUTIVOCIT_NEW = @IDSEDE_PARAMETRO + REPLACE(SPACE(10 - LEN(@CONSECUTIVOCIT_NEW)) + LTRIM(RTRIM(@CONSECUTIVOCIT_NEW)), SPACE(1), 0)

									SELECT * INTO #CIT_CLONE FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT

									BEGIN
										SELECT @FECHA_AUX_1 = DBO.FNK_GETDATE()
										SELECT @EXISTE_CIT = 1
										SELECT @FECHA_AUX_1 = FECHA FROM #CIT_CLONE

										WHILE @EXISTE_CIT = 1
										BEGIN
											SELECT @FECHA_AUX_1 = DATEADD(MINUTE, 1, @FECHA_AUX_1)
											IF NOT EXISTS(SELECT 1 FROM CIT WHERE FECHA = @FECHA_AUX_1 AND IDMEDICO = @IDMEDICO)
												SELECT @EXISTE_CIT = 0
										END
									END

									-- Clon de 2ª atención: IDPLAN / FINALIDAD / CAUSAEXTERNA desde MPE
									UPDATE #CIT_CLONE SET CONSECUTIVO = @CONSECUTIVOCIT_NEW, FECHA = @FECHA_AUX_1, IDPESPECIAL = @IDPESPECIAL
										,CONSECUTIVOHCA = NULL
										,CUMPLIDA = 1
										,IDSERVICIO = COALESCE(@IDSERVICIOPYM, IDSERVICIO)
										,IDPLAN = COALESCE(@IDPLAN_MPE, IDPLAN)
										,CLASEORDEN = 'PyP'
										,PROCEDENCIA = 'HCA'
										,CNSORIGINAL = COALESCE(CNSORIGINAL, @CONSECUTIVOCIT)
										,FINALIDAD = COALESCE(@FINALIDAD_MPE, FINALIDAD)
										,FINCONSULTA = COALESCE(@FINALIDAD_MPE, FINCONSULTA)
										,CAUSAEXTERNA = COALESCE(@CAUSAEXTERNA_MPE, CAUSAEXTERNA)
									WHERE 1 = 1

