                                                     IDIPS ,CLASECONTRATO ,ENPAQUETE ,IDCIRUGIA ,CNSFACT ,SOAT ,COPAGOPROPIO ,CNSHACTRAN ,ALTOCOSTO ,IDDX ,IDEMEDICA ,
                                                     IDTERCEROCA ,FINALIDAD ,TIPOCAJA ,CONSECUTIVOHCA ,AQUIENCOBRO ,VALORPROV ,CODUNG ,CODPRG ,NOCITA ,REASIGNADA ,IDCONTRATO ,
                                                     ITFC ,CNSITFC ,SYS_COMPUTERNAME ,NOCOBRAR ,CCONTRATANTE ,CONTABILIZADA ,NROCOMPROBANTE ,MARCACONT ,QXCONSECUTIVO ,FECHACIRUGIA ,FECHAREASIG ,
                                                     USUARIOREASIG ,CODCUPS ,IDPLAN_AFI ,IDTERCERO_AFI ,NOMBREACOMPA ,TELEFONOACOMPA ,PARENTESCOACOMPA ,NOMBRERESPO ,TELEFONORESPO ,PARENTESCORESPO ,USUARIONOFACTURABLE ,
                                                     FECHA_NOFAC ,PVEZANO ,F_REQUERIDA ,RIESGO ,DURACION ,MVARIAS ,NROCITAS ,CNSORIGINAL ,PREGUNTAPOR ,MPLAN ,IDPLANDISP ,
                                                     WEB ,DIRECCION ,CIUDAD ,CORREGIMIENTO ,LAT_DIR ,LNG_DIR ,IDBARRIO ,MODALIDAD ,TIPOAFILIADO ,IDAUTSE ,COVID ,
                                                     USUATENCION ,USURESPONSABLE ,USUGENAGENDA ,FGENERACION ,IDKPAGE ,COMERCIAL ,HORADESDE ,HORAHASTA ,RESULTADOLLAMADA ,USUPREANALITICA ,FECHAPREANALITICA ,
                                                     FECHAENVIOLAB ,ESTADOPREANALITICA ,USUNOPROCESA ,FECHANOPROCESA ,RAZONNOPROCESA ,ESPROGRAMAS ,URLVIDEOLLAMADA ,CANTIDADC ,IDFIRMAPTE ,IDFIRMARESP ,MODELOS ,
                                                     RCAMBIO ,CONFIRMADA ,ENUSO ,USUARIOENUSO ,NOPROGRAMACION ,CITAENSEDE ,CONDUCTOR ,RAZONMEDDIF ,NOASISTIO_IDCAUSAL ,NOASISTIO_OBSERVACION ,FECHACONFIRMA ,
                                                     USUCONFIRMA ,EXTRA ,TIME_EXTRA ,IDAUTSES ,RES_ONCO ,REQ_AUTORIZACION ,TIENE_LAB ,OBS_CONFIRMADO ,CNSHCA_CITACONTROL ,FIRMA_PACIENTE ,FIRMA_ACUDIENTE ,
                                                     CONSECUTIVOMAGP ,MARCA ,NFACTURA ,COPA_VAR_PORC ,TIPO_DESC_FAR ,COPA_VAR_EXA ,TIPO_DESC_EXA ,COPA_VAR_APOYO ,TIPO_DESC_APOYO ,COPA_VAR_INTERC ,TIPO_DESC_INTERC ,
                                                     COPAGO_FI_CON ,COPAGO_FI_FAR ,COPAGO_VA_FAR ,COPAGO_FI_EXA ,COPAGO_VA_EXA ,EMBARAZADA ,IDMAD ,TVALORACION ,CNSPAQ ,IDROL ,IDMEDICO_GEN ,
                                                     IDSEDCONS ,ITEM_DISMED_AGEN ,FVENCEAUTORIZACION ,AUTAUDITADO ,VALORCOPAGO_EXONERA ,EXONERACION ,TIPO_EXONERACION ,VALOR_UNITARIO_SIN_IGV ,VALOR_IGV_UNITARIO ,VALOR_UNITARIO_CON_IGV ,FIRMA_EXO_PX ,
                                                     IDAPLIM ,VALOR_COPAGO_UNIT_SIN_IGV ,VALOR_COPAGO_IGV_UNIT ,VALOR_COPAGO_TOTAL_SIN_IGV ,VALOR_COPAGO_TOTAL_CON_IGV ,RAZONCITA ,CAUSAEXTERNA ,BLOQUEADO ,IDMEDICO_GEN_RET ,ENFACT ,USUARIO_ENFACT ,
                                                     FECHA_ENFACT ,FACTURADA_TERCERO ,N_FACTURA_TERCERO ,IDAPLIMBLOQUEO ,USU_EXONERA ,OBS_EXONERA ,SIRAS
                                    FROM #CIT_CLONE
								END
								ELSE
								BEGIN
									-- 3ª+: el clon ya existe ? no crear otra ni mover esta HC
									SET @CONSECUTIVOCIT_NEW = NULL
								END
							END
							ELSE
							BEGIN
								-- 1ª atención con plantilla PyP sobre cita sin programa: conservar datos originales (no MPE)
								SET @CONSECUTIVOCIT_NEW = @CONSECUTIVOCIT
							END

							IF COALESCE(@CONSECUTIVOCIT_NEW, '') <> ''
								SELECT @CONSECUTIVOCIT = @CONSECUTIVOCIT_NEW
						END

						IF EXISTS( -- NOTA: ESTO ES UNA SOLUCION TEMPORAL AL PROBLEMA DE ATENCION DE CITAS CON CONSECUTIVO DE GESTION, SE DEBE QUITAR APENAS SE TERMINE LA INCIDENCIA
							SELECT 1 FROM CIT
							WHERE @NUEVA_HCA=1
							AND CONSECUTIVO=@CONSECUTIVOCIT
							--AND  CAST(CONCAT(REPLACE(CONVERT(VARCHAR,@FECHA1,102),'.','-'), ' ', LEFT(CONVERT(VARCHAR(10), @FECHA1, 108),2), ':00:00') AS DATETIME)
							-- < CAST(CONCAT(R(CONVERT(VARCHAR,DBO.FNK_GETDATE(),102),'.','-'), ' ', LEFT(CONVERT(VARCHAR(10), DBO.FNK_GETDATE(), 108),2), ':00:00') AS DATETIME)
							AND CAST(CIT.FECHA AS DATE)<CAST(DBO.FNK_GETDATE() AS DATE)
							AND @CLASEPLANTILLA NOT IN ('NT_ACLA')
							AND NOT EXISTS (SELECT 1 FROM PERMESP WHERE USUARIO=@USUARIO AND CAST(CIT.FECHA AS DATE) BETWEEN CAST(PERMESP.FECHA AS DATE) AND CAST(PERMESP.FECHAFINAL AS DATE) )
							AND NOT EXISTS (SELECT 1 FROM USUSU INNER JOIN USGRUH ON USGRUH.GRUPO = DBO.FNK_DESCIFRAR(USUSU.GRUPO)
												WHERE USUARIO = @USUARIO AND USGRUH.IDPROCEDIMIENTO ='CONSULTA_EXTERNA_WEB' AND USGRUH.IDCONTROL ='EditaFechaHCA' AND USGRUH.PERMISO = 1)
						) AND 1 = 2
						BEGIN
							RAISERROR ('Fecha de la cita menor a la actual, no se puede continuar' , 16, 1);
							IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
							RETURN
						END
					END

					IF COALESCE(@IDAFILIADO,'')='' SELECT @IDAFILIADO = IDAFILIADO FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT

					IF @NUEVA_HCA=1 AND NOT EXISTS(SELECT 1 FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT AND IDAFILIADO=@IDAFILIADO)
					BEGIN
					    SELECT TOP 1 @CNS_AUX = CONSECUTIVO
					    FROM CIT
					    WHERE IDAFILIADO=@IDAFILIADO
					    AND IDMEDICO = @IDMEDICO
					    AND CAST(FECHA AS DATE) = CAST(GETDATE() AS DATE)
					    ORDER BY FECHAATENCION

					    IF COALESCE(@CNS_AUX,'')='' AND COALESCE(@CNS_AUX,'')<>@CONSECUTIVOCIT
						    SET @CONSECUTIVOCIT = @CNS_AUX
					END


					-- EZERPA 24.02.2023 Confirmar llegada a citas virtuales, y llamar el SPK_PAGOSCAJA_CIT
					IF EXISTS(SELECT 1 FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT AND FECHALLEGA IS NULL AND COALESCE(MODALIDAD,'Presencial')='Virtual')
					BEGIN
						UPDATE CIT SET FECHALLEGA = DBO.FNK_GETDATE(), USUARIOLLEGA = @USUARIO
							,CONSECUTIVOHCA = COALESCE(CONSECUTIVOHCA, @CONSECUTIVO)
						WHERE  CONSECUTIVO = @CONSECUTIVOCIT
						AND IDMEDICO = @IDMEDICO

						IF DBO.FNK_VALORVARIABLE('GENERA_COPAGO_HCA')='SI'
						BEGIN
						    IF  DBO.FNK_VALORVARIABLE('GENERA_COPAGO_CITAS')='LLEGA'
						    BEGIN
							    SELECT @PART = 1
							    FROM CIT WHERE
							    CONSECUTIVO = @CONSECUTIVOCIT
							    AND IDPLAN IN (
								    SELECT DATO FROM USVGS
								    WHERE IDVARIABLE IN ('IDPLANPART','IDPLANPART2','IDPLANPART3','IDPLANPART4','IDPLANPART5')
								    AND COALESCE(DATO,'') <> ''
							    )
							    EXEC SPK_PAGOSCAJA_CIT @CONSECUTIVOCIT, @SYS_COMPUTERNAME, @COMPANIA, @SEDE, @USUARIO, @PART
						    END
						END
					END
				END

				IF COALESCE(@NOADMISION,'')=''
				BEGIN
					SELECT @NOADMISION=NOADMISION FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT
					IF DBO.FNK_VALORVARIABLE('CIT_CREA_HADM') <> 'SI'
					BEGIN
						SELECT @NOADMISION = @CONSECUTIVOCIT
					END
				END
			END

			-- Datos del medico
			SELECT @AUDITORIA = JSON_VALUE(@PARAMETROS,'$.AUDITORIA')
			IF @AUDITORIA = 1
			BEGIN
			    SELECT @IDMEDICO = IDMEDICO, @USUARIO_AUX = USUARIO ,@IDEMEDICA = IDEMEDICA FROM HCA WHERE CONSECUTIVO = @CONSECUTIVOHCA
			    --Se revisa si en la audioria cambio el medico que diligencia (Asi dice Quasar) que es HCA.IDMEDICO
			    SELECT @IDMEDICOX = JSON_VALUE(@PARAMETROS ,'$.IDMEDICO')
			    IF @IDMEDICO <> @IDMEDICOX
			    BEGIN
				    SELECT @IDMEDICO = @IDMEDICOX
				    SELECT @IDEMEDICA = IDEMEDICA FROM MED WHERE IDMEDICO = @IDMEDICO
			    END
			    SELECT @SYS_COMPUTERNAME = COALESCE(SYS_COMPUTERNAME, @@SERVERNAME)
				FROM   USUSU
				WHERE  USUARIO = @USUARIO_AUX
			END
			ELSE
			BEGIN
				SELECT @IDMEDICO = IDMEDICO ,@SYS_COMPUTERNAME = COALESCE(SYS_COMPUTERNAME, @@SERVERNAME)
				FROM   USUSU
				WHERE  USUARIO = @USUARIO
			END
			-- Area funcional y centro de costo donde se origina la HC

			SELECT @IDAREA = IDAREA ,@CCOSTO = CCOSTO
			FROM UBEQ
			WHERE SYS_COMPUTERNAME = @SYS_COMPUTERNAME

			SELECT #T.*
				,EDAD = CAST(DATEDIFF(DAY, AFI.FNACIMIENTO, current_timestamp) / (365.23076923074) AS INT)
				,ENEPICRISIS = COALESCE(MPL.ENEPICRISIS, 0)
			INTO #HCA
			FROM OPENJSON(@PARAMETROS) WITH (
				 CLASEPLANTILLA	VARCHAR(8)	'$.CLASEPLANTILLA'		,TIPODX			VARCHAR(10)	'$.TIPODX'
				,IDDX			VARCHAR(10)	'$.IDDX'				,CONSECUTIVOCIT VARCHAR(20) '$.CONSECUTIVOCIT'
				,NOADMISION		VARCHAR(20) '$.NOADMISION'			,IDAFILIADO		VARCHAR(20) '$.IDAFILIADO'
				,PROCEDENCIA	VARCHAR(10) '$.PROCEDENCIA'			,TAS			VARCHAR(10) '$.TAS'
				,TAD			VARCHAR(10) '$.TAD'					,FC				VARCHAR(10) '$.FC'
				,FR				VARCHAR(10) '$.FR'					,TEMP			VARCHAR(10) '$.TEMP'
				,TALLA			VARCHAR(10) '$.TALLA'				,PULSO			VARCHAR(10) '$.PULSO'
				,PESO			VARCHAR(10) '$.PESO'				,GLASGOW		VARCHAR(11) '$.GLASGOW'
				,TIPOGLASGOW	VARCHAR(20) '$.TIPOGLASGOW'			,HIDRATACION	VARCHAR(10) '$.HIDRATACION'
				,TAM			VARCHAR(10) '$.TAM'					,DIURESIS		VARCHAR(10) '$.DIURESIS'
				,IDPLAN			VARCHAR(10) '$.IDPLAN'				,MED_ESPEC		VARCHAR(4)	'$.MED_ESPEC'
				,CODAZUL		BIT	        '$.CODAZUL'				,COVID			SMALLINT	'$.COVID'
				,ITEMHCSEGD		INT			'$.ITEMHCSEGD'			,DIASPRORROGA	INT			'$.DIASPRORROGA'
				,CHECK1			BIT			'$.CHECK1'				,CHECK2			BIT			'$.CHECK2'
				,CHECK3			BIT			'$.CHECK3'				,NECPAL			BIT			'$.NECPAL'
				,S1				BIT			'$.S1'					,S2				BIT			'$.S2'
				,S3				BIT			'$.S3'					,S4				BIT			'$.S4'
				,S5				BIT			'$.S5'					,S6				BIT			'$.S6'
				,PROT_ID        INT			'$.PROT_ID'				,PROT_IDPESPECIAL VARCHAR(5)'$.PROT_IDPESPECIAL'
				,ESNOTAACLARATORIA BIT		'$.ESNOTAACLARATORIA'	,PROT_JUSTIFICACION VARCHAR(1000) '$.PROT_JUSTIFICACION'
				,PROT_FECHA     VARCHAR(10) '$.PROT_FECHA'			,PROT_PROCESO   SMALLINT    '$.PROT_PROCESO'       --"1 incluir|5 auditoría|3 alta|2 cambio protocolo|4 cambio programa|0 nada
				,NOTACNSORI     VARCHAR(13) '$.NOTACNSORI'			,REVISAESP      BIT			'$.REVISAESP'
				,ESTANCIA		VARCHAR(20) '$.ESTANCIA'            ,PROT_MOTIVO    VARCHAR(5)  '$.PROT_MOTIVO'
				,IDMEDICOESP    VARCHAR(20) '$.IDMEDICOESP'
				,GRUPAL	        VARCHAR(10) '$.GRUPAL'
				,FECHASINTOMAS	VARCHAR(10) '$.FECHASINTOMAS'
                ,FECHACONFIRMACION	VARCHAR(10) '$.FECHACONFIRMACION'
				,FECHA_DILIGENCIA  DATETIME
                ,MDX		    NVARCHAR(MAX) AS JSON
				,TGANT          NVARCHAR(MAX) AS JSON
                ,HCATD		    NVARCHAR(MAX) AS JSON
				,ID_HCATD_AUD   INT         '$.ID_HCATD_AUD'
				,MPLD           NVARCHAR(MAX) AS JSON
                ,MPLSV		    NVARCHAR(MAX) AS JSON
				,HCADCP         NVARCHAR(MAX) AS JSON
                ,ESCALAS	    NVARCHAR(MAX) AS JSON
				,MPLGLU         NVARCHAR(MAX) AS JSON
				,HCPRUM       	NVARCHAR(MAX) AS JSON
				,CEOM       	NVARCHAR(MAX) AS JSON
				,CITSER       	NVARCHAR(MAX) AS JSON
                ,GRUPO		    NVARCHAR(MAX) AS JSON -- PREBIOLOGICOS
                ,HCAPREB	    NVARCHAR(MAX) AS JSON -- PREBIOLOGICOS
				,HCASER		    NVARCHAR(MAX) AS JSON -- SERVICIOS AUTOMATICOS
				,ALTA		    NVARCHAR(MAX) AS JSON -- DATOS DEL ALTA MEDICA
				,HCANED		    NVARCHAR(MAX) AS JSON -- RECORD DE ANESTESIA
				,HCANEDMED		NVARCHAR(MAX) AS JSON -- RECORD DE ANESTESIA - ANESTESICOS
				,datRIAS        NVARCHAR(MAX) AS JSON -- Dato del RIAS	&& SIOS_VIH
				,datRIASGest    NVARCHAR(MAX) AS JSON -- Hábitos y detalle por trimestre (RIAS_GESTACION_DETALLES)
				,AIEPI          NVARCHAR(MAX) AS JSON -- Dato del AIEPI
				,AFIFAM         NVARCHAR(MAX) AS JSON -- Dato del Familiares
				,AFIFAMREL      NVARCHAR(MAX) AS JSON -- Dato del Relaciones Familiares
				,AFIECOMAPA     NVARCHAR(MAX) AS JSON -- Datos ECOMAPA
                ,EXAMENESRIAS   NVARCHAR(MAX) AS JSON -- Datos de Examenes RIAS
                ,ARTICULACIONES NVARCHAR(MAX) AS JSON -- Datos de las Articulaciones

			) AS #T
                LEFT JOIN AFI ON AFI.IDAFILIADO=#T.IDAFILIADO
                LEFT JOIN MPL ON MPL.CLASEPLANTILLA=#T.CLASEPLANTILLA

         IF EXISTS (SELECT 1 FROM  CIT WHERE  CONSECUTIVO = @CONSECUTIVOCIT AND CIT.PROCEDENCIA IN ('HADMACTIV', 'HADMSER', 'PHD', 'PHDV', 'TCONTROL'))  OR @CIT_PROCEDENCIA = 'TCONTROL' OR @PROP_PROCEDENCIA = 'PHD_ADMITIDOS'
		   BEGIN
			   SELECT @PROCEDENCIA = 'QX'
            SELECT @NOADMISION = COALESCE(@NOADMISION,NOADMISION) FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT AND CIT.PROCEDENCIA IN ('HADMACTIV', 'HADMSER', 'PHD', 'PHDV', 'TCONTROL')
            UPDATE #HCA SET PROCEDENCIA = 'QX' WHERE 1 = 1
		   END

			-- Cita clonada (PyP o morbilidad): alinear #HCA con @CONSECUTIVOCIT actual
			IF COALESCE(@CONSECUTIVOCIT, '') <> ''
				AND EXISTS (SELECT 1 FROM #HCA WHERE COALESCE(CONSECUTIVOCIT, '') <> @CONSECUTIVOCIT)
				UPDATE #HCA SET CONSECUTIVOCIT = @CONSECUTIVOCIT WHERE 1 = 1

			IF @PROCEDENCIA = 'QX' AND @DAALTA = 1 AND @NIT='830507718'
			BEGIN
				DECLARE @MSG_INTERCONSULTAS NVARCHAR(MAX);
				DECLARE @CODOM_INTERCONSULTA VARCHAR(10) = DBO.FNK_VALORVARIABLE('OMCODINTERCONSULTA');

				SELECT @MSG_INTERCONSULTAS = STRING_AGG(CAST(LINEA AS NVARCHAR(500)), CHAR(13) + CHAR(10))
				FROM (
					SELECT DISTINCT
						LEFT(
							'INTERCONSULTA: ' + O.IDSERVICIO
							--+ ' IDMEDICA: ' + COALESCE(O.IDEMEDICA, 'SIN ESPECIALIDAD')
							+ ' - ' + COALESCE(M.DESCRIPCION, ''),
							200
						) AS LINEA
					FROM OMSOLI O WITH (NOLOCK)
					LEFT JOIN MES M ON M.IDEMEDICA = O.IDEMEDICA
					WHERE COALESCE(O.ESTADO, 0) = 0
						AND O.NOADMISION = @NOADMISION
						AND O.CODOM = @CODOM_INTERCONSULTA
						AND O.PROCEDENCIA = 'QX'
						AND O.IDSERVICIO<>'890454-1'
                        AND @DESTINO NOT IN ('4','5') /*FALLECIDO,REMITIDO*/
				) AS PENDIENTES;

				IF @MSG_INTERCONSULTAS IS NOT NULL
				BEGIN
					SELECT @ERROR_MSG = 
						CONCAT(
							N'No puede dar alta. Existen interconsultas pendientes:',
							CHAR(13), CHAR(10),
							@MSG_INTERCONSULTAS
						);
					RAISERROR(@ERROR_MSG, 16, 1);
					RETURN;
				END
			END

			--PROCESO DE ALTA
			IF @PROCEDENCIA='QX' AND @DAALTA=1
			BEGIN
				SELECT @AUX = ALTA FROM #HCA

				SELECT @IDMEDICOALTA = IIF(DBO.FNK_VALORVARIABLE('ALTAMED_TIPOMED')='TRATANTE',IDMEDICOTRA, @IDMEDICO)
					,@DXINGRESO = DXINGRESO, @DESTINO = DESTINO, @ESTADOPSALIDA = ESTADOPSALIDA
					,@FECHAALTA = REPLACE(FECHAALTA,'-','')+' '+HORAALTA, @HORASUSPENDE = REPLACE(FECHAALTA,'-','')+' '+HORASUSPENDE, @CCOSTO_ALTA = CCOSTO_ALTA, @DXSALIDA1 = DXSALIDA1
					,@DXSALIDA2 = DXSALIDA2, @DXSALIDA3 = DXSALIDA3, @CAUSABMUERTE = CAUSABMUERTE, @ACTADEFUNCION = ACTADEFUNCION
					,@DXEGRESO	= DXEGRESO
				FROM OPENJSON(@AUX) WITH (
					IDMEDICOTRA		VARCHAR(20) '$.IDMEDICOTRA'
					,DXINGRESO		VARCHAR(6)	'$.DXINGRESO'
					,DXEGRESO		VARCHAR(6)	'$.DXEGRESO'
					,DESTINO		VARCHAR(2)	'$.DESTINO'
					,ESTADOPSALIDA	VARCHAR(2)	'$.ESTADOPSALIDA'
					,FECHAALTA		VARCHAR(15) '$.FECHAALTA'
					,HORAALTA		VARCHAR(10) '$.HORAALTA'
					,HORASUSPENDE	VARCHAR(15) '$.HORASUSPENDE'
					,CCOSTO_ALTA	VARCHAR(10)	'$.CCOSTO_ALTA'  --STORRES
					,DXSALIDA1		VARCHAR(6)	'$.DXSALIDA1'
					,DXSALIDA2		VARCHAR(6)	'$.DXSALIDA2'
					,DXSALIDA3		VARCHAR(6)	'$.DXSALIDA3'
					,CAUSABMUERTE	VARCHAR(10) '$.CAUSABMUERTE'
					,ACTADEFUNCION	VARCHAR(10) '$.ACTADEFUNCION'

				)

				IF @HORASUSPENDE IS NULL
					INSERT INTO @TBLERRORES (ERROR) SELECT 'Debe diligenciar la hora de suspension del tratamiento'
				IF CONVERT(datetime, @HORASUSPENDE )>CONVERT(datetime, @FECHAALTA)
					INSERT INTO @TBLERRORES (ERROR) SELECT 'Hora suspension mayor al de lata no es posible'
				IF (SELECT FECHA FROM HADM WHERE NOADMISION=@NOADMISION)>CONVERT(datetime, @FECHAALTA)
					INSERT INTO @TBLERRORES (ERROR) SELECT 'Fecha de alta no puede ser menor a la fecha de ingreso FECHA_INGRESO='
				IF CAST(@FECHAALTA AS DATE)>CAST(GETDATE() AS DATE)
					INSERT INTO @TBLERRORES (ERROR) SELECT 'Fecha de alta no puede ser mayor a la fecha de hoy FECHA_ACTUAL='+CONVERT(VARCHAR, GETDATE(), 103)
				IF DATEDIFF(MINUTE, CONVERT(datetime, @FECHAALTA), GETDATE())>30
					INSERT INTO @TBLERRORES (ERROR) SELECT 'Hora alta no puede ser menor a la actual'
				IF COALESCE((SELECT COALESCE(CERRADA,0) FROM HADM WHERE NOADMISION=@NOADMISION),1)<>0
					INSERT INTO @TBLERRORES (ERROR) SELECT 'Paciente ya cuenta con alta, no es posible realizar una nueva'
				IF @ESTADOPSALIDA=2 AND COALESCE(@CAUSABMUERTE,'')=''
					INSERT INTO @TBLERRORES (ERROR) SELECT 'Debe ingresar la causa basica de La muerte'
				IF (SELECT COUNT(1) FROM MDX WHERE IDDX=COALESCE(@DXINGRESO,'')
							AND NOT EXISTS (SELECT 1 FROM TGEN WHERE TABLA='GENERAL' AND CAMPO='DXNOACEPTADO' AND CODIGO=MDX.IDDX))<=0
					INSERT INTO @TBLERRORES (ERROR) SELECT 'Dx de ingreso no existe en MDX'
				IF (SELECT COUNT(1) FROM MDX WHERE IDDX=COALESCE(@DXEGRESO,'')
							AND NOT EXISTS (SELECT 1 FROM TGEN WHERE TABLA='GENERAL' AND CAMPO='DXNOACEPTADO' AND CODIGO=MDX.IDDX))<=0
					INSERT INTO @TBLERRORES (ERROR) SELECT 'Dx de egreso no existe en MDX'
				IF COALESCE(@ESTADOPSALIDA,'') NOT IN (1,2)
					INSERT INTO @TBLERRORES (ERROR) SELECT 'Debe ingresar el estado del paciente al salir'
				IF NOT EXISTS (SELECT 1 FROM CEN WHERE CCOSTO=COALESCE(@CCOSTO_ALTA,''))
					INSERT INTO @TBLERRORES (ERROR) SELECT 'El Ccosto de alta no existe.'


				IF @VALIDA_EPIANTESALTA='SI'
				BEGIN
					IF @PERMITE_ALTASINEPI='SI'
					BEGIN
						IF EXISTS(SELECT 1 FROM HCA WHERE NOADMISION=@NOADMISION AND PROCEDENCIA='QX')
							AND NOT EXISTS (SELECT 1 FROM HCA WHERE NOADMISION=@NOADMISION AND PROCEDENCIA='QX' AND CLASEPLANTILLA=@HCPLANTILLAEPI)
							AND (SELECT DATEDIFF(MINUTE,FECHA,GETDATE()) FROM HADM WHERE NOADMISION=@NOADMISION)>TRY_CAST(@MINTOSMAXSINEPI AS INT)
						BEGIN
							INSERT INTO @TBLERRORES (ERROR)
							SELECT 'El tiempo transcurrido entre la admision y el alta medica es mayor a: '+@MINTOSMAXSINEPI+' minutos, se debe realizar la epicrisis'
						END
					END
					ELSE
					BEGIN
					IF  NOT EXISTS (SELECT 1 FROM HCA WHERE NOADMISION=@NOADMISION AND PROCEDENCIA='QX' AND CLASEPLANTILLA=@HCPLANTILLAEPI)
							AND (SELECT DATEDIFF(MINUTE,FECHA,GETDATE()) FROM HADM WHERE NOADMISION=@NOADMISION)>CAST(@MINTOSMAXSINEPI AS INT)
						BEGIN
							INSERT INTO @TBLERRORES (ERROR)
							SELECT 'El tiempo transcurrido entre la admision y el alta medica es mayor a: '+@MINTOSMAXSINEPI+' minutos, se debe realizar la epicrisis'
						END
					END
				END
				IF EXISTS(SELECT 1 FROM @TBLERRORES)
				BEGIN
					SELECT @CMD=STUFF((SELECT '  '+ CONVERT(VARCHAR, ROW_NUMBER() OVER(ORDER BY ERROR DESC))+' - '+ERROR FROM @TBLERRORES FOR XML PATH('')),1,1,'')
					DELETE FROM @TBLERRORES WHERE 1=1
					RAISERROR (@CMD, 16, 1);
					IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
					RETURN
				END
			END

			IF @PROCEDENCIA IS NULL
				SET @PROCEDENCIA = 'QX'

			IF COALESCE(@IDAFILIADO, '') = '' AND COALESCE(@CONSECUTIVOCIT, '') <> ''
				SELECT @IDAFILIADO = IDAFILIADO FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT

			IF @PROCEDENCIA = 'GESTIONES'
				SELECT @IDAFILIADO = @IDAFILIADO_OTRO

			IF @PROCEDENCIA = 'QX' AND COALESCE(@CONSECUTIVOCIT,'')<>''
				SELECT @PROCEDENCIA = 'IPS'

  
         IF EXISTS (SELECT 1 FROM  CIT WHERE  CONSECUTIVO = @CONSECUTIVOCIT AND CIT.PROCEDENCIA IN ('HADMACTIV', 'HADMSER', 'PHD', 'PHDV', 'TCONTROL'))  OR @CIT_PROCEDENCIA = 'TCONTROL' OR @PROP_PROCEDENCIA = 'PHD_ADMITIDOS'
		   BEGIN
			   SELECT @PROCEDENCIA = 'QX'
            SELECT @NOADMISION = COALESCE(@NOADMISION,NOADMISION) FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT AND CIT.PROCEDENCIA IN ('HADMACTIV', 'HADMSER', 'PHD', 'PHDV', 'TCONTROL')
		   END
            IF (SELECT PROT_PROCESO FROM #HCA)='1' AND COALESCE(@IDPLAN_NEW,'')<>'' AND @PROCEDENCIA='IPS' /*ARTMEDICA*/
            BEGIN
                UPDATE CIT SET IDPESPECIAL=@PROT_IDPESPECIAL WHERE CONSECUTIVO=@CONSECUTIVOCIT
                SELECT @IDTERCERO = IDTERCEROCA FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT
                UPDATE AFI SET IDPLAN=@IDPLAN_NEW WHERE IDAFILIADO=@IDAFILIADO
                
                IF EXISTS (SELECT 1 FROM TGEN WHERE TABLA='CIT' AND CAMPO='CAMBIA_PLAN' AND CODIGO=@IDTERCERO)
                BEGIN
                    UPDATE CIT SET IDPLAN=@IDPLAN_NEW, CLASEORDEN='Modelo' WHERE CONSECUTIVO=@CONSECUTIVOCIT
                END
            END

			SELECT @AUX = HCATD
			FROM #HCA

			SELECT DURACION = TRY_CAST(DURACION_STRING AS DECIMAL(14,2))
				,*
			INTO #HCATD
			FROM OPENJSON(@AUX) WITH (
				ID				INT				'$.ID'
				,CODOM			VARCHAR(10)		'$.CODOM'		,IDSERVICIO		VARCHAR(20) '$.IDSERVICIO'
				,OBSERVACION	NVARCHAR(MAX)	'$.OBSERVACION'	,FRECUENCIA		VARCHAR(50) '$.FRECUENCIA'
				,DURACION_STRING VARCHAR(MAX)	'$.DURACION'	,TIPODURACION	VARCHAR(1)  '$.TIPODURACION'
				,TIPOFRECUENCIA VARCHAR(1)	'$.TIPOFRECUENCIA'	,CANTIDAD		DECIMAL(18, 6) '$.CANTIDAD'
				,CLASE			VARCHAR(1)		'$.CLASE'		,VIA			VARCHAR(13) '$.VIA'
				,CODPAQUETE		VARCHAR(20)		'$.CODPAQUETE'	,LUNES			SMALLINT	'$.LUNES'
				,MARTES			SMALLINT		'$.MARTES'		,MIERCOLES		SMALLINT	'$.MIERCOLES'
				,JUEVES			SMALLINT		'$.JUEVES'		,VIERNES		SMALLINT	'$.VIERNES'
				,SABADO			SMALLINT		'$.SABADO'		,DOMINGO		SMALLINT	'$.DOMINGO'
				,RAZONNEC		SMALLINT		'$.RAZONNEC'	,DOSISUNICA		SMALLINT	'$.DOSISUNICA'
				,NDOSISINICIO	SMALLINT		'$.NDOSISINICIO'
				,TIPO			VARCHAR(15)		'$.TIPO'		,CANTIDADBOLO	VARCHAR(20) '$.CANTIDADBOLO'
				,IDSERVICIOMEZCLA VARCHAR(20)	'$.IDSERVICIOMEZCLA'
				,QMEZCLA		VARCHAR(20)		'$.QMEZCLA'		,HORAAM			SMALLINT	'$.HORAAM'
				,HORAPM			SMALLINT		'$.HORAPM'		,QAM			VARCHAR(100)'$.QAM'
				,QPM			VARCHAR(100)	'$.QPM'			,FECHAINI		VARCHAR(15)	'$.FECHAINI'
				,IDCAUSAL		VARCHAR(10)		'$.IDCAUSAL'	,AVISADOENF		INT			'$.AVISADOENF'
				,RUTA			BIT				'$.RUTA'		,TOTALUNIDADES	VARCHAR(10) '$.TOTALUNIDADES'
				,PRESCRIPCION	VARCHAR(1000)	'$.PRESCRIPCION',ITEM_DXUNIRS	INT			'$.DXUNIRS'
				,IDDX			VARCHAR(10)	    '$.IDDX'
				,IDDX_UNIRS		VARCHAR(10)	    '$.IDDXUNIRS.IDDX',EFECTOS		VARCHAR(MAX)'$.EFECTOS'
				,TOTAL_CONTROLADOS	INT			'$.TOTAL_CONTROLADOS'
				,ENCARGOS		VARCHAR(10)		'$.ENCARGOS'	,NOINGRESO		VARCHAR(20)'$.NOINGRESO'
				,NOPRESTACION	VARCHAR(10)		'$.NOPRESTACION'
				,FFINALDOSIS	VARCHAR(15)		'$.FFINALDOSIS'	,HFINALDOSIS	VARCHAR(15)	'$.HFINALDOSIS'
				,COPIADO		SMALLINT		'$.COPIADO'
				,HORAINI		VARCHAR(5)		'$.HORAINI'
				,CANTIDADORI	DECIMAL (14, 2)	'$.CANTIDADORI'
				,FRECUENCIAORI	DECIMAL (14, 2) '$.FRECUENCIAORI'
				,DURACIONORI	DECIMAL (14, 2) '$.DURACIONORI'
				,GOTEO			DECIMAL (14, 2) '$.GOTEO'
				,DOSIF			SMALLINT		'$.DOSIF'
				,TIPOSOLBS		VARCHAR(20)		'$.TIPOSOLBS'
				,BSCAPACIDAD	DECIMAL(14, 2)	'$.BSCAPACIDAD'
				,QIMPSERVICIO	VARCHAR(20)		'$.QIMPSERVICIO'
				,QIMPMEZCLA		VARCHAR(20)		'$.QIMPMEZCLA'
				,DURACIONIMP	VARCHAR(20)		'$.DURACIONIMP'
				,IDBODEGA		VARCHAR(20)		'$.IDBODEGA'
				,PROTOCOLO		BIT				'$.PROTOCOLO'
				,ENAYUNO		BIT				'$.ENAYUNO'
				,APLICADA		SMALLINT		'$.APLICADA'
				,CANTDIAS		SMALLINT		'$.CANTDIAS'
				,STAFF			BIT				'$.STAFF'
				,CASO_DIFICIL_STAFF	BIT			'$.CASO_DIFICIL_STAFF'
				,ID_PRIO_STAFF	    INT			'$.ID_PRIO_STAFF'
				,FORMULADO_STAFF    BIT			'$.FORMULADO_STAFF'
				,ESTADO_STAFF       VARCHAR(20)	'$.ESTADO_STAFF'
				,CATEGORIA_STAFF    VARCHAR(20)	'$.CATEGORIA_STAFF'
				,ID_CHECKLIST       VARCHAR(20)	'$.ID_CHECKLIST'
				,NIVEL_PREVENCION	INT			'$.NIVEL_PREVENCION'
				,IDCEOM         	INT			'$.IDCEOM'
				,IDPATOLOGIA	VARCHAR(20)		'$.IDPATOLOGIA'
				,LATERALIDAD	VARCHAR(20)		'$.LATERALIDAD'
				,SEGMENTO		NVARCHAR(255)	'$.SEGMENTO' -- NUEVO: segmento anatómico por ítem de orden
				,CATEGORIATM	VARCHAR(50)		'$.CATEGORIATM'
				,OBSERVACION_STAFF	NVARCHAR(MAX) '$.OBSERVACION_STAFF'
				,PRIORIDADES_STAFF	NVARCHAR(MAX)	AS JSON
				,HCATDO			NVARCHAR(MAX)	 AS JSON
				,HCATDH			NVARCHAR(MAX)	 AS JSON
				,HCATDPT		NVARCHAR(MAX)	 AS JSON
				,ANT_VIG		NVARCHAR(MAX)	 AS JSON
				,NOINSTITUCIONAL	BIT			'$.NOINSTITUCIONAL'
				,DOSIS_TITULABLE	INT			'$.DOSIS_TITULABLE'
				,ID_HCATD_AUD		INT				'$.ID_HCATD_AUD'
				,REQ_AUDITORIA		BIT				'$.REQ_AUDITORIA'
				,JUSTIFICACION_PROT	NVARCHAR(MAX)	'$.JUSTIFICACION_PROT'
			)
			CREATE INDEX IX_HCATD_IDSERVICIO ON #HCATD(IDSERVICIO);
			CREATE INDEX IX_HCATD_CODOM ON #HCATD(CODOM);

			-- DENEGAR_INTERCONS: bloquear solo si la interconsulta NUEVA (HCATD.ID NULL)
			-- ya tiene el mismo IDSERVICIO pendiente en OMSOLI (NOADMISION + CODOM + ESTADO=0).
			IF @DENEGAR_INTERCONS = 'SI'
			BEGIN
				DECLARE @MSG_DENEGAR_IC NVARCHAR(MAX)

				SELECT @MSG_DENEGAR_IC = STRING_AGG(CAST(LINEA AS NVARCHAR(500)), CHAR(13) + CHAR(10))
				FROM (
					SELECT DISTINCT
						LEFT(
							COALESCE(O.IDSERVICIO, '') + ' - ' + COALESCE(SER.DESCSERVICIO, ''),
							200
						) AS LINEA
					FROM #HCATD H
					INNER JOIN OMSOLI O WITH (NOLOCK)
						ON O.NOADMISION = @NOADMISION
						AND O.CODOM = @CODOM_INTERCONSULTA_CFG
						AND O.IDSERVICIO = H.IDSERVICIO
						AND COALESCE(O.ESTADO, 0) = 0
					LEFT JOIN SER WITH (NOLOCK) ON SER.IDSERVICIO = O.IDSERVICIO
					WHERE H.CODOM = @CODOM_INTERCONSULTA_CFG
						AND H.ID IS NULL
						AND COALESCE(H.IDSERVICIO, '') <> ''
				) AS DUPLICADOS

				IF @MSG_DENEGAR_IC IS NOT NULL
				BEGIN
					SELECT @ERROR_MSG = CONCAT(
						N'Ya existe una interconsulta pendiente para este servicio en la admisión:',
						CHAR(13), CHAR(10),
						@MSG_DENEGAR_IC
					)
					RAISERROR(@ERROR_MSG, 16, 1)
					RETURN
				END
			END

			/* Aprobación auditoría OM (PLANTILLA_AUD_OM): marcar OM para no re-encolar en HCATD_AUD */
			SELECT @ID_HCATD_AUD_MPL = ID_HCATD_AUD FROM #HCA
			IF COALESCE(@ID_HCATD_AUD_MPL, 0) > 0
			BEGIN
				UPDATE #HCATD
				SET ID_HCATD_AUD = COALESCE(ID_HCATD_AUD, @ID_HCATD_AUD_MPL),
					REQ_AUDITORIA = 0
			END
			ELSE
			BEGIN
				UPDATE #HCATD
				SET REQ_AUDITORIA = 0
				WHERE COALESCE(ID_HCATD_AUD, 0) > 0
			END

			-- IDDX: diagnóstico clínico en $.IDDX (OrdenesComponent) o UNIRS en $.IDDXUNIRS.IDDX
			UPDATE #HCATD
			SET IDDX = COALESCE(NULLIF(RTRIM(IDDX_UNIRS), ''), NULLIF(RTRIM(IDDX), ''))

			-- TOTALUNIDADES: mínimo 1 unidad a dispensar (evita guardar 0 o negativo)
			UPDATE #HCATD
			SET TOTALUNIDADES = CAST(
				IIF(COALESCE(TRY_CAST(NULLIF(LTRIM(RTRIM(TOTALUNIDADES)), '') AS INT), 0) < 1, 1,
					TRY_CAST(NULLIF(LTRIM(RTRIM(TOTALUNIDADES)), '') AS INT))
			AS VARCHAR(10))

			SELECT @AUX = CEOM
			FROM #HCA

            SELECT *
			INTO #CEOM
			FROM OPENJSON(@AUX)
            WITH (
				IDCEOM			INT			    '$.IDCEOM'
				,IDSERVICIO		VARCHAR(20)     '$.IDSERVICIO'
				,CODOM   		VARCHAR(10)     '$.CODOM'
				,CLASE			VARCHAR(1)		'$.CLASE'
				,ACTIVO			BIT				'$.ACTIVO'
				,EXTRAINSTITUCIONAL	BIT			'$.EXTRAINSTITUCIONAL'
				,RUTA       	BIT			    '$.RUTA'
                ,CANTIDAD		DECIMAL(18, 6)  '$.CANTIDAD'
                ,FRECUENCIA		VARCHAR(50)     '$.FRECUENCIA'
				,DURACION		DECIMAL(14, 2)	'$.DURACION'
                ,TIPODURACION	VARCHAR(1)      '$.TIPODURACION'
				,TIPOFRECUENCIA VARCHAR(1)	    '$.TIPOFRECUENCIA'
                ,TOTALUNIDADES	VARCHAR(10)     '$.TOTALUNIDADES'
				,OBSERVACION	NVARCHAR(MAX)	'$.OBSERVACION'
				,PRESCRIPCION	VARCHAR(1024)	'$.PRESCRIPCION'
                ,VIA			VARCHAR(13)     '$.VIA'
				,FECHAINI		VARCHAR(10)	    '$.FECHAINI'
				,FECHAFIN		VARCHAR(10)		'$.FECHAFIN'
				,FECHASUSPENDE	VARCHAR(10)		'$.FECHASUSPENDE'
				,CAUSASUSPENSION VARCHAR(15)    '$.CAUSASUSPENSION'
				,OBSSUSPENSION   VARCHAR(15)	'$.OBSSUSPENSION'
			)

			UPDATE #CEOM
			SET TOTALUNIDADES = CAST(
				IIF(COALESCE(TRY_CAST(NULLIF(LTRIM(RTRIM(TOTALUNIDADES)), '') AS INT), 0) < 1, 1,
					TRY_CAST(NULLIF(LTRIM(RTRIM(TOTALUNIDADES)), '') AS INT))
			AS VARCHAR(10))

			SELECT @AUX = HCPRUM FROM #HCA

            SELECT *
			INTO #HCPRUM
			FROM OPENJSON(@AUX)
            WITH (
                CONSECUTIVOHCA VARCHAR(13)          '$.HCPRUM.CONSECUTIVOHCA'
                ,IDAFILIADO VARCHAR(20)             '$.HCPRUM.IDAFILIADO'
                ,IDCEOM INT                         '$.HCPRUM.IDCEOM'
                ,IDSERVICIO VARCHAR (20)            '$.HCPRUM.IDSERVICIO'
                ,TIPO VARCHAR(10)                   '$.HCPRUM.TIPO'
                ,ESDISPONIBILIDAD VARCHAR (20)      '$.HCPRUM.ESDISPONIBILIDAD'
                ,DISPONIBILIDAD VARCHAR (512)       '$.HCPRUM.DISPONIBILIDAD'
                ,ESPRESCRIPCION  VARCHAR (20)       '$.HCPRUM.ESPRESCRIPCION'
                ,PRESCRIPCION VARCHAR (512)         '$.HCPRUM.PRESCRIPCION'
                ,ESDISPENSACION VARCHAR (20)        '$.HCPRUM.ESDISPENSACION'
                ,DISPENSACION VARCHAR (512)         '$.HCPRUM.DISPENSACION'
                ,ESCALIDAD VARCHAR (20)             '$.HCPRUM.ESCALIDAD'
                ,CALIDAD VARCHAR (512)              '$.HCPRUM.CALIDAD'
                ,ESADMINISTRACION VARCHAR (20)      '$.HCPRUM.ESADMINISTRACION'
                ,ADMINISTRACION VARCHAR (512)       '$.HCPRUM.ADMINISTRACION'
                ,ESUSO VARCHAR (20)                 '$.HCPRUM.ESUSO'
                ,USO VARCHAR (512)                  '$.HCPRUM.USO'
                ,RECOMENDACIONES VARCHAR (512)      '$.HCPRUM.RECOMENDACIONES'
			)

			SELECT @AUX = CITSER FROM #HCA
            SELECT *
			INTO #CITSER
			FROM OPENJSON(@AUX)
            WITH (
                IDSERVICIO VARCHAR (20)     '$.IDSERVICIO'
                ,REALIZADO BIT              '$.REALIZADO'
			)


			SELECT @CLASEPLANTILLA = CLASEPLANTILLA
				,@TIPODX = TIPODX
				,@IDAFILIADO = COALESCE(@IDAFILIADO, IDAFILIADO)
				,@PROCEDENCIA = PROCEDENCIA
				,@IDPLAN = IDPLAN
				,@ITEMHCSEGD = ITEMHCSEGD
				,@DIASPRORROGA = DIASPRORROGA
				,@NECPAL = NECPAL
				,@PROT_IDPESPECIAL    = PROT_IDPESPECIAL
				,@PROT_ID             = PROT_ID
				,@PROT_JUSTIFICACION  = PROT_JUSTIFICACION
				,@PROT_MOTIVO         = PROT_MOTIVO
				,@PROT_FECHA          = CONVERT(DATE,SUBSTRING(PROT_FECHA,9,2)+'/'+SUBSTRING(PROT_FECHA,6,2)+'/'+SUBSTRING(PROT_FECHA,1,4))
				,@PROT_PROCESO        = PROT_PROCESO
				,@ESNOTAACLARATORIA   = ESNOTAACLARATORIA
				,@NOTACNSORI          = NOTACNSORI
			FROM #HCA

            --VALIDACION DE CITA ASIGNADA A 2 MESES ARTMEDICA
            IF @PROCEDENCIA='IPS'
            BEGIN
                DECLARE @IDEMEDICA_MODELO VARCHAR(20)
			    SELECT @IDEMEDICA_MODELO=IIF(CIT.IDAPLIM>0, MED.IDEMEDICA,CIT.IDEMEDICA), @IDPESPECIAL_CITA = IDPESPECIAL
                FROM CIT 
                LEFT JOIN MED ON MED.IDMEDICO=@IDMEDICO
                WHERE CONSECUTIVO = @CONSECUTIVOCIT

			    --PROCESO DE MODELOS MPE PROTOCOLOS  "1 incluir|3 alta del programa|2 cambiar de protocolo|0 nada|4 Cambio de programa
                IF ((@CLASEORDENX='Modelo' AND COALESCE(@PROT_PROCESO,0)<>3) OR (@CLASEORDENX='Normal' AND COALESCE(@PROT_PROCESO,0)=1))
                    AND EXISTS(SELECT 1 FROM MPE INNER JOIN MPEMES ON MPEMES.IDPESPECIAL=MPE.IDPESPECIAL
                        WHERE MPE.IDPESPECIAL=COALESCE(@PROT_IDPESPECIAL,@IDPESPECIAL_CITA) AND DIASMINGCITA>0 AND MPEMES.IDEMEDICA=@IDEMEDICA_MODELO)
                BEGIN
                    SET @CMD=NULL
                    IF NOT EXISTS(
                        SELECT 1
                        FROM CIT WITH(NOLOCK)
                            INNER JOIN MPE WITH(NOLOCK) ON MPE.IDPESPECIAL=COALESCE(@PROT_IDPESPECIAL,@IDPESPECIAL_CITA)
                            INNER JOIN MPEMES MES WITH(NOLOCK) ON MES.IDPESPECIAL=MPE.IDPESPECIAL AND MES.IDEMEDICA=CIT.IDEMEDICA
                        WHERE CIT.IDAFILIADO=@IDAFILIADO 
                        AND CIT.FECHA>=DATEADD(DAY, 1, CONVERT(DATE, GETDATE())) 
                        AND CIT.IDPESPECIAL=COALESCE(@PROT_IDPESPECIAL,@IDPESPECIAL_CITA)
                        AND CIT.FECHA<=DATEADD(DAY, MPE.DIASMINGCITA, CONVERT(DATE, GETDATE()))
                    )
                    BEGIN
                        SELECT @CMD='Debe asignar una cita para minimo ' +convert(varchar(5),MPE.DIASMINGCITA)+' dias, segun el programa: '+coalesce(mpe.descespecial,'')
                        FROM MPE WHERE IDPESPECIAL=COALESCE(@PROT_IDPESPECIAL,@IDPESPECIAL_CITA)
                        RAISERROR(@CMD,16,1)
                        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
                        RETURN
                    END
                END      
            END
            IF EXISTS (SELECT 1 FROM  CIT WHERE  CONSECUTIVO = @CONSECUTIVOCIT AND CIT.PROCEDENCIA = 'PHDV')
			BEGIN
				SELECT @PROCEDENCIA = 'QX'    , @NOADMISION = NOADMISION ,@CCOSTO = CCOSTO FROM CIT WHERE    CONSECUTIVO = @CONSECUTIVOCIT AND CIT.PROCEDENCIA = 'PHDV'
			END
			--Aqui debemos revisar la sede
			IF @PROCEDENCIA = 'IPS' AND COALESCE(@CONSECUTIVOCIT,'')<>''
				SELECT @SEDE = TRIM(CIT.IDSEDE) FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT --STORRES

			IF COALESCE(@CONSECUTIVOCIT,'')<>'' AND COALESCE(@AUDITORIA,0) = 0
            BEGIN
				SELECT @IDEMEDICA=IIF(CIT.IDAPLIM>0, MED.IDEMEDICA,CIT.IDEMEDICA), @IDPLAN = COALESCE(@IDPLAN,CIT.IDPLAN) 
                FROM CIT 
                LEFT JOIN MED ON MED.IDMEDICO=@IDMEDICO
                WHERE CONSECUTIVO = @CONSECUTIVOCIT
            END

			IF COALESCE(@AUDITORIA,0) = 0
			BEGIN
				IF COALESCE(@IDEMEDICA,'')='' AND COALESCE(@IDMEDICO,'')<>''
					SELECT @IDEMEDICA = MED.IDEMEDICA FROM MED WHERE IDMEDICO=@IDMEDICO
			END

			SELECT @CLASE = CLASE ,@AMBITO = AMBITO ,@TIENEOM = TIENEOM ,@NOCOPIAOM = COALESCE(NOCOPIAOM,0)
			FROM   MPL
			WHERE  CLASEPLANTILLA = @CLASEPLANTILLA

			IF @PROCEDENCIA='QX' AND @TIENEOM>0
			BEGIN
				IF DBO.FNK_VALORVARIABLE('HC_CONFIRMA_OMHOSPI')='SI'
				BEGIN
					IF NOT EXISTS (SELECT 1 FROM #HCATD A WHERE A.CODOM=DBO.FNK_VALORVARIABLE('OMCODHOSPITALIZAR') AND A.CLASE IN ('I','C','B'))
					BEGIN
						RAISERROR ('Es necesario que ordene o especifique la estancia del paciente' , 16, 1);
						IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
						RETURN
					END
				END
				IF DBO.FNK_VALORVARIABLE('HC_CONFIRMA_OMDIETA')='SI'
				BEGIN
					IF NOT EXISTS (SELECT 1 FROM #HCATD A WHERE A.CODOM=DBO.FNK_VALORVARIABLE('OMCODDIETAS') AND A.CLASE IN ('I','C','B'))
					BEGIN
						RAISERROR ('Es necesario que ordene o especifique la dieta del paciente' , 16, 1);
						IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
						RETURN
					END
				END
				IF DBO.FNK_VALORVARIABLE('OM_UNICO_ESTANCIA')='SI'
				BEGIN
					IF (SELECT COUNT(1) FROM #HCATD A WHERE A.CODOM=DBO.FNK_VALORVARIABLE('OMCODHOSPITALIZAR') AND A.CLASE IN ('I','C','B'))>1
					BEGIN
						RAISERROR ('Solo debe ordenar un servicio de estancia' , 16, 1);
						IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
						RETURN
					END
				END
				IF DBO.FNK_VALORVARIABLE('OM_UNICO_OXIGENO')='SI'
				BEGIN
					IF (SELECT COUNT(1) FROM #HCATD A WHERE A.CODOM=DBO.FNK_VALORVARIABLE('OMCODMEDOXIGENO') AND A.CLASE IN ('I','C','B'))>1
					BEGIN
						RAISERROR ('Solo debe ordenar un servicio de oxigeno' , 16, 1);
						IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
						RETURN
					END
				END
			END
			SELECT @PREFIJO = '@' + CASE @CLASE
					WHEN 'HC'
						THEN 'HC'
					WHEN 'NE'
						THEN 'HCNE'
					WHEN 'NA'
						THEN 'HCNA'
					ELSE 'HCON'
					END

			IF COALESCE(@CONSECUTIVOHCA,'')<>'' 
                SET @CONSECUTIVO=@CONSECUTIVOHCA
			ELSE
			BEGIN
				EXEC SPK_GENCONSECUTIVO '01',@SEDE,@PREFIJO,@CONSECUTIVO OUTPUT

				SELECT @CONSECUTIVO = CASE
						WHEN @PREFIJO <> '@HC'
							THEN RIGHT(@PREFIJO, 2)
						ELSE ''
						END + @SEDE + REPLACE(SPACE(8 - LEN(@CONSECUTIVO)) + LTRIM(RTRIM(@CONSECUTIVO)), SPACE(1), 0)

				IF @PROCEDENCIA='QX'
                BEGIN
                    SELECT @ITEMRED = MAX(ITEMRED) + 1 FROM HCA WHERE NOADMISION = @NOADMISION
                END
				ELSE
                BEGIN
                    SELECT @ITEMRED = MAX(ITEMRED) + 1 FROM HCA WHERE CONSECUTIVOCIT = @CONSECUTIVOCIT
                END                

				IF @ITEMRED IS NULL SET @ITEMRED = 1
			END

			IF COALESCE(@IDAFILIADO,'') = ''
				SELECT @IDAFILIADO = IDAFILIADO FROM #HCA

			SELECT @IDPLAN_HADM = IDPLAN, @IDPLAN=COALESCE(@IDPLAN,IDPLAN), @IDTERCERO = IDTERCERO FROM HADM WHERE NOADMISION=@NOADMISION

			IF COALESCE(@IDPLAN,'')<>'' AND COALESCE(@CCOSTO,'')=''
				SELECT @IDAREA=IDAREA, @CCOSTO=CCOSTO FROM CEN WHERE CCOSTO=(SELECT CCOSTO FROM PLN WHERE IDPLAN=@IDPLAN)

			IF @PROCEDENCIA='QX' AND COALESCE(@NOADMISION,'')<>''
			BEGIN
				SELECT @CCOSTO = IIF(COALESCE(HHAB.CCOSTO,'')='', SEC.CCOSTO, HHAB.CCOSTO)
				FROM HHAB LEFT JOIN HHAB SEC ON SEC.HABCAMA=HHAB.SECTOR WHERE HHAB.NOADMISION=@NOADMISION
				IF COALESCE(@CCOSTO,'')=''
					SELECT TOP 1 @CCOSTO = CCOSTO FROM HNAT WHERE NOADMISION=@NOADMISION AND FECHA<=DBO.FNK_GETDATE() ORDER BY FECHA DESC
				IF COALESCE(@CCOSTO,'')=''
					SELECT @CCOSTO = CCOSTO FROM UBEQ WHERE SYS_ComputerName=@SYS_COMPUTERNAME

				SELECT @IDAREA=IDAREA FROM CEN WHERE CCOSTO=@CCOSTO
			END
			IF @PROCEDENCIA = 'IPS' AND @CONSECUTIVOCIT IS NOT NULL
				SELECT @CCOSTO = CCOSTO, @IDAREA = IDAREA FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT AND COALESCE(CCOSTO,'')<>''

			SELECT TOP 1 @ESTANCIA=ESTANCIA FROM #HCA

			IF @PROCEDENCIA='QX' AND @CLASE='HC'
			BEGIN
				IF DBO.FNK_VALORVARIABLE('EVOESTANCIA_PIDE')<>'NO' AND COALESCE(@ESTANCIA,'')=''
				BEGIN
					RAISERROR ('Debe seleccionar la estancia del paciente' , 16, 1);
					IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
					RETURN
				END
				IF COALESCE(@ESTANCIA,'')<>''
				BEGIN
					UPDATE HHAB SET TIPOESTANCIA=@ESTANCIA WHERE NOADMISION=@NOADMISION
					UPDATE HADM SET TIPOESTANCIA=@ESTANCIA WHERE NOADMISION=@NOADMISION
				END
			END

			IF COALESCE(@IDAFILIADO,'')='' AND @PROCEDENCIA='QX'
				SELECT @IDAFILIADO = IDAFILIADO FROM HADM WHERE NOADMISION=@NOADMISION

			-- FECHA_ACTUAL_DIL_HC=SI: solo al diligenciar (nueva HC), sin reglas por procedencia..
			IF @FECHA_ACTUAL_DIL_HC = 'SI' AND @NUEVA_HCA = 1 AND @EDITAFECHA <> 1
				SET @FECHAHCA = CONVERT(SMALLDATETIME, DBO.FNK_GETDATE())

			IF @NUEVA_HCA=1
			BEGIN
				IF @CONSECUTIVOCIT IS NULL
					SELECT @CONSECUTIVOCIT = CONSECUTIVOCIT FROM #HCA WHERE COALESCE(CONSECUTIVOCIT,'')<>''

				-- EZERPA 29/01/2021 Para evitar las historias clinicas sin planes
				SELECT @NOADMISION = COALESCE(@NOADMISION, NOADMISION) FROM #HCA

				--JEDM 20221109  CREAR CITA
				IF @PROCEDENCIA IN ('GESTIONES', 'URGENCIA', 'GESTADVA', 'GESTSER')
                    AND NOT EXISTS(SELECT 1 FROM MPL WHERE CLASEPLANTILLA=@CLASEPLANTILLA AND NOFACTURABLE=1)
				BEGIN
					IF COALESCE(@IDEMEDICA,'')='' AND COALESCE(@IDMEDICO,'')<>''
						SELECT @IDEMEDICA = MED.IDEMEDICA FROM MED WHERE IDMEDICO=@IDMEDICO

					SELECT @CONSECUTIVOCIT = NULL


					WHILE @CONSECUTIVOCIT IS NULL OR EXISTS(SELECT 1 FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT)
					BEGIN
						EXEC SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@CIT',  @CONSECUTIVOCIT OUTPUT
						SELECT @CONSECUTIVOCIT = @SEDE + REPLACE(SPACE(10 - LEN(@CONSECUTIVOCIT))+LTRIM(RTRIM(@CONSECUTIVOCIT)),SPACE(1),0)
					END

					SELECT	 @IDTERCEROGESTION	= AFI.IDADMINISTRADORA
							,@IDPLANGESTION		= AFI.IDPLAN
					FROM	AFI
					WHERE	IDAFILIADO = @IDAFILIADO_OTRO

					SELECT	@IDSERVICIOGESTION = IDSERVICIOGESTION
					FROM	MES
					WHERE	IDEMEDICA = @IDEMEDICA

					IF COALESCE(@IDSERVICIOGESTION, '') = ''
						SELECT @IDSERVICIOGESTION = 'GEST0001'

					SELECT @IDPESPECIAL = AFIPE.IDPESPECIAL
					FROM AFIPE
					WHERE IDAFILIADO = @IDAFILIADO_OTRO

                    DECLARE @IDROL VARCHAR(10)
					SELECT @CODUNG = CODUNG, @IDROL=IDROL
					FROM MPE
					WHERE IDPESPECIAL = @IDPESPECIAL

                    SET @SEDE = CASE WHEN @NIT = '900095504'
                                      THEN CASE WHEN @IDPLANGESTION NOT IN  ('C_PGPS', 'S_PGPS')
                                                THEN '02' ELSE '01'
                                           END
                                      ELSE @SEDE
                                  END
                    SET @CODUNG = CASE WHEN @NIT = '900095504'
                                      THEN CASE WHEN @IDPLANGESTION NOT IN  ('C_PGPS', 'S_PGPS')
                                                THEN '02' ELSE '01'
                                           END
                                      ELSE @CODUNG
                                  END
					INSERT INTO CIT (CONSECUTIVO, FECHA, IDMEDICO, IDAFILIADO, IDEMEDICA, IDCONTRATANTE, IDTERCEROCA, IDPLAN
						, IDSERVICIO, TIPOSOLICITUD , ATENCION, CLASEORDEN, IDAREA, CCOSTO, CODUNG, IDPESPECIAL, COPAGOPROPIO
						, PROCEDENCIA, TIPODTO, TIPOCOPAGO, IDSEDE , CUMPLIDA, ESTADO, FGENERACION, AQUIENCOBRO, TIPOAFILIADO
						, FECHASOL, FACTURABLE, USUARIO, MODALIDAD, TIPOCITA, CLASECONTRATO,CONSECUTIVOHCA,IDROL)
					SELECT
						 @CONSECUTIVOCIT	,dbo.FNK_GETDATE()		,@IDMEDICO			,@IDAFILIADO_OTRO
						,@IDEMEDICA			,@IDTERCEROGESTION		,@IDTERCEROGESTION	,@IDPLANGESTION
						,@IDSERVICIOGESTION	,'Otra'					,'Otras'			,'Modelo'
						,@IDAREA			,@CCOSTO				,@CODUNG			,@IDPESPECIAL
						,0					,@PROCEDENCIA			,'P'				,'N'
						,@SEDE				,1						,'Activa'			,dbo.FNK_GETDATE()
						,'N'				,AFI.TIPOAFILIADO		,dbo.FNK_GETDATE()	,1
						,@USUARIO			,'Virtual'				,'Cita'				,'C'
						,@CONSECUTIVO
                        ,@IDROL
					FROM AFI
					WHERE IDAFILIADO = @IDAFILIADO_OTRO
				END

				IF @PROCEDENCIA = 'GESTION'
				BEGIN
					SELECT @CONSECUTIVOCIT = NULL
					
                    EXEC SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@CIT',  @CONSECUTIVOCIT OUTPUT
					SELECT @CONSECUTIVOCIT = @SEDE + REPLACE(SPACE(10 - LEN(@CONSECUTIVOCIT))+LTRIM(RTRIM(@CONSECUTIVOCIT)),SPACE(1),0)

					SELECT	 @IDTERCEROGESTION	= AFI.IDADMINISTRADORA
							,@IDPLANGESTION		= AFI.IDPLAN
					FROM AFI
					WHERE IDAFILIADO = @IDAFILIADO

					SELECT   @IDPESPECIAL		= IDPESPECIAL
							,@IDSERVICIO_PROT	= IDSERVICIO
					FROM	AFIPROT
					WHERE	ID = @IDGESTION

					SELECT @CODUNG = CODUNG
					FROM MPE
					WHERE IDPESPECIAL = @IDPESPECIAL

					INSERT INTO CIT (CONSECUTIVO, FECHA, IDMEDICO, IDAFILIADO, IDEMEDICA, IDCONTRATANTE, IDTERCEROCA, IDPLAN
						, IDSERVICIO, TIPOSOLICITUD, ATENCION, CLASEORDEN, IDAREA, CCOSTO, CODUNG, IDPESPECIAL, COPAGOPROPIO
						, PROCEDENCIA, TIPODTO, TIPOCOPAGO, IDSEDE, CUMPLIDA, ESTADO, FGENERACION
						, AQUIENCOBRO, TIPOAFILIADO, FECHASOL, USUARIO, FACTURABLE, MODALIDAD, TIPOCITA
						, CLASECONTRATO, CONSECUTIVOHCA)
					SELECT	@CONSECUTIVOCIT		,dbo.FNK_GETDATE()		,@IDMEDICO				,@IDAFILIADO
							,@IDEMEDICA			,@IDTERCEROGESTION		,@IDTERCEROGESTION		,@IDPLANGESTION
							,@IDSERVICIO_PROT	,'Otra'					,'Otras'				,'Modelo'
							,''					,''						,@CODUNG				,@IDPESPECIAL
							,0					,@PROCEDENCIA			,'P'					,'N'
							,@SEDE				,1						,'Activa'				,dbo.FNK_GETDATE()
							,'N'				,a.TIPOAFILIADO			,dbo.FNK_GETDATE()		,@USUARIO
							,1					,'Virtual'				,'Cita'					,'C'
							,@CONSECUTIVO
					FROM AFI a
					WHERE a.IDAFILIADO = @IDAFILIADO
				END

				SELECT @IDPLAN_NUEVAHCA = CASE WHEN COALESCE(IDPLAN,'')='COVID19' THEN COALESCE((SELECT TOP 1 IDPLAN FROM CIT WHERE CONSECUTIVO=#HCA.CONSECUTIVOCIT), @IDPLAN_HADM) ELSE COALESCE(IDPLAN,@IDPLAN,@IDPLAN_HADM) END FROM #HCA

				IF COALESCE(@IDPLAN_NUEVAHCA, '') = ''
					SELECT @IDPLAN_NUEVAHCA = NULLIF(LTRIM(RTRIM(IDPLAN)), '') FROM HADM WHERE NOADMISION = @NOADMISION

				IF COALESCE(@IDPLAN_NUEVAHCA, '') = ''
					SELECT TOP 1 @IDPLAN_NUEVAHCA = NULLIF(LTRIM(RTRIM(IDPLAN)), '')
					FROM CIT
					WHERE CONSECUTIVO = COALESCE(@CONSECUTIVOCIT, @NOADMISION)

				IF COALESCE(@IDPLAN_NUEVAHCA, '') = '' AND COALESCE(@NOADMISION, '') <> ''
					SELECT TOP 1 @IDPLAN_NUEVAHCA = NULLIF(LTRIM(RTRIM(IDPLAN)), '')
					FROM CIT
					WHERE NOADMISION = @NOADMISION
					ORDER BY FECHA DESC

				IF COALESCE(@IDPLAN_NUEVAHCA, '') = ''
					SELECT @IDPLAN_NUEVAHCA = NULLIF(LTRIM(RTRIM(IDPLAN)), '')
					FROM AFI
					WHERE IDAFILIADO = COALESCE(@IDAFILIADO, (SELECT TOP 1 IDAFILIADO FROM #HCA))

				IF COALESCE(@IDPLAN_NUEVAHCA, '') = '' AND @PROCEDENCIA <> 'LX'
				BEGIN
					RAISERROR('No fue posible determinar IDPLAN para guardar la historia clinica.',16,1)
					IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
					RETURN
				END
				
                IF @PROCEDENCIA IN ( 'AUDITEXT','GESTIONES','URGENCIA','GESTADVA','GESTSER')
                BEGIN
					SELECT @IDAFILIADO = @IDAFILIADO_OTRO
                END

				IF COALESCE(@NOADMISION, '') <> ''
				BEGIN
					EXEC DBO.SPQ_TRAE_TERPAGADOR @NOADMISION = @NOADMISION, @IDTERCERO = @IDTERCERO_SOAT OUTPUT, @IDPLAN = @IDPLAN_SOAT OUTPUT;
				END

				INSERT INTO HCA (CONSECUTIVO,ITEMRED,CLASEPLANTILLA,AMBITO,FECHA,NOADMISION,IDAFILIADO,TIPODX
								,IDDX,IDMEDICO,IDMEDICODILIGENCIA,PROCEDENCIA,ALTA,CLASE,IDAREA,CCOSTO,USUARIO,TAS,TAD
								,FC,FR,TEMP,TALLA,PULSO,PESO,GLASGOW,TIPOGLASGOW,HIDRATACION,TAM,DIURESIS,CONSECUTIVOCIT
								,IDPLAN,MED_ESPEC,CODAZUL,COVID,CNSWEB,CHECK1,CHECK2,CHECK3,NECPAL,N_S1,N_S2,N_S3,N_S4,N_S5,N_S6
								,NOTA_ACLARA,CNSHCA_NOTA,IDMEDICOESP,REVISAESP,REVISADO
								,GRUPAL,COPIADA,CONSECUTIVOCOPIA,EDAD,IDEMEDICA,IDEMEDICAESP, ENEPICRISIS, TIPOPM, ESTANCIA
								,FECHA_DILIGENCIA,FECHA_REGISTRO, FECHASINTOMAS, FECHACONFIRMACION, ARTICULACIONES, TOPICO
								,IDTERCERO_SOAT, IDPLAN_SOAT
								)
				SELECT @CONSECUTIVO CONSECUTIVO	,@ITEMRED ITEMRED	,CLASEPLANTILLA
					,@AMBITO AMBITO				,@FECHAHCA FECHA	,@NOADMISION
					,COALESCE(@IDAFILIADO,IDAFILIADO)				,TIPODX
					,IDDX						,@IDMEDICO IDMEDICO
					,@IDMEDICO IDMEDICODILIGENCIA					,@PROCEDENCIA PROCEDENCIA
					,@DAALTA ALTA				,@CLASE CLASE		,@IDAREA IDAREA
					,@CCOSTO CCOSTO				,@USUARIO USUARIO	,TAS
					,TAD						,FC					,FR
					,TEMP						,TALLA				,PULSO
					,PESO						,GLASGOW			,TIPOGLASGOW
					,HIDRATACION				,TAM				,DIURESIS
					-- Preferir @CONSECUTIVOCIT (puede ser cita clonada PyP/morbilidad); no depender de @IDPESPECIAL
					,CASE WHEN @PROCEDENCIA IN ('GESTIONES','URGENCIA','GESTADVA','GESTION','GESTSER') THEN @CONSECUTIVOCIT
						 ELSE COALESCE(NULLIF(LTRIM(RTRIM(@CONSECUTIVOCIT)), ''), @CONSECUTIVOCIT_ORIGEN, CONSECUTIVOCIT)
					 END	,@IDPLAN_NUEVAHCA
					,COALESCE((SELECT TOP 1 IDEMEDICA FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT), MED_ESPEC, @IDEMEDICA)		,COALESCE(CODAZUL,0)
					,COALESCE(COVID,0)			,@CNSWEB			,CHECK1
					,CHECK2						,CHECK3				,NECPAL
					,S1,S2,S3,S4,S5,S6
					,CASE @ESNOTAACLARATORIA WHEN 1 THEN 1 ELSE 0 END
					,@NOTACNSORI
					,IDMEDICOESP
					,REVISAESP
					,REVISADO=IIF(DBO.FNK_VALORVARIABLE('AVAL_AUTOMATICO')='SI',1,0) 
					,0
					,IIF(@CONSECUTIVO_HCA_ORIGEN IS NULL, 0, 1)
					,@CONSECUTIVO_HCA_ORIGEN
					,#HCA.EDAD
					, --COALESCE((SELECT TOP 1 IDEMEDICA FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT),@IDEMEDICA) -- JCLLAMAS
					CASE WHEN @PROCEDENCIA <> 'IPS' AND COALESCE(@NEWIDEMEDICA, '') <> '' THEN @NEWIDEMEDICA
						 ELSE COALESCE((SELECT TOP 1 IDEMEDICA FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT), @IDEMEDICA)
					END					
					,COALESCE((SELECT TOP 1 IDEMEDICA FROM CIT WHERE CONSECUTIVO=@CONSECUTIVOCIT),(SELECT IDEMEDICA FROM MED WHERE IDMEDICO=IDMEDICOESP))
					,#HCA.ENEPICRISIS
					,IIF(dbo.FNK_VALORVARIABLE('PLANDEMANEJO_AUT')='SI','Automatico','Normal')
					,@ESTANCIA
					,COALESCE(FECHA_DILIGENCIA, GETDATE())
					,GETDATE()
                    ,TRY_CAST(#HCA.FECHASINTOMAS AS DATE)
                    ,TRY_CAST(#HCA.FECHACONFIRMACION AS DATE)
                    ,ARTICULACIONES, @TOPICO_SELECCIONADOS, @IDTERCERO_SOAT, @IDPLAN_SOAT
				FROM #HCA

                IF EXISTS (SELECT 1 FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT AND PROCEDENCIA = 'HADMSER')
                BEGIN
                   UPDATE HCA SET PROCEDENCIA = 'QX' WHERE CONSECUTIVOCIT = @CONSECUTIVOCIT
                END
			END
			ELSE
  			BEGIN
				SELECT @IDMEDICO_AUX = IDMEDICO FROM USUSU WHERE USUARIO=@USUARIO

				IF COALESCE(@IDPLAN_NUEVAHCA, '') = ''
					SELECT @IDPLAN_NUEVAHCA = NULLIF(LTRIM(RTRIM(IDPLAN)), '') FROM HCA WHERE CONSECUTIVO = @CONSECUTIVOHCA

				IF COALESCE(@IDPLAN_NUEVAHCA, '') = ''
					SELECT @IDPLAN_NUEVAHCA = NULLIF(LTRIM(RTRIM(IDPLAN)), '') FROM HADM WHERE NOADMISION = @NOADMISION

				IF COALESCE(@IDPLAN_NUEVAHCA, '') = ''
					SELECT TOP 1 @IDPLAN_NUEVAHCA = NULLIF(LTRIM(RTRIM(IDPLAN)), '')
					FROM CIT
					WHERE CONSECUTIVO = COALESCE(@CONSECUTIVOCIT, @NOADMISION)

				IF COALESCE(@IDPLAN_NUEVAHCA, '') = ''
					SELECT @IDPLAN_NUEVAHCA = NULLIF(LTRIM(RTRIM(IDPLAN)), '')
					FROM AFI
					WHERE IDAFILIADO = COALESCE(@IDAFILIADO, (SELECT TOP 1 IDAFILIADO FROM #HCA))

				IF COALESCE(@IDPLAN_NUEVAHCA, '') = ''
				BEGIN
					RAISERROR('No fue posible determinar IDPLAN para actualizar la historia clinica.',16,1)
					IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
					RETURN
				END

				IF COALESCE(@NOADMISION, '') <> '' AND @IDTERCERO_SOAT IS NULL
				BEGIN
					EXEC DBO.SPQ_TRAE_TERPAGADOR @NOADMISION = @NOADMISION, @IDTERCERO = @IDTERCERO_SOAT OUTPUT, @IDPLAN = @IDPLAN_SOAT OUTPUT;
				END

				UPDATE HCA SET
					TIPODX = #HCA.TIPODX	,IDDX = #HCA.IDDX		,IDMEDICO = CASE WHEN @AUDITORIA = 1 THEN @IDMEDICO ELSE HCA.IDMEDICO END
					,USUARIO = @USUARIO		,TAS = #HCA.TAS			,TAD = #HCA.TAD			,FC = #HCA.FC
					,FR = #HCA.FR			,TEMP = #HCA.TEMP		,TALLA = #HCA.TALLA		,PULSO = #HCA.PULSO
					,PESO = #HCA.PESO		,GLASGOW = #HCA.GLASGOW ,TIPOGLASGOW = #HCA.TIPOGLASGOW
					,HIDRATACION = #HCA.HIDRATACION					,TAM = #HCA.TAM
					,DIURESIS = #HCA.DIURESIS
					,CODAZUL = COALESCE(#HCA.CODAZUL,0)
					,COVID = COALESCE(#HCA.COVID,0)
					,FECHA = CASE WHEN @EDITAFECHA=1 THEN @FECHAHCA ELSE FECHA END
					,IDMEDICOESP=#HCA.IDMEDICOESP
					,REVISAESP=#HCA.REVISAESP
					,ESTANCIA=@ESTANCIA
					,REVISADO =
						CASE WHEN COALESCE(#HCA.REVISAESP,0) = 0 THEN 0
						ELSE CASE WHEN #HCA.IDMEDICOESP = @IDMEDICO_AUX THEN 1 ELSE 0 END
						END
					,DX1=NULL, DX2=NULL, DX3=NULL, DX4=NULL
                    ,FECHASINTOMAS=TRY_CAST(#HCA.FECHASINTOMAS AS DATE)
                    ,FECHACONFIRMACION=TRY_CAST(#HCA.FECHACONFIRMACION AS DATE)
                    ,ARTICULACIONES = #HCA.ARTICULACIONES
					,IDPLAN = COALESCE(NULLIF(HCA.IDPLAN,''), @IDPLAN_NUEVAHCA)
					,CNSWEB = COALESCE(NULLIF(HCA.CNSWEB,''), @CNSWEB)
					,IDTERCERO_SOAT = @IDTERCERO_SOAT
					,IDPLAN_SOAT = @IDPLAN_SOAT
				FROM HCA INNER JOIN #HCA ON HCA.CONSECUTIVO = @CONSECUTIVOHCA
			END

			IF EXISTS(
				SELECT 1
				FROM HCA
				WHERE CONSECUTIVO = @CONSECUTIVO
				AND (COALESCE(CNSWEB, '') = '' OR (COALESCE(IDPLAN, '') = '' AND @PROCEDENCIA<> 'LX'))
			)
			BEGIN
				RAISERROR('La historia clinica no puede quedar sin CNSWEB o IDPLAN.',16,1)
				IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
				RETURN
			END

	        IF @PROCEDENCIA='IPS'
	        BEGIN
			    UPDATE HCA SET REVISADO=1, REVISAESP=1, IDMEDICOESP=@IDMEDICO_GEN
                WHERE CONSECUTIVO=@CONSECUTIVO AND COALESCE(@IDMEDICO_GEN,'')<>'' AND @IDMEDICO_GEN<>@IDMEDICO_CIT
                    AND EXISTS (SELECT 1 FROM MED WHERE IDMEDICO=@IDMEDICO_GEN) AND @IDMEDICO_GEN=@IDMEDICO

                IF COALESCE(@IDMEDICO_GEN,'')<>'' AND COALESCE(@IDMEDICO_CIT,'')<>'' AND @IDMEDICO_GEN<>@IDMEDICO_CIT
                BEGIN
                    UPDATE HCA SET IDMEDICO=@IDMEDICO_CIT WHERE CONSECUTIVO=@CONSECUTIVO
                END
                UPDATE CIT SET ENUSO=0, USUARIOENUSO=NULL WHERE USUARIOENUSO=@USUARIO
            END
   
			-- Diagnosticos relacionados
			BEGIN
				DECLARE @HCADX_TARGET VARCHAR(20) = @CONSECUTIVO
				DECLARE @APLICAR_SYNC_MDX BIT = CASE WHEN @NUEVA_HCA = 0 OR COALESCE(@SYNC_MDX, 0) = 1 THEN 1 ELSE 0 END

				IF EXISTS(SELECT 1 FROM #MDX)
				BEGIN
					IF @APLICAR_SYNC_MDX = 1
					BEGIN
						DELETE FROM HCADX WHERE CONSECUTIVO = @HCADX_TARGET
						AND IDDX NOT IN (SELECT IDDX FROM #MDX)
					END

					INSERT INTO HCADX (CONSECUTIVO,IDDX,TIPO,ESTADO,TIPODX, FECHASINTOMAS, FECHACONFIRMACION)
					SELECT @HCADX_TARGET,MDX.IDDX,'Relacionado','Activo',#MDX.TIPODX, TRY_CAST(#MDX.FECHASINTOMAS AS DATE), TRY_CAST(#MDX.FECHACONFIRMACION AS DATE)
					FROM #MDX
					INNER JOIN MDX ON MDX.IDDX = #MDX.IDDX
					WHERE MDX.IDDX NOT IN (SELECT IDDX FROM HCADX WHERE CONSECUTIVO = @HCADX_TARGET)

                    IF COALESCE(DBO.FNK_VALORVARIABLE('IDALERTA_DXAUTO'),'')<>'' AND EXISTS (SELECT 1 FROM TALR WHERE IDALERTA=DBO.FNK_VALORVARIABLE('IDALERTA_DXAUTO'))
                    BEGIN
                        DECLARE CUR_ALERDX CURSOR FOR
                        SELECT SMSALERTA FROM MDX
                        WHERE IDDX IN (SELECT IDDX FROM #MDX UNION ALL SELECT @IDDX) AND GENALERTA=1 AND TRIM(COALESCE(SMSALERTA,''))<>''

                        OPEN CUR_ALERDX
                        FETCH NEXT FROM CUR_ALERDX INTO @MENSAJE_ALERTA
                        WHILE @@FETCH_STATUS=0
                        BEGIN

					        EXEC SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@ALR',  @CNSALR OUTPUT
					        SELECT @CNSALR = @SEDE + REPLACE(SPACE(8 - LEN(@CNSALR))+LTRIM(RTRIM(@CNSALR)),SPACE(1),0)

                            INSERT INTO ALR (CONSECUTIVO, IDAFILIADO, IDALERTA, FECHAALERTA, FECHAAVISO, OBS, IDFUNCIONARIO, CLASE, COLOR, CNSWEB, CONSECUTIVOHCA, PROCEDENCIA)
                            SELECT @CNSALR, @IDAFILIADO, TALR.IDALERTA, GETDATE(), GETDATE(), @MENSAJE_ALERTA, @USUARIO, TALR.CLASEALERTA,TALR.COLOR, @CNSWEB, @CONSECUTIVO,'HCA'
                            FROM TALR
                            WHERE TALR.IDALERTA=DBO.FNK_VALORVARIABLE('IDALERTA_DXAUTO')

                            FETCH NEXT FROM CUR_ALERDX INTO @MENSAJE_ALERTA
                        END
                        CLOSE CUR_ALERDX
                        DEALLOCATE CUR_ALERDX
                    END

					-- Incluir los diagnosticos elegidos en la orden (clínico o UNIRS)
                    IF ISNULL(@AUDITORIA,0)=0
                    BEGIN
					    SELECT @AUX = HCATD FROM #HCA
					    INSERT INTO HCADX (CONSECUTIVO,IDDX,TIPO,ESTADO,TIPODX)
					    SELECT @HCADX_TARGET, dx.IDDX_VAL, 'Relacionado', 'Activo', 'Definitivo'
					    FROM OPENJSON(@AUX) WITH (
						    IDDX_ORD VARCHAR(10) '$.IDDX',
						    IDDX_UNIRS VARCHAR(10) '$.IDDXUNIRS.IDDX'
					    ) j
					    CROSS APPLY (
						    SELECT COALESCE(NULLIF(RTRIM(j.IDDX_UNIRS), ''), NULLIF(RTRIM(j.IDDX_ORD), '')) AS IDDX_VAL
					    ) dx
					    WHERE dx.IDDX_VAL IS NOT NULL
					    AND dx.IDDX_VAL NOT IN (
						    SELECT IDDX FROM HCADX WHERE CONSECUTIVO = @HCADX_TARGET
						    UNION ALL
						    SELECT IDDX FROM HCA WHERE CONSECUTIVO = @HCADX_TARGET
					    )
					    GROUP BY dx.IDDX_VAL
                    END

					-- Set-based: asignar DX1-DX4 desde HCADX (reemplaza cursor)
					;WITH RankedDX AS (
						SELECT IDDX, ROW_NUMBER() OVER (ORDER BY ITEM) AS rn
						FROM HCADX
						WHERE CONSECUTIVO = @HCADX_TARGET
					)
					UPDATE HCA SET
						DX1 = COALESCE(NULLIF(RTRIM(DX1),''), (SELECT IDDX FROM RankedDX WHERE rn=1)),
						DX2 = COALESCE(NULLIF(RTRIM(DX2),''), (SELECT IDDX FROM RankedDX WHERE rn=2)),
						DX3 = COALESCE(NULLIF(RTRIM(DX3),''), (SELECT IDDX FROM RankedDX WHERE rn=3)),
						DX4 = COALESCE(NULLIF(RTRIM(DX4),''), (SELECT IDDX FROM RankedDX WHERE rn=4))
					WHERE CONSECUTIVO = @HCADX_TARGET
				END
			END

			-- Dar de alta cuando son admisiones
            IF @DAALTA > 0
			BEGIN
				UPDATE HADM SET CERRADA =2, IDMEDICOALTA = @IDMEDICOALTA, USUALTAMED =@USUARIO
					,DXINGRESO		= @DXINGRESO
					,DXEGRESO		= @DXEGRESO
					,ESTADOPSALIDA	= @ESTADOPSALIDA
					,IDMEDICOTRA	= @IDMEDICOALTA   --OJO REVISAR JEDM
					,CAUSABMUERTE	= @CAUSABMUERTE
					,DXSALIDA1		= @DXSALIDA1
					,DXSALIDA2		= @DXSALIDA2
					,DXSALIDA3		= @DXSALIDA3
					,DESTINO		= @DESTINO
					,CCOSTO_ALTA	= @CCOSTO_ALTA
					,FECHAALTAMED	= COALESCE(CONVERT(DATETIME, @FECHAALTA),DBO.FNK_GETDATE())
					,ACTADEFUNCION	= @ACTADEFUNCION
				WHERE  NOADMISION = @NOADMISION

				---tipo de admision consulta prioritaria, se da alta med y enfermeria
				SELECT @TIPOADM= TIPOADM, @HABCAMA =HABCAMA  FROM HADM WHERE NOADMISION= @NOADMISION
				IF @TIPOADM = DBO.FNK_VALORVARIABLE('ID_ADM_PRIORITARIA') AND @PROCEDENCIA = 'QX'
				BEGIN
					UPDATE HADM SET FECHAALTAMED = COALESCE(CONVERT(DATETIME, @FECHAALTA),DBO.FNK_GETDATE()), CERRADA= '3', FECHAALTAENF = COALESCE(CONVERT(DATETIME, @FECHAALTA),DBO.FNK_GETDATE())   
					WHERE NOADMISION = @NOADMISION
					UPDATE HHAB SET ESTADOHAB = 'Libre',NOADMISION=NULL, IDAFILIADO=NULL WHERE HABCAMA= @HABCAMA
				END

				IF DBO.FNK_VALORVARIABLE('EPI_MEDICOTRATANTE')='SI'
					UPDATE HCA SET IDMEDICODILIGENCIA = @IDMEDICOALTA WHERE NOADMISION = @NOADMISION AND CLASEPLANTILLA=DBO.FNK_VALORVARIABLE('HCPLANTILLAEPI')

				IF DBO.FNK_VALORVARIABLE('LIBCAMAALTAMED')='SI'
					UPDATE HHAB SET ESTADOHAB='Libre',NOADMISION=NULL,IDAFILIADO=NULL WHERE NOADMISION=@NOADMISION

				IF (SELECT COUNT(1) FROM HCA INNER JOIN HCATD ON HCA.CONSECUTIVO=HCATD.CONSECUTIVO WHERE HCA.PROCEDENCIA='QX' AND HCA.NOADMISION=@NOADMISION)<=0 AND DBO.FNK_VALORVARIABLE('ALTAMEDYALTAENFDEUNA')='SI'
				BEGIN
					UPDATE HADM SET CERRADA =3, IDMEDICOALTA = @IDMEDICOALTA, IDUSUARIOALTAENF=@USUARIO,
						FECHAALTAENF  = COALESCE(CONVERT(DATETIME, @FECHAALTA),DBO.FNK_GETDATE())
					WHERE NOADMISION=@NOADMISION

					IF DBO.FNK_VALORVARIABLE('LIBCAMAALTAENF')='SI' OR DBO.FNK_VALORVARIABLE('LIBCAMANOTACIERRE')=''
						UPDATE HHAB SET ESTADOHAB='Libre',NOADMISION=NULL,IDAFILIADO=NULL WHERE NOADMISION=@NOADMISION
				END
				SELECT TOP 1 @CMD=DB_LOG FROM BDIX..CIA WHERE DB_BASE=DB_NAME()
				EXEC SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@LOG',  @CNSLOG OUTPUT
				SELECT @CNSLOG = @SEDE + REPLACE(SPACE(8 - LEN(@CNSLOG))+LTRIM(RTRIM(@CNSLOG)),SPACE(1),0)

				SELECT @CMD='INSERT INTO '+@CMD+'..USLOG (CNSLOG, COMPANIA, NOADMISION, PROCESO, REQUEST, REFERENCIA, USUARIO, FECHA, SYS_ComputerName, TABLA)
							SELECT '''+@CNSLOG+''', '''+@COMPANIA+''', '''+@NOADMISION+''', ''ALTA'',''PROCESS'', ''Alta medica desde HC'', '''+@USUARIO+''', GETDATE(), '''+@SYS_ComputerName+''', ''HADM'''
				EXEC (@CMD)
			END
			
            -- Antecedentes para los que no son RIAS
			IF (SELECT COALESCE(@RIAS,'') )= ''
			BEGIN
				IF @NUEVA_HCA=1 AND NOT EXISTS (
						SELECT 1
						FROM HCAAP
						WHERE IDAFILIADO = @IDAFILIADO
						)
					AND @IDAFILIADO IS NOT NULL
				BEGIN
					EXEC SPK_CREA_ANTECEDENTESHC @IDAFILIADO
				END
				SELECT @AUX = TGANT
				FROM #HCA

                SELECT *
				INTO #HCAAP
				FROM OPENJSON(@AUX) WITH (
					ANTECEDENTE VARCHAR(MAX) '$.TEXTO'
					,CNSTGANTOP VARCHAR(20) '$.CNSTGANTOP'
					,CNSTGANT VARCHAR(20) '$.CNSTGANT'
					,CNSTGANTOP2 VARCHAR(50) '$.CNSTGANTOP2'
					,NUMERICO VARCHAR(20) '$.NUMERICO'
					,FECHAHCAAP VARCHAR(10) '$.FECHA'
					,FAM_PRIMER_NOMBRE VARCHAR(100) '$.FAMILIAR.PRIMER_NOMBRE'
					,FAM_SEGUNDO_NOMBRE VARCHAR(100) '$.FAMILIAR.SEGUNDO_NOMBRE'
					,FAM_PRIMER_APELLIDO VARCHAR(100) '$.FAMILIAR.PRIMER_APELLIDO'
					,FAM_SEGUNDO_APELLIDO VARCHAR(100) '$.FAMILIAR.SEGUNDO_APELLIDO'
					,FAM_GENERO VARCHAR(20) '$.FAMILIAR.GENERO'
					,FAM_CIE VARCHAR(20) '$.FAMILIAR.CIE.cie'
					,FAM_CIEVERSION VARCHAR(200) '$.FAMILIAR.CIE.cieversion'
					,FAM_PARENTESCO VARCHAR(50) '$.FAMILIAR.PARENTESCO'
					,FAM_STATUS VARCHAR(20) '$.FAMILIAR.STATUS'
					,STATUS_ALERGIA VARCHAR(50) '$.STATUS_ALERGIA'
					-- AGREGAR ESTOS CAMPOS PARA PACIENTE:
					,PAC_CIE VARCHAR(20) '$.PACIENTE.CIE.cie'
					,PAC_CIEVERSION VARCHAR(200) '$.PACIENTE.CIE.cieversion'
				)


				DECLARE HCAAPCUR CURSOR
				FOR
					 SELECT ANTECEDENTE,CNSTGANTOP,CNSTGANT,CNSTGANTOP2, NUMERICO,FECHAHCAAP
					,FAM_PRIMER_NOMBRE,FAM_SEGUNDO_NOMBRE,FAM_PRIMER_APELLIDO,FAM_SEGUNDO_APELLIDO
					,FAM_GENERO,FAM_CIE,FAM_CIEVERSION,FAM_PARENTESCO, FAM_STATUS, STATUS_ALERGIA
					,PAC_CIE, PAC_CIEVERSION  
					FROM #HCAAP

				OPEN HCAAPCUR
				FETCH NEXT
				FROM HCAAPCUR
				INTO @ANTECEDENTE,@CNSTGANTOP,@CNSTGANT,@CNSTGANTOP2,@NUMERICO,@FECHAHCAAP
				,@FAM_PRIMER_NOMBRE,@FAM_SEGUNDO_NOMBRE,@FAM_PRIMER_APELLIDO,@FAM_SEGUNDO_APELLIDO
				,@FAM_GENERO,@FAM_CIE,@FAM_CIEVERSION,@FAM_PARENTESCO, @FAM_STATUS, @STATUS_ALERGIA,@PAC_CIE, @PAC_CIEVERSION 

				WHILE @@FETCH_STATUS = 0
				BEGIN
					SELECT @CNSHCAAP = CNSHCAAP
					FROM HCAAP
					WHERE IDAFILIADO = @IDAFILIADO
						AND CNSTGANT = @CNSTGANT

					IF COALESCE(@CNSHCAAP, '')=''
					BEGIN
						EXEC SPK_CREA_ANTECEDENTESHC @IDAFILIADO

						SELECT @CNSHCAAP = CNSHCAAP
						FROM HCAAP
						WHERE IDAFILIADO = @IDAFILIADO
							AND CNSTGANT = @CNSTGANT
					END

					IF @CNSTGANT IS NOT NULL AND @CNSHCAAP IS NOT NULL
					BEGIN
						INSERT INTO HCAAPD (
							CNSHCAAP,
							FINGRESO,
							CONSECUTIVOHCA,
							ANTECEDENTE,
							TIPO_ALERGIA,
							NUMERICO,
							FECHA,
							CNSTGANTOP,
							ORDEN,
							PRIMER_NOMBRE,
							SEGUNDO_NOMBRE,
							PRIMER_APELLIDO,
							SEGUNDO_APELLIDO,
							GENERO,
							CIE,
							CIEVERSION,
							PARENTESCO,
							STATUS,
							STATUS_ALERGIA
						)
						VALUES (
							@CNSHCAAP,
							COALESCE(@FECHA, CURRENT_TIMESTAMP),
							@CONSECUTIVO,
							@ANTECEDENTE,
							@CNSTGANTOP2,
							@NUMERICO,
							@FECHAHCAAP,
							@CNSTGANTOP,
							0,
							@FAM_PRIMER_NOMBRE,
							@FAM_SEGUNDO_NOMBRE,
							@FAM_PRIMER_APELLIDO,
							@FAM_SEGUNDO_APELLIDO,
							@FAM_GENERO,
							COALESCE(@FAM_CIE, @PAC_CIE),
							COALESCE(@FAM_CIEVERSION, @PAC_CIEVERSION),
							@FAM_PARENTESCO,
							@FAM_STATUS,
							@STATUS_ALERGIA
						)
					END

					FETCH NEXT
					FROM HCAAPCUR
					INTO @ANTECEDENTE,@CNSTGANTOP,@CNSTGANT,@CNSTGANTOP2,@NUMERICO,@FECHAHCAAP
					,@FAM_PRIMER_NOMBRE,@FAM_SEGUNDO_NOMBRE,@FAM_PRIMER_APELLIDO,@FAM_SEGUNDO_APELLIDO
					,@FAM_GENERO,@FAM_CIE,@FAM_CIEVERSION,@FAM_PARENTESCO, @FAM_STATUS, @STATUS_ALERGIA,@PAC_CIE, @PAC_CIEVERSION 
				END

				CLOSE HCAAPCUR
				DEALLOCATE HCAAPCUR

				DECLARE @IDALERTA_ALERGIA VARCHAR(10)
				DECLARE @INTENTOS INT = 0
				SELECT @IDALERTA_ALERGIA = DBO.FNK_VALORVARIABLE('IDTIPOALERTA_ALERGIA')

				IF COALESCE(@IDALERTA_ALERGIA, '') <> '' 
				   AND EXISTS (SELECT 1 FROM TALR WHERE IDALERTA = @IDALERTA_ALERGIA)
				BEGIN
					DECLARE ALER_CUR CURSOR FOR
						SELECT 
							HCAAPD.ANTECEDENTE,
							HCAAPD.TIPO_ALERGIA AS CNSTGANTOP2,
							HCAAPD.STATUS_ALERGIA,
							TGANT.NOMBRE AS NOMBRE_ANTECEDENTE,
							CASE 
								WHEN HCAAPD.TIPO_ALERGIA = 'medicamento' THEN 'Medicamento'
								WHEN HCAAPD.TIPO_ALERGIA = 'alimento' THEN 'Alimento'
								WHEN HCAAPD.TIPO_ALERGIA = 'sustancia_ambiente' THEN 'Sustancia del ambiente'
								WHEN HCAAPD.TIPO_ALERGIA = 'sustancia_piel' THEN 'Sustancia que entran en contacto con la piel'
								WHEN HCAAPD.TIPO_ALERGIA = 'picadura_insectos' THEN 'Picadura de insectos'
								WHEN HCAAPD.TIPO_ALERGIA = 'otra' THEN 'Otra'
								ELSE HCAAPD.TIPO_ALERGIA
							END AS DESCRIPCION_TIPO_ALERGIA
						FROM HCAAPD
						INNER JOIN HCAAP ON HCAAPD.CNSHCAAP = HCAAP.CNSHCAAP
						INNER JOIN TGANT ON HCAAP.CNSTGANT = TGANT.CNSTGANT
						WHERE HCAAP.IDAFILIADO = @IDAFILIADO
							AND HCAAPD.CONSECUTIVOHCA = @CONSECUTIVO
							AND HCAAPD.STATUS_ALERGIA = 'Activo'
							AND HCAAPD.TIPO_ALERGIA IS NOT NULL
							-- Verificar que no exista ya una alerta activa para esta alergia en esta HCA
							AND NOT EXISTS (
								SELECT 1 FROM ALR 
								WHERE ALR.IDAFILIADO = @IDAFILIADO 
									AND ALR.IDALERTA = @IDALERTA_ALERGIA
									AND ALR.CONSECUTIVOHCA = @CONSECUTIVO
									AND ALR.OBS LIKE '%' + HCAAPD.TIPO_ALERGIA + '%'
									AND COALESCE(ALR.ESTADO,'') <> 'Cerrado'
							)

					OPEN ALER_CUR
					FETCH NEXT FROM ALER_CUR INTO @ANTECEDENTE_ALER, @TIPO_ALERGIA_ALER, @STATUS_ALERGIA_ALER, @NOMBRE_ANTECEDENTE_ALER, @DESC_TIPO_ALERGIA_ALER

					WHILE @@FETCH_STATUS = 0
					BEGIN
						IF NOT EXISTS (
							SELECT 1 FROM ALR 
							WHERE ALR.IDAFILIADO = @IDAFILIADO 
								AND ALR.IDALERTA = @IDALERTA_ALERGIA
								AND ALR.CONSECUTIVOHCA = @CONSECUTIVO
								AND ALR.OBS LIKE '%' + @TIPO_ALERGIA_ALER + '%'
								AND COALESCE(ALR.ESTADO,'') <> 'Cerrado'
						)
						BEGIN
							SET @INTENTOS = 0
							SET @CNSALR = NULL
            
							WHILE (@CNSALR IS NULL OR EXISTS(SELECT 1 FROM ALR WHERE CONSECUTIVO = @CNSALR)) AND @INTENTOS < 10
							BEGIN
								EXEC SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@ALR', @CNSALR OUTPUT
								SELECT @CNSALR = @SEDE + REPLACE(SPACE(8 - LEN(@CNSALR))+LTRIM(RTRIM(@CNSALR)),SPACE(1),0)
								SET @INTENTOS = @INTENTOS + 1
							END
            
							IF EXISTS(SELECT 1 FROM ALR WHERE CONSECUTIVO = @CNSALR)
							BEGIN
								FETCH NEXT FROM ALER_CUR INTO @ANTECEDENTE_ALER, @TIPO_ALERGIA_ALER, @STATUS_ALERGIA_ALER, @NOMBRE_ANTECEDENTE_ALER, @DESC_TIPO_ALERGIA_ALER
								CONTINUE
							END

						SELECT @MENSAJE_ALERTA_ALER = 'Paciente presenta alergia activa: ' + 
							COALESCE(@NOMBRE_ANTECEDENTE_ALER, 'Alergia') + 
							CASE 
								WHEN COALESCE(@DESC_TIPO_ALERGIA_ALER,'') <> '' 
								THEN ' - Tipo: ' + @DESC_TIPO_ALERGIA_ALER 
								ELSE '' 
							END +
							CASE 
								WHEN COALESCE(@ANTECEDENTE_ALER,'') <> '' 
								THEN '. Detalle: ' + LEFT(@ANTECEDENTE_ALER, 200)
								ELSE '' 
							END

						-- Insertar la alerta usando el IDALERTA obtenido de la variable IDTIPOALERTA_ALERGIA
						INSERT INTO ALR (
							CONSECUTIVO, 
							IDAFILIADO, 
							IDALERTA, 
							FECHAALERTA, 
							FECHALIMITE, 
							FECHAAVISO, 
							OBS, 
							IDFUNCIONARIO, 
							CLASE, 
							IDSERVICIO,
							CANTIDAD,
							CARGADAS,
							ORDEN,
							COLOR, 
							CNSWEB, 
							CONSECUTIVOHCA, 
							PROCEDENCIA,
							CONSECUTIVOPROC,
							ESTADO,
							USUARIOCIERRA
						)
						SELECT 
							@CNSALR, 
							@IDAFILIADO, 
							TALR.IDALERTA, 
							GETDATE(), 
							GETDATE(), 
							GETDATE(), 
							@MENSAJE_ALERTA_ALER, 
							@USUARIO, 
							TALR.CLASEALERTA, 
							NULL, 
							NULL, 
							NULL, 
							TALR.ORDEN,
							TALR.COLOR, 
							@CNSWEB, 
							@CONSECUTIVO, 
							'HCA',
							NULL, 
							'Activo',
							NULL  
						FROM TALR
						WHERE TALR.IDALERTA = @IDALERTA_ALERGIA
						END  -- Fin del IF de verificación de duplicados

						FETCH NEXT FROM ALER_CUR INTO @ANTECEDENTE_ALER, @TIPO_ALERGIA_ALER, @STATUS_ALERGIA_ALER, @NOMBRE_ANTECEDENTE_ALER, @DESC_TIPO_ALERGIA_ALER
					END

					CLOSE ALER_CUR
					DEALLOCATE ALER_CUR
				END


				SELECT @CANT_ANT_FALTANTES = CLASEANT
				from dbo.FNK_REVISA_ANTHC_REQS(@IDAFILIADO,@CLASEPLANTILLA)
				IF @CANT_ANT_FALTANTES>0
				BEGIN
					SELECT @MENSAJE_ALERTA = 'Es necesario diligenciar '+STR(@CANT_ANT_FALTANTES)+' antecedentes obligatoriamente.'
					RAISERROR (@MENSAJE_ALERTA, 16, 1);
					IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
					RETURN
				END
			END
			ELSE  --Antecedentes RIAS
			BEGIN
				-- Extraer la matriz TGANT del JSON recibido
				SELECT @TGANTJson = JSON_QUERY(@JSON, '$.PARAMETROS.TGANT');
				DECLARE ANT_C CURSOR FOR
				SELECT t.CNSTGANT, t.TIPOANT, t.NOMBRE, t.ORDEN, a.CNSHCAAPD, a.CNSHCAAP, a.FINGRESO, a.CONSECUTIVOHCA, a.ANTECEDENTE
				FROM ( SELECT CNSTGANT, TIPOANT, NOMBRE, ORDEN, ANTECEDENTES
						FROM OPENJSON(@TGANTJson) WITH (
						CNSTGANT NVARCHAR(100) '$.CNSTGANT',
						TIPOANT NVARCHAR(100) '$.TIPOANT',
						NOMBRE NVARCHAR(100) '$.NOMBRE',
						ORDEN INT '$.ORDEN',
						ANTECEDENTES NVARCHAR(MAX) AS JSON
					)
				) t
				CROSS APPLY OPENJSON(t.ANTECEDENTES) WITH (
					CNSHCAAPD NVARCHAR(100) '$.CNSHCAAPD',
					CNSHCAAP NVARCHAR(100) '$.CNSHCAAP',
					FINGRESO DATE '$.FINGRESO',
					CONSECUTIVOHCA NVARCHAR(100) '$.CONSECUTIVOHCA',
					ANTECEDENTE NVARCHAR(MAX) '$.ANTECEDENTE'
				) a;
				OPEN ANT_C
				FETCH NEXT FROM ANT_C INTO @CNSTGANTCUR ,@TIPOANT,@NOMBREANT ,@ORDENCUR ,@CNSHCAAPD ,@CNSHCAAPCUR ,@FECHAING ,@CNSHCAANT, @ANTECEDENTECUR
				WHILE @@fetch_status = 0
				BEGIN
					IF TRY_CONVERT(FLOAT, @CNSHCAAPD) IS NOT NULL
					BEGIN
						UPDATE HCAAPD SET ANTECEDENTE = @ANTECEDENTECUR WHERE CNSHCAAPD = @CNSHCAAPD
					END
					ELSE
					BEGIN
						IF (SELECT COUNT(1) FROM HCAAP WHERE CNSTGANT = @CNSTGANTCUR AND IDAFILIADO = @IDAFILIADO )<= 0
						begin
							INSERT INTO HCAAP (CNSTGANT ,IDAFILIADO )
							SELECT @CNSTGANTCUR, @IDAFILIADO
						end
						SELECT @CNSHCAAPCUR = CNSHCAAP FROM HCAAP WHERE CNSTGANT = @CNSTGANTCUR AND IDAFILIADO = @IDAFILIADO
						INSERT INTO HCAAPD (CNSHCAAP ,FINGRESO ,CONSECUTIVOHCA ,ANTECEDENTE )
						SELECT @CNSHCAAPCUR, @FECHAING ,@CNSHCAANT ,@ANTECEDENTECUR
					END
					FETCH NEXT FROM ANT_C INTO @CNSTGANTCUR ,@TIPOANT,@NOMBREANT,@ORDENCUR  ,@CNSHCAAPD ,@CNSHCAAPCUR ,@FECHAING ,@CNSHCAANT, @ANTECEDENTECUR
				END
				CLOSE ANT_C
				DEALLOCATE ANT_C
			END

			IF COALESCE(@RIAS,'') = ''
			BEGIN
				DELETE FROM HCADL WHERE CONSECUTIVO=@CONSECUTIVOHCA
				DELETE FROM HCAD WHERE CONSECUTIVO=@CONSECUTIVOHCA

				SELECT @AUX = MPLD
				FROM #HCA
				IF @CLASEPLANTILLA=@CLASE_PLANTILLA_EVOLUCION
				BEGIN
					SELECT * INTO #HCA_EVOL
					FROM (
						SELECT CAMPO, VALOR
						FROM OPENJSON(@AUX) WITH (
								CAMPO			VARCHAR(15) '$.CAMPO'
								,VALOR			VARCHAR(MAX) '$.VALOR'
									) AS TABLA
						) AS T
						PIVOT
						(
							MAX(VALOR) FOR CAMPO IN (EVOLSUB,EVOLUCION,ANALISIS,RESUMEN,JUSTESTANCIA,RESPARACLINI)
						) AS PVT

					UPDATE HCA SET EVOLSUB=LEFT(A.EVOLSUB,4095), EVOLUCION=LEFT(A.EVOLUCION,4096), ANALISIS=LEFT(A.ANALISIS,4095)
						,RESUMEN=LEFT(A.RESUMEN,1024), JUSTESTANCIA=LEFT(A.JUSTESTANCIA,1024), RESPARACLINI=LEFT(A.RESPARACLINI,1024)
					FROM HCA
					CROSS JOIN #HCA_EVOL A
					WHERE HCA.CONSECUTIVO=@CONSECUTIVO
				END
				ELSE
				BEGIN
					--- EDGARDO 26-11-2023 para la HC Imagen Descrita
					SELECT #T.CAMPO ,#T.SECUENCIA ,#T.TIPO_CAMPO
							,VALOR =
							IIF (#T.VALOR IS NOT NULL,#T.VALOR
								,IIF( #T.TIPO_CAMPO IN ('Titulo','Subtitulo','Separador','Informativo'), MPLD.DESCCAMPO,
									CAST(IIF(#T.TIPO_CAMPO = 'Check', #T.[CHECK], NULL) AS VARCHAR)
								)
							)
                            ,#T.VALORLISTA ,#T.MPLDL ,#T.INTERPRETACION ,#T.DOCUMENTOID ,#T.MEMO ,#T.MATRIZ ,MPLD.IDIMAGEN,#T.ANCHOIMG-- #T.IDIMAGEN ,#T.ANCHOIMG
							,#T.ALTOIMG ,MPLD.ESCALAX ,MPLD.ESCALAY
                    INTO #MPLD
					FROM OPENJSON(@AUX) WITH (
							CAMPO			VARCHAR(12) '$.CAMPO'
							,SECUENCIA		SMALLINT	'$.SECUENCIA'
							,TIPO_CAMPO		VARCHAR(50) '$.TIPO_CAMPO'
							,VALOR			VARCHAR(MAX) '$.VALOR'
							,VALORLISTA		VARCHAR(256) '$.VALORLISTA'
							,INTERPRETACION VARCHAR(200) '$.INTERPRETACION'
							,MPLDL			NVARCHAR(MAX) AS JSON
							,DOCUMENTOID	VARCHAR(100) '$.DOCUMENTOID'
							,MEMO			VARCHAR(MAX) '$.MEMO'
                            ,MATRIZ         NVARCHAR(MAX) '$.MATRIZ'
							--,IDIMAGEN		VARCHAR(50)	 '$.IDIMAGEN'
							,ANCHOIMG		INT			 '$.ANCHOIMG'
							,ALTOIMG		INT			 '$.ALTOIMG'
							,ESCALAX		FLOAT		 '$.ESCALAX'
							,ESCALAY		FLOAT		 '$.ESCALAY'
							,[CHECK]			BIT			 '$.CHECK'

							) AS #T
					INNER JOIN MPLD ON MPLD.CLASEPLANTILLA = @CLASEPLANTILLA
						AND MPLD.CAMPO = #T.CAMPO
						AND MPLD.SECUENCIA = #T.SECUENCIA

					DECLARE HCADCUR CURSOR
                    FOR
                        SELECT CAMPO,SECUENCIA,VALOR,VALORLISTA,MPLDL,INTERPRETACION,DOCUMENTOID, MEMO , MATRIZ , IDIMAGEN , ANCHOIMG, ALTOIMG, ESCALAX, ESCALAY
						FROM #MPLD

					OPEN HCADCUR
					FETCH NEXT
                    FROM HCADCUR INTO @CAMPO,@SECUENCIA,@VALOR,@VALORLISTA,@MPLDL,@INTERPRETACION,@DOCUMENTOID, @MEMO , @MATRIZ , @IDIMAGEN , @ANCHOIMG, @ALTOIMG, @ESCALAX, @ESCALAY
					WHILE @@FETCH_STATUS = 0
					BEGIN
						SELECT @TIPO_CAMPO = TIPO_CAMPO,
								@ENEPICRISIS = COALESCE(ENEPICRISIS, 0)
						FROM   MPLD
						WHERE  CLASEPLANTILLA = @CLASEPLANTILLA
						AND    SECUENCIA = @SECUENCIA

						SELECT *
						INTO #HCADL
						FROM OPENJSON(@MPLDL) WITH (
							CHECKM		VARCHAR(10)   '$.CHECK'
							,DESCRIPCION VARCHAR(MAX) '$.DESCRIPCION'
							,VALORLISTA VARCHAR(256)  '$.VALORLISTA'
							,ID			VARCHAR(20)   '$.ID'
							,XPOS		INT			  '$.XPOS'
							,YPOS		INT			  '$.YPOS'
							,COLOR		VARCHAR(20)   '$.COLOR'
							,FORMA		VARCHAR(20)   '$.FORMA'
							,IMGSERIE   VARCHAR(20)   '$.IMGSERIE'
							,TITULOMAPA VARCHAR(20)   '$.TITULOMAPA'
							,TAMANO     INT			  '$.TAMANO'
						)

                        INSERT INTO HCAD (CONSECUTIVO,CLASEPLANTILLA,CAMPO,SECUENCIA,ENEPICRISIS,TIPOCAMPO,ALFANUMERICO,FECHA,MEMO,OBS,LISTA,NUMERICO, IDIMAGEN , ANCHOIMG, ALTOIMG, ESCALAX, ESCALAY, MATRIZ )
						SELECT @CONSECUTIVO,@CLASEPLANTILLA,@CAMPO,@SECUENCIA,@ENEPICRISIS,@TIPO_CAMPO
							,LEFT(CASE @TIPO_CAMPO
								WHEN 'Alfanumerico'
									THEN @VALOR
								WHEN 'Numerico'
									THEN NULL
								WHEN 'Calculado'
									THEN @VALOR
								WHEN 'Krystalos'
									THEN @VALOR
								WHEN 'RadioButton'
									THEN @VALORLISTA
								WHEN 'Lista'
									THEN @VALORLISTA
								WHEN 'Memo'
									THEN NULL
								WHEN 'Informativo'
									THEN NULL
								WHEN 'Fecha'
									THEN NULL
								WHEN 'MultiCheck'
									THEN NULL
								WHEN 'Imagen'
									THEN @DOCUMENTOID
								WHEN 'ImgDescrita'
									THEN @IDIMAGEN
								ELSE @VALOR
								END,200) ALFANUMERICO
							--  ,CASE @TIPO_CAMPO WHEN 'Fecha'  THEN CASE WHEN ISDATE(@VALOR)>0 THEN dbo.FNK_FORMATEAR_FECHA(LTRIM(RTRIM(@VALOR))) ELSE NULL END ELSE NULL END FECHA
							,CASE @TIPO_CAMPO
								WHEN 'Fecha'
									THEN CASE
											--WHEN ISDATE(CONVERT(DATETIME,@VALOR,110)) > 0
											WHEN ISDATE(REPLACE(@VALOR,'-','')) > 0 --EZERPA 18.01.2020 Daba error cuando no diligencian la fecha porque no es obligatoria en la plantilla y viene en formato yyyy-dd-mm
												THEN CONVERT(DATETIME,@VALOR,110)
											ELSE NULL
											END
								ELSE NULL
								END FECHA
							,CASE @TIPO_CAMPO
								WHEN 'Memo'
									THEN @VALOR
								WHEN 'NotaEnfermeria'
									THEN COALESCE(@MEMO, @VALOR)
								WHEN 'Informativo'
									THEN @VALOR
								WHEN 'Interpretacion'
									THEN COALESCE(@MEMO, @VALOR)
								WHEN 'Lista'
									THEN (SELECT TOP 1 DESCRIPCION FROM #HCADL WHERE VALORLISTA=@VALORLISTA)
								WHEN 'RadioButton'
									THEN (SELECT TOP 1 DESCRIPCION FROM #HCADL WHERE VALORLISTA=@VALORLISTA)
								WHEN 'Krystalos'
									THEN @MEMO
								ELSE COALESCE(@INTERPRETACION, @VALOR)
								END MEMO
							,NULL
							,NULL
							,CASE @TIPO_CAMPO
								WHEN 'Numerico'
									THEN CASE
											WHEN @VALOR IS NULL
												OR ISNUMERIC(@VALOR) < 1
												THEN NULL
											ELSE CONVERT(DECIMAL(14, 2), @VALOR)
											END
								WHEN 'Escala'
									THEN CASE
											WHEN @VALOR IS NULL
												OR ISNUMERIC(@VALOR) < 1
												THEN NULL
											ELSE CONVERT(DECIMAL(14, 2), @VALOR)
											END
								WHEN 'RadioButton'
									THEN CASE
											WHEN @VALOR IS NULL
												OR ISNUMERIC(@VALOR) < 1
												THEN NULL
											ELSE CONVERT(DECIMAL(14, 2), @VALOR)
											END
								WHEN 'Lista'
									THEN CASE
											WHEN @VALOR IS NULL
												OR ISNUMERIC(@VALOR) < 1
												THEN NULL
											ELSE CONVERT(DECIMAL(14, 2), RTRIM(LTRIM(@VALOR)))
											END
								WHEN 'Check'
									THEN CASE
											WHEN @VALOR IS NULL
												OR ISNUMERIC(@VALOR) < 1
												THEN NULL
											ELSE CONVERT(DECIMAL(14, 2), RTRIM(LTRIM(@VALOR)))
											END
								ELSE NULL
								END NUMERICO
							, @IDIMAGEN
							, @ANCHOIMG
							, @ALTOIMG
							, @ESCALAX
                            , @ESCALAY
                            , CASE WHEN @TIPO_CAMPO IN ('Matriz', 'NotaEnfermeria') THEN @MATRIZ ELSE NULL END

						SELECT @AUX1 = 0
						SET @ITEM = 0
						IF @@ROWCOUNT>0
						BEGIN
						    -- Procesar filas dinámicas de Matriz con fechas (si aplica)
						    IF @TIPO_CAMPO = 'Matriz' AND @MATRIZ IS NOT NULL AND LEN(LTRIM(RTRIM(@MATRIZ))) > 0
						    BEGIN
							    -- Verificar si el JSON tiene filas dinámicas (con __fecha)
							    DECLARE @MatrizValues NVARCHAR(MAX) = JSON_QUERY(@MATRIZ, '$.values')
							    IF @MatrizValues IS NOT NULL
							    BEGIN
								    -- Crear tabla temporal para procesar filas dinámicas
								    CREATE TABLE #MatrizFilasDinamicas (
									    FILA_KEY NVARCHAR(100),
									    FECHA DATE,
									    VALORES NVARCHAR(MAX)
								    )

								    -- Extraer filas dinámicas que tienen __fecha
								    INSERT INTO #MatrizFilasDinamicas (FILA_KEY, FECHA, VALORES)
								    SELECT
									    [key] AS FILA_KEY,
									    TRY_CAST(JSON_VALUE([value], '$.__fecha') AS DATE) AS FECHA,
									    [value] AS VALORES
								    FROM OPENJSON(@MatrizValues)
								    WHERE JSON_VALUE([value], '$.__fecha') IS NOT NULL

								    DROP TABLE #MatrizFilasDinamicas
							    END
						    END
							
                            DECLARE HCADLCUR CURSOR
							FOR SELECT CHECKM, DESCRIPCION, VALORLISTA, ID, XPOS, YPOS, COLOR, FORMA, IMGSERIE  , TITULOMAPA, TAMANO
									FROM #HCADL
							OPEN HCADLCUR
							FETCH NEXT FROM HCADLCUR
							INTO @CHECKM,@DESCRIPCION,@VALORLISTAHCADL	,@IDPUNTO		,@XPOS		,@YPOS	,@COLOR	,@FORMA	,@IMGSERIE   ,@TITULOMAPA ,@TAMANO
							
                            WHILE @@FETCH_STATUS = 0
							BEGIN
								SET @ITEM = @ITEM + 1
								INSERT INTO HCADL (CONSECUTIVO, SECUENCIA, ITEM, VALORLISTA, CHECKM, DESCRIPCION, ID, XPOS, YPOS, COLOR, FORMA, IMGSERIE, TITULOMAPA, TAMANO)
								SELECT @CONSECUTIVO,@SECUENCIA
									,@ITEM
									,@VALORLISTAHCADL
									,CASE LOWER(@CHECKM)
										WHEN 'True'
											THEN 1
										WHEN 'true'
											THEN 1
										ELSE 0
										END
									,@DESCRIPCION
									,@IDPUNTO		,@XPOS		,@YPOS	,@COLOR	,@FORMA	,@IMGSERIE   ,@TITULOMAPA , @TAMANO
								FETCH NEXT
								FROM HCADLCUR
									INTO @CHECKM,@DESCRIPCION,@VALORLISTAHCADL	,@IDPUNTO		,@XPOS		,@YPOS	,@COLOR	,@FORMA	,@IMGSERIE   ,@TITULOMAPA ,@TAMANO
							END
							CLOSE HCADLCUR
							DEALLOCATE HCADLCUR
						END
						DROP TABLE #HCADL
						FETCH NEXT FROM HCADCUR
                        INTO @CAMPO ,@SECUENCIA ,@VALOR ,@VALORLISTA ,@MPLDL ,@INTERPRETACION ,@DOCUMENTOID ,@MEMO ,@MATRIZ ,@IDIMAGEN  ,@ANCHOIMG ,@ALTOIMG ,@ESCALAX ,@ESCALAY
					END
					CLOSE HCADCUR
					DEALLOCATE HCADCUR

					-- Vincular OMSOLI a esta HCA (marcación/cobro final en SPK_OMSOLI_GENCARGO)
					IF COALESCE(@CNSOMSOLI,'') <> ''
					BEGIN
						UPDATE OMSOLI
						SET CONSECUTIVOATIENDE = @CONSECUTIVO,
							IDMEDICOATIENDE = COALESCE(NULLIF(LTRIM(RTRIM(OMSOLI.IDMEDICOATIENDE)), ''), @IDMEDICO)
						WHERE OMSOLI.CNSOMSOLI = @CNSOMSOLI
							AND OMSOLI.NOADMISION = @NOADMISION
							AND COALESCE(OMSOLI.ESTADO, 0) = 0
					END
					ELSE
					BEGIN
                        -- Campo Krystalos INTERCONSULTA / OMSOLI: marcar solicitud como anulada
                        UPDATE OMSOLI
                        SET ESTADO = 2,
                            IDMEDICOATIENDE = COALESCE(NULLIF(LTRIM(RTRIM(OMSOLI.IDMEDICOATIENDE)), ''), @IDMEDICO),
                            CONSECUTIVOATIENDE = @CONSECUTIVO,
                            FECATIENDE = COALESCE(OMSOLI.FECATIENDE, @FECHAHCA, GETDATE())
                        FROM OMSOLI
                            INNER JOIN HCAD ON HCAD.CONSECUTIVO = @CONSECUTIVO AND HCAD.CLASEPLANTILLA = @CLASEPLANTILLA AND HCAD.TIPOCAMPO = 'Krystalos' AND COALESCE(HCAD.ALFANUMERICO, '') <> ''
                            INNER JOIN MPLD ON MPLD.CLASEPLANTILLA = HCAD.CLASEPLANTILLA
                                AND MPLD.CAMPO = HCAD.CAMPO
                                AND MPLD.SECUENCIA = HCAD.SECUENCIA
                                AND MPLD.O_KRYSTALOS = 'INTERCONSULTA' 
                                AND MPLD.T_KRYSTALOS = 'OMSOLI' 
                                AND MPLD.C_KRYSTALOS = 'CNSOMSOLI'
                        WHERE OMSOLI.NOADMISION = @NOADMISION
                            AND COALESCE(OMSOLI.ESTADO, 0) = 0
                            AND HCAD.ALFANUMERICO = OMSOLI.CNSOMSOLI 
					END
				END

				-- Imagenes cargadas mientras se diligenciaba la plantilla
				IF @USA_DOCU_BD = 'SI' AND COALESCE(@DBNAME_DOCU, '') <> '' AND EXISTS(SELECT * FROM SYS.DATABASES WHERE NAME = @DBNAME_DOCU)
				BEGIN
					SET @SQL = 'UPDATE ' + QUOTENAME(@DBNAME_DOCU) + '.[dbo].[DOCS]
					SET DocCnsAuxiliar = @CONSECUTIVO
					WHERE COALESCE(DOCTIPO, '''') = ''HCA''
					AND DocCnsAuxiliar IS NULL
					AND DocConsecutivo = @CNSWEB'

					EXEC sp_executesql @SQL, N'@CONSECUTIVO VARCHAR(20), @CNSWEB VARCHAR(20)', @CONSECUTIVO = @CONSECUTIVO, @CNSWEB = @CNSWEB
				END
				ELSE
				BEGIN
					UPDATE DOCS
					SET DocCnsAuxiliar = @CONSECUTIVO
					WHERE COALESCE(DOCTIPO, '') = 'HCA'
					AND DocCnsAuxiliar IS NULL
					AND DocConsecutivo = @CNSWEB
				END

			END
			ELSE   --Detalles de la plantilla de historia clinica RIAS Y AIEPI en RIAS
			BEGIN
                SELECT @AUX = datRIAS FROM #HCA

				/* SIOS_VIH (Cuenta de Alto Costo / Res. 273): persiste JSON clinico en ALTOC_VIH.
				   Front: SIOSVihComponent.vue envia RIAS='SIOS_VIH' y datRIAS = dataSIOS.
				   @CONSECUTIVO ya es el CONSECUTIVO HCA (nuevo o edicion) en este punto del flujo. */
				IF @RIAS = 'SIOS_VIH'
				BEGIN
					IF ISJSON(@AUX) = 1
					BEGIN
						EXEC dbo.SPK_GRABA_ALTOC_VIH
							 @CONSECUTIVOHCA = @CONSECUTIVO
							,@IDAFILIADO     = @IDAFILIADO
							,@JSON           = @AUX
							,@USUARIO        = @USUARIO
					END
				END

				IF @RIAS = 'ES_RIAS_CONTROLPRENATAL'
				BEGIN
				   DECLARE @IDGESTACION_INS INT = NULL;
				   DECLARE @datRIASGest NVARCHAR(MAX);
				   DECLARE @FUM_T DATE, @FPP_T DATE;
				   DECLARE @JDet NVARCHAR(MAX);

				   SELECT * INTO #RIAS FROM dbo.fn_ExtractRIAS_CONTROLPRENATAL(@AUX);
				   SELECT @datRIASGest = datRIASGest FROM #HCA;
				   SELECT @FUM_T = TRY_CAST(NULLIF(LTRIM(RTRIM(FULTMESTRUACION)), N'') AS DATE) FROM #RIAS;
				   SELECT @FPP_T = TRY_CAST(NULLIF(LTRIM(RTRIM(PROBPARTOFEC)), N'') AS DATE) FROM #RIAS;

				   IF OBJECT_ID(N'dbo.RIAS_GESTACION', N'U') IS NOT NULL
				   BEGIN
					   IF ISJSON(@datRIASGest) = 1 AND @datRIASGest IS NOT NULL AND LEN(LTRIM(RTRIM(@datRIASGest))) > 2
					   BEGIN
						   SELECT @IDGESTACION_INS = TRY_CAST(JSON_VALUE(@datRIASGest, N'$.IDGESTACION') AS INT);
						   IF @IDGESTACION_INS IS NOT NULL AND NOT EXISTS (
							   SELECT 1 FROM dbo.RIAS_GESTACION G WITH (NOLOCK)
							   WHERE G.IDGESTACION = @IDGESTACION_INS AND G.IDAFILIADO = @IDAFILIADO)
							   SET @IDGESTACION_INS = NULL;
					   END

					   IF @IDGESTACION_INS IS NULL
					   BEGIN
						   SELECT TOP 1 @IDGESTACION_INS = G.IDGESTACION
						   FROM dbo.RIAS_GESTACION G WITH (NOLOCK)
						   WHERE G.IDAFILIADO = @IDAFILIADO AND G.ACTIVO = N'S'
							 AND (
								 (@FUM_T IS NOT NULL AND G.FULTMESTRUACION = @FUM_T)
								 OR (@FUM_T IS NULL AND @FPP_T IS NOT NULL AND G.PROBPARTOFEC = @FPP_T)
							 )
						   ORDER BY G.IDGESTACION DESC;
					   END

					   IF @IDGESTACION_INS IS NULL
					   BEGIN
						   INSERT INTO dbo.RIAS_GESTACION (IDAFILIADO, FULTMESTRUACION, PROBPARTOFEC, ACTIVO, USUARIOCREA)
						   VALUES (@IDAFILIADO, @FUM_T, @FPP_T, N'S', @USUARIO);
						   SET @IDGESTACION_INS = CAST(SCOPE_IDENTITY() AS INT);
					   END

					   SET @JDet = JSON_QUERY(@datRIASGest, N'$.detalles');
					   IF ISJSON(@datRIASGest) = 1 AND @JDet IS NOT NULL AND ISJSON(@JDet) = 1
					   BEGIN
						   MERGE dbo.RIAS_GESTACION_DETALLES AS T
						   USING (
							   SELECT
								   J.NRO_TRIMESTRE,
								   NULLIF(LTRIM(RTRIM(J.HAB_HIPERTENSION)), N'') AS HAB_HIPERTENSION,
								   NULLIF(LTRIM(RTRIM(J.HAB_FUMADORACTIVO)), N'') AS HAB_FUMADORACTIVO,
								   NULLIF(LTRIM(RTRIM(J.HAB_FUMADORPASIVO)), N'') AS HAB_FUMADORPASIVO,
								   NULLIF(LTRIM(RTRIM(J.HAB_DROGAS)), N'') AS HAB_DROGAS,
								   NULLIF(LTRIM(RTRIM(J.HAB_ALCOHOL)), N'') AS HAB_ALCOHOL,
								   NULLIF(LTRIM(RTRIM(J.HAB_VIOLENCIA)), N'') AS HAB_VIOLENCIA,
								   NULLIF(LTRIM(RTRIM(J.HAB_LEVOBJETOSPESADOS)), N'') AS HAB_LEVOBJETOSPESADOS,
								   NULLIF(LTRIM(RTRIM(J.MP_CURSOMATERNIDAD)), N'') AS MP_CURSOMATERNIDAD
							   FROM OPENJSON(@JDet)
							   WITH (
								   NRO_TRIMESTRE TINYINT '$.NRO_TRIMESTRE',
								   HAB_HIPERTENSION NVARCHAR(20) '$.HAB_HIPERTENSION',
								   HAB_FUMADORACTIVO VARCHAR(10) '$.HAB_FUMADORACTIVO',
								   HAB_FUMADORPASIVO VARCHAR(10) '$.HAB_FUMADORPASIVO',
								   HAB_DROGAS VARCHAR(10) '$.HAB_DROGAS',
								   HAB_ALCOHOL VARCHAR(10) '$.HAB_ALCOHOL',
								   HAB_VIOLENCIA VARCHAR(20) '$.HAB_VIOLENCIA',
								   HAB_LEVOBJETOSPESADOS VARCHAR(10) '$.HAB_LEVOBJETOSPESADOS',
								   MP_CURSOMATERNIDAD NVARCHAR(200) '$.MP_CURSOMATERNIDAD'
							   ) J
							   WHERE J.NRO_TRIMESTRE IN (1, 2, 3)
						   ) AS S
						   ON T.IDGESTACION = @IDGESTACION_INS AND T.NRO_TRIMESTRE = S.NRO_TRIMESTRE
						   WHEN MATCHED THEN UPDATE SET
							   HAB_HIPERTENSION = S.HAB_HIPERTENSION,
							   HAB_FUMADORACTIVO = S.HAB_FUMADORACTIVO,
							   HAB_FUMADORPASIVO = S.HAB_FUMADORPASIVO,
							   HAB_DROGAS = S.HAB_DROGAS,
							   HAB_ALCOHOL = S.HAB_ALCOHOL,
							   HAB_VIOLENCIA = S.HAB_VIOLENCIA,
							   HAB_LEVOBJETOSPESADOS = S.HAB_LEVOBJETOSPESADOS,
							   MP_CURSOMATERNIDAD = S.MP_CURSOMATERNIDAD
						   WHEN NOT MATCHED BY TARGET THEN
							   INSERT (IDGESTACION, NRO_TRIMESTRE, HAB_HIPERTENSION, HAB_FUMADORACTIVO, HAB_FUMADORPASIVO, HAB_DROGAS, HAB_ALCOHOL, HAB_VIOLENCIA, HAB_LEVOBJETOSPESADOS, MP_CURSOMATERNIDAD)
							   VALUES (@IDGESTACION_INS, S.NRO_TRIMESTRE, S.HAB_HIPERTENSION, S.HAB_FUMADORACTIVO, S.HAB_FUMADORPASIVO, S.HAB_DROGAS, S.HAB_ALCOHOL, S.HAB_VIOLENCIA, S.HAB_LEVOBJETOSPESADOS, S.MP_CURSOMATERNIDAD);
					   END

					   UPDATE dbo.RIAS_GESTACION
					   SET GEST_DET_JSON_CACHE = (
							   SELECT d.NRO_TRIMESTRE, d.HAB_HIPERTENSION, d.HAB_FUMADORACTIVO, d.HAB_FUMADORPASIVO,
									  d.HAB_DROGAS, d.HAB_ALCOHOL, d.HAB_VIOLENCIA, d.HAB_LEVOBJETOSPESADOS, d.MP_CURSOMATERNIDAD
							   FROM dbo.RIAS_GESTACION_DETALLES d
							   WHERE d.IDGESTACION = @IDGESTACION_INS
							   ORDER BY d.NRO_TRIMESTRE
							   FOR JSON PATH
						   ),
						   FULTMESTRUACION = COALESCE(@FUM_T, FULTMESTRUACION),
						   PROBPARTOFEC = COALESCE(@FPP_T, PROBPARTOFEC)
					   WHERE IDGESTACION = @IDGESTACION_INS;
				   END

				   -- Solo borrar fila RIAS de la HC que se edita; con @CONSECUTIVOHCA vacío (HC nueva) no borrar
				   IF @NUEVA_HCA = 0 AND COALESCE(@CONSECUTIVOHCA, '') <> ''
					   DELETE FROM RIAS_CONTROLPRENATAL WHERE CONSECUTIVOHCA = @CONSECUTIVOHCA

				   INSERT INTO RIAS_CONTROLPRENATAL (CONSECUTIVOHCA ,IDAFILIADO ,MOTIVOCONSULTA ,ENFERMEDADACTUAL ,FULTMESTRUACION ,GRUPO_SANG ,GRUPO_SANGCONYUGE ,PROBPARTOFEC ,PROBPARTOPOR ,PROBPARTOOBS ,OBSERVACIONES ,
									  CABEZACARACUELLO ,CARDIPULMONAR ,ABDOMINAL ,GENITOURINARIO ,EXTREMIDADES ,PIELYFANERAS ,SISTEMANERVCENTRAL ,HAB_TRIMESTRE ,HAB_HIPERTENSION ,HAB_FUMADORACTIVO ,HAB_FUMADORPASIVO ,HAB_DROGAS ,
									  HAB_ALCOHOL ,HAB_VIOLENCIA ,HAB_LEVOBJETOSPESADOS ,CR_RIESGO ,CR_JUSTIFICACION ,PLANTRATAMIENTO ,AA_FRECUENCIA ,AA_CANTIDAD ,AA_FORMASPREPARACION ,AA_TIPOSDEALIMENTOS ,AA_ULTIMAS24HORAS ,
									  PRACTICACRIANZA ,CAPACIRECURSOS ,EXPINQUITUDESSALUD ,SITUACIONESRIESGO ,CUELLOGLANDTIROIDEA ,OROFARINGE ,COLUMNA ,VALSALUDSEXUAL ,VALSALUDBUCAL ,DESARROLLOAPRENDIZAJE ,EXAMENOFTALMOSCOPICO ,
									  OI_PUPILAREACTIVA ,OI_PERCEPCOLOR ,OI_VISIONLEJANA ,OI_RESPUESTAMOTORA ,OD_PUPILAREACTIVA ,OD_PERCEPCOLOR ,OD_VISIONLEJANA ,OD_RESPUESTAMOTORA ,VIOLENCIAMALTRATO ,VIOLENCIASEXUAL ,HOSP_ULTIMOSDIAS ,
									  HOSP_MOTIVO ,FECHAPROXCONTROL ,RIT_REALIZADA ,RIT_CULTURALES ,RIT_DESARMONIA_UM ,RIT_QUIENTRATO ,OI_VISIONCERCANA ,OD_VISIONCERCANA ,GOODENOUGHHARRYS ,CONSUMO_HABALIMENT,PRACTICAS_HABSALUDA
									 ,ACTI_LABORALECONOMICA ,EMBARAZODESEADO  ,ATENCIPRECONCEP   ,ASESOYPROVIMETODO  ,ACIDOFOLICO3MESES ,CITASPRECOCEPCIONA,ABD_ALTURAUTERINA ,ABD_FETOCARDIA   ,ABD_SITUACION   ,ABD_PRESENTACION
									 ,ABD_MOVFETALES,MP_CURSOMATERNIDAD
									 ,AA_AYER_AGUA  ,AA_LECHEFORMULA  ,AA_EDADINICOMPLEM ,HABSA_SUENOCUANTAS ,HABSA_DONDEDUERME ,HABSA_COMOCONQUIEN
									 ,VALSALUDAUDITIVA   ,VALDESAFISICOGNITIVO ,VALESTADONUTRICIONAL ,VALSALUDMENTAL ,VALCONTEXTOSOCIAL
									 ,VALESQUEMAVAC  ,VALPRACALIMENTARIA   ,VALCPACIDADFUNCIONAL,VALDESAAUTONOMIA,IDGESTACION
									 )
				   SELECT @CONSECUTIVO ,@IDAFILIADO  ,MOTIVOCONSULTA ,ENFERMEDADACTUAL ,FULTMESTRUACION ,GRUPO_SANG ,GRUPO_SANGCONYUGE ,PROBPARTOFEC ,PROBPARTOPOR ,PROBPARTOOBS ,OBSERVACIONES ,
						  CABEZACARACUELLO ,CARDIPULMONAR ,ABDOMINAL ,GENITOURINARIO ,EXTREMIDADES ,PIELYFANERAS ,SISTEMANERVCENTRAL ,
						  CAST(NULL AS VARCHAR(20)) ,CAST(NULL AS NVARCHAR(MAX)) ,CAST(NULL AS VARCHAR(10)) ,CAST(NULL AS VARCHAR(10)) ,CAST(NULL AS VARCHAR(10)) ,
						  CAST(NULL AS VARCHAR(10)) ,CAST(NULL AS VARCHAR(20)) ,CAST(NULL AS VARCHAR(10)) ,CR_RIESGO ,CR_JUSTIFICACION ,PLANTRATAMIENTO ,AA_FRECUENCIA ,AA_CANTIDAD ,AA_FORMASPREPARACION ,AA_TIPOSDEALIMENTOS ,AA_ULTIMAS24HORAS ,
						  PRACTICACRIANZA ,CAPACIRECURSOS ,EXPINQUITUDESSALUD ,SITUACIONESRIESGO ,CUELLOGLANDTIROIDEA ,OROFARINGE ,COLUMNA ,VALSALUDSEXUAL ,VALSALUDBUCAL ,DESARROLLOAPRENDIZAJE ,EXAMENOFTALMOSCOPICO ,
						  OI_PUPILAREACTIVA ,OI_PERCEPCOLOR ,OI_VISIONLEJANA ,OI_RESPUESTAMOTORA ,OD_PUPILAREACTIVA ,OD_PERCEPCOLOR ,OD_VISIONLEJANA ,OD_RESPUESTAMOTORA ,VIOLENCIAMALTRATO ,VIOLENCIASEXUAL ,HOSP_ULTIMOSDIAS ,
						  HOSP_MOTIVO ,FECHAPROXCONTROL ,RIT_REALIZADA ,RIT_CULTURALES ,RIT_DESARMONIA_UM ,RIT_QUIENTRATO ,OI_VISIONCERCANA ,OD_VISIONCERCANA ,GOODENOUGHHARRYS,CONSUMO_HABALIMENT,PRACTICAS_HABSALUDA
						 ,ACTI_LABORALECONOMICA ,EMBARAZODESEADO  ,ATENCIPRECONCEP   ,ASESOYPROVIMETODO  ,ACIDOFOLICO3MESES ,CITASPRECOCEPCIONA
						 ,ABD_ALTURAUTERINA ,ABD_FETOCARDIA  ,ABD_SITUACION     ,ABD_PRESENTACION  ,ABD_MOVFETALES,CAST(NULL AS NVARCHAR(200))
						 ,AA_AYER_AGUA  ,AA_LECHEFORMULA  ,AA_EDADINICOMPLEM ,HABSA_SUENOCUANTAS ,HABSA_DONDEDUERME ,HABSA_COMOCONQUIEN
						 ,VALSALUDAUDITIVA   ,VALDESAFISICOGNITIVO ,VALESTADONUTRICIONAL ,VALSALUDMENTAL ,VALCONTEXTOSOCIAL
						 ,VALESQUEMAVAC  ,VALPRACALIMENTARIA   ,VALCPACIDADFUNCIONAL,VALDESAAUTONOMIA ,@IDGESTACION_INS
				   FROM #RIAS

					--PARTE DE AIEPI
					IF @CLASEPLANTILLA IN ('PI_RIAS','IN_RIAS')
					BEGIN
					   SELECT @AUX = AIEPI FROM #HCA
					   -- Paso 1: Crear una tabla temporal para almacenar los datos parseados
					   CREATE TABLE #ParsedData ( CODIGO VARCHAR(50) COLLATE Modern_Spanish_CI_AS, CLASE VARCHAR(20) COLLATE Modern_Spanish_CI_AS, TIPO VARCHAR(100) COLLATE Modern_Spanish_CI_AS
												, NOMBRE VARCHAR(MAX) COLLATE Modern_Spanish_CI_AS, ORDEN INT, RESPUESTA VARCHAR(MAX) COLLATE Modern_Spanish_CI_AS)
					   -- Paso 2: Parsear el JSON e insertar los datos en la tabla temporal
					   INSERT INTO #ParsedData (CODIGO, CLASE, TIPO, NOMBRE, ORDEN, RESPUESTA)
					   SELECT CODIGO, CLASE, TIPO, NOMBRE, ORDEN, RESPUESTA
					   FROM OPENJSON(@AUX)
					   WITH (
						   CODIGO VARCHAR(50),
						   CLASE  VARCHAR(20),
						   TIPO   VARCHAR(100),
						   NOMBRE VARCHAR(MAX),
						   ORDEN  INT,
						   RESPUESTA VARCHAR(MAX)
					   );
					   -- Paso 3: Actualizar los registros existentes en AIEPIAFI
					   UPDATE A SET A.RESPUESTA = P.RESPUESTA FROM AIEPIAFI A INNER JOIN #ParsedData P ON A.IDAFILIADO = @IDAFILIADO AND A.CODIGO = P.CODIGO
					   WHERE  A.CONSECUTIVOHCA = @CONSECUTIVOHCA
					   -- Paso 4: Insertar los registros nuevos en AIEPIAFI
					   INSERT INTO AIEPIAFI (IDAFILIADO, CODIGO, RESPUESTA ,CONSECUTIVOHCA)
					   SELECT @IDAFILIADO, P.CODIGO, P.RESPUESTA ,CASE WHEN COALESCE(@CONSECUTIVOHCA,'')='' THEN @CONSECUTIVO ELSE @CONSECUTIVOHCA END
					   FROM #ParsedData P
					   WHERE NOT EXISTS ( SELECT 1 FROM AIEPIAFI A WHERE A.IDAFILIADO = @IDAFILIADO AND A.CODIGO = P.CODIGO AND A.CONSECUTIVOHCA = @CONSECUTIVOHCA)
					   -- Paso 5: Limpiar la tabla temporal
					   DROP TABLE #ParsedData
					END
			    END
            END
	
			-- Ordenes Medicas
			BEGIN
				-- Detectar cambios en OM (inserción o edición) antes de persistir
				SET @HUBO_CAMBIOS_OM = 0
				IF @NUEVA_HCA = 1 AND EXISTS (SELECT 1 FROM #HCATD)
					SET @HUBO_CAMBIOS_OM = 1
				ELSE IF @NUEVA_HCA = 0 AND COALESCE(@CONSECUTIVOHCA,'') <> ''
				BEGIN
					IF EXISTS (
						SELECT 1 FROM HCATD h
						WHERE h.CONSECUTIVO = @CONSECUTIVOHCA
						  AND NOT EXISTS (SELECT 1 FROM #HCATD src WHERE src.ID = h.ID)
					)
						SET @HUBO_CAMBIOS_OM = 1
					IF @HUBO_CAMBIOS_OM = 0 AND EXISTS (SELECT 1 FROM #HCATD WHERE ID IS NULL)
						SET @HUBO_CAMBIOS_OM = 1
					IF @HUBO_CAMBIOS_OM = 0 AND NOT EXISTS (SELECT 1 FROM #HCATD WHERE ID IS NOT NULL) AND EXISTS (SELECT 1 FROM #HCATD)
						SET @HUBO_CAMBIOS_OM = 1
					IF @HUBO_CAMBIOS_OM = 0 AND EXISTS (
						SELECT 1 FROM #HCATD src
						INNER JOIN HCATD h ON h.ID = src.ID AND h.CONSECUTIVO = @CONSECUTIVOHCA
						WHERE COALESCE(src.CODOM,'') <> COALESCE(h.CODOM,'')
						   OR src.IDSERVICIO <> h.IDSERVICIO
						   OR COALESCE(src.CANTIDAD,0) <> COALESCE(h.CANTIDAD,0)
						   OR COALESCE(src.CLASE,'') <> COALESCE(h.CLASE,'')
					)
						SET @HUBO_CAMBIOS_OM = 1
				END
				IF @DAALTA = 1
					SET @HUBO_CAMBIOS_OM = 1

				IF COALESCE(@CONSECUTIVOHCA,'')<>''
				BEGIN
					SELECT @ITEMRED = ITEMRED FROM HCA WHERE CONSECUTIVO = @CONSECUTIVOHCA

					--elimino las ordenes medicas que fueron borradas en la edicion de la hca
                    DECLARE @ID_HCATD_CUR INT
                    DECLARE _CUR_DEL_HCATD CURSOR FOR
                    -- NOT EXISTS evita que un ID NULL en #HCATD invalide todo el NOT IN (3VL)
                    SELECT ID FROM HCATD WHERE CONSECUTIVO= @CONSECUTIVOHCA
                        AND NOT EXISTS (SELECT 1 FROM #HCATD h WHERE h.ID = HCATD.ID)
                    OPEN _CUR_DEL_HCATD 
                    FETCH NEXT FROM _CUR_DEL_HCATD INTO @ID_HCATD_CUR
                    WHILE @@FETCH_STATUS=0
                    BEGIN
						DELETE FROM HCATD_AUD WHERE ID_HCATD = @ID_HCATD_CUR
						DELETE FROM AUTSES WHERE HCATD_ID = @ID_HCATD_CUR			
						DELETE FROM HCATDOD WHERE HCATDO_ITEM IN (SELECT ITEM FROM HCATDO WHERE ID = @ID_HCATD_CUR)
						DELETE FROM HCATDO WHERE ID = @ID_HCATD_CUR
						DELETE HCATDH FROM HCATDH 
						INNER JOIN HCATD ON HCATD.CONSECUTIVO=HCATDH.CONSECUTIVO AND HCATD.CODOM=HCATDH.CODOM AND HCATD.IDSERVICIO=HCATDH.IDSERVICIO
						WHERE HCATD.ID = @ID_HCATD_CUR
						DELETE FROM HCATDPT WHERE IDHCATD = @ID_HCATD_CUR
                        DELETE FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA AND ID = @ID_HCATD_CUR
                        FETCH NEXT FROM _CUR_DEL_HCATD INTO @ID_HCATD_CUR
                    END
                    CLOSE _CUR_DEL_HCATD
                    DEALLOCATE _CUR_DEL_HCATD

					IF EXISTS(SELECT 1 FROM #HCATD WHERE ID IS NOT NULL)
					BEGIN
						-- Eliminar dependientes para refrescar desde payload
						--DELETE FROM AUTSES WHERE HCATD_ID IN (SELECT ID FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA)
						--DELETE FROM HCATDOD WHERE HCATDO_ITEM IN (SELECT ITEM FROM HCATDO WHERE ID IN (SELECT ID FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA))
						--DELETE FROM HCATDO WHERE ID IN (SELECT ID FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA)
						--DELETE FROM HCATDH WHERE CONSECUTIVO=@CONSECUTIVOHCA
						--DELETE FROM HCATDPT WHERE CONSECUTIVO=@CONSECUTIVOHCA
                        --ALTER TABLE HCATD DISABLE TRIGGER TK_HCATD_BORRADO
						--DELETE FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA AND ID NOT IN (SELECT ID FROM #HCATD WHERE ID IS NOT NULL)
                        --ALTER TABLE HCATD ENABLE TRIGGER TK_HCATD_BORRADO

                        --DECLARE @ID_HCATD_CUR INT
                        --DECLARE _CUR_DEL_HCATD CURSOR FOR
                        --SELECT ID FROM #HCATD WHERE ID IS NOT NULL
                        --OPEN _CUR_DEL_HCATD 
                        --FETCH NEXT FROM _CUR_DEL_HCATD INTO @ID_HCATD_CUR
                        --WHILE @@FETCH_STATUS=0
                        --BEGIN
                        --    DELETE FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA AND ID = @ID_HCATD_CUR
                        --    FETCH NEXT FROM _CUR_DEL_HCATD INTO @ID_HCATD_CUR
                        --END
                        --CLOSE _CUR_DEL_HCATD
                        --DEALLOCATE _CUR_DEL_HCATD
	  
                        --UPDATE HCATD existentes (los que tienen ID en payload)
                        UPDATE h SET
							CODOM = CASE WHEN src.CODOM IS NOT NULL THEN src.CODOM ELSE (SELECT TOP 1 HCCOM.CODOM FROM HCCOMD INNER JOIN HCCOM ON HCCOM.CODOM=HCCOMD.CODOM AND PREFIJO=(SELECT PREFIJO FROM SER WHERE IDSERVICIO=src.IDSERVICIO)) END,
							IDSERVICIO = src.IDSERVICIO, 
                            CANTIDAD = src.CANTIDAD, 
                            VIA = COALESCE(src.VIA,'No Aplica'),
							OBSERVACION = COALESCE(src.OBSERVACION,''), 
                            CLASE = IIF(@DAALTA=1,'S',src.CLASE),
							FRECUENCIA = CASE WHEN COALESCE(src.FRECUENCIA,'')='' THEN 24 ELSE CAST(src.FRECUENCIA AS DECIMAL(14,2)) END,
							DURACION = COALESCE((src.DURACION * CASE WHEN src.CLASE='C' THEN 1 ELSE CASE WHEN src.TIPODURACION='D' THEN 24 ELSE 1 END END),24),
							TIPO = ISNULL(src.TIPO,'Horaria'), 
                            CODPAQUETE = src.CODPAQUETE, 
                            LUNES = src.LUNES, 
                            MARTES = src.MARTES,
							MIERCOLES = src.MIERCOLES, 
                            JUEVES = src.JUEVES, 
                            VIERNES = src.VIERNES, 
                            SABADO = src.SABADO, 
                            DOMINGO = src.DOMINGO,
							RAZONNEC = src.RAZONNEC, 
                            DOSISUNICA = src.DOSISUNICA, 
                            NDOSISINICIO = src.NDOSISINICIO,
                            CANTIDADBOLO = TRY_CAST(src.CANTIDADBOLO AS DECIMAL(14,2)),
							IDSERVICIOMEZCLA = src.IDSERVICIOMEZCLA, 
                            QMEZCLA = TRY_CAST(src.QMEZCLA AS DECIMAL(14,2)),
							IDTIPOCONC = SER.PRESUNI,
							HORAAM = src.HORAAM, 
                            HORAPM = src.HORAPM, 
                            QAM = TRY_CAST(src.QAM AS DECIMAL(14,2)), 
                            QPM = TRY_CAST(src.QPM AS DECIMAL(14,2)),
							FECHAINI = REPLACE(src.FECHAINI,'-','')+' '+src.HORAINI, 
                            IDCAUSAL = src.IDCAUSAL,
							AVISADOENF = IIF(@NUEVA_HCA=1 AND src.CLASE IN ('S','B'),0,src.AVISADOENF),
							RUTA = IIF(@PROT_PROCESO=3,1,COALESCE(src.RUTA,0)), 
                            TOTALUNIDADES = IIF(COALESCE(TRY_CAST(src.TOTALUNIDADES AS INT), 0) < 1, 1, CAST(CAST(src.TOTALUNIDADES AS DECIMAL(14,2)) AS INT)),
							PRESCRIPCION = src.PRESCRIPCION, 
                            TIPODURACION = COALESCE(src.TIPODURACION,'D'), 
                            TIPOFRECUENCIA = src.TIPOFRECUENCIA,
							ITEM_DXUNIRS = src.ITEM_DXUNIRS, 
                            IDDX = src.IDDX, 
                            EFECTOS = src.EFECTOS,
							TOTAL_CONTROLADOS = src.TOTAL_CONTROLADOS, 
                            ENCARGOS = src.ENCARGOS, 
                            NOPRESTACION = src.NOPRESTACION,
							NOINGRESO = src.NOINGRESO,
							FFINALDOSIS = IIF(@DAALTA=1,@HORASUSPENDE,IIF(COALESCE(src.FFINALDOSIS+src.HFINALDOSIS,'')='',NULL,REPLACE(src.FFINALDOSIS,'-','')+' '+src.HFINALDOSIS)),
							COPIADO = src.COPIADO, 
                            CANTIDADORI = src.CANTIDADORI, 
                            FRECUENCIAORI = src.FRECUENCIAORI, 
                            DURACIONORI = src.DURACIONORI,
							GOTEO = src.GOTEO, 
                            DOSIF = src.DOSIF, 
                            TIPOSOLBS = src.TIPOSOLBS, 
                            BSCAPACIDAD = src.BSCAPACIDAD,
							QIMPSERVICIO = TRY_CAST(src.QIMPSERVICIO AS DECIMAL(14,2)), 
                            QIMPMEZCLA = TRY_CAST(src.QIMPMEZCLA AS DECIMAL(14,2)),
							DURACIONIMP = TRY_CAST(src.DURACIONIMP AS DECIMAL(14,2)), 
                            IDBODEGA = src.IDBODEGA, 
                            PROTOCOLO = src.PROTOCOLO,
							APLICADA = COALESCE(src.APLICADA,0), 
                            CANTDIAS = COALESCE(src.CANTDIAS,0),
							ENAYUNO = IIF(COALESCE(src.ENAYUNO,0)=0,NULL,1),
							STAFF = COALESCE(src.STAFF, h.STAFF),
							PRIORIDADES_STAFF = IIF(src.STAFF=1,src.PRIORIDADES_STAFF,NULL), 
                            CASO_DIFICIL_STAFF = IIF(src.STAFF=1,src.CASO_DIFICIL_STAFF,NULL),
							ID_PRIO_STAFF = IIF(src.STAFF=1,src.ID_PRIO_STAFF,NULL), 
                            OBSERVACION_STAFF = IIF(src.STAFF=1,src.OBSERVACION_STAFF,NULL),
							FECHA_STAFF = IIF(src.STAFF=1,getdate(),NULL), 
                            ESTADO_STAFF = IIF(src.STAFF=1,src.ESTADO_STAFF,NULL),
							CATEGORIA_STAFF = IIF(src.STAFF=1,src.CATEGORIA_STAFF,NULL), 
                            ID_CHECKLIST = IIF(src.STAFF=1,src.ID_CHECKLIST,NULL),
							NIVEL_PREVENCION = src.NIVEL_PREVENCION, 
                            IDPATOLOGIA = src.IDPATOLOGIA, 
                            FORMULADO_STAFF = src.FORMULADO_STAFF,
							FORM_ESPECIAL = src.ANT_VIG, 
                            NOINSTITUCIONAL = COALESCE(src.NOINSTITUCIONAL,0), 
                            LATERALIDAD = COALESCE(src.LATERALIDAD,'No aplica'),
                            SEGMENTO = COALESCE(src.SEGMENTO, @SEGMENTO), -- NUEVO: persistencia de segmento
                            CATEGORIATM = src.CATEGORIATM
						FROM HCATD h
						INNER JOIN #HCATD src ON src.ID = h.ID AND h.CONSECUTIVO = @CONSECUTIVOHCA
						LEFT JOIN SER ON SER.IDSERVICIO = src.IDSERVICIO
						LEFT JOIN MPE ON MPE.IDPESPECIAL = @IDPESPECIAL
					END
					ELSE
					BEGIN
						-- Comportamiento anterior: DELETE todo + INSERT (cuando frontend no envía ID)
						DELETE FROM HCATD_AUD WHERE ID_HCATD IN (SELECT ID FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA)
						DELETE FROM AUTSES WHERE HCATD_ID IN (SELECT ID FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA)
						DELETE FROM HCATDOD WHERE HCATDO_ITEM IN (SELECT ITEM FROM HCATDO WHERE ID IN (SELECT ID FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA))
						DELETE FROM HCATDO WHERE ID IN (SELECT ID FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA)
						DELETE FROM HCATDH WHERE CONSECUTIVO=@CONSECUTIVOHCA
						DELETE FROM HCATDPT WHERE CONSECUTIVO=@CONSECUTIVOHCA
						DELETE FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA
                        
                        DECLARE @CODOM_CUR VARCHAR(10), @IDSERVICIO_CUR  VARCHAR(20)
                        DECLARE _CUR_DEL_HCATD_A CURSOR FOR
                        SELECT IDSERVICIO, CODOM FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA

                        OPEN _CUR_DEL_HCATD_A 
                        FETCH NEXT FROM _CUR_DEL_HCATD_A INTO @IDSERVICIO_CUR, @CODOM_CUR

                        WHILE @@FETCH_STATUS=0
						BEGIN
                            DELETE FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVOHCA AND CODOM=@CODOM_CUR AND IDSERVICIO=@IDSERVICIO_CUR
                            FETCH NEXT FROM _CUR_DEL_HCATD_A INTO @IDSERVICIO_CUR, @CODOM_CUR
                        END
                        CLOSE _CUR_DEL_HCATD_A
                        DEALLOCATE _CUR_DEL_HCATD_A
					END
				END

				-- Validar ordenes cuando solicitan un UNIRS
				IF EXISTS(SELECT 1 FROM #HCATD WHERE COALESCE(ITEM_DXUNIRS,0)>0)
				BEGIN
					SELECT @IDSERVICIOS_UNIRS = dbo.FNK_VALORVARIABLE('IDSERVICIOS_UNIRS')
					IF COALESCE(@IDSERVICIOS_UNIRS,'')=''
					BEGIN
						RAISERROR ('Variable de sistema IDSERVICIOS_UNIRS no configurada, favor contactar al departamento de tecnologia'
							, 16, 1);
						IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
						RETURN
					END

					SELECT WORD AS IDSERVICIO INTO #IDSERVICIOS_UNIRS FROM dbo.FNK_EXPLODE(dbo.FNK_VALORVARIABLE('IDSERVICIOS_UNIRS'),',')
					IF NOT EXISTS(
						SELECT 1 FROM #HCATD WHERE IDSERVICIO IN (
							SELECT IDSERVICIO FROM #IDSERVICIOS_UNIRS iu
						)
					)
					BEGIN
						SELECT @MENSAJE_ALERTA ='Para aprobar la prescripcion de un UNIRS debes prescribir al menos uno de los siguientes servicios: '
						SELECT  @MENSAJE_ALERTA = 'Para aprobar la prescripcion de un UNIRS debes incluir en la orden la Junta Medica.'

						RAISERROR (@MENSAJE_ALERTA, 16, 1);
						IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
						RETURN
					END
				END

				-- Validaciones específicas para plantilla HIM (Ingreso Médico de Urgencia)
				IF @NIT = '830507718' -- Clinica Medical
				BEGIN
					IF @CLASEPLANTILLA = 'HIM' -- Ingreso Médico de Urgencia
					BEGIN
						-- Obtener datos de MPLD para validaciones
						SELECT @AUX = MPLD FROM #HCA

						-- Validación 1: Campo 3500 - Tórax (MultiCheck)
						-- Si hay algún hallazgo marcado (excepto VALOR 500), debe existir el servicio 871121
						IF EXISTS (
							SELECT 1
							FROM OPENJSON(@AUX) WITH (
								CAMPO VARCHAR(12) '$.CAMPO',
								TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
								MPLDL NVARCHAR(MAX) AS JSON
							) AS MPLD_JSON
							WHERE MPLD_JSON.CAMPO = '3500'
								AND MPLD_JSON.TIPO_CAMPO = 'MultiCheck'
								AND EXISTS (
									SELECT 1
									FROM OPENJSON(MPLD_JSON.MPLDL) WITH (
										[CHECK] BIT '$.CHECK',
										VALOR INT '$.VALOR'
									) AS MPLDL_ITEMS
									WHERE MPLDL_ITEMS.[CHECK] = 1
										AND MPLDL_ITEMS.VALOR != 500
								)
						)
						AND NOT EXISTS (
							SELECT 1 FROM #HCATD WHERE IDSERVICIO = '871121'
						)
						BEGIN
							RAISERROR ('Debe solicitar el examen 871121 - RADIOGRAFIA DE TORAX (PA O AP Y LATERAL DECUBITO LATERAL OBLICUAS O LATERAL) porque se encontraron hallazgos positivos en el examen de torax', 16, 1);
							IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
							RETURN
						END

						-- Validación 2: Campo 3900 - Pelvis (MultiCheck)
						-- Si hay algún hallazgo marcado (excepto VALOR 500), debe existir el servicio 873412
						IF EXISTS (
							SELECT 1
							FROM OPENJSON(@AUX) WITH (
								CAMPO VARCHAR(12) '$.CAMPO',
								TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
								MPLDL NVARCHAR(MAX) AS JSON
							) AS MPLD_JSON
							WHERE MPLD_JSON.CAMPO = '3900'
								AND MPLD_JSON.TIPO_CAMPO = 'MultiCheck'
								AND EXISTS (
									SELECT 1
									FROM OPENJSON(MPLD_JSON.MPLDL) WITH (
										[CHECK] BIT '$.CHECK',
										VALOR INT '$.VALOR'
									) AS MPLDL_ITEMS
									WHERE MPLDL_ITEMS.[CHECK] = 1
										AND MPLDL_ITEMS.VALOR != 500
								)
						)
						AND NOT EXISTS (
							SELECT 1 FROM #HCATD WHERE IDSERVICIO = '873412'
						)
						BEGIN
							RAISERROR ('Debe solicitar el examen 873412 - RADIOGRAFIA DE CADERA COMPARATIVA porque se encontraron hallazgos positivos en el examen de pelvis', 16, 1);
							IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
							RETURN
						END

						-- Validación 3: Campo 4100 - Abdomen (MultiCheck)
						-- Si hay algún hallazgo marcado (excepto VALOR 11), debe existir el servicio 872002
						-- EZERPA 30.05.26 / El cliente indica que no se debe validar
						-- IF EXISTS (
						-- 	SELECT 1
						-- 	FROM OPENJSON(@AUX) WITH (
						-- 		CAMPO VARCHAR(12) '$.CAMPO',
						-- 		TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
						-- 		MPLDL NVARCHAR(MAX) AS JSON
						-- 	) AS MPLD_JSON
						-- 	WHERE MPLD_JSON.CAMPO = '4100'
						-- 		AND MPLD_JSON.TIPO_CAMPO = 'MultiCheck'
						-- 		AND EXISTS (
						-- 			SELECT 1
						-- 			FROM OPENJSON(MPLD_JSON.MPLDL) WITH (
						-- 				[CHECK] BIT '$.CHECK',
						-- 				VALOR INT '$.VALOR'
						-- 			) AS MPLDL_ITEMS
						-- 			WHERE MPLDL_ITEMS.[CHECK] = 1
						-- 				AND MPLDL_ITEMS.VALOR != 11
						-- 		)
						-- )
						-- AND NOT EXISTS (
						-- 	SELECT 1 FROM #HCATD WHERE IDSERVICIO = '872002'
						-- )
						-- BEGIN
						-- 	RAISERROR ('Debe solicitar el examen 872002 - RADIOGRAFIA DE ABDOMEN SIMPLE porque se encontraron hallazgos positivos en el examen de abdomen', 16, 1);
						-- 	IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
						-- 	RETURN
						-- END

						-- Validación 4: Campo 4200 - Hallazgos de Extremidades (Matriz) - Brazo
						-- Si hay algún hallazgo marcado en brazo__d o brazo__i, debe existir el servicio 873121
						DECLARE @MATRIZ_4200 NVARCHAR(MAX)
						SELECT @MATRIZ_4200 = MATRIZVAL
						FROM OPENJSON(@AUX) WITH (
							CAMPO VARCHAR(12) '$.CAMPO',
							TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
							MATRIZVAL NVARCHAR(MAX) '$.MATRIZVAL'
						) AS MPLD_JSON
						WHERE MPLD_JSON.CAMPO = '4200'
							AND MPLD_JSON.TIPO_CAMPO = 'Matriz'

						-- Si no se encuentra MATRIZVAL, intentar con MATRIZ
						IF @MATRIZ_4200 IS NULL
						BEGIN
							SELECT @MATRIZ_4200 = JSON_QUERY(MATRIZ, '$.values')
							FROM OPENJSON(@AUX) WITH (
								CAMPO VARCHAR(12) '$.CAMPO',
								TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
								MATRIZ NVARCHAR(MAX) '$.MATRIZ'
							) AS MPLD_JSON
							WHERE MPLD_JSON.CAMPO = '4200'
								AND MPLD_JSON.TIPO_CAMPO = 'Matriz'
						END

						-- Verificar si hay hallazgos en brazo (derecho o izquierdo)
						IF @MATRIZ_4200 IS NOT NULL
							AND EXISTS (
								SELECT 1
								FROM OPENJSON(@MATRIZ_4200) AS matriz_rows
								WHERE JSON_VALUE(matriz_rows.[value], '$.brazo__d') = 'true'
									OR JSON_VALUE(matriz_rows.[value], '$.brazo__i') = 'true'
							)
							AND NOT EXISTS (
								SELECT 1 FROM #HCATD WHERE IDSERVICIO IN ('873121D','873121I')
							)
						BEGIN
							RAISERROR ('Debe solicitar el examen 873121D - RADIOGRAFIA DE HUMERO LATERALIDAD DERECHA o 873121I - RADIOGRAFIA DE HUMERO LATERALIDAD IZQUIERDA porque se encontraron hallazgos positivos en el brazo', 16, 1);
							IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
							RETURN
						END

						-- Validación 5: Campo 4200 - Hallazgos de Extremidades (Matriz) - Pierna
						-- Si hay algún hallazgo marcado en pierna__d o pierna__i, debe existir el servicio 873313
						-- Reutilizar @MATRIZ_4200 ya declarada en validación anterior
						IF @MATRIZ_4200 IS NOT NULL
							AND EXISTS (
								SELECT 1
								FROM OPENJSON(@MATRIZ_4200) AS matriz_rows
								WHERE JSON_VALUE(matriz_rows.[value], '$.pierna__d') = 'true'
									OR JSON_VALUE(matriz_rows.[value], '$.pierna__i') = 'true'
							)
							AND NOT EXISTS (
								SELECT 1 FROM #HCATD WHERE IDSERVICIO IN ('873313D','873313I')
							)
						BEGIN
							RAISERROR ('Debe solicitar el examen 873313D - RADIOGRAFIA DE PIERNA AP Y LATERAL LATERALIDAD DERECHA o 873313I - RADIOGRAFIA DE PIERNA AP Y LATERAL LATERALIDAD IZQUIERDA porque se encontraron hallazgos positivos en la pierna', 16, 1);
							RETURN
						END

						-- Validación 6: Campo 4200 - Hallazgos de Extremidades (Matriz) - Pies
						-- Si hay algún hallazgo marcado en pies__d o pies__i, debe existir el servicio 873333
						-- Reutilizar @MATRIZ_4200 ya declarada en validación anterior
						IF @MATRIZ_4200 IS NOT NULL
							AND EXISTS (
								SELECT 1
								FROM OPENJSON(@MATRIZ_4200) AS matriz_rows
								WHERE JSON_VALUE(matriz_rows.[value], '$.pies__d') = 'true'
									OR JSON_VALUE(matriz_rows.[value], '$.pies__i') = 'true'
							)
							AND NOT EXISTS (
								SELECT 1 FROM #HCATD WHERE IDSERVICIO IN ('873333D','873333I')
							)
						BEGIN
							RAISERROR ('Debe solicitar el examen 873333D - RADIOGRAFIA DE PIE AP Y LATERAL LATERALIDAD DERECHA o 873333I - RADIOGRAFIA DE PIE AP Y LATERAL LATERALIDAD IZQUIERDA porque se encontraron hallazgos positivos en los pies', 16, 1);
							RETURN
						END

						-- Validación 7: Campo 4300 - Hallazgo de Columna (Matriz)
						-- Si hay algún hallazgo en columna cervical (excepto filas de "sin hallazgos"), debe existir el servicio 871010
						DECLARE @MATRIZ_4300 NVARCHAR(MAX)
						SELECT @MATRIZ_4300 = MATRIZVAL
						FROM OPENJSON(@AUX) WITH (
							CAMPO VARCHAR(12) '$.CAMPO',
							TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
							MATRIZVAL NVARCHAR(MAX) '$.MATRIZVAL'
						) AS MPLD_JSON
						WHERE MPLD_JSON.CAMPO = '4300'
							AND MPLD_JSON.TIPO_CAMPO = 'Matriz'

						-- Si no se encuentra MATRIZVAL, intentar con MATRIZ
						IF @MATRIZ_4300 IS NULL
						BEGIN
							SELECT @MATRIZ_4300 = JSON_QUERY(MATRIZ, '$.values')
							FROM OPENJSON(@AUX) WITH (
								CAMPO VARCHAR(12) '$.CAMPO',
								TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
								MATRIZ NVARCHAR(MAX) '$.MATRIZ'
							) AS MPLD_JSON
							WHERE MPLD_JSON.CAMPO = '4300'
								AND MPLD_JSON.TIPO_CAMPO = 'Matriz'
						END

						-- Verificar si hay hallazgos en columna cervical
						-- Excluir filas "sin hallazgos": la plantilla HIM usa no_se_encontraron_hallazgos_positivos
						-- (sin_hallazgos / no_se_encuentran_hallazgos_positivos se mantienen por compatibilidad)
						IF @MATRIZ_4300 IS NOT NULL
							AND EXISTS (
								SELECT 1
								FROM OPENJSON(@MATRIZ_4300) AS matriz_rows
								WHERE matriz_rows.[key] NOT IN (
										'sin_hallazgos',
										'no_se_encontraron_hallazgos_positivos',
										'no_se_encuentran_hallazgos_positivos'
									)
									AND JSON_VALUE(matriz_rows.[value], '$.cervical') = 'true'
							)
							AND NOT EXISTS (
								SELECT 1 FROM #HCATD WHERE IDSERVICIO = '871010'
							)
						BEGIN
							RAISERROR ('Debe solicitar el examen 871010 - RADIOGRAFIA DE COLUMNA CERVICAL porque se encontraron hallazgos positivos en la columna cervical', 16, 1);
							RETURN
						END

						-- Validaciones inversas: Si se envía un examen pero no hay hallazgos positivos
						-- Validación inversa 1: Campo 3500 - Tórax
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '871121')
							AND NOT EXISTS (
								SELECT 1
								FROM OPENJSON(@AUX) WITH (
									CAMPO VARCHAR(12) '$.CAMPO',
									TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
									MPLDL NVARCHAR(MAX) AS JSON
								) AS MPLD_JSON
								WHERE MPLD_JSON.CAMPO = '3500'
									AND MPLD_JSON.TIPO_CAMPO = 'MultiCheck'
									AND EXISTS (
										SELECT 1
										FROM OPENJSON(MPLD_JSON.MPLDL) WITH (
											[CHECK] BIT '$.CHECK',
											VALOR INT '$.VALOR'
										) AS MPLDL_ITEMS
										WHERE MPLDL_ITEMS.[CHECK] = 1
											AND MPLDL_ITEMS.VALOR != 500
									)
							)
						BEGIN
							RAISERROR ('Ha enviado el estudio 871121 - RADIOGRAFIA DE TORAX (PA O AP Y LATERAL DECUBITO LATERAL OBLICUAS O LATERAL) y no ha marcado ningun hallazgo positivo para Torax', 16, 1);
							RETURN
						END

						-- Validación inversa 2: Campo 3900 - Pelvis
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '873412')
							AND NOT EXISTS (
								SELECT 1
								FROM OPENJSON(@AUX) WITH (
									CAMPO VARCHAR(12) '$.CAMPO',
									TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
									MPLDL NVARCHAR(MAX) AS JSON
								) AS MPLD_JSON
								WHERE MPLD_JSON.CAMPO = '3900'
									AND MPLD_JSON.TIPO_CAMPO = 'MultiCheck'
									AND EXISTS (
										SELECT 1
										FROM OPENJSON(MPLD_JSON.MPLDL) WITH (
											[CHECK] BIT '$.CHECK',
											VALOR INT '$.VALOR'
										) AS MPLDL_ITEMS
										WHERE MPLDL_ITEMS.[CHECK] = 1
											AND MPLDL_ITEMS.VALOR != 500
									)
							)
						BEGIN
							RAISERROR ('Ha enviado el estudio 873412 - RADIOGRAFIA DE CADERA COMPARATIVA y no ha marcado ningun hallazgo positivo para Pelvis', 16, 1);
							RETURN
						END

						-- Validación inversa 3: Campo 4100 - Abdomen
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '872002')
							AND NOT EXISTS (
								SELECT 1
								FROM OPENJSON(@AUX) WITH (
									CAMPO VARCHAR(12) '$.CAMPO',
									TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
									MPLDL NVARCHAR(MAX) AS JSON
								) AS MPLD_JSON
								WHERE MPLD_JSON.CAMPO = '4100'
									AND MPLD_JSON.TIPO_CAMPO = 'MultiCheck'
									AND EXISTS (
										SELECT 1
										FROM OPENJSON(MPLD_JSON.MPLDL) WITH (
											[CHECK] BIT '$.CHECK',
											VALOR INT '$.VALOR'
										) AS MPLDL_ITEMS
										WHERE MPLDL_ITEMS.[CHECK] = 1
											AND MPLDL_ITEMS.VALOR != 11
									)
							)
						BEGIN
							RAISERROR ('Ha enviado el estudio 872002 - RADIOGRAFIA DE ABDOMEN SIMPLE y no ha marcado ningun hallazgo positivo para Abdomen', 16, 1);
							RETURN
						END

						-- Validación inversa 4: Campo 4200 - Brazo
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '873121')
							AND (@MATRIZ_4200 IS NULL OR NOT EXISTS (
								SELECT 1
								FROM OPENJSON(@MATRIZ_4200) AS matriz_rows
								WHERE JSON_VALUE(matriz_rows.[value], '$.brazo__d') = 'true'
									OR JSON_VALUE(matriz_rows.[value], '$.brazo__i') = 'true'
							))
						BEGIN
							RAISERROR ('Ha enviado el estudio 873121 - RADIOGRAFIA DE HUMERO y no ha marcado ningun hallazgo positivo para Brazo', 16, 1);
							RETURN
						END

						-- Validación inversa 5: Campo 4200 - Pierna
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '873313')
							AND (@MATRIZ_4200 IS NULL OR NOT EXISTS (
								SELECT 1
								FROM OPENJSON(@MATRIZ_4200) AS matriz_rows
								WHERE JSON_VALUE(matriz_rows.[value], '$.pierna__d') = 'true'
									OR JSON_VALUE(matriz_rows.[value], '$.pierna__i') = 'true'
							))
						BEGIN
							RAISERROR ('Ha enviado el estudio 873313 - RADIOGRAFIA DE PIERNA AP Y LATERAL y no ha marcado ningun hallazgo positivo para Pierna', 16, 1);
							RETURN
						END

						-- Validación inversa 6: Campo 4200 - Pies
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '873333')
							AND (@MATRIZ_4200 IS NULL OR NOT EXISTS (
								SELECT 1
								FROM OPENJSON(@MATRIZ_4200) AS matriz_rows
								WHERE JSON_VALUE(matriz_rows.[value], '$.pies__d') = 'true'
									OR JSON_VALUE(matriz_rows.[value], '$.pies__i') = 'true'
							))
						BEGIN
							RAISERROR ('Ha enviado el estudio 873333 - RADIOGRAFIA DE PIE AP Y LATERAL y no ha marcado ningun hallazgo positivo para Pies', 16, 1);
							RETURN
						END

						-- Validación inversa 7: Campo 4300 - Columna Cervical
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '871010')
							AND (@MATRIZ_4300 IS NULL OR NOT EXISTS (
								SELECT 1
								FROM OPENJSON(@MATRIZ_4300) AS matriz_rows
								WHERE matriz_rows.[key] NOT IN (
										'sin_hallazgos',
										'no_se_encontraron_hallazgos_positivos',
										'no_se_encuentran_hallazgos_positivos'
									)
									AND JSON_VALUE(matriz_rows.[value], '$.cervical') = 'true'
							))
						BEGIN
							RAISERROR ('Ha enviado el estudio 871010 - RADIOGRAFIA DE COLUMNA CERVICAL y no ha marcado ningun hallazgo positivo para Columna Cervical', 16, 1);
							RETURN
						END

						-- Validación 8: Cama en habitaciones TGEN HIM_OM_AUTO_HAB ? servicios HIM_OM_AUTO_SERV obligatorios
						DECLARE @HABCAMA_CAMA VARCHAR(10)
						DECLARE @MSG_OM_AUTO_HIM NVARCHAR(500)
						SELECT @HABCAMA_CAMA = HABCAMA FROM HADM WHERE NOADMISION = @NOADMISION

						IF EXISTS (
							SELECT 1
							FROM HHAB CAMA
							INNER JOIN HHAB HAB ON HAB.HABCAMA = CAMA.HABITACION AND HAB.NIVEL = 3
							INNER JOIN TGEN TG ON TG.TABLA = 'HC' AND TG.CAMPO = 'HIM_OM_AUTO_HAB' AND TG.CODIGO = HAB.HABITACION
							WHERE CAMA.HABCAMA = @HABCAMA_CAMA
						)
						AND EXISTS (
							SELECT 1
							FROM TGEN T
							WHERE T.TABLA = 'HC'
								AND T.CAMPO = 'HIM_OM_AUTO_SERV'
								AND COALESCE(T.CHECK1, 1) = 1
								AND COALESCE(T.DATO1, 'HIM') IN ('HIM', '')
								AND NOT EXISTS (SELECT 1 FROM #HCATD H WHERE H.IDSERVICIO = T.CODIGO)
						)
						BEGIN
							SELECT @MSG_OM_AUTO_HIM = STRING_AGG(
								CAST(T.CODIGO + N' - ' + COALESCE(NULLIF(LTRIM(RTRIM(T.DESCRIPCION)), N''), SER.DESCSERVICIO, N'') AS NVARCHAR(500)),
								N', '
							)
							FROM TGEN T
							LEFT JOIN SER ON SER.IDSERVICIO = T.CODIGO
							WHERE T.TABLA = 'HC'
								AND T.CAMPO = 'HIM_OM_AUTO_SERV'
								AND COALESCE(T.CHECK1, 1) = 1
								AND COALESCE(T.DATO1, 'HIM') IN ('HIM', '')
								AND NOT EXISTS (SELECT 1 FROM #HCATD H WHERE H.IDSERVICIO = T.CODIGO)
							SELECT @MSG_OM_AUTO_HIM = COALESCE(@MSG_OM_AUTO_HIM, '')
							RAISERROR (
								'Debe solicitar la interconsulta %s porque el paciente fue asignado a una cama de habitación configurada para OM automática HIM',
								16, 1,
								@MSG_OM_AUTO_HIM
							);
							IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
							RETURN
						END

						-- Actualizar OBSERVACION en #HCATD con los hallazgos concatenados
						-- Campo 3500 - Tórax -> Servicio 871121
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '871121')
						BEGIN
							DECLARE @HALLAZGOS_TORAX NVARCHAR(MAX) = ''
							SELECT @HALLAZGOS_TORAX = STUFF((
								SELECT ', ' + VALORLISTA
								FROM OPENJSON(@AUX) WITH (
									CAMPO VARCHAR(12) '$.CAMPO',
									TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
									MPLDL NVARCHAR(MAX) AS JSON
								) AS MPLD_JSON
								CROSS APPLY OPENJSON(MPLD_JSON.MPLDL) WITH (
									[CHECK] BIT '$.CHECK',
									VALOR INT '$.VALOR',
									VALORLISTA VARCHAR(256) '$.VALORLISTA'
								) AS MPLDL_ITEMS
								WHERE MPLD_JSON.CAMPO = '3500'
									AND MPLD_JSON.TIPO_CAMPO = 'MultiCheck'
									AND MPLDL_ITEMS.[CHECK] = 1
									AND MPLDL_ITEMS.VALOR != 500
								FOR XML PATH(''), TYPE
							).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
							
							IF @HALLAZGOS_TORAX IS NOT NULL AND LEN(@HALLAZGOS_TORAX) > 0
							BEGIN
								UPDATE #HCATD 
								SET OBSERVACION = COALESCE(OBSERVACION, '') + 
									CASE WHEN LEN(COALESCE(OBSERVACION, '')) > 0 THEN '; ' ELSE '' END +
									'Hallazgos Torax: ' + @HALLAZGOS_TORAX
								WHERE IDSERVICIO = '871121'
							END
						END

						-- Campo 3900 - Pelvis -> Servicio 873412
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '873412')
						BEGIN
							DECLARE @HALLAZGOS_PELVIS NVARCHAR(MAX) = ''
							SELECT @HALLAZGOS_PELVIS = STUFF((
								SELECT ', ' + VALORLISTA
								FROM OPENJSON(@AUX) WITH (
									CAMPO VARCHAR(12) '$.CAMPO',
									TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
									MPLDL NVARCHAR(MAX) AS JSON
								) AS MPLD_JSON
								CROSS APPLY OPENJSON(MPLD_JSON.MPLDL) WITH (
									[CHECK] BIT '$.CHECK',
									VALOR INT '$.VALOR',
									VALORLISTA VARCHAR(256) '$.VALORLISTA'
								) AS MPLDL_ITEMS
								WHERE MPLD_JSON.CAMPO = '3900'
									AND MPLD_JSON.TIPO_CAMPO = 'MultiCheck'
									AND MPLDL_ITEMS.[CHECK] = 1
									AND MPLDL_ITEMS.VALOR != 500
								FOR XML PATH(''), TYPE
							).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
							
							IF @HALLAZGOS_PELVIS IS NOT NULL AND LEN(@HALLAZGOS_PELVIS) > 0
							BEGIN
								UPDATE #HCATD 
								SET OBSERVACION = COALESCE(OBSERVACION, '') + 
									CASE WHEN LEN(COALESCE(OBSERVACION, '')) > 0 THEN '; ' ELSE '' END +
									'Hallazgos Pelvis: ' + @HALLAZGOS_PELVIS
								WHERE IDSERVICIO = '873412'
							END
						END

						-- Campo 4100 - Abdomen -> Servicio 872002
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '872002')
						BEGIN
							DECLARE @HALLAZGOS_ABDOMEN NVARCHAR(MAX) = ''
							SELECT @HALLAZGOS_ABDOMEN = STUFF((
								SELECT ', ' + VALORLISTA
								FROM OPENJSON(@AUX) WITH (
									CAMPO VARCHAR(12) '$.CAMPO',
									TIPO_CAMPO VARCHAR(50) '$.TIPO_CAMPO',
									MPLDL NVARCHAR(MAX) AS JSON
								) AS MPLD_JSON
								CROSS APPLY OPENJSON(MPLD_JSON.MPLDL) WITH (
									[CHECK] BIT '$.CHECK',
									VALOR INT '$.VALOR',
									VALORLISTA VARCHAR(256) '$.VALORLISTA'
								) AS MPLDL_ITEMS
								WHERE MPLD_JSON.CAMPO = '4100'
									AND MPLD_JSON.TIPO_CAMPO = 'MultiCheck'
									AND MPLDL_ITEMS.[CHECK] = 1
									AND MPLDL_ITEMS.VALOR != 11
								FOR XML PATH(''), TYPE
							).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
							
							IF @HALLAZGOS_ABDOMEN IS NOT NULL AND LEN(@HALLAZGOS_ABDOMEN) > 0
							BEGIN
								UPDATE #HCATD 
								SET OBSERVACION = COALESCE(OBSERVACION, '') + 
									CASE WHEN LEN(COALESCE(OBSERVACION, '')) > 0 THEN '; ' ELSE '' END +
									'Hallazgos Abdomen: ' + @HALLAZGOS_ABDOMEN
								WHERE IDSERVICIO = '872002'
							END
						END

						-- Campo 4200 - Brazo -> Servicio 873121
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '873121')
							AND @MATRIZ_4200 IS NOT NULL
						BEGIN
							DECLARE @HALLAZGOS_BRAZO NVARCHAR(MAX) = ''
							SELECT @HALLAZGOS_BRAZO = STUFF((
								SELECT ', ' + matriz_rows.[key] + 
									CASE 
										WHEN JSON_VALUE(matriz_rows.[value], '$.brazo__d') = 'true' AND JSON_VALUE(matriz_rows.[value], '$.brazo__i') = 'true' THEN ' (Bilateral)'
										WHEN JSON_VALUE(matriz_rows.[value], '$.brazo__d') = 'true' THEN ' (Derecho)'
										WHEN JSON_VALUE(matriz_rows.[value], '$.brazo__i') = 'true' THEN ' (Izquierdo)'
										ELSE ''
									END
								FROM OPENJSON(@MATRIZ_4200) AS matriz_rows
								WHERE JSON_VALUE(matriz_rows.[value], '$.brazo__d') = 'true'
									OR JSON_VALUE(matriz_rows.[value], '$.brazo__i') = 'true'
								FOR XML PATH(''), TYPE
							).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
							
							IF @HALLAZGOS_BRAZO IS NOT NULL AND LEN(@HALLAZGOS_BRAZO) > 0
							BEGIN
								UPDATE #HCATD 
								SET OBSERVACION = COALESCE(OBSERVACION, '') + 
									CASE WHEN LEN(COALESCE(OBSERVACION, '')) > 0 THEN '; ' ELSE '' END +
									'Hallazgos Brazo: ' + @HALLAZGOS_BRAZO
								WHERE IDSERVICIO = '873121'
							END
						END

						-- Campo 4200 - Pierna -> Servicio 873313
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '873313')
							AND @MATRIZ_4200 IS NOT NULL
						BEGIN
							DECLARE @HALLAZGOS_PIERNA NVARCHAR(MAX) = ''
							SELECT @HALLAZGOS_PIERNA = STUFF((
								SELECT ', ' + matriz_rows.[key] + 
									CASE 
										WHEN JSON_VALUE(matriz_rows.[value], '$.pierna__d') = 'true' AND JSON_VALUE(matriz_rows.[value], '$.pierna__i') = 'true' THEN ' (Bilateral)'
										WHEN JSON_VALUE(matriz_rows.[value], '$.pierna__d') = 'true' THEN ' (Derecho)'
										WHEN JSON_VALUE(matriz_rows.[value], '$.pierna__i') = 'true' THEN ' (Izquierdo)'
										ELSE ''
									END
								FROM OPENJSON(@MATRIZ_4200) AS matriz_rows
								WHERE JSON_VALUE(matriz_rows.[value], '$.pierna__d') = 'true'
									OR JSON_VALUE(matriz_rows.[value], '$.pierna__i') = 'true'
								FOR XML PATH(''), TYPE
							).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
							
							IF @HALLAZGOS_PIERNA IS NOT NULL AND LEN(@HALLAZGOS_PIERNA) > 0
							BEGIN
								UPDATE #HCATD 
								SET OBSERVACION = COALESCE(OBSERVACION, '') + 
									CASE WHEN LEN(COALESCE(OBSERVACION, '')) > 0 THEN '; ' ELSE '' END +
									'Hallazgos Pierna: ' + @HALLAZGOS_PIERNA
								WHERE IDSERVICIO = '873313'
							END
						END

						-- Campo 4200 - Pies -> Servicio 873333
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '873333')
							AND @MATRIZ_4200 IS NOT NULL
						BEGIN
							DECLARE @HALLAZGOS_PIES NVARCHAR(MAX) = ''
							SELECT @HALLAZGOS_PIES = STUFF((
								SELECT ', ' + matriz_rows.[key] + 
									CASE 
										WHEN JSON_VALUE(matriz_rows.[value], '$.pies__d') = 'true' AND JSON_VALUE(matriz_rows.[value], '$.pies__i') = 'true' THEN ' (Bilateral)'
										WHEN JSON_VALUE(matriz_rows.[value], '$.pies__d') = 'true' THEN ' (Derecho)'
										WHEN JSON_VALUE(matriz_rows.[value], '$.pies__i') = 'true' THEN ' (Izquierdo)'
										ELSE ''
									END
								FROM OPENJSON(@MATRIZ_4200) AS matriz_rows
								WHERE JSON_VALUE(matriz_rows.[value], '$.pies__d') = 'true'
									OR JSON_VALUE(matriz_rows.[value], '$.pies__i') = 'true'
								FOR XML PATH(''), TYPE
							).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
							
							IF @HALLAZGOS_PIES IS NOT NULL AND LEN(@HALLAZGOS_PIES) > 0
							BEGIN
								UPDATE #HCATD 
								SET OBSERVACION = COALESCE(OBSERVACION, '') + 
									CASE WHEN LEN(COALESCE(OBSERVACION, '')) > 0 THEN '; ' ELSE '' END +
									'Hallazgos Pies: ' + @HALLAZGOS_PIES
								WHERE IDSERVICIO = '873333'
							END
						END

						-- Campo 4300 - Columna Cervical -> Servicio 871010
						IF EXISTS (SELECT 1 FROM #HCATD WHERE IDSERVICIO = '871010')
							AND @MATRIZ_4300 IS NOT NULL
						BEGIN
							DECLARE @HALLAZGOS_CERVICAL NVARCHAR(MAX) = ''
							SELECT @HALLAZGOS_CERVICAL = STUFF((
								SELECT ', ' + matriz_rows.[key]
								FROM OPENJSON(@MATRIZ_4300) AS matriz_rows
								WHERE matriz_rows.[key] NOT IN (
										'sin_hallazgos',
										'no_se_encontraron_hallazgos_positivos',
										'no_se_encuentran_hallazgos_positivos'
									)
									AND JSON_VALUE(matriz_rows.[value], '$.cervical') = 'true'
								FOR XML PATH(''), TYPE
							).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
							
							IF @HALLAZGOS_CERVICAL IS NOT NULL AND LEN(@HALLAZGOS_CERVICAL) > 0
							BEGIN
								UPDATE #HCATD 
								SET OBSERVACION = COALESCE(OBSERVACION, '') + 
									CASE WHEN LEN(COALESCE(OBSERVACION, '')) > 0 THEN '; ' ELSE '' END +
									'Hallazgos Columna Cervical: ' + @HALLAZGOS_CERVICAL
								WHERE IDSERVICIO = '871010'
							END
						END
					END

					IF @CLASEPLANTILLA IN ('EVOORTO', 'INTER', 'INOM', 'INTORTO')  -- EVOORTO ==> paso a ser INTORTO: Evolucion de Ortopedia, INTER: Interconsulta Cirugia General, INOM: Respuesta a Interconsulta Cirugia de Mano
					BEGIN
						DECLARE @MATRIZ_4400 NVARCHAR(MAX)

						-- Tomar el JSON de valores de la matriz 4400 desde MPLD del request
						SELECT @MATRIZ_4400 = MPLD_JSON.MATRIZVAL
						FROM OPENJSON(@AUX) WITH (
							CAMPO       VARCHAR(12)  '$.CAMPO',
							TIPO_CAMPO  VARCHAR(50)  '$.TIPO_CAMPO',
							MATRIZVAL   NVARCHAR(MAX) '$.MATRIZVAL'
						) AS MPLD_JSON
						WHERE MPLD_JSON.CAMPO = '4400'
						  AND MPLD_JSON.TIPO_CAMPO = 'Matriz'

						-- Si no vino MATRIZVAL, intentar con MATRIZ.values
						IF @MATRIZ_4400 IS NULL
						BEGIN
							SELECT @MATRIZ_4400 = JSON_QUERY(MPLD_JSON.MATRIZ, '$.values')
							FROM OPENJSON(@AUX) WITH (
								CAMPO       VARCHAR(12)   '$.CAMPO',
								TIPO_CAMPO  VARCHAR(50)   '$.TIPO_CAMPO',
								MATRIZ      NVARCHAR(MAX) '$.MATRIZ'
							) AS MPLD_JSON
							WHERE MPLD_JSON.CAMPO = '4400'
							  AND MPLD_JSON.TIPO_CAMPO = 'Matriz'
						END

						IF @MATRIZ_4400 IS NOT NULL
						BEGIN
							;WITH HALLAZGOS_INGRESO AS (
								SELECT
									CELL_KEY   = LTRIM(RTRIM(COALESCE(C.[key], ''))),
									-- Prefijo de columna: lo anterior al separador '__'.
									-- 'rodilla__izq' => 'rodilla'. Si no hay '__', se usa la clave completa.
									COL_KEY    = CASE
													WHEN CHARINDEX('__', LTRIM(RTRIM(COALESCE(C.[key], '')))) > 0
													THEN LEFT(LTRIM(RTRIM(COALESCE(C.[key], ''))), CHARINDEX('__', LTRIM(RTRIM(COALESCE(C.[key], '')))) - 1)
													ELSE LTRIM(RTRIM(COALESCE(C.[key], '')))
												 END
								FROM OPENJSON(@MATRIZ_4400, '$.hallazgos_del_ingreso') C
								WHERE C.[value] = 'true' OR TRY_CAST(C.[value] AS bit) = 1
							),
							EVALUACION_CLINICA AS (
								-- Se excluyen las filas que no son de evaluación clínica (hallazgos_del_ingreso,
								-- sin_hallazgo_clinico) para que cualquier fila marcada por el médico —
								-- incluyendo opciones de normalidad — satisfaga la validación.
								SELECT
									CELL_KEY   = LTRIM(RTRIM(COALESCE(C.[key], ''))),
									COL_KEY    = CASE
													WHEN CHARINDEX('__', LTRIM(RTRIM(COALESCE(C.[key], '')))) > 0
													THEN LEFT(LTRIM(RTRIM(COALESCE(C.[key], ''))), CHARINDEX('__', LTRIM(RTRIM(COALESCE(C.[key], '')))) - 1)
													ELSE LTRIM(RTRIM(COALESCE(C.[key], '')))
												 END
								FROM OPENJSON(@MATRIZ_4400) R
								CROSS APPLY OPENJSON(R.[value]) C
								WHERE R.[key] NOT IN (
									'hallazgos_del_ingreso',
									'sin_hallazgo_clinico'
								)
								AND (C.[value] = 'true' OR TRY_CAST(C.[value] AS bit) = 1)
							),
							-- Regla: cada celda marcada en "Hallazgos del ingreso" exige al menos un item
							-- de evaluacion clinica en la MISMA celda (columna + lateralidad), ej. muslo__izq.
							-- Filas excluidas: hallazgos_del_ingreso, sin_hallazgo_clinico.
							-- Si no hay hallazgos del ingreso marcados, no bloquea.
							HALLAZGOS_SIN_DEFINIR AS (
								SELECT H.CELL_KEY
								FROM HALLAZGOS_INGRESO H
								WHERE NOT EXISTS (
									SELECT 1 FROM EVALUACION_CLINICA E
									WHERE E.CELL_KEY = H.CELL_KEY
								)
							)
							SELECT @CMD = STUFF((
								SELECT ', ' + DBO.FNK_CAPITALIZAR_TEXTO(REPLACE(HS.CELL_KEY, '__', ' '))
								FROM HALLAZGOS_SIN_DEFINIR HS
								ORDER BY HS.CELL_KEY
								FOR XML PATH(''), TYPE
							).value('.', 'VARCHAR(MAX)'), 1, 2, '')

							IF COALESCE(@CMD, '') <> ''
							BEGIN
								RAISERROR(
									'Existen hallazgos marcados en "Hallazgos del ingreso" para las siguientes celdas: %s. Debe marcar al menos un item de la evaluacion clinica en la misma celda/lateralidad antes de guardar.',
									16,
									1,
									@CMD
								)
								RETURN
							END
						END
					END
				END

				INSERT INTO HCATD (CONSECUTIVO,ITEMRED,CODOM,IDSERVICIO,CANTIDAD,VIA,OBSERVACION,CLASE,FRECUENCIA,DURACION,TIPO
					,PRIMER,CODPAQUETE,LUNES,MARTES,MIERCOLES,JUEVES,VIERNES,SABADO,DOMINGO,RAZONNEC,DOSISUNICA,NDOSISINICIO,CANTIDADBOLO
					,IDSERVICIOMEZCLA,QMEZCLA,IDTIPOCONC,HORAAM,HORAPM,QAM,QPM ,FECHAINI,IDCAUSAL,AVISADOENF,RUTA ,TOTALUNIDADES
					,PRESCRIPCION ,TIPODURACION,TIPOFRECUENCIA ,ITEM_DXUNIRS,IDDX,EFECTOS ,TOTAL_CONTROLADOS, ENCARGOS ,NOPRESTACION
					,NOINGRESO ,FFINALDOSIS ,COPIADO ,CANTIDADORI ,FRECUENCIAORI ,DURACIONORI ,GOTEO ,DOSIF ,TIPOSOLBS ,BSCAPACIDAD
					,QIMPSERVICIO ,QIMPMEZCLA ,DURACIONIMP ,IDBODEGA ,PROTOCOLO ,APLICADA ,CANTDIAS ,ENAYUNO
                    ,STAFF
                    ,PRIORIDADES_STAFF ,CASO_DIFICIL_STAFF ,ID_PRIO_STAFF ,OBSERVACION_STAFF ,FECHA_STAFF ,ESTADO_STAFF ,CATEGORIA_STAFF
					,ID_CHECKLIST, NIVEL_PREVENCION, IDPATOLOGIA, FORMULADO_STAFF, FORM_ESPECIAL, NOINSTITUCIONAL, LATERALIDAD, SEGMENTO, CATEGORIATM
					,DOSIS_TITULABLE
				)
				SELECT @CONSECUTIVO
					,@ITEMRED
					,CASE
						WHEN CODOM IS NOT NULL
							THEN CODOM
						ELSE (
								SELECT TOP 1 HCCOM.CODOM
								FROM HCCOMD
								INNER JOIN hccom ON hccom.CODOM = hccomd.CODOM
									AND PREFIJO = (
										SELECT PREFIJO
										FROM SER
										WHERE IDSERVICIO = #HCATD.IDSERVICIO
										)
								)
						END
					,#HCATD.IDSERVICIO ,#HCATD.CANTIDAD ,COALESCE(#HCATD.VIA,'No Aplica') ,COALESCE(OBSERVACION,'') ,IIF(@DAALTA=1, 'S', CLASE)
					,CASE WHEN COALESCE(FRECUENCIA,'')='' THEN 24 ELSE CAST(FRECUENCIA AS DECIMAL(14,2)) END
					,COALESCE((DURACION * CASE
						WHEN CLASE = 'C'
							THEN 1
						ELSE CASE
								WHEN TIPODURACION = 'D'
									THEN 24
								ELSE 1
								END
						END),24)
					,ISNULL(#HCATD.TIPO, 'Horaria')
					,CASE ROW_NUMBER() OVER (PARTITION BY #HCATD.CODOM ORDER BY #HCATD.CODOM)
						WHEN 1 THEN 1
						ELSE 0 END
					,CODPAQUETE ,LUNES ,MARTES ,MIERCOLES ,JUEVES ,VIERNES ,SABADO ,DOMINGO ,RAZONNEC ,DOSISUNICA
					,NDOSISINICIO
					,try_cast(CANTIDADBOLO as decimal(14,2))
                    ,IDSERVICIOMEZCLA
                    ,try_cast(QMEZCLA as decimal(14,2))
                    ,SER.PRESUNI
                    ,HORAAM
                    ,HORAPM
                    ,try_cast(QAM as decimal(14,2))
                    ,try_cast(QPM as decimal(14,2))
                    ,REPLACE(FECHAINI,'-','')+' '+HORAINI
                    ,IDCAUSAL
					,IIF(@NUEVA_HCA=1 AND CLASE IN ('S','B'),0,AVISADOENF)
					,IIF(@PROT_PROCESO=3,1,COALESCE(#HCATD.RUTA, 0))
					,IIF(COALESCE(TRY_CAST(TOTALUNIDADES AS INT), 0) < 1, 1, CAST(CAST(TOTALUNIDADES AS DECIMAL(14,2)) AS INT))
                    ,PRESCRIPCION
					,COALESCE(TIPODURACION, 'D')
                    ,TIPOFRECUENCIA
					,ITEM_DXUNIRS
                    ,IDDX
                    ,EFECTOS
					,TOTAL_CONTROLADOS
					,ENCARGOS
					,NOPRESTACION
					,NOINGRESO
					,IIF(@DAALTA=1, @HORASUSPENDE,
					            IIF(COALESCE(FFINALDOSIS+HFINALDOSIS,'')='',NULL,REPLACE(FFINALDOSIS,'-','')+' '+HFINALDOSIS))
				    ,#HCATD.COPIADO
                    ,#HCATD.CANTIDADORI
                    ,#HCATD.FRECUENCIAORI
                    ,#HCATD.DURACIONORI
					,#HCATD.GOTEO
                    ,#HCATD.DOSIF
                    ,#HCATD.TIPOSOLBS
                    ,#HCATD.BSCAPACIDAD
					,try_cast(#HCATD.QIMPSERVICIO as decimal(14,2))
					,try_cast(#HCATD.QIMPMEZCLA as decimal(14,2))
					,try_cast(#HCATD.DURACIONIMP as decimal(14,2))
					,#HCATD.IDBODEGA
					,#HCATD.PROTOCOLO
					,COALESCE(#HCATD.APLICADA,0)
					,COALESCE(#HCATD.CANTDIAS,0)
					,IIF(COALESCE(#HCATD.ENAYUNO, 0)=0,NULL,1)
					,COALESCE(#HCATD.STAFF,0)
                    /*Si tiene un idceom significa que es de tratamientoactivo, por ende ya no necesita staff*/
					,IIF(#HCATD.STAFF=1,PRIORIDADES_STAFF,NULL)
					,IIF(#HCATD.STAFF=1,CASO_DIFICIL_STAFF,NULL)
					,IIF(#HCATD.STAFF=1,ID_PRIO_STAFF,NULL)
					,IIF(#HCATD.STAFF=1,OBSERVACION_STAFF,NULL)
					,IIF(#HCATD.STAFF=1,GETDATE(),NULL)
					,IIF(#HCATD.STAFF=1,'PENDIENTE',NULL)
					,IIF(#HCATD.STAFF=1,MPE.CATEGORIA_STAFF,NULL)
					,IIF(#HCATD.STAFF=1,MPE.ID_CHECKLIST,NULL)
                    /**/
					,NIVEL_PREVENCION
					,#HCATD.IDPATOLOGIA
					,#HCATD.FORMULADO_STAFF
					,#HCATD.ANT_VIG
					,COALESCE(#HCATD.NOINSTITUCIONAL, 0)
					,COALESCE(#HCATD.LATERALIDAD, 'No aplica')
					,COALESCE(#HCATD.SEGMENTO, @SEGMENTO) -- NUEVO: persistencia de segmento
					,#HCATD.CATEGORIATM
					,#HCATD.DOSIS_TITULABLE
                FROM #HCATD
				LEFT JOIN SER ON SER.IDSERVICIO = #HCATD.IDSERVICIO
				LEFT JOIN MPE ON MPE.IDPESPECIAL = @IDPESPECIAL
				WHERE #HCATD.ID IS NULL

				-- Protocolo: auditoría (TIPO=Auditoria) o justificación de ciclo (TIPO=Justificacion ? HCATD_AUD.JUSTIFICACION).
				IF @VALIDAR_SER_PROT = 'SI'
				BEGIN
					IF COALESCE(@MIN_CARACTER_PROT, 0) < 1
						SET @MIN_CARACTER_PROT = 1

					UPDATE H
					SET REQ_AUDITORIA = CASE
						WHEN EXISTS (
							SELECT 1
							FROM #HCATD T
							WHERE T.IDSERVICIO = H.IDSERVICIO
							  AND (
									T.ID = H.ID
									OR (T.ID IS NULL AND H.CONSECUTIVO = @CONSECUTIVO)
							  )
							  AND COALESCE(T.ID_HCATD_AUD, 0) > 0
						) THEN 0
						WHEN EXISTS (
							SELECT 1
							FROM AFIPROT AP WITH (NOLOCK)
							INNER JOIN PROTD D WITH (NOLOCK)
								ON (
									D.ID = AP.IDPROTD
									OR (
										AP.IDPROTD IS NULL
										AND D.IDPROT = AP.IDPROT
										AND D.IDSERVICIO = AP.IDSERVICIO
									)
								)
							INNER JOIN PROT PR WITH (NOLOCK)
								ON PR.ID = D.IDPROT
							WHERE AP.IDAFILIADO = @IDAFILIADO
							  AND AP.IDSERVICIO = H.IDSERVICIO
							  AND D.IDSERVICIO = H.IDSERVICIO
							  AND COALESCE(AP.ESTADO, '') NOT IN ('Anulado', 'Cancelado')
							  AND COALESCE(PR.ESTADO, 'Activo') = 'Activo'
							  AND COALESCE(D.ESTADO, 'Activo') = 'Activo'
							  AND D.JUSTIFICACION = 'Auditoria'
						) THEN 1
						WHEN @PROT_PROCESO = 1
						  AND COALESCE(@PROT_ID, 0) > 0
						  AND EXISTS (
							SELECT 1
							FROM PROTD D WITH (NOLOCK)
							INNER JOIN PROT PR WITH (NOLOCK)
								ON PR.ID = D.IDPROT
							WHERE D.IDPROT = @PROT_ID
							  AND D.IDSERVICIO = H.IDSERVICIO
							  AND COALESCE(PR.ESTADO, 'Activo') = 'Activo'
							  AND COALESCE(D.ESTADO, 'Activo') = 'Activo'
							  AND UPPER(LTRIM(RTRIM(REPLACE(COALESCE(D.JUSTIFICACION, ''), N'Í', 'I')))) = 'AUDITORIA'
						  ) THEN 1
						-- Cita Modelo: protocolo en AFIPE.IDPROT sin filas AFIPROT aún
						WHEN @CLASEORDENX = 'Modelo'
						  AND COALESCE(@PROT_IDPESPECIAL, @IDPESPECIAL_CITA, @IDPESPECIAL_CIT, '') <> ''
						  AND EXISTS (
							SELECT 1
							FROM AFIPE PE WITH (NOLOCK)
							INNER JOIN PROTD D WITH (NOLOCK)
								ON D.IDPROT = PE.IDPROT
							   AND D.IDSERVICIO = H.IDSERVICIO
							INNER JOIN PROT PR WITH (NOLOCK)
								ON PR.ID = D.IDPROT
							WHERE PE.IDAFILIADO = @IDAFILIADO
							  AND PE.IDPESPECIAL = COALESCE(@PROT_IDPESPECIAL, @IDPESPECIAL_CITA, @IDPESPECIAL_CIT)
							  AND COALESCE(PE.ESTADO, 'Activo') = 'Activo'
							  AND PE.FECHAFINAL IS NULL
							  AND COALESCE(PE.IDPROT, 0) > 0
							  AND COALESCE(PR.ESTADO, 'Activo') = 'Activo'
							  AND COALESCE(D.ESTADO, 'Activo') = 'Activo'
							  AND UPPER(LTRIM(RTRIM(REPLACE(COALESCE(D.JUSTIFICACION, ''), N'Í', 'I')))) = 'AUDITORIA'
							  AND NOT EXISTS (
								SELECT 1
								FROM AFIPROT AP WITH (NOLOCK)
								WHERE AP.IDAFILIADO = @IDAFILIADO
								  AND AP.IDSERVICIO = H.IDSERVICIO
								  AND COALESCE(AP.ESTADO, '') NOT IN ('Anulado', 'Cancelado')
							  )
						  ) THEN 1
						ELSE 0
					END
					FROM HCATD H
					WHERE H.CONSECUTIVO = @CONSECUTIVO

					INSERT INTO DBO.HCATD_AUD (ID_HCATD, CONSECUTIVO_HCATD, ESTADO, FECHA, USUARIO, TIPO, JUSTIFICACION)
					SELECT
						H.ID,
						H.CONSECUTIVO,
						'Pendiente',
						GETDATE(),
						@USUARIO,
						'Auditoria',
						LTRIM(RTRIM(T.JUSTIFICACION_PROT))
					FROM HCATD H
					INNER JOIN #HCATD T
						ON T.IDSERVICIO = H.IDSERVICIO
					   AND (
							T.ID = H.ID
							OR (T.ID IS NULL AND H.CONSECUTIVO = @CONSECUTIVO)
					   )
					WHERE H.CONSECUTIVO = @CONSECUTIVO
					  AND COALESCE(H.REQ_AUDITORIA, 0) = 1
					  AND NULLIF(LTRIM(RTRIM(T.JUSTIFICACION_PROT)), '') IS NOT NULL
					  AND LEN(LTRIM(RTRIM(T.JUSTIFICACION_PROT))) >= @MIN_CARACTER_PROT
					  AND NOT EXISTS (SELECT 1 FROM DBO.HCATD_AUD X WHERE X.ID_HCATD = H.ID)
					  AND NOT EXISTS (
							SELECT 1
							FROM #HCATD T
							WHERE T.IDSERVICIO = H.IDSERVICIO
							  AND (
									T.ID = H.ID
									OR (T.ID IS NULL AND H.CONSECUTIVO = @CONSECUTIVO)
							  )
							  AND COALESCE(T.ID_HCATD_AUD, 0) > 0
					  )

					INSERT INTO DBO.HCATD_AUD (ID_HCATD, CONSECUTIVO_HCATD, ESTADO, FECHA, USUARIO, TIPO, JUSTIFICACION)
					SELECT
						H.ID,
						H.CONSECUTIVO,
						'Aprobado',
						GETDATE(),
						@USUARIO,
						'Justificacion',
						LTRIM(RTRIM(T.JUSTIFICACION_PROT))
					FROM HCATD H
					INNER JOIN #HCATD T
						ON T.IDSERVICIO = H.IDSERVICIO
					   AND (
							T.ID = H.ID
							OR (T.ID IS NULL AND H.CONSECUTIVO = @CONSECUTIVO)
					   )
					WHERE H.CONSECUTIVO = @CONSECUTIVO
					  AND NULLIF(LTRIM(RTRIM(T.JUSTIFICACION_PROT)), '') IS NOT NULL
					  AND LEN(LTRIM(RTRIM(T.JUSTIFICACION_PROT))) >= @MIN_CARACTER_PROT
					  AND (
							EXISTS (
							SELECT 1
							FROM AFIPROT AP WITH (NOLOCK)
							INNER JOIN PROTD D WITH (NOLOCK)
								ON (
									D.ID = AP.IDPROTD
									OR (
										AP.IDPROTD IS NULL
										AND D.IDPROT = AP.IDPROT
										AND D.IDSERVICIO = AP.IDSERVICIO
									)
								)
							INNER JOIN PROT PR WITH (NOLOCK)
								ON PR.ID = D.IDPROT
							WHERE AP.IDAFILIADO = @IDAFILIADO
							  AND AP.IDSERVICIO = H.IDSERVICIO
							  AND D.IDSERVICIO = H.IDSERVICIO
							  AND COALESCE(AP.ESTADO, '') NOT IN ('Anulado', 'Cancelado')
							  AND COALESCE(PR.ESTADO, 'Activo') = 'Activo'
							  AND COALESCE(D.ESTADO, 'Activo') = 'Activo'
							  AND UPPER(LTRIM(RTRIM(REPLACE(COALESCE(D.JUSTIFICACION, ''), N'Í', 'I')))) = 'JUSTIFICACION'
							)
							OR (
								@CLASEORDENX = 'Modelo'
								AND COALESCE(@PROT_IDPESPECIAL, @IDPESPECIAL_CITA, @IDPESPECIAL_CIT, '') <> ''
								AND EXISTS (
									SELECT 1
									FROM AFIPE PE WITH (NOLOCK)
									INNER JOIN PROTD D WITH (NOLOCK)
										ON D.IDPROT = PE.IDPROT
									   AND D.IDSERVICIO = H.IDSERVICIO
									INNER JOIN PROT PR WITH (NOLOCK)
										ON PR.ID = D.IDPROT
									WHERE PE.IDAFILIADO = @IDAFILIADO
									  AND PE.IDPESPECIAL = COALESCE(@PROT_IDPESPECIAL, @IDPESPECIAL_CITA, @IDPESPECIAL_CIT)
									  AND COALESCE(PE.ESTADO, 'Activo') = 'Activo'
									  AND PE.FECHAFINAL IS NULL
									  AND COALESCE(PE.IDPROT, 0) > 0
									  AND COALESCE(PR.ESTADO, 'Activo') = 'Activo'
									  AND COALESCE(D.ESTADO, 'Activo') = 'Activo'
									  AND UPPER(LTRIM(RTRIM(REPLACE(COALESCE(D.JUSTIFICACION, ''), N'Í', 'I')))) = 'JUSTIFICACION'
									  AND NOT EXISTS (
										SELECT 1
										FROM AFIPROT AP WITH (NOLOCK)
										WHERE AP.IDAFILIADO = @IDAFILIADO
										  AND AP.IDSERVICIO = H.IDSERVICIO
										  AND COALESCE(AP.ESTADO, '') NOT IN ('Anulado', 'Cancelado')
									  )
								)
							)
					  )
					  AND NOT EXISTS (SELECT 1 FROM DBO.HCATD_AUD X WHERE X.ID_HCATD = H.ID)
					  AND NOT EXISTS (
							SELECT 1
							FROM #HCATD TX
							WHERE TX.IDSERVICIO = H.IDSERVICIO
							  AND (
									TX.ID = H.ID
									OR (TX.ID IS NULL AND H.CONSECUTIVO = @CONSECUTIVO)
							  )
							  AND COALESCE(TX.ID_HCATD_AUD, 0) > 0
					  )
				END

				-- PROA: sincronizar HCATD_PROA (justificación médico) para Iniciar + RESTRINGIDO=1
				-- Inserta si no existe; si existe, actualiza FORM_ESPECIAL/TIPO_PROCESO/snapshot sin tocar respuesta epi.
				IF OBJECT_ID('DBO.HCATD_PROA', 'U') IS NOT NULL
				BEGIN
					DECLARE @PROA_CNSPROA VARCHAR(20), @PROA_CNSPROAH VARCHAR(20)
					DECLARE @PROA_IDSERVICIO VARCHAR(20), @PROA_CODOM VARCHAR(10), @PROA_ITEMRED INT
					DECLARE @PROA_PRESCRIPCION VARCHAR(500), @PROA_VIA VARCHAR(13)
					DECLARE @PROA_FREQ DECIMAL(14,2), @PROA_TIPOFREQ VARCHAR(20)
					DECLARE @PROA_DIAS DECIMAL(14,2), @PROA_FECHAINI DATETIME, @PROA_FECHA_VENCE DATETIME
					DECLARE @PROA_TIPO_PROC VARCHAR(80), @PROA_FORM NVARCHAR(MAX)
					DECLARE @PROA_TIPODUR VARCHAR(1)
					DECLARE @PROA_FORM_ANT NVARCHAR(MAX), @PROA_TIPO_ANT VARCHAR(80)
					DECLARE @PROA_PRES_ANT VARCHAR(500), @PROA_DIAS_ANT DECIMAL(14,2)
					DECLARE @PROA_ESTADO_INI VARCHAR(20), @PROA_AUT_INF VARCHAR(20), @PROA_AUT_EPI VARCHAR(10)
					DECLARE @PROA_ESTADO_ANT VARCHAR(20)

					DECLARE cur_proa CURSOR LOCAL FAST_FORWARD FOR
						SELECT H.IDSERVICIO, H.CODOM, H.ITEMRED, H.PRESCRIPCION, H.VIA,
							H.FRECUENCIA, H.TIPOFRECUENCIA, H.DURACION, H.TIPODURACION,
							H.FECHAINI, H.FORM_ESPECIAL
						FROM HCATD H WITH (NOLOCK)
						INNER JOIN SER S WITH (NOLOCK) ON S.IDSERVICIO = H.IDSERVICIO
						WHERE H.CONSECUTIVO = @CONSECUTIVO
						  AND H.CLASE = 'I'
						  AND COALESCE(S.RESTRINGIDO, 0) = 1;

					OPEN cur_proa;
					FETCH NEXT FROM cur_proa INTO @PROA_IDSERVICIO, @PROA_CODOM, @PROA_ITEMRED, @PROA_PRESCRIPCION, @PROA_VIA,
						@PROA_FREQ, @PROA_TIPOFREQ, @PROA_DIAS, @PROA_TIPODUR, @PROA_FECHAINI, @PROA_FORM;
					WHILE @@FETCH_STATUS = 0
					BEGIN
						IF COALESCE(@PROA_TIPODUR, 'D') = 'D' AND COALESCE(@PROA_DIAS, 0) >= 24
							SET @PROA_DIAS = @PROA_DIAS / 24.0;
						ELSE IF COALESCE(@PROA_TIPODUR, 'D') = 'H'
							SET @PROA_DIAS = CASE WHEN COALESCE(@PROA_DIAS, 0) <= 0 THEN 1 ELSE CEILING(@PROA_DIAS / 24.0) END;
						IF COALESCE(@PROA_DIAS, 0) <= 0 SET @PROA_DIAS = 1;
						IF @PROA_FECHAINI IS NULL SET @PROA_FECHAINI = GETDATE();
						SET @PROA_FECHA_VENCE = DATEADD(DAY, CAST(@PROA_DIAS AS INT), @PROA_FECHAINI);

						-- Extraer TIPO_PROCESO: preferir CAMPO estable; fallback DESCCAMPO histórico
						SET @PROA_TIPO_PROC = NULL;
						IF ISJSON(@PROA_FORM) = 1
						BEGIN
							SELECT TOP 1 @PROA_TIPO_PROC = JSON_VALUE(m.value, '$.VALOR')
							FROM OPENJSON(@PROA_FORM, '$.MPLD') m
							WHERE UPPER(COALESCE(JSON_VALUE(m.value, '$.CAMPO'), '')) = 'TIPO_PROCESO'
							ORDER BY TRY_CAST(JSON_VALUE(m.value, '$.SECUENCIA') AS INT);

							IF @PROA_TIPO_PROC IS NULL
							BEGIN
								SELECT TOP 1 @PROA_TIPO_PROC = JSON_VALUE(m.value, '$.VALOR')
								FROM OPENJSON(@PROA_FORM, '$.MPLD') m
								WHERE UPPER(COALESCE(JSON_VALUE(m.value, '$.DESCCAMPO'), '')) LIKE '%TIPO%PROCESO%'
								ORDER BY TRY_CAST(JSON_VALUE(m.value, '$.SECUENCIA') AS INT);
							END
						END;

						SET @PROA_ESTADO_INI = 'Solicitado';
						SET @PROA_AUT_INF = 'No Aplica';
						SET @PROA_AUT_EPI = 'No';
						IF COALESCE(@PROA_TIPO_PROC, '') = 'Profiláctico'
						BEGIN
							SET @PROA_ESTADO_INI = 'Aprobado';
							SET @PROA_AUT_EPI = 'Si';
						END;

						SET @PROA_CNSPROA = NULL;
						SET @PROA_FORM_ANT = NULL;
						SET @PROA_TIPO_ANT = NULL;
						SET @PROA_PRES_ANT = NULL;
						SET @PROA_DIAS_ANT = NULL;

						SELECT TOP 1
							@PROA_CNSPROA = P.CNSPROA,
							@PROA_FORM_ANT = P.FORM_ESPECIAL,
							@PROA_TIPO_ANT = P.TIPO_PROCESO,
							@PROA_PRES_ANT = P.PRESCRIPCION,
							@PROA_DIAS_ANT = P.DIAS_TRATAMIENTO,
							@PROA_ESTADO_ANT = P.ESTADO
						FROM DBO.HCATD_PROA P WITH (UPDLOCK, HOLDLOCK)
						WHERE P.ESTADO_REG = 'A'
						  AND P.CONSECUTIVO = @CONSECUTIVO
						  AND P.IDSERVICIO = @PROA_IDSERVICIO
						  AND COALESCE(P.CODOM, '') = COALESCE(@PROA_CODOM, '')
						  AND COALESCE(P.ITEMRED, -1) = COALESCE(@PROA_ITEMRED, -1);

						IF @PROA_CNSPROA IS NOT NULL
						BEGIN
							-- Sync justificación médica; profilaxis Solicitado ? auto Aprobado
							UPDATE DBO.HCATD_PROA
							SET PRESCRIPCION = @PROA_PRESCRIPCION,
								VIA = @PROA_VIA,
								FRECUENCIA = @PROA_FREQ,
								TIPOFRECUENCIA = @PROA_TIPOFREQ,
								DIAS_TRATAMIENTO = @PROA_DIAS,
								DIAS_AUTORIZADOS = CASE
									WHEN ESTADO = 'Solicitado' THEN @PROA_DIAS
									ELSE COALESCE(DIAS_AUTORIZADOS, @PROA_DIAS)
								END,
								FECHAINI_TRAT = @PROA_FECHAINI,
								FECHA_VENCE = CASE
									WHEN ESTADO = 'Solicitado' THEN @PROA_FECHA_VENCE
									WHEN DIAS_AUTORIZADOS IS NOT NULL AND FECHAINI_TRAT IS NOT NULL
										THEN DATEADD(DAY, CAST(COALESCE(DIAS_AUTORIZADOS, @PROA_DIAS) AS INT), COALESCE(FECHAINI_TRAT, @PROA_FECHAINI))
									ELSE @PROA_FECHA_VENCE
								END,
								TIPO_PROCESO = @PROA_TIPO_PROC,
								FORM_ESPECIAL = @PROA_FORM,
								AUT_INFECTOLOGIA = CASE
									WHEN COALESCE(@PROA_TIPO_PROC, '') = 'Profiláctico' AND ESTADO = 'Solicitado' THEN 'No Aplica'
									ELSE AUT_INFECTOLOGIA
								END,
								AUT_EPIDEMIOLOGIA = CASE
									WHEN COALESCE(@PROA_TIPO_PROC, '') = 'Profiláctico' AND ESTADO = 'Solicitado' THEN 'Si'
									ELSE AUT_EPIDEMIOLOGIA
								END,
								ESTADO = CASE
									WHEN COALESCE(@PROA_TIPO_PROC, '') = 'Profiláctico' AND ESTADO = 'Solicitado' THEN 'Aprobado'
									ELSE ESTADO
								END
							WHERE CNSPROA = @PROA_CNSPROA;

							IF COALESCE(@PROA_FORM_ANT, '') <> COALESCE(@PROA_FORM, '')
								OR COALESCE(@PROA_TIPO_ANT, '') <> COALESCE(@PROA_TIPO_PROC, '')
								OR COALESCE(@PROA_PRES_ANT, '') <> COALESCE(@PROA_PRESCRIPCION, '')
								OR COALESCE(@PROA_DIAS_ANT, -1) <> COALESCE(@PROA_DIAS, -1)
								OR (
									COALESCE(@PROA_TIPO_PROC, '') = 'Profiláctico'
									AND COALESCE(@PROA_ESTADO_ANT, '') = 'Solicitado'
								)
							BEGIN
								SET @PROA_CNSPROAH = NULL;
								BEGIN TRY
									EXEC DBO.SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@HCATDPROAH', @PROA_CNSPROAH OUTPUT;
									SELECT @PROA_CNSPROAH = LEFT(@SEDE, 2) + REPLACE(SPACE(8 - LEN(@PROA_CNSPROAH)) + LTRIM(RTRIM(@PROA_CNSPROAH)), SPACE(1), '0');
								END TRY
								BEGIN CATCH
									SET @PROA_CNSPROAH = LEFT(REPLACE(CONVERT(VARCHAR(36), NEWID()), '-', ''), 20);
								END CATCH;

								INSERT INTO DBO.HCATD_PROAH (CNSPROAH, CNSPROA, ACCION, ESTADO_ANT, ESTADO_NUEVO, DETALLE, USUARIO, FECHA)
								VALUES (
									@PROA_CNSPROAH, @PROA_CNSPROA,
									CASE WHEN COALESCE(@PROA_TIPO_PROC, '') = 'Profiláctico' AND COALESCE(@PROA_ESTADO_ANT, '') = 'Solicitado' THEN 'APROBAR' ELSE 'CAMBIAR' END,
									@PROA_ESTADO_ANT,
									CASE WHEN COALESCE(@PROA_TIPO_PROC, '') = 'Profiláctico' AND COALESCE(@PROA_ESTADO_ANT, '') = 'Solicitado' THEN 'Aprobado' ELSE NULL END,
									CONCAT('Sync FORM_ESPECIAL/TIPO_PROCESO OM=', @CONSECUTIVO, ' srv=', @PROA_IDSERVICIO),
									@USUARIO, GETDATE()
								);
							END
						END
						ELSE
						BEGIN
							-- Reformulación del mismo medicamento en la misma admisión: el sistema no
							-- permite "editar" una orden PROA, solo Suspender + Iniciar de nuevo. Si ya
							-- había otra solicitud PROA ACTIVA (ESTADO_REG='A') para este mismo
							-- NOADMISION+IDSERVICIO ligada a un Iniciar anterior (CONSECUTIVO distinto),
							-- queda superada por este nuevo Iniciar: se marca ESTADO_REG='I' para que deje
							-- de competir en el gate de IZSOL (ancla al Iniciar vigente, ver SPQ_IZSOL) y
							-- en el tablero de Seguimiento Epidemiológico. Histórico preservado en
							-- HCATD_PROAH. No aplica si es la primera solicitud (no actualiza filas).
							DECLARE @PROA_SUPERADOS TABLE (CNSPROA VARCHAR(20), ESTADO_ANT VARCHAR(20));

							UPDATE DBO.HCATD_PROA
							SET ESTADO_REG = 'I'
							OUTPUT deleted.CNSPROA, deleted.ESTADO INTO @PROA_SUPERADOS(CNSPROA, ESTADO_ANT)
							WHERE ESTADO_REG = 'A'
							  AND NOADMISION = @NOADMISION
							  AND IDSERVICIO = @PROA_IDSERVICIO
							  AND CONSECUTIVO <> @CONSECUTIVO;

							IF EXISTS (SELECT 1 FROM @PROA_SUPERADOS)
							BEGIN
								INSERT INTO DBO.HCATD_PROAH (CNSPROAH, CNSPROA, ACCION, ESTADO_ANT, ESTADO_NUEVO, DETALLE, USUARIO, FECHA)
								SELECT
									LEFT(REPLACE(CONVERT(VARCHAR(36), NEWID()), '-', ''), 20),
									S.CNSPROA, 'SUPERADO', S.ESTADO_ANT, S.ESTADO_ANT,
									CONCAT('Reformulación del mismo medicamento: reemplazada por nuevo Iniciar OM=', @CONSECUTIVO, ' srv=', @PROA_IDSERVICIO),
									@USUARIO, GETDATE()
								FROM @PROA_SUPERADOS S;
							END

							SET @PROA_CNSPROA = NULL;
							BEGIN TRY
								EXEC DBO.SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@HCATDPROA', @PROA_CNSPROA OUTPUT;
								SELECT @PROA_CNSPROA = LEFT(@SEDE, 2) + REPLACE(SPACE(8 - LEN(@PROA_CNSPROA)) + LTRIM(RTRIM(@PROA_CNSPROA)), SPACE(1), '0');
							END TRY
							BEGIN CATCH
								SET @PROA_CNSPROA = LEFT(REPLACE(CONVERT(VARCHAR(36), NEWID()), '-', ''), 20);
							END CATCH;

							INSERT INTO DBO.HCATD_PROA (
								CNSPROA, NOADMISION, IDAFILIADO, IDSERVICIO, CODOM, CONSECUTIVO, ITEMRED,
								PRESCRIPCION, VIA, FRECUENCIA, TIPOFRECUENCIA, DIAS_TRATAMIENTO, DIAS_AUTORIZADOS, FECHAINI_TRAT, FECHA_VENCE,
								TIPO_PROCESO, FORM_ESPECIAL,
								AJUSTADO_A, DOSIS_RENAL, FALLA_HEPATICA, AUT_INFECTOLOGIA, AUT_EPIDEMIOLOGIA,
								ESTADO, IDUSUARIO_SOL, FECHA_SOL, ESTADO_REG
							)
							VALUES (
								@PROA_CNSPROA, @NOADMISION, @IDAFILIADO, @PROA_IDSERVICIO, @PROA_CODOM, @CONSECUTIVO, @PROA_ITEMRED,
								@PROA_PRESCRIPCION, @PROA_VIA, @PROA_FREQ, @PROA_TIPOFREQ, @PROA_DIAS, @PROA_DIAS, @PROA_FECHAINI, @PROA_FECHA_VENCE,
								@PROA_TIPO_PROC, @PROA_FORM,
								'No', 'No', 'No', @PROA_AUT_INF, @PROA_AUT_EPI,
								@PROA_ESTADO_INI, @USUARIO, GETDATE(), 'A'
							);

							SET @PROA_CNSPROAH = NULL;
							BEGIN TRY
								EXEC DBO.SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@HCATDPROAH', @PROA_CNSPROAH OUTPUT;
								SELECT @PROA_CNSPROAH = LEFT(@SEDE, 2) + REPLACE(SPACE(8 - LEN(@PROA_CNSPROAH)) + LTRIM(RTRIM(@PROA_CNSPROAH)), SPACE(1), '0');
							END TRY
							BEGIN CATCH
								SET @PROA_CNSPROAH = LEFT(REPLACE(CONVERT(VARCHAR(36), NEWID()), '-', ''), 20);
							END CATCH;

							INSERT INTO DBO.HCATD_PROAH (CNSPROAH, CNSPROA, ACCION, ESTADO_ANT, ESTADO_NUEVO, DETALLE, USUARIO, FECHA)
							VALUES (@PROA_CNSPROAH, @PROA_CNSPROA, 'CREAR', NULL, @PROA_ESTADO_INI, @PROA_PRESCRIPCION, @USUARIO, GETDATE());
						END

						FETCH NEXT FROM cur_proa INTO @PROA_IDSERVICIO, @PROA_CODOM, @PROA_ITEMRED, @PROA_PRESCRIPCION, @PROA_VIA,
							@PROA_FREQ, @PROA_TIPOFREQ, @PROA_DIAS, @PROA_TIPODUR, @PROA_FECHAINI, @PROA_FORM;
					END;
					CLOSE cur_proa; DEALLOCATE cur_proa;
				END

				DECLARE @IDHCATD INT
				DECLARE @IDHCATD_STAFF INT
				DECLARE @MENOR BIT = 0

				SELECT @IDHCATD = ID
				FROM HCATD
				WHERE CONSECUTIVO=@CONSECUTIVO
				AND NIVEL_PREVENCION=2

				IF @IDHCATD IS NOT NULL
				BEGIN
					INSERT INTO HCATD_STAFF(CONSECUTIVO,USUARIO,ID_HCATD)
					SELECT @CONSECUTIVO, @USUARIO, ID
					FROM HCATD
					WHERE CONSECUTIVO=@CONSECUTIVO
					AND NIVEL_PREVENCION=2
					AND NOT EXISTS(SELECT 1 FROM HCATD_STAFF WHERE CONSECUTIVO = HCATD.CONSECUTIVO AND ID_HCATD = HCATD.ID)

					SELECT @IDHCATD_STAFF = scope_identity()

                    -- If no insert occurred (duplicate exists), retrieve the existing ID
					IF @IDHCATD_STAFF IS NULL
						SELECT TOP 1 @IDHCATD_STAFF = ID FROM HCATD_STAFF WHERE CONSECUTIVO = @CONSECUTIVO AND ID_HCATD = @IDHCATD ORDER BY ID DESC

					IF @IDHCATD_STAFF IS NOT NULL
					BEGIN
						UPDATE HCATD_STAFF SET
							ESTADO_REV_ADMINISTRATIVA = 1,
							FFINALIZA_REV_ADM = GETDATE(),
							USUARIO_FIN_REV_ADM = @USUARIO,
                        ESTADO_CASO='STAFF'
						WHERE ID = @IDHCATD_STAFF

						INSERT INTO HCATD_STAFF_LOG(STAFF_ID, ACCION, VALOR_ANTERIOR, VALOR_NUEVO, FECHA, USUARIO)
						SELECT @IDHCATD_STAFF, 'Finaliza revision administrativa', 'No Finalizado', 'Finalizado', GETDATE(), @USUARIO
					END

				END
				ELSE
				BEGIN
					SELECT @IDHCATD = ID
					FROM HCATD
					INNER JOIN SER ON SER.IDSERVICIO=HCATD.IDSERVICIO
					WHERE CONSECUTIVO = @CONSECUTIVO AND HCATD.STAFF=1

					IF @IDHCATD IS NOT NULL
					BEGIN
						INSERT INTO HCATD_STAFF(CONSECUTIVO,USUARIO,ID_HCATD)
						SELECT @CONSECUTIVO, @USUARIO, @IDHCATD
                        FROM HCATD
					    WHERE ID=@IDHCATD AND NOT EXISTS(SELECT 1 FROM HCATD_STAFF WHERE CONSECUTIVO = HCATD.CONSECUTIVO AND ID_HCATD = HCATD.ID)

						SELECT @IDHCATD_STAFF = scope_identity()

                        -- If no insert occurred (duplicate exists), retrieve the existing ID
						IF @IDHCATD_STAFF IS NULL
							SELECT TOP 1 @IDHCATD_STAFF = ID FROM HCATD_STAFF WHERE CONSECUTIVO = @CONSECUTIVO AND ID_HCATD = @IDHCATD ORDER BY ID DESC

						SELECT @MENOR = IIF(DATEDIFF(DAY, AFI.FNACIMIENTO, current_timestamp) / (365.23076923074)<18,1,0) FROM AFI WHERE IDAFILIADO = @IDAFILIADO

						IF (@MENOR = 1 OR EXISTS(
							SELECT 1
							FROM CIT
							INNER JOIN MPE ON MPE.IDPESPECIAL = CIT.IDPESPECIAL
							WHERE CONSECUTIVO = @CONSECUTIVOCIT
							AND (
								(DESCESPECIAL LIKE '%OTRAS%' AND DESCESPECIAL LIKE '%AUTOINM%') OR
								DESCESPECIAL LIKE '%LUPUS%' OR
								DESCESPECIAL LIKE '%LES%'
							)
						)) AND @IDHCATD_STAFF IS NOT NULL
						BEGIN
							UPDATE HCATD_STAFF SET
								ESTADO_REV_ADMINISTRATIVA = 1,
								FFINALIZA_REV_ADM = GETDATE(),
								USUARIO_FIN_REV_ADM = @USUARIO,
                                ESTADO_CASO='STAFF'
							WHERE ID = @IDHCATD_STAFF

							INSERT INTO HCATD_STAFF_LOG(STAFF_ID, ACCION, VALOR_ANTERIOR, VALOR_NUEVO, FECHA, USUARIO)
							SELECT @IDHCATD_STAFF, 'Finaliza revision administrativa', 'No Finalizado', 'Finalizado', GETDATE(), @USUARIO
						END
					END
				END
				UPDATE CEOM SET
					CODOM=COALESCE(B.CODOM,'01'), CLASE =B.CLASE, ACTIVO =B.ACTIVO, EXTRAINSTITUCIONAL =B.EXTRAINSTITUCIONAL, RUTA =B.RUTA
                    ,CANTIDAD =B.CANTIDAD, FRECUENCIA =B.FRECUENCIA, DURACION =B.DURACION, TIPODURACION =B.TIPODURACION
                    ,TIPOFRECUENCIA =B.TIPOFRECUENCIA, TOTALUNIDADES =B.TOTALUNIDADES, OBSERVACION =B.OBSERVACION
                    ,PRESCRIPCION =B.PRESCRIPCION, VIA =B.VIA, FECHAINI =TRY_CAST(B.FECHAINI AS DATE)
                    ,CAUSASUSPENSION =B.CAUSASUSPENSION, OBSSUSPENSION=B.OBSSUSPENSION
                    ,FECHASUSPENDE =IIF(B.ACTIVO=0 AND TRY_CAST(B.FECHASUSPENDE AS DATE) IS NOT NULL,TRY_CAST(B.FECHASUSPENDE AS DATE),A.FECHASUSPENDE)
                    ,USUARIOSUSPENDE =IIF(B.ACTIVO=0 AND TRY_CAST(B.FECHASUSPENDE AS DATE) IS NOT NULL,@USUARIO,A.USUARIOSUSPENDE)
					,FECHAACTUALIZACION=GETDATE()
                FROM CEOM A
                INNER JOIN #CEOM B ON A.ID=B.IDCEOM
                WHERE A.IDAFILIADO=@IDAFILIADO

			    INSERT INTO CEOM (IDAFILIADO ,CONSECUTIVOHCA , CODOM, IDSERVICIO ,CLASE ,ACTIVO ,EXTRAINSTITUCIONAL ,RUTA ,CANTIDAD ,FRECUENCIA ,DURACION ,TIPODURACION ,
                    TIPOFRECUENCIA ,TOTALUNIDADES ,OBSERVACION ,PRESCRIPCION ,VIA ,FECHAINI , CAUSASUSPENSION ,OBSSUSPENSION,FECHASUSPENDE, FECHAFIN, FECHAACTUALIZACION)
                SELECT @IDAFILIADO ,@CONSECUTIVO , CODOM, IDSERVICIO ,CLASE ,ACTIVO ,EXTRAINSTITUCIONAL ,RUTA ,CANTIDAD ,FRECUENCIA ,DURACION ,TIPODURACION ,
                    TIPOFRECUENCIA ,TOTALUNIDADES ,OBSERVACION ,PRESCRIPCION ,VIA ,TRY_CAST(FECHAINI AS DATE),CAUSASUSPENSION ,OBSSUSPENSION
                    ,TRY_CAST(FECHASUSPENDE AS DATE)
                    ,CASE TIPODURACION WHEN 'H' THEN DATEADD(HOUR , TRY_CAST(DURACION AS SMALLINT), TRY_CAST(FECHAINI AS DATETIME))
                                        WHEN 'M' THEN DATEADD(MONTH , TRY_CAST(DURACION AS SMALLINT), TRY_CAST(FECHAINI AS DATE))
                                        ELSE DATEADD(DAY , TRY_CAST(DURACION AS SMALLINT), TRY_CAST(FECHAINI AS DATE))
                                        END
                    ,GETDATE()
                FROM #CEOM A
				WHERE A.IDCEOM IS NULL

                UPDATE HCPRUM SET  ESDISPONIBILIDAD = B.ESDISPONIBILIDAD, DISPONIBILIDAD = B.DISPONIBILIDAD
                    ,ESPRESCRIPCION = B.ESPRESCRIPCION, PRESCRIPCION = B.PRESCRIPCION, ESDISPENSACION=B.ESDISPENSACION
                    ,DISPENSACION=B.DISPENSACION, ESCALIDAD=B.ESCALIDAD, CALIDAD=B.CALIDAD, ESADMINISTRACION = B.ESADMINISTRACION
                    ,ADMINISTRACION=B.ADMINISTRACION, ESUSO=B.ESUSO, USO=B.USO, RECOMENDACIONES=B.RECOMENDACIONES
                FROM HCPRUM A INNER JOIN #HCPRUM B ON A.CONSECUTIVOHCA=B.CONSECUTIVOHCA AND A.IDAFILIADO=B.IDAFILIADO AND A.IDSERVICIO=B.IDSERVICIO

                INSERT INTO HCPRUM (CONSECUTIVOHCA ,IDAFILIADO ,IDMEDICO ,IDCEOM ,IDSERVICIO ,TIPO ,ESDISPONIBILIDAD ,DISPONIBILIDAD ,ESPRESCRIPCION ,PRESCRIPCION ,ESDISPENSACION ,DISPENSACION ,
                    ESCALIDAD ,CALIDAD ,ESADMINISTRACION ,ADMINISTRACION ,ESUSO ,USO ,RECOMENDACIONES )
                SELECT @CONSECUTIVO ,@IDAFILIADO ,@IDMEDICO ,C.ID ,A.IDSERVICIO, 'HCPRUM' ,A.ESDISPONIBILIDAD ,A.DISPONIBILIDAD ,A.ESPRESCRIPCION ,A.PRESCRIPCION ,A.ESDISPENSACION ,A.DISPENSACION ,
                    A.ESCALIDAD ,A.CALIDAD ,A.ESADMINISTRACION ,A.ADMINISTRACION ,A.ESUSO ,A.USO ,A.RECOMENDACIONES
			    FROM #HCPRUM A
                INNER JOIN CEOM C ON C.IDAFILIADO=@IDAFILIADO AND C.IDSERVICIO=A.IDSERVICIO
                WHERE NOT EXISTS (SELECT 1 FROM HCPRUM B WHERE B.CONSECUTIVOHCA=@CONSECUTIVO AND A.IDAFILIADO=B.IDAFILIADO AND A.IDSERVICIO=B.IDSERVICIO)


				UPDATE HCATD SET FECHAFIN=IIF(COALESCE(HCATD.CANTDIAS,0)>0, COALESCE(FECHAINI, GETDATE())+COALESCE(HCATD.CANTDIAS,0),NULL)
				WHERE CONSECUTIVO=@CONSECUTIVO

				--Servicios de ruta genere anexo 3 OSOLANO 2022.11.02
				IF @PROCEDENCIA='IPS'
					SELECT @IDTERCERO = IDTERCEROCA, @IDPLAN = IDPLAN FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT
				ELSE
					SELECT @IDTERCERO = IDADMINISTRADORA, @IDPLAN = IDPLAN FROM AFI WHERE IDAFILIADO = @IDAFILIADO

                SELECT @ANEXOAUTO = COALESCE(ANEXOAUTO,0) FROM PPT WHERE IDTERCERO=@IDTERCERO AND IDPLAN=@IDPLAN

				IF EXISTS (SELECT 1 FROM #HCATD WHERE COALESCE(RUTA,0)=IIF(@ANEXOAUTO=1,COALESCE(RUTA,0),1) AND COALESCE(#HCATD.ESTADO_STAFF,'')='')
                    AND @PROCEDENCIA<>'QX'
                    AND COALESCE(@IXCOUNTRY,'')<>'PERU'
					
				BEGIN
					--20240217 Se retira while ya que cliente indica que el anexo va agrupado y no dividido
					EXEC SPK_GENERA_ANEXO03_CE @CONSECUTIVO, NULL, @SEDE, @SYS_COMPUTERNAME, @ANEXOAUTO
				END

				--HCATDH Nutricion parenteral / Medicamentos dosis por jornada
				BEGIN
					DELETE HCATDH FROM HCATDH
					INNER JOIN #HCATD src ON src.IDSERVICIO = HCATDH.IDSERVICIO AND src.CODOM = HCATDH.CODOM
					WHERE HCATDH.CONSECUTIVO = @CONSECUTIVO
					  AND COALESCE(src.HCATDH,'') <> ''

					DECLARE _HcatdhCur CURSOR FOR
					SELECT IDSERVICIO, HCATDH FROM #HCATD

					OPEN _HcatdhCur
					FETCH NEXT FROM _HcatdhCur INTO @IDSERVICIO,@AUX

					WHILE @@FETCH_STATUS = 0
					BEGIN
						INSERT INTO HCATDH (CONSECUTIVO, ITEMRED, CODOM, IDSERVICIO ,HORA ,CANTIDAD ,IDSERVICIOD)
						SELECT
							@CONSECUTIVO AS CONSECUTIVO
							,@ITEMRED
							,#T.CODOM
							,#T.IDSERVICIO
							,COALESCE(#T.HORA,ROW_NUMBER() OVER (ORDER BY #T.IDSERVICIO, #T.CODOM))
							,#T.CANTIDAD
							,#T.IDSERVICIOD
						FROM OPENJSON(@AUX) WITH (
							IDSERVICIO VARCHAR(20) '$.IDSERVICIO'
							,CODOM VARCHAR(20) '$.CODOM'
							,HORA VARCHAR(2) '$.HORA'
							,CANTIDAD DECIMAL(14,2) '$.CANTIDAD'
							,IDSERVICIOD VARCHAR(20) '$.IDSERVICIOD'
						) #T
						FETCH NEXT FROM _HcatdhCur INTO @IDSERVICIO,@AUX
					END
					CLOSE _HcatdhCur
					DEALLOCATE _HcatdhCur
				END

				--HCATDPT Patologia
				BEGIN
					DELETE FROM HCATDPT
					WHERE IDHCATD IN (
						SELECT h.ID FROM HCATD h
						INNER JOIN #HCATD src ON src.IDSERVICIO = h.IDSERVICIO AND src.CODOM = h.CODOM
						WHERE h.CONSECUTIVO = @CONSECUTIVO AND COALESCE(src.HCATDPT,'') <> ''
					)

					DECLARE _HcatdptCur CURSOR FOR
					SELECT IDSERVICIO, HCATDPT FROM #HCATD

					OPEN _HcatdptCur
					FETCH NEXT FROM _HcatdptCur INTO @IDSERVICIO,@AUX

					WHILE @@FETCH_STATUS = 0
					BEGIN
                        INSERT INTO HCATDPT (IDHCATD ,PROCEDENCIA ,CONSECUTIVO ,CODOM ,IDSERVICIO ,TIEMPO_EVOLUCION ,FECHA_MUESTRA ,DATOS_CLINICOS ,PARTE_CUERPO ,LATERALIDAD ,HISTORIA_GINECO ,
                             TRATA_HORMONAL ,OTROS_TRATA ,NUMERO_MUESTRA ,METODO_OBTENCION ,HALLAZGOS_QX ,PIEZA_REMITIDA ,IDDX ,ESTADO 
                             ,USUARIO_ENTREGA ,USUARIO_TRANSPORTA ,MEDIO_TRANSPORTE ,
                             TEMP_ALMACENA ,FECHA_ENVIA ,FIJACION ,TIPO_FIJADOR ,TIPO_BIOPSIA ,TIPO_FALLA ,USUARIO_RECIBE ,OBS_RECIBE ,FECHA_RECIBE ,CORTES ,TIPO_ESTUDIO ,
                             IMPRESO ,CNSPATOLOGIA )
						SELECT HCATD.ID ,'OMEDICA',@CONSECUTIVO,HCATD.CODOM,@IDSERVICIO,#T.TIEMPO_EVOLUCION,REPLACE(TRY_CAST(FECHA_MUESTRA AS DATE),'-','')+' '+COALESCE(HORA_MUESTRA,'00:00')
							,#T.DATOS_CLINICOS,#T.PARTE_CUERPO,#T.LATERALIDAD,#T.HISTORIA_GINECO,#T.TRATA_HORMONAL,#T.OTROS_TRATA,#T.NUMERO_MUESTRA,#T.METODO_OBTENCION,
							#T.HALLAZGOS_QX,#T.PIEZA_REMITIDA,#T.IDDX,COALESCE(#T.ESTADO,'0'),#T.USUARIO_ENTREGA ,#T.USUARIO_TRANSPORTA,#T.MEDIO_TRANSPORT,#T.TEMP_ALMACENA		
                            ,TRY_CAST(#T.FECHA_ENVIA AS DATETIME),#T.FIJACION,#T.TIPO_FIJADOR,#T.TIPO_BIOPSIA,#T.TIPO_FALLA			
                            ,#T.USUARIO_RECIBE,#T.OBS_RECIBE,TRY_CAST(#T.FECHA_RECIBE AS DATETIME),#T.CORTES,#T.TIPO_ESTUDIO		
                            ,#T.IMPRESO,#T.CNSPATOLOGIA
						FROM OPENJSON(@AUX) WITH (
							TIEMPO_EVOLUCION	VARCHAR(MAX)	'$.TIEMPO_EVOLUCION'
							,FECHA_MUESTRA		VARCHAR(20)		'$.FECHA_MUESTRA'
							,HORA_MUESTRA		VARCHAR(20)		'$.HORA_MUESTRA'
							,DATOS_CLINICOS		VARCHAR(MAX)	'$.DATOS_CLINICOS'
							,PARTE_CUERPO		VARCHAR(50)		'$.PARTE_CUERPO'
							,LATERALIDAD		VARCHAR(50)		'$.LATERALIDAD'
							,HISTORIA_GINECO	VARCHAR(20)		'$.HISTORIA_GINECO'
							,TRATA_HORMONAL		VARCHAR(20)		'$.TRATA_HORMONAL'
							,OTROS_TRATA		VARCHAR(1024)	'$.OTROS_TRATA'
							,NUMERO_MUESTRA		SMALLINT		'$.NUMERO_MUESTRA'
							,METODO_OBTENCION	VARCHAR(50)		'$.METODO_OBTENCION'
							,HALLAZGOS_QX		VARCHAR(1024)	'$.HALLAZGOS_QX'
							,PIEZA_REMITIDA		VARCHAR(20)		'$.PIEZA_REMITIDA'
							,IDDX				VARCHAR(20)		'$.IDDX'
							,ESTADO				VARCHAR(20)		'$.ESTADO'
							,USUARIO_ENTREGA	VARCHAR(20)		'$.USUARIO_ENTREGA'
							,USUARIO_TRANSPORTA	VARCHAR(20)		'$.USUARIO_TRANSPORTA'
							,MEDIO_TRANSPORT	VARCHAR(20)		'$.MEDIO_TRANSPORTE'
							,TEMP_ALMACENA		SMALLINT		'$.TEMP_ALMACENA'
							,FECHA_ENVIA		VARCHAR(20)		'$.FECHA_ENVIA'
							,FIJACION			VARCHAR(50)		'$.FIJACION'
							,TIPO_FIJADOR		VARCHAR(20)		'$.TIPO_FIJADOR'
							,TIPO_BIOPSIA		VARCHAR(50)		'$.TIPO_BIOPSIA'
							,TIPO_FALLA			VARCHAR(50)		'$.TIPO_FALLA'
							,USUARIO_RECIBE		VARCHAR(20)		'$.USUARIO_RECIBE'
							,OBS_RECIBE 		VARCHAR(1024)	'$.OBS_RECIBE'
							,FECHA_RECIBE		VARCHAR(20)		'$.FECHA_RECIBE'
							,CORTES				SMALLINT		'$.CORTES'
							,TIPO_ESTUDIO		VARCHAR(1)	    '$.TIPO_ESTUDIO'
							,IMPRESO			BIT 		    '$.IMPRESO'
							,CNSPATOLOGIA		VARCHAR(20)		'$.CNSPATOLOGIA'
						) #T INNER JOIN HCATD ON HCATD.CONSECUTIVO=@CONSECUTIVO AND HCATD.IDSERVICIO=@IDSERVICIO
						FETCH NEXT FROM _HcatdptCur INTO @IDSERVICIO,@AUX
					END
					CLOSE _HcatdptCur
					DEALLOCATE _HcatdptCur
				END

				-- Citas de control en la HCA - EZERPA 24.05.2023
				BEGIN
					INSERT INTO HCATDC(CONSECUTIVOHCA,FECHA_SUGERIDA,IDSERVICIO,IDEMEDICA)
					SELECT CONSECUTIVO,
						CASE HCATD.TIPOFRECUENCIA
						WHEN 'D' THEN DATEADD(DAY,HCATD.FRECUENCIA,GETDATE())
						WHEN 'S' THEN DATEADD(WEEK,HCATD.FRECUENCIA,GETDATE())
						WHEN 'M' THEN DATEADD(MONTH,HCATD.FRECUENCIA,GETDATE())
						WHEN 'A' THEN DATEADD(YEAR,HCATD.FRECUENCIA,GETDATE())
						END,
						HCATD.IDSERVICIO,
						SER.IDEMEDICA
					FROM HCATD LEFT JOIN SER ON SER.IDSERVICIO=HCATD.IDSERVICIO
					WHERE CONSECUTIVO=@CONSECUTIVO
					AND CODOM = DBO.FNK_VALORVARIABLE('OMCODCITADECONTROL')
				END
				
				DELETE FROM HCATDO WHERE CONSECUTIVO=@CONSECUTIVO
				DELETE OD 
				FROM HCATDOD OD
				INNER JOIN HCATDO O ON O.ITEM=OD.HCATDO_ITEM
				WHERE O.CONSECUTIVO=@CONSECUTIVO
                -- Medicamentos Oncologicos EZERPA 01.06.2023
				DECLARE _cursor CURSOR FOR
				    SELECT IDSERVICIO,HCATDO FROM #HCATD
				OPEN _cursor
				FETCH NEXT FROM _cursor INTO @IDSERVICIO,@AUX

				WHILE @@FETCH_STATUS = 0
				BEGIN
					SELECT @ID_HCATD = ID FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVO AND IDSERVICIO=@IDSERVICIO

					INSERT INTO HCATDO (ID ,CONSECUTIVO ,IDSERVICIO ,IDSERVICIO_PPAL ,IDARTICULO ,CANTIDAD ,IDTIPOCONC ,VIA
						,OBSERVACION ,TIPOFRECUENCIA ,FRECUENCIA ,DURACION ,TOTALUNIDADES ,CICLOS ,PRESCRIPCION
						,PRESCRIPCION_CORTA ,TIPODURACION )
					SELECT
						@ID_HCATD AS ID
						,@CONSECUTIVO AS CONSECUTIVO
						,#T.IDSERVICIO
						,@IDSERVICIO IDSERVICIO_PPAL
						,SER.IDARTICULO
						,#T.CANTIDAD
						,SER.PRESUNI AS IDTIPOCONC
						,#T.VIA
						,#T.OBSERVACION
						,TIPOFRECUENCIA
						,DBO.FNK_LIMPIATEXTO(FRECUENCIA,'0-9,') FRECUENCIA
						,#T.DURACION
						,IIF(COALESCE(#T.TOTALUNIDADES, 0) < 1, 1, #T.TOTALUNIDADES)
						,#T.CICLOS
						,#T.PRESCRIPCION
						,LTRIM(RTRIM(#T.PRESCRIPCION_CORTA))
						,#T.TIPODURACION
					FROM OPENJSON(@AUX) WITH (
						IDSERVICIO VARCHAR(20) '$.IDSERVICIO'
						,CANTIDAD DECIMAL(14,2) '$.CANTIDAD'
						,VIA VARCHAR(50) '$.VIA'
						,OBSERVACION VARCHAR(MAX) '$.OBSERVACION'
						,TIPOFRECUENCIA VARCHAR(50) '$.TIPOFRECUENCIA'
						,FRECUENCIA NVARCHAR(MAX) AS JSON
						,DURACION INT '$.DURACION'
						,TOTALUNIDADES INT '$.TOTALUNIDADES'
						,CICLOS INT '$.CICLO'
						,PRESCRIPCION VARCHAR(MAX) '$.PRESCRIPCION'
						,PRESCRIPCION_CORTA VARCHAR(MAX) '$.PRESCRIPCION_CORTA'
						,TIPODURACION VARCHAR(MAX) '$.TIPODURACION'

					) #T INNER JOIN SER ON SER.IDSERVICIO=#T.IDSERVICIO

				    FETCH NEXT FROM _cursor INTO @IDSERVICIO,@AUX
				END

				CLOSE _cursor
				DEALLOCATE _cursor

				--Generar esquema oncologico (HCATDOD) - EZERPA 08.06.2023
				EXEC dbo.SPK_GENERA_HCATDOD @CONSECUTIVO

                --Insertar en AUTSES - EZERPA 13.06.2023
				SELECT TOP 1 @DIA_ACTUAL = DIA
					,@CICLO_ACTUAL = CICLO
				FROM HCATDOD
				WHERE CONSECUTIVOCIT = @CONSECUTIVOCIT

				SELECT @ULTIMO_CICLO = MAX(CICLO)
				FROM HCATDOD WHERE HCATDO_ITEM IN (
					SELECT HCATDO_ITEM FROM HCATDOD WHERE CONSECUTIVOCIT=@CONSECUTIVOCIT
				)

				SELECT @ULTIMO_DIA_CICLO = MAX(DIA)
				FROM HCATDOD WHERE HCATDO_ITEM IN (
					SELECT HCATDO_ITEM FROM HCATDOD WHERE CONSECUTIVOCIT=@CONSECUTIVOCIT
				)
				AND CICLO = @CICLO_ACTUAL


				IF @CICLO_ACTUAL = @ULTIMO_CICLO
					SELECT @CICLO = @CICLO_ACTUAL
				ELSE
				BEGIN
					IF @DIA_ACTUAL = @ULTIMO_DIA_CICLO
						SELECT @CICLO = @CICLO_ACTUAL + 1
					ELSE
						SELECT @CICLO = @CICLO_ACTUAL
				END

				INSERT INTO AUTSES (FECHA ,IDAFILIADO ,CANTIDAD ,IDSERVICIO ,IDEMEDICA ,CLASE , NOAUTORIZACION ,TIPOSES ,IDTERCERO ,IDPLAN ,ESTADO ,PROCEDENCIA ,NOADMISION , CICLO ,HCATD_ID ,REFERENCIA )
				SELECT HCA.FECHA,HCA.IDAFILIADO,1 CANTIDAD,HCATD.IDSERVICIO,COALESCE(MED.IDEMEDICA,CIT.IDEMEDICA) IDEMEDICA
					,'INTERNO' CLASE
					, COALESCE(CIT.NOAUTORIZACION, HADM.NOAUTORIZACION) NOAUTORIZACION
					,'ONCOLOGIA' TIPOSES
					,COALESCE(CIT.IDTERCEROCA, HADM.IDTERCERO,AFI.IDADMINISTRADORA) AS IDTERCERO
					,IDPLAN = COALESCE(HCA.IDPLAN,CIT.IDPLAN,HADM.IDPLAN,AFI.IDPLAN)
					,'Activo' ESTADO
					,'ONCO' PROCEDENCIA
					,HCA.NOADMISION
					,COALESCE(@CICLO, 1) CICLO
					,HCATD.ID HCATD_ID
					,@CONSECUTIVO REFERENCIA
				FROM HCATD
				INNER JOIN HCA ON HCA.CONSECUTIVO = HCATD.CONSECUTIVO
				INNER JOIN AFI ON AFI.IDAFILIADO  = HCA.IDAFILIADO
				LEFT JOIN CIT ON CIT.CONSECUTIVO  = HCA.CONSECUTIVOCIT
				INNER JOIN MED ON MED.IDMEDICO    = COALESCE(HCA.IDMEDICO, CIT.IDMEDICO)
				LEFT JOIN HADM ON HADM.NOADMISION = HCA.NOADMISION
				WHERE ID IN (SELECT ID FROM HCATDO WHERE CONSECUTIVO = @CONSECUTIVO)

				-- EZERPA 08.08.23 / Como es atencion oncologica la especialidad de la HCA debe ser el que la esta atendiendo
				-- JLLAMAS 01.12.25 / tomar el IDMEDICA cuando se selecciona al momento de la atención @NEWIDEMEDICA.
				UPDATE HCA 
				   SET --IDEMEDICA = @IDEMEDICA
				     IDEMEDICA = CASE WHEN @PROCEDENCIA <> 'IPS' AND COALESCE(@NEWIDEMEDICA, '') <> '' THEN @NEWIDEMEDICA ELSE @IDEMEDICA END
					,IDEMEDICAESP = MEDESP.IDEMEDICA
				FROM HCA LEFT JOIN MED MEDESP ON MEDESP.IDMEDICO = HCA.IDMEDICOESP
				WHERE CONSECUTIVO = @CONSECUTIVO

			END
			--EZ 15.08.2025-Validaciones para clinica internacional
			BEGIN
				IF @NIT = '20100054184' AND @IDPLAN = 'PAQ001' -- MAD
				BEGIN

					-- PRUEBA MOLECULAR - COVID - Agregar el dx Si el profesional no lo agrego
					IF EXISTS(
						SELECT IDDX FROM MDX
						WHERE IDDX = 'U07.2'
						AND IDDX NOT IN (
							SELECT IDDX FROM HCADX WHERE CONSECUTIVO = @CONSECUTIVO
							UNION ALL SELECT IDDX FROM HCA WHERE CONSECUTIVO = @CONSECUTIVO
						) AND EXISTS(SELECT 1 FROM HCATD WHERE CONSECUTIVO = @CONSECUTIVO AND IDSERVICIO = 'SANG040500')
					)
					BEGIN
						SELECT  @MENSAJE_ALERTA = CONCAT('Esta solicitando ', TRIM(DESCSERVICIO) ,' sin incluir el diagnostico clinico (U07.2)')
						FROM SER WHERE IDSERVICIO = 'SANG040500'
						RAISERROR (@MENSAJE_ALERTA, 16, 1);
						RETURN
					END

					-- DENGUE NS1 AND IGG/IGM PRUEBA RAPIDA, AGREGAR EL DIAGNOSTICO SI EL PROFESIONAL NO LO AGREGO
					IF EXISTS(
						SELECT IDDX FROM MDX
						WHERE IDDX = 'B34.9'
						AND IDDX NOT IN (
							SELECT IDDX FROM HCADX WHERE CONSECUTIVO = @CONSECUTIVO
							UNION ALL SELECT IDDX FROM HCA WHERE CONSECUTIVO = @CONSECUTIVO
						) AND EXISTS(SELECT 1 FROM HCATD WHERE CONSECUTIVO = @CONSECUTIVO AND IDSERVICIO = 'SANG034680')
					)
					BEGIN
						SELECT  @MENSAJE_ALERTA = CONCAT('Esta solicitando ', TRIM(DESCSERVICIO) ,' sin incluir el diagnostico clinico (B34.9)')
						FROM SER WHERE IDSERVICIO = 'SANG034680'
						RAISERROR (@MENSAJE_ALERTA, 16, 1);
						IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
						RETURN
					END
				END
			END
			-- Signos Varios
			BEGIN
				SELECT @AUX = MPLSV FROM   #HCA

				IF @AUX IS NULL
					SET @AUX = '[]'

				IF OBJECT_ID('tempdb..#HCASVT') IS NOT NULL
					DROP TABLE #HCASVT

				SELECT
					RENGLON          = COALESCE(
										   NULLIF(LTRIM(RTRIM(j.ID)), ''),
										   NULLIF(LTRIM(RTRIM(j.CNSNESIGVIT)), '')
									   ),
					CLASEPLANTILLASV = j.CLASEPLANTILLA,
					OBSERVACION      = j.OBSERVACION,
					FECHA            = j.FECHA,
					VALORES          = j.VALORES,
					CCOSTO           = j.CCOSTO
				INTO   #HCASVT
				FROM   OPENJSON(@AUX) WITH (
					ID             VARCHAR(100)   '$.ID',
					CNSNESIGVIT    VARCHAR(100)   '$.CNSNESIGVIT',
					CLASEPLANTILLA VARCHAR(8)     '$.CLASEPLANTILLA',
					OBSERVACION    VARCHAR(5000)  '$.OBSERVACION',
					FECHA          DATETIME       '$.FECHA',
					CCOSTO         VARCHAR(20)    '$.CCOSTO',
					VALORES        NVARCHAR(MAX)  AS JSON
				) j
				WHERE  COALESCE(
						   NULLIF(LTRIM(RTRIM(j.ID)), ''),
						   NULLIF(LTRIM(RTRIM(j.CNSNESIGVIT)), '')
					   ) IS NOT NULL

				IF DBO.FNK_VALORVARIABLE('SIGNOSVITALREQ') = 'SI'
				BEGIN
					IF EXISTS (
							SELECT 1
							FROM   MPL
							WHERE  CLASEPLANTILLA = @CLASEPLANTILLA
							  AND  COALESCE(PIDESV, 0) = 1
					   )
					   AND NOT EXISTS (SELECT 1 FROM #HCASVT)
					   AND NOT EXISTS (SELECT 1 FROM HCASV WHERE CONSECUTIVO = @CONSECUTIVO)
					BEGIN
						RAISERROR ('Debe diligenciar al menos un Signo Vital.', 16, 1)
						RETURN
					END
				END

				MERGE HCASVT AS h
				USING #HCASVT AS t
				ON h.RENGLON = t.RENGLON
				WHEN MATCHED THEN
					UPDATE SET
						h.OBSERVACION      = t.OBSERVACION,
						h.CLASEPLANTILLASV = t.CLASEPLANTILLASV,
						h.VALORES          = t.VALORES,
						h.FECHAREGCLIENTE  = t.FECHA,
						h.CCOSTO           = t.CCOSTO
				WHEN NOT MATCHED BY TARGET THEN
					INSERT (RENGLON, OBSERVACION, CLASEPLANTILLASV, VALORES, FECHAREGCLIENTE, CCOSTO)
					VALUES (t.RENGLON, t.OBSERVACION, t.CLASEPLANTILLASV, t.VALORES, t.FECHA, t.CCOSTO);

				DELETE d
				FROM   HCASV d
				WHERE  d.CONSECUTIVO = @CONSECUTIVO
				  AND  d.RENGLON NOT IN (SELECT t.RENGLON FROM #HCASVT t)
				  AND  EXISTS (SELECT 1 FROM #HCASVT)

				DELETE d
				FROM   HCASV d
				WHERE  d.CONSECUTIVO = @CONSECUTIVO AND d.RENGLON IN (SELECT t.RENGLON FROM #HCASVT t)

				INSERT INTO HCASV ( CONSECUTIVO, RENGLON, CODIGOSV, DATO, GRUPO, CLASESV, VALOR, SINCRONIZADO, ORDENSV )
				SELECT @CONSECUTIVO, t.RENGLON, x.CODIGOSV, x.DATO, TGSV.GRUPO, TGSV.CLASESV, NULL, 0, x.ORDENSV
				FROM   #HCASVT t
				CROSS APPLY OPENJSON(t.VALORES) WITH (
					CODIGOSV         VARCHAR(20) '$.CODIGOSV',
					DATO             VARCHAR(20) '$.DATO',
					CLASEPLANTILLASV VARCHAR(8)  '$.CLASEPLANTILLA',
					ORDENSV          SMALLINT    '$.ORDENSV'
				) x
				INNER JOIN TGSV ON x.CODIGOSV = TGSV.CODIGOSV
                					
			END
			--Escalas
			BEGIN
				SELECT @AUX = ESCALAS
				FROM   #HCA

				SELECT * INTO #QESCALAS
				FROM OPENJSON(@AUX) WITH (
					 ID                VARCHAR(100)  '$.ID'
					,ESCALA            VARCHAR(20)   '$.ESCALA.value'
					,FECHA             DATETIME      '$.FECHA'
				    ,TOTAL             DECIMAL(14,2) '$.TOTAL'
				    ,INTERPRETACION    VARCHAR(1000) '$.INTERPRETA'
					,VALORES           NVARCHAR(MAX) AS JSON
                    ,RTA_JSON          NVARCHAR(MAX) AS JSON
				)

				DECLARE ESCCUR CURSOR FOR
				SELECT VALORES, ID ,ESCALA, FECHA, TOTAL, INTERPRETACION,RTA_JSON FROM  #QESCALAS
				OPEN ESCCUR
				FETCH NEXT FROM ESCCUR
				INTO @AUX ,@RENGLON ,@ESCALA, @FECHA, @TOTAL, @INTERPRETACION, @RTA_JSON
				WHILE @@FETCH_STATUS = 0
				BEGIN
					INSERT INTO QCORE10 (ESCALA ,CONSECUTIVOHCA ,IDAFILIADO ,FECHAREG ,USUREG, TOTAL, INTERPRETACION,RTA_JSON )
					SELECT @ESCALA ,@CONSECUTIVO ,@IDAFILIADO ,@FECHA, @USUARIO, @TOTAL, @INTERPRETACION ,@RTA_JSON
					SELECT @IDESC = @@IDENTITY

                    IF EXISTS (SELECT 1 FROM TALR WHERE IDALERTA=@IDALERTA_ESCAUTO)
                        AND EXISTS(SELECT 1 FROM TGEN WHERE TABLA='ESCALAS' AND CAMPO='NOMBRE' AND CODIGO=@ESCALA AND @TOTAL>TRY_cAST(DATO4 AS decimal(14,2)))
                    BEGIN
					    EXEC SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@ALR',  @CNSALR OUTPUT
					    SELECT @CNSALR = @SEDE + REPLACE(SPACE(8 - LEN(@CNSALR))+LTRIM(RTRIM(@CNSALR)),SPACE(1),0)

                        INSERT INTO ALR (CONSECUTIVO, IDAFILIADO, IDALERTA, FECHAALERTA, FECHAAVISO, OBS, IDFUNCIONARIO, CLASE, COLOR, CNSWEB, CONSECUTIVOHCA, PROCEDENCIA)
                        SELECT @CNSALR, @IDAFILIADO, TALR.IDALERTA, GETDATE(), GETDATE(), 'Escala '+COALESCE(TGEN.DESCRIPCION,'')+' fuera de rangos normales: '+CONVERT(VARCHAR,TRY_cAST(@TOTAL AS DECIMAL(14,2)))
                            , @USUARIO, TALR.CLASEALERTA,TALR.COLOR, @CNSWEB, @CONSECUTIVO,'HCA'
                        FROM TALR
                            LEFT JOIN TGEN ON TABLA='ESCALAS' AND CAMPO='NOMBRE' AND CODIGO=@ESCALA
                        WHERE TALR.IDALERTA=DBO.FNK_VALORVARIABLE('IDALERTA_ESCAUTO')
                    END

					-- Set-based: UPDATE masivo de QCORE10 desde OPENJSON (reemplaza cursor CORE10CUR con 80+ UPDATEs)
					UPDATE QCORE10 SET
						C0010=COALESCE(v.C0010,q.C0010),C0020=COALESCE(v.C0020,q.C0020),C0030=COALESCE(v.C0030,q.C0030),C0040=COALESCE(v.C0040,q.C0040),C0050=COALESCE(v.C0050,q.C0050),C0060=COALESCE(v.C0060,q.C0060),C0070=COALESCE(v.C0070,q.C0070),C0080=COALESCE(v.C0080,q.C0080),C0090=COALESCE(v.C0090,q.C0090),C0100=COALESCE(v.C0100,q.C0100),
						C0110=COALESCE(v.C0110,q.C0110),C0120=COALESCE(v.C0120,q.C0120),C0130=COALESCE(v.C0130,q.C0130),C0140=COALESCE(v.C0140,q.C0140),C0150=COALESCE(v.C0150,q.C0150),C0160=COALESCE(v.C0160,q.C0160),C0170=COALESCE(v.C0170,q.C0170),C0180=COALESCE(v.C0180,q.C0180),C0190=COALESCE(v.C0190,q.C0190),C0200=COALESCE(v.C0200,q.C0200),
						C0210=COALESCE(v.C0210,q.C0210),C0220=COALESCE(v.C0220,q.C0220),C0230=COALESCE(v.C0230,q.C0230),C0240=COALESCE(v.C0240,q.C0240),C0250=COALESCE(v.C0250,q.C0250),C0260=COALESCE(v.C0260,q.C0260),C0270=COALESCE(v.C0270,q.C0270),C0280=COALESCE(v.C0280,q.C0280),C0290=COALESCE(v.C0290,q.C0290),C0300=COALESCE(v.C0300,q.C0300),
						C0310=COALESCE(v.C0310,q.C0310),C0320=COALESCE(v.C0320,q.C0320),C0330=COALESCE(v.C0330,q.C0330),C0340=COALESCE(v.C0340,q.C0340),C0350=COALESCE(v.C0350,q.C0350),C0360=COALESCE(v.C0360,q.C0360),C0370=COALESCE(v.C0370,q.C0370),C0380=COALESCE(v.C0380,q.C0380),C0390=COALESCE(v.C0390,q.C0390),C0400=COALESCE(v.C0400,q.C0400),
						C0410=COALESCE(v.C0410,q.C0410),C0420=COALESCE(v.C0420,q.C0420),C0430=COALESCE(v.C0430,q.C0430),C0440=COALESCE(v.C0440,q.C0440),C0450=COALESCE(v.C0450,q.C0450),C0460=COALESCE(v.C0460,q.C0460),C0470=COALESCE(v.C0470,q.C0470),C0480=COALESCE(v.C0480,q.C0480),C0490=COALESCE(v.C0490,q.C0490),C0500=COALESCE(v.C0500,q.C0500),
						C0510=COALESCE(v.C0510,q.C0510),C0520=COALESCE(v.C0520,q.C0520),C0530=COALESCE(v.C0530,q.C0530),C0540=COALESCE(v.C0540,q.C0540),C0550=COALESCE(v.C0550,q.C0550),C0560=COALESCE(v.C0560,q.C0560),C0570=COALESCE(v.C0570,q.C0570),C0580=COALESCE(v.C0580,q.C0580),C0590=COALESCE(v.C0590,q.C0590),C0600=COALESCE(v.C0600,q.C0600),
						C0610=COALESCE(v.C0610,q.C0610),C0620=COALESCE(v.C0620,q.C0620),C0630=COALESCE(v.C0630,q.C0630),C0640=COALESCE(v.C0640,q.C0640),C0650=COALESCE(v.C0650,q.C0650),C0660=COALESCE(v.C0660,q.C0660),C0670=COALESCE(v.C0670,q.C0670),C0680=COALESCE(v.C0680,q.C0680),C0690=COALESCE(v.C0690,q.C0690),C0700=COALESCE(v.C0700,q.C0700),
						C0710=COALESCE(v.C0710,q.C0710),C0720=COALESCE(v.C0720,q.C0720),C0730=COALESCE(v.C0730,q.C0730),C0740=COALESCE(v.C0740,q.C0740),C0750=COALESCE(v.C0750,q.C0750),C0760=COALESCE(v.C0760,q.C0760),C0770=COALESCE(v.C0770,q.C0770),C0780=COALESCE(v.C0780,q.C0780),C0790=COALESCE(v.C0790,q.C0790),C0800=COALESCE(v.C0800,q.C0800),
						M0000=COALESCE(v.M0000,q.M0000),M0010=COALESCE(v.M0010,q.M0010),M0020=COALESCE(v.M0020,q.M0020),M0030=COALESCE(v.M0030,q.M0030),M0040=COALESCE(v.M0040,q.M0040),M0050=COALESCE(v.M0050,q.M0050),M0060=COALESCE(v.M0060,q.M0060),M0070=COALESCE(v.M0070,q.M0070),M0080=COALESCE(v.M0080,q.M0080),M0090=COALESCE(v.M0090,q.M0090),M0100=COALESCE(v.M0100,q.M0100),
						D0000=COALESCE(v.D0000,q.D0000),D0010=COALESCE(v.D0010,q.D0010),
						LATERALIDAD=COALESCE(v.LATERALIDAD,q.LATERALIDAD),ZONA=COALESCE(v.ZONA,q.ZONA)
					FROM QCORE10 q
					CROSS APPLY (
						SELECT
							MAX(j.C0010) AS C0010,MAX(j.C0020) AS C0020,MAX(j.C0030) AS C0030,MAX(j.C0040) AS C0040,MAX(j.C0050) AS C0050,MAX(j.C0060) AS C0060,MAX(j.C0070) AS C0070,MAX(j.C0080) AS C0080,MAX(j.C0090) AS C0090,MAX(j.C0100) AS C0100,
							MAX(j.C0110) AS C0110,MAX(j.C0120) AS C0120,MAX(j.C0130) AS C0130,MAX(j.C0140) AS C0140,MAX(j.C0150) AS C0150,MAX(j.C0160) AS C0160,MAX(j.C0170) AS C0170,MAX(j.C0180) AS C0180,MAX(j.C0190) AS C0190,MAX(j.C0200) AS C0200,
							MAX(j.C0210) AS C0210,MAX(j.C0220) AS C0220,MAX(j.C0230) AS C0230,MAX(j.C0240) AS C0240,MAX(j.C0250) AS C0250,MAX(j.C0260) AS C0260,MAX(j.C0270) AS C0270,MAX(j.C0280) AS C0280,MAX(j.C0290) AS C0290,MAX(j.C0300) AS C0300,
							MAX(j.C0310) AS C0310,MAX(j.C0320) AS C0320,MAX(j.C0330) AS C0330,MAX(j.C0340) AS C0340,MAX(j.C0350) AS C0350,MAX(j.C0360) AS C0360,MAX(j.C0370) AS C0370,MAX(j.C0380) AS C0380,MAX(j.C0390) AS C0390,MAX(j.C0400) AS C0400,
							MAX(j.C0410) AS C0410,MAX(j.C0420) AS C0420,MAX(j.C0430) AS C0430,MAX(j.C0440) AS C0440,MAX(j.C0450) AS C0450,MAX(j.C0460) AS C0460,MAX(j.C0470) AS C0470,MAX(j.C0480) AS C0480,MAX(j.C0490) AS C0490,MAX(j.C0500) AS C0500,
							MAX(j.C0510) AS C0510,MAX(j.C0520) AS C0520,MAX(j.C0530) AS C0530,MAX(j.C0540) AS C0540,MAX(j.C0550) AS C0550,MAX(j.C0560) AS C0560,MAX(j.C0570) AS C0570,MAX(j.C0580) AS C0580,MAX(j.C0590) AS C0590,MAX(j.C0600) AS C0600,
							MAX(j.C0610) AS C0610,MAX(j.C0620) AS C0620,MAX(j.C0630) AS C0630,MAX(j.C0640) AS C0640,MAX(j.C0650) AS C0650,MAX(j.C0660) AS C0660,MAX(j.C0670) AS C0670,MAX(j.C0680) AS C0680,MAX(j.C0690) AS C0690,MAX(j.C0700) AS C0700,
							MAX(j.C0710) AS C0710,MAX(j.C0720) AS C0720,MAX(j.C0730) AS C0730,MAX(j.C0740) AS C0740,MAX(j.C0750) AS C0750,MAX(j.C0760) AS C0760,MAX(j.C0770) AS C0770,MAX(j.C0780) AS C0780,MAX(j.C0790) AS C0790,MAX(j.C0800) AS C0800,
							MAX(j.M0000) AS M0000,MAX(j.M0010) AS M0010,MAX(j.M0020) AS M0020,MAX(j.M0030) AS M0030,MAX(j.M0040) AS M0040,MAX(j.M0050) AS M0050,MAX(j.M0060) AS M0060,MAX(j.M0070) AS M0070,MAX(j.M0080) AS M0080,MAX(j.M0090) AS M0090,MAX(j.M0100) AS M0100,
							MAX(j.D0000) AS D0000,MAX(j.D0010) AS D0010,
							MAX(j.LATERALIDAD) AS LATERALIDAD,MAX(j.ZONA) AS ZONA
						FROM OPENJSON(@AUX) WITH (
						C0010 INT '$.c0010',C0020 INT '$.c0020',C0030 INT '$.c0030',C0040 INT '$.c0040',C0050 INT '$.c0050',C0060 INT '$.c0060',C0070 INT '$.c0070',C0080 INT '$.c0080',C0090 INT '$.c0090',C0100 INT '$.c0100',
						C0110 INT '$.c0110',C0120 INT '$.c0120',C0130 INT '$.c0130',C0140 INT '$.c0140',C0150 INT '$.c0150',C0160 INT '$.c0160',C0170 INT '$.c0170',C0180 INT '$.c0180',C0190 INT '$.c0190',C0200 INT '$.c0200',
						C0210 INT '$.c0210',C0220 INT '$.c0220',C0230 INT '$.c0230',C0240 INT '$.c0240',C0250 INT '$.c0250',C0260 INT '$.c0260',C0270 INT '$.c0270',C0280 INT '$.c0280',C0290 INT '$.c0290',C0300 INT '$.c0300',
						C0310 INT '$.c0310',C0320 INT '$.c0320',C0330 INT '$.c0330',C0340 INT '$.c0340',C0350 INT '$.c0350',C0360 INT '$.c0360',C0370 INT '$.c0370',C0380 INT '$.c0380',C0390 INT '$.c0390',C0400 INT '$.c0400',
						C0410 INT '$.c0410',C0420 INT '$.c0420',C0430 INT '$.c0430',C0440 INT '$.c0440',C0450 INT '$.c0450',C0460 INT '$.c0460',C0470 INT '$.c0470',C0480 INT '$.c0480',C0490 INT '$.c0490',C0500 INT '$.c0500',
						C0510 INT '$.c0510',C0520 INT '$.c0520',C0530 INT '$.c0530',C0540 INT '$.c0540',C0550 INT '$.c0550',C0560 INT '$.c0560',C0570 INT '$.c0570',C0580 INT '$.c0580',C0590 INT '$.c0590',C0600 INT '$.c0600',
						C0610 INT '$.c0610',C0620 INT '$.c0620',C0630 INT '$.c0630',C0640 INT '$.c0640',C0650 INT '$.c0650',C0660 INT '$.c0660',C0670 INT '$.c0670',C0680 INT '$.c0680',C0690 INT '$.c0690',C0700 INT '$.c0700',
						C0710 INT '$.c0710',C0720 INT '$.c0720',C0730 INT '$.c0730',C0740 INT '$.c0740',C0750 INT '$.c0750',C0760 INT '$.c0760',C0770 INT '$.c0770',C0780 INT '$.c0780',C0790 INT '$.c0790',C0800 INT '$.c0800',
						M0000 VARCHAR(500) '$.m0000',M0010 VARCHAR(500) '$.m0010',M0020 VARCHAR(500) '$.m0020',M0030 VARCHAR(500) '$.m0030',M0040 VARCHAR(500) '$.m0040',M0050 VARCHAR(500) '$.m0050',M0060 VARCHAR(500) '$.m0060',M0070 VARCHAR(500) '$.m0070',M0080 VARCHAR(500) '$.m0080',M0090 VARCHAR(500) '$.m0090',M0100 VARCHAR(500) '$.m0100',
						D0000 DECIMAL(14,2) '$.d0000',D0010 DECIMAL(14,2) '$.d0010',
						LATERALIDAD VARCHAR(50) '$.lateralidad',ZONA VARCHAR(50) '$.zona'
					) j
					) v
					WHERE q.ID = @IDESC
					FETCH NEXT FROM ESCCUR
					INTO @AUX ,@RENGLON ,@ESCALA, @FECHA, @TOTAL, @INTERPRETACION, @RTA_JSON
				END
				CLOSE ESCCUR
				DEALLOCATE ESCCUR
			END
			--Glucometria
			BEGIN
				SELECT @AUX = MPLGLU
				FROM   #HCA
				SELECT * INTO #RESGLUC --CMT RESGLUC,X,I
				FROM OPENJSON(@AUX) WITH (
						ID           VARCHAR(100)  '$.ID'
						,FECHA        DATE          '$.FECHA'
						,AD           VARCHAR(100) '$.AD'
						,DD           VARCHAR(100) '$.DD'
						,AA           VARCHAR(100) '$.AA'
						,DA           VARCHAR(100) '$.DA'
						,AC           VARCHAR(100) '$.AC'
						,DC           VARCHAR(100) '$.DC'
						,OTRO         VARCHAR(100) '$.OTRO'
						,OBSERVACION  VARCHAR(500)  '$.OBSERVACION'
				)

				-- Set-based: Glucometría (reemplaza cursor GLUCUR)
				INSERT INTO RESGLUC (CONSECUTIVOHCA, IDAFILIADO, FECHA, AD, DD, AA, DA, AC, DC, OTRO, OBSERVACION, PROCEDENCIA, FECHAREG, USUREG)
				SELECT @CONSECUTIVO, @IDAFILIADO, FECHA
					,TRY_CONVERT(DECIMAL(14,2), REPLACE(IIF(COALESCE(AD,'')='','0',AD),',','.'))
					,TRY_CONVERT(DECIMAL(14,2), REPLACE(IIF(COALESCE(DD,'')='','0',DD),',','.'))
					,TRY_CONVERT(DECIMAL(14,2), REPLACE(IIF(COALESCE(AA,'')='','0',AA),',','.'))
					,TRY_CONVERT(DECIMAL(14,2), REPLACE(IIF(COALESCE(DA,'')='','0',DA),',','.'))
					,TRY_CONVERT(DECIMAL(14,2), REPLACE(IIF(COALESCE(AC,'')='','0',AC),',','.'))
					,TRY_CONVERT(DECIMAL(14,2), REPLACE(IIF(COALESCE(DC,'')='','0',DC),',','.'))
					,TRY_CONVERT(DECIMAL(14,2), REPLACE(IIF(COALESCE(OTRO,'')='','0',OTRO),',','.'))
					,OBSERVACION, 'HCA', DBO.FNK_GETDATE(), @USUARIO
				FROM #RESGLUC
			END
			--Prebiologicos
			BEGIN
				DELETE FROM HCAPREB WHERE CONSECUTIVO=@CONSECUTIVOHCA

				SELECT @AUX = HCAPREB
				FROM   #HCA

				INSERT INTO HCAPREB(CONSECUTIVO,IDSERVICIO,FECHA,RESULTADO,OBSERVACION)
				SELECT COALESCE(@CONSECUTIVO, @CONSECUTIVOHCA),IDSERVICIO,FECHA,RESULTADO,OBSERVACION
				FROM OPENJSON(@AUX) WITH (
					IDSERVICIO         VARCHAR(20)	'$.IDSERVICIO'
					,RESULTADO		   VARCHAR(255) '$.RESULTADO'
					,FECHA			   DATE			'$.FECHA'
					,OBSERVACION	   VARCHAR(1000)'$.OBSERVACION'
				)
			END
			--Laboratorios
			BEGIN
				UPDATE RESLAB SET CONSECUTIVOHCA = COALESCE(@CONSECUTIVO, @CONSECUTIVOHCA) WHERE CNSWEB = @CNSWEB
			END
			-- Odontogramas
			BEGIN
				UPDATE HCO SET FECHA=@FECHAHCA WHERE CNSWEB = @CNSWEB
			END
			--Incapacidades
			BEGIN
				UPDATE IME SET CONSECUTIVOHCA =  COALESCE(@CONSECUTIVO, @CONSECUTIVOHCA) WHERE CNSWEB = @CNSWEB
			END
			--Alertas
			UPDATE ALR SET CONSECUTIVOHCA = @CONSECUTIVO
			WHERE CONSECUTIVOHCA IS NULL AND CNSWEB = @CNSWEB
			--Record de Anestesia
			BEGIN
				DELETE FROM HCANED WHERE CONSECUTIVOHCA = @CONSECUTIVOHCA

				SELECT @AUX = HCANED
				FROM #HCA

				INSERT INTO HCANED (CONSECUTIVOHCA ,ITEM ,FECHAEVO ,PSISTOLICA ,PDIASTOLICA ,FCARDIACA ,RESPIRACION ,TEMPERATURA ,SAT02 ,CO2 ,OBSERVACION
				,EVT_VIA_AEREA ,EVT_QUIRURGICO )
				SELECT COALESCE(@CONSECUTIVO, @CONSECUTIVOHCA) ,ITEM ,CAST(FECHAEVO AS DATETIME) ,PSISTOLICA ,PDIASTOLICA ,FC ,FR ,TEMP ,SAT02 ,CO2 ,OBSERVACION
					,ISNULL(EVT_VIA_AEREA, 0) ,ISNULL(EVT_QUIRURGICO, 0)
				FROM OPENJSON (@AUX) WITH (
					ITEM			INT			'$.ITEM',			FECHAEVO	VARCHAR(15)		'$.FECHAEVO',
					PSISTOLICA		INT			'$.PSISTOLICA',		PDIASTOLICA	INT				'$.PDIASTOLICA',	FC		INT			'$.FC',
					FR				INT			'$.FR',				TEMP		DECIMAL(9,2)	'$.TEMP',			SAT02	INT			'$.SAT02',
					CO2				INT			'$.CO2',			OBSERVACION	VARCHAR(4096)	'$.OBSERVACION',
					EVT_VIA_AEREA	SMALLINT	'$.EVT_VIA_AEREA',	EVT_QUIRURGICO	SMALLINT	'$.EVT_QUIRURGICO', CONSECUTIVOHCA VARCHAR(13) '$.CONSECUTIVOHCA'
				)J WHERE J.CONSECUTIVOHCA = COALESCE(@CONSECUTIVO, @CONSECUTIVOHCA)
				   OR J.CONSECUTIVOHCA IS NULL
				--   EVT_VIA_AEREA:  0=Ninguno, 1=Intubación, 2=Extubación
				--   EVT_QUIRURGICO: 0=Ninguno, 1=Inducción, 2=Incisión, 3=Cierre
			END
			--Record de Anestesia - Anestesicos
			BEGIN
				DELETE FROM HCANEDMED WHERE CONSECUTIVOHCA = @CONSECUTIVOHCA

				SELECT @AUX = HCANEDMED
				FROM #HCA

				INSERT INTO HCANEDMED (CONSECUTIVOHCA ,IDSERVICIO ,CANTIDAD ,FECHA ,OBSERVACION )
				SELECT COALESCE(@CONSECUTIVO, @CONSECUTIVOHCA) ,IDSERVICIO ,CANTIDAD ,CAST(FECHAEVO AS DATETIME) ,OBSERVACION
				FROM OPENJSON (@AUX) WITH (
					IDSERVICIO	VARCHAR(20)		'$.IDSERVICIO',	FECHAEVO	VARCHAR(15)		'$.FECHAEVO',
					CANTIDAD	DECIMAL(9,2)	'$.CANTIDAD',	OBSERVACION	VARCHAR(2048)	'$.OBSERVACION',
					CONSECUTIVOHCA VARCHAR(13) '$.CONSECUTIVOHCA'
				)J WHERE J.CONSECUTIVOHCA = COALESCE(@CONSECUTIVO, @CONSECUTIVOHCA)
				   OR J.CONSECUTIVOHCA IS NULL
			END
			--Cita

			IF @NUEVA_HCA=1
			BEGIN
                BEGIN /*  GENERA CARGOS DE SERVICIO POR SER PHDV*/
		            IF EXISTS (SELECT 1 FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT AND CIT.PROCEDENCIA = 'PHDV')
		            BEGIN
			            SELECT @IDEMEDICA = IDEMEDICA FROM MED WHERE  IDMEDICO = @IDMEDICO
			            IF EXISTS (SELECT 1  FROM MPLSER  INNER JOIN MESS ON MPLSER.IDSERVICIO = MESS.IDSERVICIO AND MESS.IDEMEDICA = @IDEMEDICA
			                        WHERE MPLSER.CLASEPLANTILLA = @CLASEPLANTILLA)
			            BEGIN
				            UPDATE #HCA SET HCASER = (SELECT TOP 1 MESS.IDSERVICIO, 1 CANTIDAD, AUTOMATICO  FROM MPLSER
				                INNER JOIN MESS ON MPLSER.IDSERVICIO = MESS.IDSERVICIO AND MESS.IDEMEDICA = @IDEMEDICA
				                WHERE MPLSER.CLASEPLANTILLA = @CLASEPLANTILLA  FOR JSON  PATH)
                            WHERE  1 = 1
			            END
		            END
                  IF @PROP_PROCEDENCIA = 'PHD_ADMITIDOS'
                  BEGIN
                     UPDATE #HCA SET HCASER = (SELECT TOP 1 MESS.IDSERVICIO, 1 CANTIDAD, AUTOMATICO  FROM MPLSER
				                INNER JOIN MESS ON MPLSER.IDSERVICIO = MESS.IDSERVICIO AND MESS.IDEMEDICA = @IDEMEDICA
				                WHERE MPLSER.CLASEPLANTILLA = @CLASEPLANTILLA  FOR JSON  PATH)
                            WHERE  1 = 1
                  END

			        SELECT @AUX = HCASER FROM #HCA

			        SELECT * INTO #HCASER
			        FROM OPENJSON(@AUX) WITH (
				        IDSERVICIO		VARCHAR(20)	'$.IDSERVICIO',
				        CANTIDAD		SMALLINT    '$.CANTIDAD',
				        AUTOMATICO		BIT    '$.AUTOMATICO'
				        )
			        INSERT INTO HCASER (CONSECUTIVO, IDSERVICIO, CANTIDAD, AUTOMATICO)
			        SELECT @CONSECUTIVO, IDSERVICIO, CANTIDAD, AUTOMATICO FROM #HCASER
			        EXEC SPK_OM_GENCARGO_HCAUT  @NOADMISION, 'E', @CONSECUTIVO, @ITEMRED, @COMPANIA, @SEDE, @IDAREA, @CCOSTO, @USUARIO, @SYS_COMPUTERNAME
                END

                SELECT @IDDX=IDDX FROM #HCA
				IF @PROCEDENCIA<>'QX'
                BEGIN
					-- HC PyM: PyP usa MPE.FINALIDAD/CAUSA_EXTERNA; morbilidad (cita HCA Normal) usa MPE.*_MORB
					UPDATE CIT
					SET CUMPLIDA = 1
						,FECHAATENCION = DBO.FNK_GETDATE()
						,CONSECUTIVOHCA = COALESCE(CIT.CONSECUTIVOHCA, @CONSECUTIVO)
						,FINALIDAD = CASE
							WHEN COALESCE(@ES_ATENCION_MOR, 0) = 1
								OR (
									COALESCE(NULLIF(LTRIM(RTRIM(CIT.IDPESPECIAL)), ''), '') = ''
									AND CIT.PROCEDENCIA = 'HCA'
									AND UPPER(COALESCE(CIT.CLASEORDEN, '')) <> 'PYP'
								)
								THEN COALESCE(
									NULLIF(LTRIM(RTRIM(CAST(MPE.FINALIDAD_MORB AS VARCHAR(20)))), ''),
									NULLIF(LTRIM(RTRIM(@FINALIDADCONSULTA)), ''),
									CIT.FINALIDAD
								)
							WHEN COALESCE(NULLIF(LTRIM(RTRIM(@IDPESPECIAL)), ''), NULLIF(LTRIM(RTRIM(CIT.IDPESPECIAL)), ''), '') <> ''
								THEN COALESCE(NULLIF(LTRIM(RTRIM(MPE.FINALIDAD)), ''), NULLIF(LTRIM(RTRIM(@FINALIDADCONSULTA)), ''), CIT.FINALIDAD)
							ELSE COALESCE(NULLIF(LTRIM(RTRIM(@FINALIDADCONSULTA)), ''), NULLIF(LTRIM(RTRIM(MPE.FINALIDAD)), ''), CIT.FINALIDAD)
						 END
						,FINCONSULTA = CASE
							WHEN COALESCE(@ES_ATENCION_MOR, 0) = 1
								OR (
									COALESCE(NULLIF(LTRIM(RTRIM(CIT.IDPESPECIAL)), ''), '') = ''
									AND CIT.PROCEDENCIA = 'HCA'
									AND UPPER(COALESCE(CIT.CLASEORDEN, '')) <> 'PYP'
								)
								THEN COALESCE(
									NULLIF(LTRIM(RTRIM(CAST(MPE.FINALIDAD_MORB AS VARCHAR(20)))), ''),
									NULLIF(LTRIM(RTRIM(@FINALIDADCONSULTA)), ''),
									CIT.FINCONSULTA
								)
							WHEN COALESCE(NULLIF(LTRIM(RTRIM(@IDPESPECIAL)), ''), NULLIF(LTRIM(RTRIM(CIT.IDPESPECIAL)), ''), '') <> ''
								THEN COALESCE(NULLIF(LTRIM(RTRIM(MPE.FINALIDAD)), ''), NULLIF(LTRIM(RTRIM(@FINALIDADCONSULTA)), ''), CIT.FINCONSULTA)
							ELSE COALESCE(NULLIF(LTRIM(RTRIM(@FINALIDADCONSULTA)), ''), NULLIF(LTRIM(RTRIM(MPE.FINALIDAD)), ''), CIT.FINCONSULTA)
						 END
						,CAUSAEXTERNA = CASE
							WHEN COALESCE(@ES_ATENCION_MOR, 0) = 1
								OR (
									COALESCE(NULLIF(LTRIM(RTRIM(CIT.IDPESPECIAL)), ''), '') = ''
									AND CIT.PROCEDENCIA = 'HCA'
									AND UPPER(COALESCE(CIT.CLASEORDEN, '')) <> 'PYP'
								)
								THEN COALESCE(
									NULLIF(LTRIM(RTRIM(CAST(MPE.CAUSA_EXTERNA_MORB AS VARCHAR(20)))), ''),
									NULLIF(LTRIM(RTRIM(@CAUSAEXTERNA)), ''),
									CIT.CAUSAEXTERNA
								)
							WHEN COALESCE(NULLIF(LTRIM(RTRIM(@IDPESPECIAL)), ''), NULLIF(LTRIM(RTRIM(CIT.IDPESPECIAL)), ''), '') <> ''
								THEN COALESCE(NULLIF(LTRIM(RTRIM(MPE.CAUSA_EXTERNA)), ''), NULLIF(LTRIM(RTRIM(@CAUSAEXTERNA)), ''), CIT.CAUSAEXTERNA)
							ELSE COALESCE(NULLIF(LTRIM(RTRIM(@CAUSAEXTERNA)), ''), NULLIF(LTRIM(RTRIM(MPE.CAUSA_EXTERNA)), ''), CIT.CAUSAEXTERNA)
						 END
						,IDDX = @IDDX
					FROM CIT
					LEFT JOIN CIT CIT_ORIG_PYP WITH (NOLOCK) ON CIT_ORIG_PYP.CONSECUTIVO = CIT.CNSORIGINAL
					LEFT JOIN MPE WITH (NOLOCK)
						ON MPE.IDPESPECIAL = CASE
							WHEN COALESCE(@ES_ATENCION_MOR, 0) = 1
								OR (
									COALESCE(NULLIF(LTRIM(RTRIM(CIT.IDPESPECIAL)), ''), '') = ''
									AND CIT.PROCEDENCIA = 'HCA'
									AND UPPER(COALESCE(CIT.CLASEORDEN, '')) <> 'PYP'
								)
								THEN COALESCE(
									NULLIF(LTRIM(RTRIM(CIT_ORIG_PYP.IDPESPECIAL)), ''),
									NULLIF(LTRIM(RTRIM(@IDPESPECIAL)), '')
								)
							ELSE COALESCE(NULLIF(LTRIM(RTRIM(@IDPESPECIAL)), ''), NULLIF(LTRIM(RTRIM(CIT.IDPESPECIAL)), ''))
						END
					WHERE CIT.CONSECUTIVO = @CONSECUTIVOCIT
						AND @IDMEDICO IN (CIT.IDMEDICO, CIT.IDMEDICO_GEN)

                    IF EXISTS (SELECT 1 FROM APLIM WHERE CONSECUTIVOCIT = @CONSECUTIVOCIT AND COALESCE(APLICADO,0) = 0) -- APLICACION DE MEDICAMENTOS
				        AND DBO.FNK_VALORVARIABLE('APLIM_APLICADO_AUTO') <> 'NO'
			        BEGIN
                        SELECT @IDAPLIM=ID FROM APLIM WHERE CONSECUTIVOCIT = @CONSECUTIVOCIT
				        SELECT @ESTADO_ANTERIOR = ESTADO FROM APLIM WHERE ID = @IDAPLIM
                        SELECT @DETALLE_APLIMG = 'EL USUARIO '+NOMBRE+' APLICO EL MEDICAMENTO.' FROM MED WHERE IDMEDICO = @IDMEDICO

                        UPDATE CIT SET CUMPLIDA=1, FECHAATENCION = DBO.FNK_GETDATE() ,CONSECUTIVOHCA = COALESCE(CONSECUTIVOHCA, @CONSECUTIVO) WHERE CONSECUTIVO = @CONSECUTIVOCIT
			            UPDATE APLIM SET APLICADO = 1, FECHA_APLI = DBO.FNK_GETDATE(), IDMEDICO_APLI = @IDMEDICO, ESTADO='APLICADO' WHERE ID = @IDAPLIM AND COALESCE(APLICADO,0) = 0
                        EXEC SPK_AGREGAR_EVENTO_APLIM @IDAPLIM, 'APLICACION', @DETALLE_APLIMG, @IDMEDICO, 'ATENCION', @ESTADO_ANTERIOR, 'APLICADO'
			        END

				    IF EXISTS (SELECT 1 FROM RUTAAGENDA WHERE CONSECUTIVOCIT = @CONSECUTIVOCIT AND COALESCE(ESTADO,0) IN (2,5) )
				    BEGIN
					    UPDATE RUTAAGENDA SET ESTADO = 3 WHERE CONSECUTIVOCIT = @CONSECUTIVOCIT  AND COALESCE(ESTADO,0) IN (2,5 )
				    END
				    IF EXISTS (SELECT 1 FROM MADSEGUI WHERE CONSECUTIVOCIT = @CONSECUTIVOCIT AND IDMEDICO = @IDMEDICO AND COALESCE(PROCESADO,0) = 0 )
				    BEGIN
					    UPDATE MADSEGUI SET PROCESADO = 1 WHERE CONSECUTIVOCIT = @CONSECUTIVOCIT AND IDMEDICO = @IDMEDICO
				    END

				    UPDATE MAD SET TIENELAB = IIF(EXISTS (SELECT 1 FROM #HCATD WHERE CODOM=DBO.FNK_VALORVARIABLE('OMCODLABORATORIO')), 1, 0)
				    FROM CIT
				        INNER JOIN	MAD ON MAD.CONSECUTIVOCIT = CIT.CONSECUTIVO  AND CIT.PROCEDENCIA = 'MAD' AND MAD.ID = CIT.IDMAD
				    WHERE CIT.CONSECUTIVO = @CONSECUTIVOCIT

				    IF DBO.FNK_VALORVARIABLE('CIT_CREA_HADM') = 'SI'
					    EXEC SPK_CIT_CREA_HADM @CONSECUTIVOCIT, @CONSECUTIVO, @USUARIO
                END

			    IF @ESNOTAACLARATORIA=1 --ES UNA NOTA ACLARATORIA
				    UPDATE HCA SET NOTA_ACLARA = 2 ,CNSHCA_NOTA = @CONSECUTIVO WHERE CONSECUTIVO = @NOTACNSORI
			END

            IF @PROCEDENCIACIT='ONCO'
            BEGIN
                UPDATE CIT SET CUMPLIDA=1, FECHAATENCION = DBO.FNK_GETDATE() ,CONSECUTIVOHCA = COALESCE(CONSECUTIVOHCA, @CONSECUTIVO), 
                    FINCONSULTA=@FINALIDADCONSULTA,CAUSAEXTERNA=@CAUSAEXTERNA, IDDX=@IDDX
				WHERE CONSECUTIVO = @CONSECUTIVOCIT
            END
			--GESTION ACTUALIZAR GESTION GESTSER
			IF @PROCEDENCIA = 'GESTSER'
            BEGIN
				UPDATE AFIPROT SET ESTADO = 'Procesado' ,CONSECUTIVOHCA = @CONSECUTIVO, F_DEFAULT = DBO.FNK_FECHA_SIN_MLS(DBO.FNK_GETDATE()) WHERE ID = CONVERT(INT,@IDAFIPROT)
			END

            --Guardar Campos Permanentes:
			BEGIN
				SELECT @HCADCP = HCADCP FROM #HCA
				SELECT * INTO #HCADCP FROM OPENJSON(@HCADCP)
				WITH (
						TIPO_CAMPO	VARCHAR(99)			'$.TIPO_CAMPO'
						,CAMPO			VARCHAR(99)		'$.CAMPO'
						,NOMBRECAMPO	VARCHAR(99)		'$.NOMBRECAMPO'
						,DESCCAMPO		VARCHAR(99)		'$.DESCCAMPO'
						,VALOR			VARCHAR(2000)	'$.VALOR'
						,FECHA			VARCHAR(20)		'$.FECHA'
						,MEMO			VARCHAR(2000)	'$.MEMO'
				)
				ALTER TABLE #HCADCP ADD ITEM INT IDENTITY

				SELECT @I_TO = (SELECT COUNT(1) FROM #HCADCP)

				WHILE @I <= @I_TO
				BEGIN
					SELECT @CANT = COUNT(*) FROM HCADCP H INNER JOIN #HCADCP T ON H.NOMBRECAMPO = T.NOMBRECAMPO AND H.CAMPO = T.CAMPO
											WHERE T.ITEM = @I AND H.IDAFILIADO = @IDAFILIADO
					IF @CANT >0
					BEGIN
						UPDATE HCADCP
						SET ALFANUMERICO = LEFT(T.VALOR,200)
							,FECHA = IIF(ISDATE(CONCAT(SUBSTRING(T.FECHA,1,4),'-',SUBSTRING(T.FECHA,9,2),'-',SUBSTRING(T.FECHA,6,2) ))= 1,CONCAT(SUBSTRING(T.FECHA,1,4),'-',SUBSTRING(T.FECHA,9,2),'-',SUBSTRING(T.FECHA,6,2) ), NULL)
							,MEMO = T.MEMO
						FROM HCADCP
						INNER JOIN #HCADCP T ON HCADCP.NOMBRECAMPO = T.NOMBRECAMPO AND HCADCP.CAMPO = T.CAMPO
						WHERE T.ITEM = @I AND HCADCP.IDAFILIADO = @IDAFILIADO
					END
					ELSE
					BEGIN
						INSERT INTO HCADCP(IDAFILIADO, NOMBRECAMPO, CAMPO, ALFANUMERICO, FECHA, MEMO)
						SELECT @IDAFILIADO, NOMBRECAMPO,CAMPO, VALOR,
								IIF(ISDATE(CONCAT(SUBSTRING(FECHA,1,4),'-',SUBSTRING(FECHA,9,2),'-',SUBSTRING(FECHA,6,2) ))= 1,CONCAT(SUBSTRING(FECHA,1,4),'-',SUBSTRING(FECHA,9,2),'-',SUBSTRING(FECHA,6,2) ), NULL)
								,MEMO
						FROM #HCADCP WHERE ITEM = @I

					END

					SELECT @I = @I + 1
				END
			END

			--PROCESO DE MODELOS MPE PROTOCOLOS  "1 incluir|5 auditoría|3 alta del programa|2 cambiar de protocolo|4 cambio programa|0 nada
			BEGIN
                SELECT @FECHACONFIRMACION=TRY_CAST(#HCA.FECHACONFIRMACION AS DATE), @FECHASINTOMAS=TRY_CAST(#HCA.FECHASINTOMAS AS DATE) FROM #HCA
				IF @PROT_PROCESO <> 0
				BEGIN
					SELECT @IDGESTOR_NA = ID FROM GES WHERE USUARIO=DBO.FNK_VALORVARIABLE('USUGESTOR_NA')
					--BUSCAR PROT ACTUAL
					SELECT @PROT_ACTUAL = IDPROT FROM AFIPE WHERE IDAFILIADO = @IDAFILIADO AND IDPESPECIAL = @PROT_IDPESPECIAL
					IF @PROT_PROCESO = 1 
					BEGIN
                        IF EXISTS(SELECT 1 FROM AFIPE WHERE IDAFILIADO=@IDAFILIADO AND IDPESPECIAL = @PROT_IDPESPECIAL AND COALESCE(AFIPE.ESTADO,'')<>'Activo')--REINGRESO AL PROGRAMA
                        BEGIN
                            UPDATE AFIPE SET FECHA=COALESCE(@PROT_FECHA, DBO.FNK_GETDATE())----YDURANGO indica que siemrpe que se reingresa se rinicia fecha de inclusion al mpe
                                ,FECHAFINAL=NULL
                                ,IDTERCEROENTREGA=NULL
                                ,DXPE=@IDDX
                                ,FECHASINTOMAS=@FECHASINTOMAS
                                ,FECHADX=TRY_CAST(@FECHACONFIRMACION AS DATE)
                                ,IDPROT=@PROT_ID
                                ,ESTADO='Activo'
                                ,OBSERVACION=@PROT_JUSTIFICACION
                            FROM AFIPE
                            WHERE AFIPE.IDAFILIADO=@IDAFILIADO AND AFIPE.IDPESPECIAL=@PROT_IDPESPECIAL
                            
						    INSERT INTO AFIPE_LOG (IDAFILIADO ,USUARIO ,FECHA_HORA ,OBSERVACION ,ESTADO, IDPESPECIAL)   
						    SELECT @IDAFILIADO, @USUARIO, GETDATE(), LEFT(@PROT_JUSTIFICACION,500), 'Activo', @PROT_IDPESPECIAL

                            SELECT @PROT_JUSTIFICACION='Reingreso del paciente al programa el dia: '+convert(varchar,getdate(),103)
                                +' segun valoracion del profesional: '+@USUARIO+', segun Diagnostico: '+coalesce(@IDDX,'')
						    INSERT INTO AFIPE_LOG (IDAFILIADO ,USUARIO ,FECHA_HORA ,OBSERVACION ,ESTADO, IDPESPECIAL)   
						    SELECT @IDAFILIADO, @USUARIO, GETDATE(), LEFT(@PROT_JUSTIFICACION,500), 'Activo', @PROT_IDPESPECIAL
                        END
                        ELSE
                        BEGIN
						    INSERT INTO AFIPE (IDAFILIADO ,IDPESPECIAL ,NIVELRIESGO ,FECHA ,FECHAFINAL ,IDTERCEROENTREGA ,DXPE, FECHASINTOMAS,FECHADX , FECHA1TX ,ALTERNO1 ,ESTADIO ,IDPROT ,IDGESTOR ,ESTADO ,IDMEDICOTRA, OBSERVACION )
						    SELECT @IDAFILIADO, @PROT_IDPESPECIAL, NULL, COALESCE(@PROT_FECHA, DBO.FNK_GETDATE()), NULL, NULL, @IDDX, TRY_CAST(#HCA.FECHASINTOMAS AS DATE), TRY_CAST(#HCA.FECHACONFIRMACION AS DATE), NULL, NULL, NULL, @PROT_ID,
								    @IDGESTOR_NA, 'Activo', NULL, @PROT_JUSTIFICACION
						    FROM #HCA
                            WHERE NOT EXISTS(SELECT 1 FROM AFIPE WHERE AFIPE.IDAFILIADO=@IDAFILIADO AND AFIPE.IDPESPECIAL = @PROT_IDPESPECIAL )

						    INSERT INTO AFIPE_LOG (IDAFILIADO ,USUARIO ,FECHA_HORA ,OBSERVACION ,ESTADO, IDPESPECIAL)   
						    SELECT @IDAFILIADO, @USUARIO, GETDATE(), LEFT(@PROT_JUSTIFICACION,500), 'Activo', @PROT_IDPESPECIAL
						END
                        EXEC SPK_GENERA_AFIPROTOCOLO @IDAFILIADO, @PROT_IDPESPECIAL, @PROT_ID ,'01' ,@SEDE ,@USUARIO
					END
					ELSE IF @PROT_PROCESO = 3 --Alta del programa
					BEGIN
                        DECLARE @ACTIVOAFI BIT
                        SELECT @PROT_JUSTIFICACION=CONCAT(COALESCE(@PROT_JUSTIFICACION,''),'. Motivo:',CAU.DESCCAUSAL), @ACTIVOAFI=IIF(CAU.NOTIFICA=1,1,0)
                        FROM CAU WHERE IDCAUSAL=@PROT_MOTIVO

                        IF @ACTIVOAFI=1
                        BEGIN
                            UPDATE AFI SET ESTADO='Fallecido', INAC_FECHA=GETDATE(),
                                INAC_MOT='Paciente marcado como fallecido de manera automatica en la historia clinica: '+coalesce(@CONSECUTIVO,'')+
                                    ', el dia:'+CONVERT(VARCHAR,GETDATE(),103)+', por el usuario: '+COALESCE(USUSU.NOMBRE,@USUARIO,'')
                            FROM AFI 
                            LEFT JOIN USUSU ON USUSU.USUARIO=@USUARIO
                            WHERE AFI.IDAFILIADO=@IDAFILIADO
                        END
						UPDATE AFIPE SET ESTADO = 'Inactivo', FECHAFINAL = @PROT_FECHA, MOTIVO=@PROT_MOTIVO WHERE IDAFILIADO = @IDAFILIADO AND IDPESPECIAL = @PROT_IDPESPECIAL
						UPDATE AFIPROT SET ESTADO = 'Anulado' WHERE IDAFILIADO = @IDAFILIADO AND IDPESPECIAL = @PROT_IDPESPECIAL AND IDPROT = @PROT_ACTUAL AND ESTADO = 'Inicial'
					
						INSERT INTO AFIPE_LOG (IDAFILIADO ,USUARIO ,FECHA_HORA ,OBSERVACION ,ESTADO, IDPESPECIAL )   
						SELECT @IDAFILIADO, @USUARIO, GETDATE(), LEFT(@PROT_JUSTIFICACION,500), 'Inactivo', @PROT_IDPESPECIAL
					END
					ELSE IF @PROT_PROCESO = 4 --4 cambiar de PROGRAMA
					BEGIN
						SELECT @PROT_ACTUAL = IDPROT FROM AFIPE WHERE IDAFILIADO = @IDAFILIADO AND IDPESPECIAL = @IDPESPECIAL_CITA

						/*DAR DE ALTA AL PROGRAMA ANTERIOR*/
						UPDATE AFIPE SET ESTADO = 'Inactivo', FECHAFINAL = COALESCE(@PROT_FECHA, DBO.FNK_GETDATE()) WHERE IDAFILIADO = @IDAFILIADO AND IDPESPECIAL = @IDPESPECIAL_CITA
						UPDATE AFIPROT SET ESTADO = 'Anulado' WHERE IDAFILIADO = @IDAFILIADO AND IDPESPECIAL = @IDPESPECIAL_CITA AND IDPROT = @PROT_ACTUAL AND ESTADO = 'Inicial'

                        IF EXISTS(SELECT 1 FROM MPE WHERE IDPESPECIAL=@IDPESPECIAL_CITA)
                        BEGIN
						    INSERT INTO AFIPE_LOG (IDAFILIADO ,USUARIO ,FECHA_HORA ,OBSERVACION ,ESTADO, IDPESPECIAL )
						    SELECT @IDAFILIADO, @USUARIO, GETDATE(), LEFT(@PROT_JUSTIFICACION,500), 'Inactivo', @IDPESPECIAL_CITA
                        END
                        IF EXISTS(SELECT 1 FROM AFIPE WHERE IDAFILIADO=@IDAFILIADO AND IDPESPECIAL = @PROT_IDPESPECIAL AND COALESCE(AFIPE.ESTADO,'')<>'Activo')--REINGRESO AL PROGRAMA
                        BEGIN
                            UPDATE AFIPE SET FECHA=COALESCE(@PROT_FECHA, DBO.FNK_GETDATE())----YDURANGO indica que siemrpe que se reingresa se rinicia fecha de inclusion al mpe
                                ,FECHAFINAL=NULL
                                ,IDTERCEROENTREGA=NULL
                                ,DXPE=@IDDX
                                ,FECHASINTOMAS=@FECHASINTOMAS
                                ,FECHADX=TRY_CAST(@FECHACONFIRMACION AS DATE)
                                ,IDPROT=@PROT_ID
                                ,ESTADO='Activo'
                                ,OBSERVACION=@PROT_JUSTIFICACION
                            FROM AFIPE
                            WHERE AFIPE.IDAFILIADO=@IDAFILIADO AND AFIPE.IDPESPECIAL=@PROT_IDPESPECIAL
                            
						    INSERT INTO AFIPE_LOG (IDAFILIADO ,USUARIO ,FECHA_HORA ,OBSERVACION ,ESTADO, IDPESPECIAL)   
						    SELECT @IDAFILIADO, @USUARIO, GETDATE(), LEFT(@PROT_JUSTIFICACION,500), 'Activo', @PROT_IDPESPECIAL

                            SELECT @PROT_JUSTIFICACION='Reingreso del paciente al programa el dia: '+convert(varchar,getdate(),103)
                                +' segun valoracion del profesional: '+@USUARIO+', segun Diagnostico: '+coalesce(@IDDX,'')
						    INSERT INTO AFIPE_LOG (IDAFILIADO ,USUARIO ,FECHA_HORA ,OBSERVACION ,ESTADO, IDPESPECIAL)   
						    SELECT @IDAFILIADO, @USUARIO, GETDATE(), LEFT(@PROT_JUSTIFICACION,500), 'Activo', @PROT_IDPESPECIAL
                        END
                        ELSE
                        BEGIN
						    INSERT INTO AFIPE (IDAFILIADO ,IDPESPECIAL ,NIVELRIESGO ,FECHA ,FECHAFINAL ,IDTERCEROENTREGA ,DXPE, FECHASINTOMAS,FECHADX , FECHA1TX ,ALTERNO1 ,ESTADIO ,IDPROT ,IDGESTOR ,ESTADO ,IDMEDICOTRA, OBSERVACION )
						    SELECT @IDAFILIADO, @PROT_IDPESPECIAL, NULL, COALESCE(@PROT_FECHA, DBO.FNK_GETDATE()), NULL, NULL, @IDDX, TRY_CAST(#HCA.FECHASINTOMAS AS DATE), TRY_CAST(#HCA.FECHACONFIRMACION AS DATE), NULL, NULL, NULL, @PROT_ID,
								    @IDGESTOR_NA, 'Activo', NULL, @PROT_JUSTIFICACION
						    FROM #HCA
                            WHERE NOT EXISTS(SELECT 1 FROM AFIPE WHERE IDAFILIADO=@IDAFILIADO AND IDPESPECIAL = @PROT_IDPESPECIAL )

						    EXEC SPK_GENERA_AFIPROTOCOLO @IDAFILIADO, @PROT_IDPESPECIAL, @PROT_ID ,'01' ,@SEDE ,@USUARIO
						    INSERT INTO AFIPE_LOG (IDAFILIADO ,USUARIO ,FECHA_HORA ,OBSERVACION ,ESTADO, IDPESPECIAL )   
						    SELECT @IDAFILIADO, @USUARIO, GETDATE(), LEFT(@PROT_JUSTIFICACION,500), 'Activo', @PROT_IDPESPECIAL
                        END
					END
					ELSE IF @PROT_PROCESO = 2 --2 cambiar de protocolo
					BEGIN
						EXEC SPK_ACTUALIZA_AFIPROTOCOLO @IDAFILIADO, @PROT_IDPESPECIAL, @PROT_ACTUAL, @PROT_ID ,0, '01', @SEDE ,@USUARIO
					END
					ELSE IF @PROT_PROCESO = 5 -- Inclusión pendiente de auditoría (no inserta en AFIPE)
					BEGIN
						INSERT INTO AFIPE_AUD (
							IDAFILIADO, IDPESPECIAL, IDPROT, FECHA, IDMEDICO, IDTERCEROCA, IDPLAN,
							CONSECUTIVOHCA, IDDX, ESTADO, OBSERVACION
						)
						SELECT
							CIT.IDAFILIADO,
							COALESCE(NULLIF(LTRIM(RTRIM(CIT.IDPESPECIAL)), ''), @PROT_IDPESPECIAL),
							@PROT_ID,
							COALESCE(CIT.FECHAATENCION, CIT.FECHA, DBO.FNK_GETDATE()),
							CIT.IDMEDICO,
							CIT.IDTERCEROCA,
							CIT.IDPLAN,
							@CONSECUTIVO,
							COALESCE(NULLIF(LTRIM(RTRIM(CIT.IDDX)), ''), @IDDX),
							'Pendiente',
							CIT.OBSERVACIONES
						FROM CIT
						WHERE CIT.CONSECUTIVO = @CONSECUTIVOCIT
						  AND NOT EXISTS (
							SELECT 1
							FROM AFIPE_AUD A
							WHERE A.IDAFILIADO = CIT.IDAFILIADO
							  AND A.CONSECUTIVOHCA = @CONSECUTIVO
							  AND A.ESTADO = 'Pendiente'
						  )
					END
				END
				ELSE IF @CLASEORDENX='Modelo'
				BEGIN
					SELECT @DXANT=DXPE, @FECHASANT=FECHASINTOMAS, @FECHACANT=FECHADX  FROM AFIPE WHERE IDAFILIADO=@IDAFILIADO AND IDPESPECIAL=@IDPESPECIAL_CITA

					IF EXISTS(SELECT 1 FROM #HCA WHERE @IDDX<>@DXANT 
						OR @FECHASANT<>TRY_CAST(#HCA.FECHASINTOMAS AS DATETIME) OR @FECHACANT<>TRY_CAST(#HCA.FECHACONFIRMACION AS DATETIME)
						)
					BEGIN
						UPDATE AFIPE SET 
							DXPE=@IDDX
							,FECHASINTOMAS=@FECHASINTOMAS
							,FECHADX=TRY_CAST(@FECHACONFIRMACION AS DATE)
						FROM AFIPE
						WHERE AFIPE.IDAFILIADO=@IDAFILIADO AND AFIPE.IDPESPECIAL=@IDPESPECIAL_CITA
                        
						SELECT @PROT_JUSTIFICACION='Cambio de diagnostico de '+@DXANT+ ' a '+@IDDX+ ', Fecha de sintomas de '+CONVERT(VARCHAR, @FECHASANT,103)
							+' a '+CONVERT(VARCHAR,@FECHASINTOMAS, 103)+ ', Fecha de confirmacion de '+CONVERT(VARCHAR, @FECHACANT, 103)
							+' a '+CONVERT(VARCHAR,@FECHACONFIRMACION, 103)+',  por el medico: '+MED.NOMBRE+', el dia: '+CONVERT(VARCHAR,GETDATE(),103)
						FROM MED					
						WHERE IDMEDICO=(SELECT IDMEDICO FROM USUSU WHERE USUARIO=@USUARIO)

						INSERT INTO AFIPE_LOG (IDAFILIADO ,USUARIO ,FECHA_HORA ,OBSERVACION ,ESTADO, IDPESPECIAL)   
						SELECT @IDAFILIADO, @USUARIO, GETDATE(), LEFT(@PROT_JUSTIFICACION,500), 'Activo', @IDPESPECIAL_CITA
					END
				END
			END

			EXEC SPK_VALIDA_HCA_CIT @CONSECUTIVO

			UPDATE FME SET CNSHCA = @CONSECUTIVO WHERE CNSWEB = @CNSWEB

			BEGIN--AFIFAM
                SELECT @AUX = AFIFAM FROM #HCA
                SELECT * INTO #AFIFAM FROM dbo.FNQ_DATOSAFIFAM(@AUX);

			    UPDATE AFIFAM SET  AFIFAM.PNOMBRE        = X.PNOMBRE
                                  ,AFIFAM.SNOMBRE        = X.SNOMBRE
                                  ,AFIFAM.PAPELLIDO      = X.PAPELLIDO
                                  ,AFIFAM.SAPELLIDO      = X.SAPELLIDO
                                  ,AFIFAM.SEXO           = X.SEXO
                                  ,AFIFAM.FNACIMIENTO    = X.FNACIMIENTO
                                  ,AFIFAM.EDAD_ESC       = X.EDAD_ESC
                                  ,AFIFAM.PARENTESCO     = X.PARENTESCO
                                  ,AFIFAM.IDESCOLARIDAD  = X.IDESCOLARIDAD
                                  ,AFIFAM.IDOCUPACION    = X.IDOCUPACION
                                  ,AFIFAM.FECHAREG       = X.FECHAREG
                                  ,AFIFAM.USUARIOREG     = X.USUARIOREG
                                  ,AFIFAM.OBSERVACION    = X.OBSERVACION
                                  ,AFIFAM.[TOP]          = X.[TOP]
                                  ,AFIFAM.[LEFT]         = X.[LEFT]
                FROM  AFIFAM INNER JOIN #AFIFAM X ON AFIFAM.ID = X.ID
                WHERE COALESCE(X.ID,0) != 0

                INSERT INTO AFIFAM (IDAFILIADO ,PNOMBRE ,SNOMBRE ,PAPELLIDO ,SAPELLIDO ,SEXO ,FNACIMIENTO ,EDAD_ESC ,PARENTESCO ,IDESCOLARIDAD ,IDOCUPACION ,
                                    FECHAREG ,USUARIOREG ,OBSERVACION ,[TOP] ,[LEFT] ,IDUID)
                SELECT @IDAFILIADO ,PNOMBRE ,SNOMBRE ,PAPELLIDO ,SAPELLIDO ,SEXO ,FNACIMIENTO ,EDAD_ESC ,PARENTESCO ,IDESCOLARIDAD ,IDOCUPACION ,
                                    GETDATE() ,@USUARIO ,OBSERVACION, [TOP] ,[LEFT] ,IDUID
                FROM   #AFIFAM X
                WHERE  COALESCE(X.ID,0) = 0
                AND    COALESCE(X.PNOMBRE,'') != ''
                DROP TABLE #AFIFAM
            END

			SELECT @REGAFIFAM = COUNT(*) FROM AFIFAM WHERE IDAFILIADO = @IDAFILIADO

			BEGIN--AFIFAMREL
				SELECT @AUX = AFIFAMREL FROM #HCA
				SELECT * INTO #AFIFAMREL FROM dbo.FNQ_DATOSAFIFAMREL(@AUX)

				UPDATE AFIFAMREL SET  AFIFAMREL.IDAFIFAM1      = X.IDAFIFAM1
										,AFIFAMREL.IDAFIFAM2      = X.IDAFIFAM2
										,AFIFAMREL.IDAFILIADO     = X.IDAFILIADO
										,AFIFAMREL.TIPORELACION   = X.TIPORELACION
										,AFIFAMREL.X1             = X.X1
										,AFIFAMREL.Y2             = X.Y2
										,AFIFAMREL.X2             = X.X2
										,AFIFAMREL.Y1             = X.Y1
				FROM   AFIFAMREL INNER JOIN #AFIFAMREL X ON AFIFAMREL.ID = X.ID
				WHERE  COALESCE(X.ID,0) != 0

				DECLARE AFR_C CURSOR FOR
				SELECT IDAFILIADO ,IDAFIFAM1 ,IDAFIFAM2 ,TIPORELACION ,X1 ,X2 ,Y1 ,Y2  FROM   #AFIFAMREL X WHERE  X.ID IS NULL
				OPEN AFR_C
				FETCH NEXT FROM AFR_C INTO  @IDAFILIADO_AFR, @IDAFIFAM1_AFR	,@IDAFIFAM2_AFR, @TIPORELACION_AFR, @X1_AFR ,@X2_AFR ,@Y1_AFR	,@Y2_AFR
				WHILE @@fetch_status = 0
				BEGIN
					IF (TRY_CONVERT(INT, @IDAFIFAM1_AFR)) IS NULL
					BEGIN
						IF EXISTS(SELECT ID FROM AFIFAM WHERE IDUID = @IDAFIFAM1_AFR)
							SELECT @ID1_AFR = ID FROM AFIFAM WHERE IDUID = @IDAFIFAM1_AFR
					END
					ELSE
					BEGIN
						SELECT @ID1_AFR = TRY_CONVERT(INT,  @IDAFIFAM1_AFR)
					END
					IF (TRY_CONVERT(INT, @IDAFIFAM2_AFR)) IS NULL
					BEGIN
						IF EXISTS(SELECT ID FROM AFIFAM WHERE IDUID = @IDAFIFAM2_AFR)
							SELECT @ID2_AFR = ID FROM AFIFAM WHERE IDUID = @IDAFIFAM2_AFR
					END
					ELSE
					BEGIN
						SELECT @ID2_AFR =  TRY_CONVERT(INT, @IDAFIFAM2_AFR)
					END

					INSERT INTO AFIFAMREL (IDAFILIADO ,IDAFIFAM1 ,IDAFIFAM2 ,TIPORELACION ,X1 ,X2 ,Y1 ,Y2 )
					SELECT  @IDAFILIADO_AFR, @ID1_AFR	,@ID2_AFR, @TIPORELACION_AFR, @X1_AFR ,@X2_AFR ,@Y1_AFR	,@Y2_AFR

					FETCH NEXT FROM AFR_C INTO @IDAFILIADO_AFR, @IDAFIFAM1_AFR	,@IDAFIFAM2_AFR, @TIPORELACION_AFR, @X1_AFR ,@X2_AFR ,@Y1_AFR	,@Y2_AFR
				END
				CLOSE AFR_C
				DEALLOCATE AFR_C

				DROP TABLE #AFIFAMREL

			END

			BEGIN--AFIECOMAPA
				SELECT @AUX = AFIECOMAPA FROM #HCA
				SELECT * INTO #AFIECOMAPA FROM dbo.FNQ_DATOSAFIECOMAPA(@AUX)
				DELETE #AFIECOMAPA WHERE ID IS NULL AND IDAFILIADO IS NULL AND IDAFIFAM1 IS NULL AND TRABAJO IS NULL AND AMIGOS IS NULL AND EDUCACION IS NULL AND RELIGION IS NULL AND RECREACION IS NULL AND SALUD IS NULL AND TRANSPORTE IS NULL
				UPDATE AFIECOMAPA SET  AFIECOMAPA.IDAFIFAM1  = X.IDAFIFAM1
										,AFIECOMAPA.TRABAJO    = X.TRABAJO
										,AFIECOMAPA.AMIGOS     = X.AMIGOS
										,AFIECOMAPA.EDUCACION  = X.EDUCACION
										,AFIECOMAPA.RELIGION   = X.RELIGION
										,AFIECOMAPA.RECREACION = X.RECREACION
										,AFIECOMAPA.SALUD      = X.SALUD
										,AFIECOMAPA.TRANSPORTE = X.TRANSPORTE
				FROM   AFIECOMAPA INNER JOIN #AFIECOMAPA X ON AFIECOMAPA.ID = X.ID
				WHERE  COALESCE(X.ID,0) != 0

				IF @NUEVA_HCA=1 --ES INSERCION
					SELECT @FECHAINSERTAECO = CONVERT(DATE,GETDATE()), @CONSECUTIVOHCAING_ECO = @CONSECUTIVO
				ELSE
					SELECT @FECHAINSERTAECO = FECHA, @CONSECUTIVOHCAING_ECO = @CONSECUTIVOHCA FROM HCA WHERE CONSECUTIVO = @CONSECUTIVOHCA

				DECLARE ECO_C CURSOR FOR
				SELECT IDAFIFAM1 ,TRABAJO,AMIGOS,EDUCACION,RELIGION,RECREACION,SALUD,TRANSPORTE FROM   #AFIECOMAPA X WHERE  X.ID IS NULL
				OPEN ECO_C
				FETCH NEXT FROM ECO_C INTO @IDAFIFAM1_ECO,@TRABAJO ,@AMIGOS,@EDUCACION ,@RELIGION ,@RECREACION,@SALUD,@TRANSPORTE
				WHILE @@fetch_status = 0
				BEGIN
					IF (TRY_CONVERT(INT, @IDAFIFAM1_ECO)) IS NULL
					BEGIN
						IF EXISTS(SELECT ID FROM AFIFAM WHERE IDUID = @IDAFIFAM1_ECO)
							SELECT @ID1_ECO = ID FROM AFIFAM WHERE IDUID = @IDAFIFAM1_ECO
					END
					ELSE
					BEGIN
						SELECT @ID1_ECO = TRY_CONVERT(INT,  @IDAFIFAM1_ECO)
					END
					INSERT INTO AFIECOMAPA (IDAFILIADO ,FECHA ,IDAFIFAM1 ,TRABAJO ,AMIGOS ,EDUCACION ,RELIGION ,RECREACION ,SALUD ,TRANSPORTE ,CONSECUTIVOHCAING )
					SELECT @IDAFILIADO ,@FECHAINSERTAECO ,@ID1_ECO ,@TRABAJO ,@AMIGOS ,@EDUCACION ,@RELIGION ,@RECREACION ,@SALUD ,@TRANSPORTE ,@CONSECUTIVOHCAING_ECO

					FETCH NEXT FROM ECO_C INTO @IDAFIFAM1_ECO,@TRABAJO ,@AMIGOS,@EDUCACION ,@RELIGION ,@RECREACION,@SALUD,@TRANSPORTE
				END
				CLOSE ECO_C
				DEALLOCATE ECO_C

			END

			BEGIN --AFIRIAEXA=DATOS DE EXAMENES RIAS
				SELECT @AUX = EXAMENESRIAS FROM #HCA
				SELECT * INTO #EXAMENESRIAS FROM dbo.FNQ_DATOSAFIEXMANESRIAS(@AUX)
				IF @NUEVA_HCA=1 --ES INSERCION
				BEGIN
				   SELECT @CONSECUTIVOHCAING_EXARIA = @CONSECUTIVO
				   INSERT INTO AFIRIAEXA (CODIGO ,CLASERIA ,IDAFILIADO ,FECHA ,RESULTADO ,TRIMESTRE ,CONSECUTIVOHCA )
				   SELECT CODIGO, @CLASEPLANTILLA, @IDAFILIADO,	FECHA ,RESULTADO ,TRIMESTRE , @CONSECUTIVOHCAING_EXARIA
				   FROM   #EXAMENESRIAS
				END
				ELSE
				BEGIN
				   SELECT @CONSECUTIVOHCAING_EXARIA = @CONSECUTIVOHCA

				   UPDATE AFIRIAEXA
				   SET    TRIMESTRE = E.TRIMESTRE , FECHA = E.FECHA , RESULTADO = E.RESULTADO
				   FROM   #EXAMENESRIAS E
				   WHERE  AFIRIAEXA.IDAFILIADO = @IDAFILIADO
				   AND    AFIRIAEXA.CLASERIA   = @CLASEPLANTILLA
				   AND    AFIRIAEXA.CODIGO     = E.CODIGO
				   AND    AFIRIAEXA.CONSECUTIVOHCA = @CONSECUTIVOHCAING_EXARIA

				   INSERT INTO AFIRIAEXA (CODIGO ,CLASERIA ,IDAFILIADO ,FECHA ,RESULTADO ,TRIMESTRE ,CONSECUTIVOHCA )
				   SELECT CODIGO, @CLASEPLANTILLA, @IDAFILIADO,	FECHA ,RESULTADO ,TRIMESTRE , @CONSECUTIVOHCAING_EXARIA
				   FROM   #EXAMENESRIAS E
				   WHERE NOT EXISTS (SELECT 1 FROM AFIRIAEXA
									 WHERE  AFIRIAEXA.IDAFILIADO     = @IDAFILIADO
									 AND    AFIRIAEXA.CLASERIA       = @CLASEPLANTILLA
									 AND    AFIRIAEXA.CODIGO         = E.CODIGO
									 AND    AFIRIAEXA.CONSECUTIVOHCA = @CONSECUTIVOHCAING_EXARIA
									 )
				END
			END

		END TRY
		BEGIN CATCH
			-- 1. Capturar datos del error
			DECLARE @ErrorMessage NVARCHAR(MAX) = ERROR_MESSAGE();
			DECLARE @ErrorNumber INT = ERROR_NUMBER();
			DECLARE @ErrorState INT = ERROR_STATE();
			DECLARE @ErrorLine INT = ERROR_LINE();
			DECLARE @ErrorProc NVARCHAR(128) = ERROR_PROCEDURE();

			-- 2. HACER ROLLBACK INMEDIATAMENTE (evita Error 266 y permite INSERT en ERRORLOG con XACT_STATE=-1)
			IF @@TRANCOUNT > 0
				ROLLBACK TRANSACTION;

			-- 3. ESCRIBIR EN EL LOG (ya sin transacción pendiente)
			INSERT INTO dbo.ERRORLOG (
				PROCNAME, ERROR_NUMBER, ERROR_STATE, ERROR_LINE, ERROR_MESSAGE, JSON_SNIPPET, USUARIO
			)
			VALUES (
				@ErrorProc, @ErrorNumber, @ErrorState, @ErrorLine, @ErrorMessage, SUBSTRING(@JSON, 1, 4000), @USUARIO
			);

			-- 4. Retornar error al frontend
			SELECT 'KO' AS OK, '' AS CONSECUTIVO;
			SELECT @ErrorMessage AS ERROR;
			RETURN;
		END CATCH

		IF (SELECT COUNT(*) FROM @TBLERRORES) > 0
		BEGIN
			IF @@TRANCOUNT > 0
			BEGIN
				IF XACT_STATE() = -1
					ROLLBACK TRANSACTION  -- Transaccion no confirmable: rollback total obligatorio
				ELSE IF @trancount = 0
					ROLLBACK TRANSACTION
				ELSE
					ROLLBACK TRANSACTION USP_SPQ_HCA_COL_V2
			END
			SELECT 'KO' OK, '' CONSECUTIVO
			SELECT ERROR FROM @TBLERRORES
			INSERT HCAW_LOG([JSON], USUARIO, ERROR) VALUES (@JSON, @USUARIO, 1)
			RETURN
		END

		-- ===================================================================
		-- FASE-2: Operaciones post-validacion (dentro de la transaccion abierta)
		-- Envueltas en TRY/CATCH para evitar transacciones huerfanas ante fallos
		-- ===================================================================
		BEGIN TRY

		IF DBO.FNK_VALORVARIABLE('IXCOUNTRY')= 'PERU' AND @NUEVA_HCA = 1
		BEGIN
            IF EXISTS (SELECT HCATD.CODOM, CIT.ESPROGRAMAS FROM HCATD
						INNER JOIN HCA ON HCATD.CONSECUTIVO = HCA.CONSECUTIVO
						INNER JOIN CIT ON HCA.CONSECUTIVOCIT = CIT.CONSECUTIVO
						WHERE HCATD.CONSECUTIVO = @CONSECUTIVO
						GROUP BY HCATD.CODOM, CIT.ESPROGRAMAS)
			    AND EXISTS (SELECT 1 FROM TGEN WHERE TABLA = 'DISTRIBUIDORES')
            BEGIN
			    SELECT @IDPLAN  = CIT.IDPLAN, @IDTERCERO = CIT.IDTERCEROCA FROM HCA INNER JOIN CIT ON HCA.CONSECUTIVOCIT = CIT.CONSECUTIVO WHERE HCA.CONSECUTIVO = @CONSECUTIVO
			    SELECT TOP 1 @CORREGIMIENTO = AFI.CORREGIMIENTO FROM AFI WHERE IDAFILIADO = @IDAFILIADO
			    SELECT TOP 1 @IDPROVEEDOR=IDPROVEEDOR FROM EXC_SER_PLN WHERE TIPO='FARMACIA' AND IDTERCERO=@IDTERCERO AND IDPLAN=@IDPLAN AND IDPROVEEDOR IN (SELECT DATO2 FROM TGEN WHERE TABLA='DISTRIBUIDORES' AND CAMPO='FARMACIA')

			    
                IF COALESCE(@IDPROVEEDOR,'')<>''
			    BEGIN
				    SELECT TOP 1 @PROVEEDOR_FAR=EXC_SER_PLN.CODIGO FROM EXC_SER_PLN WHERE TIPO='FARMACIA' AND IDTERCERO=@IDTERCERO AND IDPLAN=@IDPLAN AND IDPROVEEDOR IN (SELECT DATO2 FROM TGEN WHERE TABLA='DISTRIBUIDORES' AND CAMPO='FARMACIA')
			    END
			    ELSE
			    BEGIN
				    SELECT TOP 1 @PROVEEDOR_FAR = EXA.CODIGO
				    FROM TGEN DIR
				    INNER JOIN TGEN EXA ON EXA.TABLA='DISTRIBUIDORES' AND EXA.CAMPO=DIR.TABLA AND EXA.CODIGO=DIR.CAMPO
				    WHERE DIR.TABLA = 'FARMACIA' AND DIR.CODIGO=@CORREGIMIENTO
			    END

			    SELECT TOP 1 @PROVEEDOR_FAR_DF = CODIGO FROM TGEN WHERE TABLA='DISTRIBUIDORES' AND CAMPO='FARMACIA' AND VALOR1=1

			    IF COALESCE(@PROVEEDOR_FAR,'')=''
			    BEGIN
				    SELECT TOP 1 @PROVEEDOR_FAR=CODIGO FROM TGEN WHERE TABLA='DISTRIBUIDORES' AND CAMPO='FARMACIA' AND VALOR1=1
			    END

			    SELECT TOP 1 @PROVEEDOR_EXA = EXA.CODIGO
			    FROM TGEN DIR
			    INNER JOIN TGEN EXA ON EXA.TABLA='DISTRIBUIDORES' AND EXA.CAMPO=DIR.TABLA AND EXA.CODIGO=DIR.CAMPO
			    WHERE DIR.TABLA = 'EXAMENES' AND DIR.CODIGO=@CORREGIMIENTO

			    IF COALESCE(@PROVEEDOR_EXA,'')=''
			    BEGIN
				    SELECT TOP 1 @PROVEEDOR_EXA=CODIGO FROM TGEN WHERE TABLA='DISTRIBUIDORES' AND CAMPO='EXAMENES' AND VALOR1=1
			    END

			    SELECT TOP 1 @PROVEEDOR_APO = EXA.CODIGO
			    FROM TGEN DIR
			    INNER JOIN TGEN EXA ON EXA.TABLA='DISTRIBUIDORES' AND EXA.CAMPO=DIR.TABLA AND EXA.CODIGO=DIR.CAMPO
			    WHERE DIR.TABLA = 'APOYO' AND DIR.CODIGO=@CORREGIMIENTO

			    IF COALESCE(@PROVEEDOR_APO,'')=''
			    BEGIN
				    SELECT TOP 1 @PROVEEDOR_APO=CODIGO FROM TGEN WHERE TABLA='DISTRIBUIDORES' AND CAMPO='APOYO' AND VALOR1=1
			    END

                IF EXISTS (SELECT 1 FROM HCATD WHERE CONSECUTIVO = @CONSECUTIVO)
                BEGIN
                    INSERT INTO QRY_ENVIOS (CONSECUTIVO, TIPOCNS, ESTADO, PROVEEDOR, FECHA_REGISTRO, CLASE, TIPO, IDAFILIADO, CANAL)
                    SELECT @CONSECUTIVO, 'HCA', 'POR ENVIAR'
                    , CASE  HCATD.CODOM
                                        WHEN DBO.FNK_VALORVARIABLE('OMCODMEDICAMENTOS')
                                            THEN COALESCE(@PROVEEDOR_FAR , @PROVEEDOR_FAR_DF)
                                        WHEN DBO.FNK_VALORVARIABLE('OMCODLABORATORIO') THEN @PROVEEDOR_EXA
                                        WHEN DBO.FNK_VALORVARIABLE('OMCODAPOYODX') THEN @PROVEEDOR_APO
                                        ELSE '' END
                    , DBO.FNK_GETDATE(), 'OM_EXTERNOS', HCATD.CODOM,@IDAFILIADO, 'MAIL'

                    FROM  HCATD
                    INNER JOIN HCA ON HCATD.CONSECUTIVO = HCA.CONSECUTIVO
                    INNER JOIN CIT ON HCA.CONSECUTIVOCIT = CIT.CONSECUTIVO
                    WHERE HCATD.CONSECUTIVO = @CONSECUTIVO
                        AND HCATD.CODOM NOT IN (DBO.FNK_VALORVARIABLE('OMCODINTERCONSULTA')) /* Las consultas no se envian a ningun proveedor */ 
                    GROUP BY HCATD.CODOM, CIT.ESPROGRAMAS

                    UPDATE QRY_ENVIOS SET QRY_ENVIOS.DESTINOS = TGEN.DATO1
                    FROM QRY_ENVIOS, TGEN
                    WHERE TGEN.TABLA = 'DISTRIBUIDORES' AND QRY_ENVIOS.PROVEEDOR = TGEN.CODIGO
                        AND TGEN.CAMPO = CASE QRY_ENVIOS.TIPO	WHEN DBO.FNK_VALORVARIABLE('OMCODMEDICAMENTOS')  THEN 'FARMACIA'
                                                            WHEN DBO.FNK_VALORVARIABLE('OMCODAPOYODX')  THEN 'APOYO'
                                                            WHEN DBO.FNK_VALORVARIABLE('OMCODLABORATORIO') THEN 'EXAMENES' END

                  IF EXISTS (SELECT  1 FROM HCATD 
                     INNER JOIN SER ON HCATD.IDSERVICIO = SER.IDSERVICIO
                     WHERE SER.PREFIJO =  DBO.FNK_VALORVARIABLE('OMCODMEDICAMENTOS') AND  HCATD.CONSECUTIVO = @CONSECUTIVO AND COALESCE(SER.ALTO_COSTO,0)=1)
                     /*AND @IDAFILIADO = '0100011327'*/ AND EXISTS (SELECT 1 FROM TGEN WHERE  TABLA = 'DISTRIBUIDORES' AND CAMPO = 'ALT_COSTO' )
                  BEGIN

                     INSERT INTO QRY_ENVIOS (CONSECUTIVO, ESTADO, DESTINOS, FECHA_REGISTRO, CLASE, TIPO, IDAFILIADO, PROVEEDOR, TIPOCNS, CANAL)
                     SELECT @CONSECUTIVO, 'POR ENVIAR', TGEN.DATO1, DBO.FNK_GETDATE(), 'OM_EXTERNOS', DBO.FNK_VALORVARIABLE('OMCODMEDICAMENTOS'), @IDAFILIADO, TGEN.CODIGO, 'HCA', 'MAIL'
                     FROM TGEN WHERE TABLA = 'DISTRIBUIDORES' AND CAMPO = 'ALT_COSTO'
                  END
                END
		   
            END
        END

		IF EXISTS (SELECT 1 FROM HCATD WHERE CONSECUTIVO = @CONSECUTIVO AND CODOM = dbo.FNK_VALORVARIABLE('OMCODHEMODIALISIS'))
			BEGIN
			DECLARE @SESIONES INT
			DECLARE @CODOM_HEM VARCHAR(10) = dbo.FNK_VALORVARIABLE('OMCODHEMODIALISIS');

			--SELECT @SESIONES = TOTALUNIDADES FROM #HCATD
			SELECT @SESIONES = SUM(
				COALESCE(
					NULLIF(TRY_CAST(TOTALUNIDADES AS INT), 0),
					TRY_CAST(CANTIDAD AS INT),
					1
				)
			)
			FROM #HCATD
			WHERE CODOM = @CODOM_HEM;
			
				DECLARE @ParamJsonHD nvarchar(max) = (
					SELECT
						CONSECUTIVOHCA      = @CONSECUTIVO, 
						IDSEDE              = @SEDE,
						SESIONES_AUTORIZADAS =  @SESIONES,
						HASTA_EGRESO         = CAST(0 AS bit),
						CONVENIO_DIRECTO   = CAST(0 AS bit) 
						
					FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
				);
				DECLARE @JsonHD nvarchar(max) = (
					SELECT
						METODO = 'CREAR_DESDE_ORDEN',
						USUARIO = @USUARIO,
						SYS_COMPUTERNAME = @SYS_COMPUTERNAME,
						PARAMETROS = JSON_QUERY(@ParamJsonHD)
					FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
				);
				EXEC dbo.SPQ_HDPI @JsonHD;
			END

		--actualizar el medico tratante si es necesario del afiliado
		SELECT @IDAFILIADOX = IDAFILIADO ,@IDMEDICOX = IDMEDICO ,@IDEMEDICAX = IDEMEDICA , @CLASEORDENX = CLASEORDEN ,@IDPESPECIALX = IDPESPECIAL
		FROM   CIT
		WHERE  CONSECUTIVO = @CONSECUTIVOCIT
        
		IF @PROCEDENCIA IN ( 'GESTIONES' ,'AUDITEXT','GESTADVA', 'URGENCIA' ,'GESTSER','IPS','GESTION')
            AND COALESCE(@CONSECUTIVOCIT,'') <> '' ---- Acabo de hacer la HCA es de procedencia cita y tengo el consecutivo d ela cita
		BEGIN
            UPDATE CITSER SET REALIZADO=A.REALIZADO
            FROM CITSER
            INNER JOIN #CITSER A ON A.IDSERVICIO=CITSER.IDSERVICIO
            WHERE CITSER.CONSECUTIVO_CIT=@CONSECUTIVOCIT

		    --AQUI SE HACE EL LLAMADO A SPK PARA QUE CREE LOS AUT Y AUTD Y AUTORIZADOR QUE SEA NECESARIO
			EXEC SPK_NHC_CONFIRMAR_OMED_CE @CONSECUTIVO ,@ITEMRED ,@CNSRPDX ,@SEDE ,@USUARIO ,@SYS_COMPUTERNAME, @IDPLAN_NEW

			IF UPPER(@CLASEORDENX) = 'MODELO' AND @NUEVA_HCA = 1 --REVISO QUE LA CITA SEA DE MODELO
			BEGIN
			    IF EXISTS(SELECT 1 FROM MPEMES WHERE IDPESPECIAL = @IDPESPECIALX AND IDEMEDICA = @IDEMEDICAX)  --VERIFICO QUE EL ESPECIALISTA QUE LO ATIENDE SEA DE LAS ESPECIALIDADES DEL MODELO
			    BEGIN
				    IF EXISTS(SELECT 1 FROM AFIPEMES WHERE IDAFILIADO = @IDAFILIADOX AND IDPESPECIAL = @IDPESPECIALX AND IDEMEDICA = @IDEMEDICAX)  --VEMOS SI YA ESTE REGISTRO EXISTE DE AFILIADO X AFIPE X MES
				    BEGIN
					    IF (SELECT COALESCE(AFIPEMES.IDMEDICO,'') FROM AFIPEMES WHERE IDAFILIADO = @IDAFILIADOX AND IDPESPECIAL = @IDPESPECIALX AND IDEMEDICA = @IDEMEDICAX) = ''
						    UPDATE AFIPEMES SET IDMEDICO = @IDMEDICOX FROM AFIPEMES WHERE IDAFILIADO = @IDAFILIADOX AND IDPESPECIAL = @IDPESPECIALX AND IDEMEDICA = @IDEMEDICAX   --ACTUALIZO EL TRATANTE
				    END
				    ELSE
				    BEGIN
					    INSERT INTO AFIPEMES (IDAFILIADO ,IDPESPECIAL ,IDEMEDICA ,IDMEDICO ,ESTADO ,USUCREA ,FECHACREA )
					    SELECT @IDAFILIADOX, @IDPESPECIALX ,@IDEMEDICAX ,@IDMEDICOX ,'' ,@USUARIO, DBO.FNK_FECHA_SIN_MLS(DBO.FNK_GETDATE())
				    END
			    END
			END
		END

        IF DBO.FNK_VALORVARIABLE('HC_TOPICO_REVISA') = 'SI' AND EXISTS (SELECT 1 FROM  PPT WHERE IDPLAN = @IDPLAN AND IDTERCERO = @IDTERCERO AND COALESCE(PPT.TOPICO,0) = 1)
        AND @NUEVA_HCA = 1
        BEGIN
            ;WITH PRESCRIPCIONES AS (
                SELECT HCATD.ID, HCATD.CONSECUTIVO, HCATD.CODOM, HCATD.IDSERVICIO, HCATD.FRECUENCIA, HCATD.CANTDIAS, HCATD.DURACION, SER.PREFIJO,
                    -- Calcular número de aplicaciones: Si CANTDIAS > 0, usarlo, sino DURACION / FRECUENCIA
                    CAST(
                        CASE 
                            WHEN COALESCE(HCATD.CANTDIAS, 0) > 0 THEN HCATD.CANTDIAS
                            ELSE CEILING(CAST(HCATD.DURACION AS FLOAT) / NULLIF(CAST(HCATD.FRECUENCIA AS FLOAT), 0))
                        END AS INT
                    ) AS NUMERO_APLICACIONES
                FROM HCATD WITH (NOLOCK)
                INNER JOIN SER ON HCATD.IDSERVICIO = SER.IDSERVICIO
                WHERE HCATD.CONSECUTIVO = @CONSECUTIVO AND COALESCE(SER.PHD, 0) = 1
                    AND (COALESCE(HCATD.CANTDIAS, 0) > 0 OR (HCATD.DURACION > 0 AND HCATD.FRECUENCIA > 0))
            ),
            -- Generador de números recursivo (hasta 10000 aplicaciones máximo)
            NUMEROS AS (
                SELECT 1 AS NUMERO
                UNION ALL
                SELECT NUMERO + 1 
                FROM NUMEROS 
                WHERE NUMERO < 10000
            )
            INSERT INTO CITACTIV (  CONSECUTIVOHCA, IDAFILIADO, PREFIJO, IDSERVICIO,  ESTADO, FECHA, HORA, FECHAGEN, USUARIO, OBSERVACION,  ID_HCATD)
            SELECT @CONSECUTIVO,@IDAFILIADO, P.PREFIJO, P.IDSERVICIO,'Por Agendar', CAST(DATEADD(HOUR, CAST(P.FRECUENCIA * (N.NUMERO - 1) AS INT), DBO.FNK_GETDATE()) AS DATE) AS FECHA_APLICACION, NULL, DBO.FNK_GETDATE(), @USUARIO, NULL, P.ID
            FROM PRESCRIPCIONES P
            CROSS JOIN NUMEROS N
            WHERE N.NUMERO <= P.NUMERO_APLICACIONES
            OPTION (MAXRECURSION 10000);
        END

        /* REGISTRA HPREP y HPREPD, CUANDO VIENE DE UNA CITA DE EVALUACION */
		IF @HUBO_CAMBIOS_OM = 1
			AND ((EXISTS (SELECT 1 FROM CIT WHERE CONSECUTIVO = @CONSECUTIVOCIT AND CIT.PROCEDENCIA IN ( 'PHDV','HADMACTIV')) AND @PROCEDENCIA = 'QX' ) OR @PROP_PROCEDENCIA = 'PHD_ADMITIDOS')
		BEGIN
			UPDATE HADM SET ESTADOV = 'CUMPLIDAVAL' WHERE HADM.NOADMISION = @NOADMISION
         UPDATE HCATD SET AVISADOENF = 0 WHERE CONSECUTIVO = @CONSECUTIVO
			EXEC SPK_NHC_CONFIRMAR_OMED_HD @CONSECUTIVO ,@ITEMRED ,@CNSRPDX ,@SEDE ,@USUARIO ,@SYS_COMPUTERNAME;
		END
     

     
        --EN ASISTENCIAL COLOCAR MEDICOING Y DXINGRESO EN LA HADM: JEDM:20250215_1239
        IF @PROCEDENCIA='QX' AND COALESCE(@NOADMISION,'') <> ''
        BEGIN
            --Llamado para gestion de orden medica hospitalaria (solo si hubo cambios en OM o es inserción)
			IF @HUBO_CAMBIOS_OM = 1
				AND (@NOCOPIAOM=0 OR @DAALTA=1) AND @CLASE= IIF(@NIT='839000794', @CLASE, 'HC') --STORRES Temporal mientras se busca le arreglo definitivo para las enfermeras en sumuywajat
			BEGIN
				EXEC SPK_NHC_INGRESAR_HCAT @CONSECUTIVO, @ITEMRED

				DECLARE CUR_HCAPM CURSOR FOR
				SELECT CODOM, IDSERVICIO, CLASE  FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVO
				OPEN CUR_HCAPM

				FETCH NEXT FROM CUR_HCAPM INTO @CODOM, @IDSERVICIO, @TIPOCAMBIO
				WHILE @@FETCH_STATUS=0
				BEGIN
					EXEC SPK_OM_AUTM_CAMBIOS @CONSECUTIVO, @CODOM, @IDSERVICIO ,@TIPOCAMBIO
					FETCH NEXT FROM CUR_HCAPM INTO @CODOM, @IDSERVICIO, @TIPOCAMBIO
				END
				CLOSE CUR_HCAPM
				DEALLOCATE CUR_HCAPM

				IF @DAALTA=1
				BEGIN
					UPDATE HCATD SET CLASE='S', FFINALDOSIS=@HORASUSPENDE WHERE CONSECUTIVO=@CONSECUTIVO
				END
			END

			IF @HUBO_CAMBIOS_OM = 1
			BEGIN
			IF (SELECT TOP 1 HTAD.CLASEPROGRAMA FROM HTAD INNER JOIN HADM ON HADM.TIPOADM=HTAD.TIPOADM WHERE NOADMISION=@NOADMISION)='HD'
				EXEC SPK_NHC_CONFIRMAR_OMED_HD @CONSECUTIVO ,@ITEMRED ,@CNSRPDX ,@SEDE ,@USUARIO ,@SYS_COMPUTERNAME
			ELSE EXEC SPK_NHC_CONFIRMAR_OMED @CONSECUTIVO ,@ITEMRED ,@CNSRPDX ,@SEDE ,@USUARIO ,@SYS_COMPUTERNAME
			END
                   
            IF @CLASE='HC' AND @AMBITO='QX'
            BEGIN
                SELECT @IDDXING = IDDX, @IDMEDICOING = IDMEDICO FROM HCA WHERE CONSECUTIVO = @CONSECUTIVO

                UPDATE HADM SET DXINGRESO   = @IDDXING     WHERE NOADMISION = @NOADMISION AND COALESCE(DXINGRESO,'') = ''
                UPDATE HADM SET IDMEDICOING = @IDMEDICOING WHERE NOADMISION = @NOADMISION AND COALESCE(IDMEDICOING,'') = ''
            END
        END

        IF COALESCE(@CONSECUTIVO,'')<>''
		BEGIN
			IF @PROCEDENCIA='QX'
			BEGIN
				-- Anexos 02/03 (ya no atiende remisión masiva)
				EXEC SPK_ANEXOS @CONSECUTIVO, 'HCA'
			END

			-- Atención + cargo OMSOLI unificados (solo CNSOMSOLI de sesión/plantilla, no masivo)
			IF @HUBO_CAMBIOS_OM = 1
				OR (
					@PROCEDENCIA = 'QX'
					AND (
						COALESCE(@CNSOMSOLI,'') <> ''
						OR EXISTS (
							SELECT 1 FROM OMSOLI WITH (NOLOCK)
							WHERE CONSECUTIVOATIENDE = @CONSECUTIVO
								AND NOADMISION = @NOADMISION
								AND COALESCE(ESTADO, 0) = 0
						)
					)
				)
			BEGIN
				EXEC SPK_OMSOLI_GENCARGO @CNSOMSOLI, @USUARIO, @SEDE, @CONSECUTIVO
			END

			/* Continuación de interconsulta: si en la HC se marcó una opción Lista/RadioButton
			   con MPLDL.CONTINUA_INTERCONSULTA=1 y se atendió un CNSOMSOLI, clonar OMSOLI
			   pendiente con SEGUIMIENTO=1, CONSECUTIVOHCA_SEG=@CONSECUTIVO y datos de
			   atención en blanco. */
			IF COALESCE(@CNSOMSOLI,'') <> ''
				AND COALESCE(@CONSECUTIVO,'') <> ''
				AND COL_LENGTH('dbo.MPLDL', 'CONTINUA_INTERCONSULTA') IS NOT NULL
				AND COL_LENGTH('dbo.OMSOLI', 'SEGUIMIENTO') IS NOT NULL
				AND COL_LENGTH('dbo.OMSOLI', 'CONSECUTIVOHCA_SEG') IS NOT NULL
				AND EXISTS (
					SELECT 1
					FROM HCAD H WITH (NOLOCK)
					INNER JOIN MPLDL L WITH (NOLOCK)
						ON L.CLASEPLANTILLA = H.CLASEPLANTILLA
						AND L.CAMPO = H.CAMPO
						AND L.VALORLISTA = H.ALFANUMERICO
					WHERE H.CONSECUTIVO = @CONSECUTIVO
						AND H.TIPOCAMPO IN ('Lista', 'RadioButton')
						AND COALESCE(L.CONTINUA_INTERCONSULTA, 0) = 1
						AND COALESCE(H.ALFANUMERICO, '') <> ''
				)
				AND EXISTS (
					SELECT 1 FROM OMSOLI O WITH (NOLOCK)
					WHERE O.CNSOMSOLI = @CNSOMSOLI
						AND O.NOADMISION = @NOADMISION
				)
				AND NOT EXISTS (
					SELECT 1
					FROM OMSOLI S WITH (NOLOCK)
					INNER JOIN OMSOLI O WITH (NOLOCK) ON O.CNSOMSOLI = @CNSOMSOLI
					WHERE S.NOADMISION = O.NOADMISION
						AND S.IDSERVICIO = O.IDSERVICIO
						AND COALESCE(S.IDEMEDICA, '') = COALESCE(O.IDEMEDICA, '')
						AND COALESCE(S.SEGUIMIENTO, 0) = 1
						AND COALESCE(S.ESTADO, 0) = 0
						AND S.CNSOMSOLI <> O.CNSOMSOLI
				)
			BEGIN
				DECLARE @CNSOMSOLI_SEG VARCHAR(20)

				EXEC SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@OMSOLI', @CNSOMSOLI_SEG OUTPUT
				SELECT @CNSOMSOLI_SEG = @SEDE + REPLACE(SPACE(8 - LEN(@CNSOMSOLI_SEG)) + LTRIM(RTRIM(@CNSOMSOLI_SEG)), SPACE(1), 0)

				IF COALESCE(@CNSOMSOLI_SEG, '') <> ''
					AND NOT EXISTS (SELECT 1 FROM OMSOLI WITH (NOLOCK) WHERE CNSOMSOLI = @CNSOMSOLI_SEG)
				BEGIN
					INSERT INTO OMSOLI (
						CNSOMSOLI, CONSECUTIVO, ITEMRED, CODOM, IDSERVICIO, IDEMEDICA,
						IDAFILIADO, PROCEDENCIA, NOADMISION, ESTADO, OBSERVACION, FECHA,
						CANTIDAD, CCOSTO, IDBODEGA, CNSIZSOLD, SEGUIMIENTO, CONSECUTIVOHCA_SEG,
						IDMEDICOATIENDE, CONSECUTIVOATIENDE, OBSATIENDE, FECATIENDE,
						NOPRESTACIONATIENDE, NOITEMATIENDE
					)
					SELECT
						@CNSOMSOLI_SEG, CONSECUTIVO, ITEMRED, CODOM, IDSERVICIO, IDEMEDICA,
						IDAFILIADO, PROCEDENCIA, NOADMISION, 0, OBSERVACION, GETDATE(),
						CANTIDAD, CCOSTO, IDBODEGA, NULL, 1, @CONSECUTIVO,
						NULL, NULL, NULL, NULL,
						NULL, NULL
					FROM OMSOLI WITH (NOLOCK)
					WHERE CNSOMSOLI = @CNSOMSOLI
				END
			END
		END

        --INSERTA LOS PROTOCOLOS PENDIENTES DEL PTE
		IF UPPER(@CLASEORDENX) = 'MODELO' AND @PROCEDENCIA <> 'IPS'
		BEGIN
      		SELECT @IDMEDICO = IDMEDICO FROM USUSU WHERE USUARIO = @USUARIO
			SELECT @IDGESTOR_NA=ID FROM GES WHERE USUARIO=DBO.FNK_VALORVARIABLE('USUGESTOR_NA')
			SELECT @CODOM_GESTION=DBO.FNK_VALORVARIABLE('OMCODGESTION')

			IF COALESCE(@IDGESTOR_NA,0)=0
				SET @IDGESTOR_NA=1
			IF EXISTS (SELECT 1 FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVO AND CODOM=@CODOM_GESTION) AND EXISTS(SELECT 1 FROM AFIPE WHERE IDAFILIADO=@IDAFILIADO AND AFIPE.IDPESPECIAL = @IDPESPECIALX  ) AND @PROCEDENCIA <> 'GESTSER'
			BEGIN
				INSERT INTO AFIPROT (IDAFILIADO, IDPESPECIAL, IDPROTD, IDGESTOR, ESTADO, PROCEDENCIA, CONSECUTIVOCIT, OBSERVACION, IDSERVICIO, F_DEFAULT, IDPROT, FACTURABLE, PRIORIDAD, CNSHCAORIG)
				SELECT HCA.IDAFILIADO, AFIPE.IDPESPECIAL, PROTD.ID, COALESCE(HCATD.IDCAUSAL,@IDGESTOR_NA), 'Inicial', 'HCA', HCA.NOADMISION, HCATD.OBSERVACION, HCATD.IDSERVICIO, HCATD.FECHAINI,
					PROTD.IDPROT, PROTD.FACTURABLE, PROT.PRIORIDAD, HCA.CONSECUTIVO
				FROM HCA
				    INNER JOIN CIT   ON HCA.CONSECUTIVOCIT = CIT.CONSECUTIVO
					INNER JOIN HCATD ON HCATD.CONSECUTIVO=@CONSECUTIVO AND HCATD.CODOM=@CODOM_GESTION
					LEFT JOIN AFIPE ON AFIPE.IDAFILIADO=HCA.IDAFILIADO AND CIT.IDPESPECIAL = AFIPE.IDPESPECIAL
					LEFT JOIN PROTD ON AFIPE.IDPROT=PROTD.IDPROT AND PROTD.IDSERVICIO=HCATD.IDSERVICIO
				    LEFT JOIN PROT  ON AFIPE.IDPROT = PROT.ID
				WHERE HCA.CONSECUTIVO=@CONSECUTIVO

			END
			IF EXISTS (SELECT 1 FROM HCATD WHERE CONSECUTIVO=@CONSECUTIVO AND CODOM=@CODOM_GESTION) AND EXISTS(SELECT 1 FROM AFIPE WHERE IDAFILIADO=@IDAFILIADO AND AFIPE.IDPESPECIAL = @IDPESPECIALX AND @PROCEDENCIA = 'GESTSER' )
			BEGIN
				INSERT INTO AFIPROT (IDAFILIADO, IDPESPECIAL, IDPROTD, IDGESTOR, ESTADO, PROCEDENCIA, CONSECUTIVOCIT, OBSERVACION, IDSERVICIO, F_DEFAULT, IDPROT, FACTURABLE, PRIORIDAD, CNSHCAORIG)
				SELECT HCA.IDAFILIADO, AFIPE.IDPESPECIAL, PROTD.ID, COALESCE(HCATD.IDCAUSAL,@IDGESTOR_NA), 'Inicial', 'HCA', HCA.NOADMISION, HCATD.OBSERVACION, HCATD.IDSERVICIO, HCATD.FECHAINI,
					PROTD.IDPROT, PROTD.FACTURABLE, PROT.PRIORIDAD, HCA.CONSECUTIVO
				FROM HCA
                    INNER JOIN HCATD ON HCATD.CONSECUTIVO=@CONSECUTIVO AND HCATD.CODOM=@CODOM_GESTION
				    LEFT JOIN AFIPE ON AFIPE.IDAFILIADO=HCA.IDAFILIADO
				    LEFT JOIN PROTD ON AFIPE.IDPROT=PROTD.IDPROT AND PROTD.IDSERVICIO=HCATD.IDSERVICIO
				    LEFT JOIN PROT  ON AFIPE.IDPROT = PROT.ID
				WHERE HCA.CONSECUTIVO=@CONSECUTIVO

			END
		END

        IF @PROCEDENCIA = 'GESTION'
			UPDATE AFIPROT SET ESTADO = 'Procesado' WHERE ID = @IDGESTION -- Entramos a dar cumplida a las atenciondes de GESTION PROGRAMDA

		IF @trancount = 0 COMMIT

		END TRY -- [FASE-2]
		BEGIN CATCH -- [FASE-2: error en operaciones pre-commit o en el COMMIT]
			DECLARE @ErrorMessageF2 NVARCHAR(MAX) = ERROR_MESSAGE();
			DECLARE @ErrorNumberF2 INT = ERROR_NUMBER();
			DECLARE @ErrorStateF2 INT = ERROR_STATE();
			DECLARE @ErrorLineF2 INT = ERROR_LINE();
			DECLARE @ErrorProcF2 NVARCHAR(128) = ERROR_PROCEDURE();

			IF CURSOR_STATUS('local', 'CUR_HCAPM') >= 0
			BEGIN
				CLOSE CUR_HCAPM
				DEALLOCATE CUR_HCAPM
			END
			IF @@TRANCOUNT > 0
				ROLLBACK TRANSACTION;

			INSERT INTO dbo.ERRORLOG (PROCNAME, ERROR_NUMBER, ERROR_STATE, ERROR_LINE, ERROR_MESSAGE, JSON_SNIPPET, USUARIO)
			VALUES (@ErrorProcF2, @ErrorNumberF2, @ErrorStateF2, @ErrorLineF2, @ErrorMessageF2, SUBSTRING(@JSON, 1, 4000), @USUARIO);

			SELECT 'KO' AS OK, '' AS CONSECUTIVO;
			SELECT @ErrorMessageF2 AS ERROR;
			INSERT HCAW_LOG([JSON], USUARIO, ERROR) VALUES (@JSON, @USUARIO, 1);
			RETURN;
		END CATCH -- [FASE-2]

		IF @CONSECUTIVO_HCA_ORIGEN IS NULL
		BEGIN
			IF UPPER(JSON_VALUE(@PARAMETROS, '$.GRUPAL')) IN ('1','TRUE')
			BEGIN
				SELECT @AUX = GRUPO
				FROM   #HCA

				SELECT *
				INTO #HCAGRUPO
				FROM OPENJSON(@AUX) WITH (
					CONSECUTIVOCIT  VARCHAR(20)    '$.CONSECUTIVO'
					,NOMBREAFI  VARCHAR(512)    '$.NOMBREAFI'
				)

				DECLARE GRUPO_CURSOR CURSOR FOR
					SELECT CONSECUTIVOCIT,NOMBREAFI
					FROM  #HCAGRUPO h
				OPEN GRUPO_CURSOR
				FETCH NEXT FROM GRUPO_CURSOR
				INTO @CONSECUTIVOCIT,@AUX
				WHILE @@FETCH_STATUS = 0
				BEGIN
					IF @PROCEDENCIA = 'QX'
					BEGIN
						EXEC SPK_HCGRUPAL_ATIENDE @CNSHCA = @CONSECUTIVO, @CNSCIT = @CONSECUTIVOCIT, @PROCEDENCIA = 'QX'
					END
					ELSE
					BEGIN
						EXEC DBO.SPQ_HCA_COL @JSON=@JSON,@CONSECUTIVO_HCA_ORIGEN = @CONSECUTIVO, @CONSECUTIVOCIT_ORIGEN = @CONSECUTIVOCIT
					END
					FETCH NEXT FROM GRUPO_CURSOR
					INTO @CONSECUTIVOCIT,@AUX
				END
				CLOSE GRUPO_CURSOR
				DEALLOCATE GRUPO_CURSOR
			END
			SELECT 'OK' OK, @CONSECUTIVO AS CONSECUTIVO
			SELECT @CONSECUTIVO AS CONSECUTIVO
		END

		IF @PROCEDENCIA = 'SEGUI'
		BEGIN
            SELECT @IDMADSEGUI = JSON_VALUE(@JSON,'$.PARAMETROS.CONSECUTIVOCIT')
		    SELECT @VALUE = VALOR, @LABEL = VALORLISTA FROM #MPLD WHERE SECUENCIA = 5000
		    IF COALESCE(@IDMADSEGUI, '')<> '' AND COALESCE(@VALUE, 0)>0
			    EXEC DBO.SPK_GESTIONA_MADSEGUI @IDMADSEGUI, @VALUE, @USUARIO, @CONSECUTIVO, @LABEL
		END

      /* INSERT EN  HCATD_MEZCLA - DILUYENTES*/
      IF EXISTS (SELECT 1 FROM HCATD, SER WHERE HCATD.IDSERVICIOMEZCLA = SER.IDSERVICIO AND HCATD.CONSECUTIVO = @CONSECUTIVO )
         AND DBO.FNK_VALORVARIABLE('USA_HCATD_MEZCLA') = 'SI'
      BEGIN
         IF OBJECT_ID('tempdb..#LIQUIDOS') IS NOT NULL
         DROP TABLE #LIQUIDOS;

         ;WITH BASE AS (
            SELECT 
               HCATD.ID,
               HCATD.IDSERVICIOMEZCLA,
               CAST(HCATD.QMEZCLA AS DECIMAL(18,4)) AS QMEZCLA,
               SER_LIQ.IDJERARQUIA,
               HCATD.PRESCRIPCION,
               HCATD.TOTALUNIDADES
            FROM HCA A 
            INNER JOIN HADM ON HADM.NOADMISION = A.NOADMISION
            INNER JOIN HCATD ON HCATD.CONSECUTIVO = A.CONSECUTIVO
            INNER JOIN SER D ON HCATD.IDSERVICIO = D.IDSERVICIO
            INNER JOIN SER SER_LIQ ON HCATD.IDSERVICIOMEZCLA = SER_LIQ.IDSERVICIO
            WHERE A.CONSECUTIVO = @CONSECUTIVO
            AND COALESCE(D.MEZCLA,0) <> 0 
            AND COALESCE(HCATD.IDSERVICIOMEZCLA,'') <> ''
         ),
         EQ_ORDER AS (
            SELECT 
               IDJERARQUIA,
               IDSERVICIO AS IDSERVICIO_EQUI,
               CAST(EQUICC AS DECIMAL(18,4)) AS EQUICC,
               ROW_NUMBER() OVER (PARTITION BY IDJERARQUIA ORDER BY CAST(EQUICC AS DECIMAL(18,4)) DESC) AS RN,
               COUNT(*) OVER (PARTITION BY IDJERARQUIA) AS MAX_RN,
               ROW_NUMBER() OVER (PARTITION BY IDJERARQUIA ORDER BY CAST(EQUICC AS DECIMAL(18,4)) ASC) AS RN_MIN
            FROM SER
            WHERE COALESCE(EQUICC,0) > 0
         ),
         REC AS (
            SELECT
               B.ID,
               B.IDSERVICIOMEZCLA,
               B.QMEZCLA,
               E.IDJERARQUIA,
               E.IDSERVICIO_EQUI,
               E.EQUICC,
               E.RN AS RN_CURRENT,
               E.MAX_RN,
               CAST(FLOOR(B.QMEZCLA / E.EQUICC) AS INT) AS CANTIDAD_EQUI,
               CAST(B.QMEZCLA - FLOOR(B.QMEZCLA / E.EQUICC) * E.EQUICC AS DECIMAL(18,4)) AS RESTO
            FROM BASE B
            INNER JOIN EQ_ORDER E 
               ON B.IDJERARQUIA = E.IDJERARQUIA
            WHERE E.RN = 1

            UNION ALL

            SELECT
               R.ID,
               R.IDSERVICIOMEZCLA,
               R.QMEZCLA,
               E.IDJERARQUIA,
               E.IDSERVICIO_EQUI,
               E.EQUICC,
               E.RN AS RN_CURRENT,
               E.MAX_RN,
               CAST(FLOOR(R.RESTO / E.EQUICC) AS INT) AS CANTIDAD_EQUI,
               CAST(R.RESTO - FLOOR(R.RESTO / E.EQUICC) * E.EQUICC AS DECIMAL(18,4)) AS RESTO
            FROM REC R
            INNER JOIN EQ_ORDER E
               ON R.IDJERARQUIA = E.IDJERARQUIA
               AND E.RN = R.RN_CURRENT + 1
            WHERE R.RESTO > 0 AND R.RN_CURRENT < E.MAX_RN
         ),
         MIN_EQ AS (
            SELECT
               IDJERARQUIA,
               IDSERVICIO_EQUI AS IDSERVICIO_EQUI_MIN,
               EQUICC AS EQUICC_MIN
            FROM EQ_ORDER
            WHERE RN_MIN = 1
         ),
         RESTO_EXTRA AS (
            SELECT
               R.ID,
               R.IDSERVICIOMEZCLA,
               M.IDSERVICIO_EQUI_MIN AS IDSERVICIO_EQUI,
               1 AS CANTIDAD_EQUI,
               M.EQUICC_MIN AS EQUICC,
               R.RESTO
            FROM REC R
            INNER JOIN MIN_EQ M ON R.IDJERARQUIA = M.IDJERARQUIA
            WHERE R.RESTO > 0
            AND R.RN_CURRENT = R.MAX_RN
         )

         SELECT
            *
         INTO #LIQUIDOS
         FROM (
            SELECT
               R.ID,
               R.IDSERVICIOMEZCLA,
               R.IDSERVICIO_EQUI,
               R.CANTIDAD_EQUI,
               R.EQUICC,
               R.RESTO
            FROM REC R
            WHERE R.CANTIDAD_EQUI > 0

            UNION ALL

            SELECT
               RE.ID,
               RE.IDSERVICIOMEZCLA,
               RE.IDSERVICIO_EQUI,
               RE.CANTIDAD_EQUI,
               RE.EQUICC,
               RE.RESTO
            FROM RESTO_EXTRA RE
         ) X
         ORDER BY X.ID, X.EQUICC DESC;

         INSERT INTO HCATD_MEZCLA (IDSERVICIO_MEZCLA,CANTIDAD_MEZCLA, IDSERVICIO_CALC,CANTIDAD_CALC, ID_HCATD, CONSECUTIVOHCA  )
         SELECT #LIQUIDOS.IDSERVICIOMEZCLA,HCATD.QMEZCLA , #LIQUIDOS.IDSERVICIO_EQUI, CANTIDAD_EQUI*TOTALUNIDADES, #LIQUIDOS.ID, @CONSECUTIVO
         FROM #LIQUIDOS, HCATD WHERE HCATD.ID = #LIQUIDOS.ID
      END

        IF DBO.FNK_VALORVARIABLE('HADM_USA_ACTIVIDADES') = 'SI' 
            AND EXISTS (SELECT 1 FROM HADM WHERE NOADMISION = @NOADMISION AND COALESCE(USACTC,0) = 2)
            AND EXISTS (SELECT 1 FROM HCATD WHERE CONSECUTIVO = @CONSECUTIVO)
        BEGIN
            SELECT @ID_CITSITEDS = ID_CITSITEDS FROM HADM WHERE NOADMISION = @NOADMISION
            SELECT  @NOPRESUPUESTO = NOPRESUPUESTO FROM HPREP WHERE NOADMISION = @NOADMISION AND CONSECUTIVOHCA = @CONSECUTIVO

            IF EXISTS (SELECT 1 FROM HPREP WHERE NOPRESUPUESTO = @NOPRESUPUESTO)
                AND EXISTS (SELECT  1 FROM HCATD INNER JOIN SER ON HCATD.IDSERVICIO = SER.IDSERVICIO
                            WHERE SER.PREFIJO = DBO.FNK_VALORVARIABLE('PREFIJOMEDICAMENTOS') AND COALESCE(SER.PHD,0) = 1 
                                AND NOT EXISTS (SELECT 1 FROM JRQ WHERE SER.IDJERARQUIA = JRQ.IDJERARQUIA AND COALESCE(JRQ.IDJERARQUIA,'') <> 'NA' ))
            BEGIN

                SELECT @MAX_NO_ITEM = ISNULL(MAX(NO_ITEM), 0) FROM HPREPD WHERE  NOPRESUPUESTO = @NOPRESUPUESTO

                SELECT
                    D.DIA,
                    SUM(
                        CASE WHEN D.DIA <= H.CANTDIAS
                            THEN CAST(H.DURACION / H.FRECUENCIA AS INT)
                            ELSE 0 END
                    ) AS TOTAL_APLICACIONES
                INTO #TEMP_DOSIS
                FROM (
                    SELECT TOP (
                        SELECT MAX(CANTDIAS) FROM HCATD WHERE CONSECUTIVO = @CONSECUTIVO
                    )
                        ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS DIA
                    FROM sys.objects
                ) D
                CROSS JOIN (
                    SELECT HCATD.FRECUENCIA, HCATD.DURACION, HCATD.CANTDIAS
                    FROM HCATD
                    INNER JOIN SER ON HCATD.IDSERVICIO = SER.IDSERVICIO
                    WHERE CONSECUTIVO = @CONSECUTIVO AND SER.PREFIJO = DBO.FNK_VALORVARIABLE('PREFIJOMEDICAMENTOS') AND COALESCE(SER.PHD,0) = 1
                    AND NOT EXISTS (SELECT 1 FROM JRQ WHERE SER.IDJERARQUIA = JRQ.IDJERARQUIA AND COALESCE(JRQ.IDJERARQUIA,'') <> 'NA' )
                ) H
                GROUP BY D.DIA
                ORDER BY D.DIA;
                  

                INSERT INTO HPREPD (NOPRESUPUESTO,NO_ITEM,IDSERVICIO,CANTIDAD, USUARIO, ESPAQUETE, TIPO_GEN, ID_CITSITEDS)
                SELECT @NOPRESUPUESTO, @MAX_NO_ITEM + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS NO_ITEM,
                    S.IDSERVICIO,
                    COUNT(*) AS VECES, @USUARIO, 1, 'Generado', @ID_CITSITEDS
                FROM #TEMP_DOSIS T
                JOIN SER S
                    ON T.TOTAL_APLICACIONES BETWEEN S.MINDOSIS AND S.MAXDOSIS
                WHERE COALESCE(S.MINDOSIS,0)<>0 AND COALESCE(S.MAXDOSIS,0)<>0
                GROUP BY S.IDSERVICIO
                ORDER BY S.IDSERVICIO;

                DROP TABLE #TEMP_DOSIS;
             
                EXEC SPK_RELIQUIDA_PRESUPUESTO_PERU @NOPRESUPUESTO, 'NUEVO'
                IF NOT EXISTS (SELECT 1 FROM HPREPD WHERE NOPRESUPUESTO = @NOPRESUPUESTO )
                BEGIN
                    DELETE FROM HPREP WHERE NOPRESUPUESTO = @NOPRESUPUESTO
                END
            END

            INSERT INTO HADMACTIV ( NOADMISION, CONSECUTIVOHCA, IDAFILIADO, IDSERVICIO, TIPO_USUARIO, IDROL, ESTADO, FECHA, HORA, FECHAGEN, USUARIO, OBSERVACION, TIPO, ID_HCATD, DURACION_APLICACION)
            SELECT @NOADMISION, @CONSECUTIVO, @IDAFILIADO,HCATD.IDSERVICIO,COALESCE(SERUSUSU.TIPO_USUARIO,PRE.PHD_TIPO_USUARIO) ,COALESCE( SERUSUSU.IDROL,PRE.PHD_IDROL)
            , CASE COALESCE(SERUSUSU.TIPO,PRE.PHD_TIPO) WHEN 'Aplicacion' THEN 'Por Iniciar' WHEN 'Consulta' THEN 'Por Agendar' END
            , NULL, NULL, DBO.FNK_GETDATE(), @USUARIO, HCATD.OBSERVACION , COALESCE(SERUSUSU.TIPO,PRE.PHD_TIPO), HCATD.ID, COALESCE(SER.DURACIONCITA,0)
            FROM HCATD
            INNER JOIN SER ON SER.IDSERVICIO = HCATD.IDSERVICIO AND COALESCE(SER.PHD,0) = 1
            INNER JOIN PRE ON SER.PREFIJO = PRE.PREFIJO AND COALESCE(PRE.PHD_TIPO_USUARIO,'')<>'' AND COALESCE(PRE.PHD_TIPO,'')<>''
            LEFT JOIN SERUSUSU ON HCATD.IDSERVICIO = SERUSUSU.IDSERVICIO
            WHERE HCATD.CONSECUTIVO = @CONSECUTIVO AND PRE.PREFIJO NOT IN ( SELECT value
                                                                                FROM STRING_SPLIT(DBO.FNK_VALORVARIABLE('PREFIJO_SER_VAR'), ',') 
                                                                            )

             IF EXISTS (SELECT 1 FROM HCATD, SER WHERE HCATD.IDSERVICIO = SER.IDSERVICIO AND HCATD.CONSECUTIVO = @CONSECUTIVO AND SER.PREFIJO IN ( SELECT value
                                                                                FROM STRING_SPLIT(DBO.FNK_VALORVARIABLE('PREFIJO_SER_VAR'), ',') 
                                                                            )  )   
            BEGIN
               INSERT INTO HADMACTIV ( NOADMISION, CONSECUTIVOHCA, IDAFILIADO, IDSERVICIO, TIPO_USUARIO, IDROL, ESTADO, FECHA, HORA, FECHAGEN, USUARIO, OBSERVACION, TIPO, ID_HCATD, DURACION_APLICACION)
               SELECT @NOADMISION, @CONSECUTIVO, @IDAFILIADO,HCATD.IDSERVICIO,COALESCE(SERUSUSU.TIPO_USUARIO,PRE.PHD_TIPO_USUARIO) ,COALESCE( SERUSUSU.IDROL,PRE.PHD_IDROL)
               , CASE COALESCE(SERUSUSU.TIPO,PRE.PHD_TIPO) WHEN 'Aplicacion' THEN 'Por Iniciar' WHEN 'Consulta' THEN 'Por Agendar'   END
               , NULL, NULL, DBO.FNK_GETDATE(), @USUARIO, HCATD.OBSERVACION , COALESCE(SERUSUSU.TIPO,PRE.PHD_TIPO), HCATD.ID, COALESCE(SER.DURACIONCITA,0)
               FROM HCATD
               INNER JOIN SER ON SER.IDSERVICIO = HCATD.IDSERVICIO AND COALESCE(SER.PHD,0) = 1
               INNER JOIN PRE ON SER.PREFIJO = PRE.PREFIJO AND COALESCE(PRE.PHD_TIPO_USUARIO,'')<>'' AND COALESCE(PRE.PHD_TIPO,'')<>''
               LEFT JOIN SERUSUSU ON HCATD.IDSERVICIO = SERUSUSU.IDSERVICIO
               CROSS APPLY (
                                  SELECT TOP (CAST(HCATD.CANTIDAD AS INT)) number
                                  FROM master..spt_values
                                  WHERE type = 'P'
                              ) N
               WHERE HCATD.CONSECUTIVO = @CONSECUTIVO AND PRE.PREFIJO IN ( SELECT value
                                                                                FROM STRING_SPLIT(DBO.FNK_VALORVARIABLE('PREFIJO_SER_VAR'), ',') 
                                                                            )
 
            END

          /*  SELECT   IDSERVICIOMEZCLA, QMEZCLA,* FROM HCATD WHERE CONSECUTIVO = @CONSECUTIVO
            SELECT  SER.DESCSERVICIO,ID_HCATD,TIPO_GEN, * FROM HPREPD 
            INNER JOIN SER ON HPREPD.IDSERVICIO = SER.IDSERVICIO
            WHERE NOPRESUPUESTO = @NOPRESUPUESTO
            */

            IF EXISTS (SELECT 1 FROM HPREPD WHERE NOPRESUPUESTO = @NOPRESUPUESTO AND TIPO_GEN = 'Diluyente')
            BEGIN
                INSERT INTO HADMACTIV ( NOADMISION, CONSECUTIVOHCA, IDAFILIADO, IDSERVICIO, TIPO_USUARIO, IDROL, ESTADO, FECHA, HORA, FECHAGEN, USUARIO, OBSERVACION
                , TIPO, ID_HCATD, PROCEDENCIA, DURACION_APLICACION, CANTIDAD_DILUYENTE)
                SELECT @NOADMISION, @CONSECUTIVO, @IDAFILIADO, IART.IDSERVICIO,'Enfermera', NULL,'Por Iniciar', NULL, NULL, DBO.FNK_GETDATE(), @USUARIO, NULL
                ,'Aplicacion', ID_HCATD, 'Diluyente', COALESCE(SER.DURACIONCITA,0) , HPREPD.CANTIDAD / (SELECT  CANTIDAD FROM HPREPD H WHERE H.NOPRESUPUESTO = @NOPRESUPUESTO AND COALESCE(H.TIPO_GEN,'')='' AND H.ID_HCATD = HPREPD.ID_HCATD )
                FROM HPREPD
                INNER JOIN IART ON HPREPD.IDSERVICIO = COALESCE(IART.IDARTICULO, IART.IDSERVICIO)
                INNER JOIN HCATD ON HPREPD.ID_HCATD = HCATD.ID 
                INNER JOIN SER HCATD_SER ON HCATD.IDSERVICIO = HCATD_SER.IDSERVICIO
                INNER JOIN SER ON IART.IDARTICULO = SER.IDSERVICIO
                WHERE HPREPD.NOPRESUPUESTO = @NOPRESUPUESTO AND HPREPD.TIPO_GEN = 'Diluyente' AND COALESCE(HCATD_SER.PHD,0)=1
            END
        END

        IF EXISTS (SELECT 1 FROM HCA WHERE CONSECUTIVO = @CONSECUTIVO AND CLASEPLANTILLA = DBO.FNK_VALORVARIABLE('HADM_ENF_MPL_VALORA'))
        BEGIN
            IF (SELECT CASE WHEN ALFANUMERICO IS NULL OR LTRIM(RTRIM(ALFANUMERICO)) = '' THEN 0 ELSE TRY_CAST(ALFANUMERICO AS INT) END 
                    FROM HCAD WHERE CONSECUTIVO = @CONSECUTIVO AND CAMPO = '12_TOT_HER') >=0
                AND EXISTS (SELECT 1 FROM PLN INNER JOIN SER ON PLN.IDSERVICIO = SER.IDSERVICIO WHERE IDPLAN IN (SELECT TRIM(value) FROM STRING_SPLIT( DBO.FNK_VALORVARIABLE('HADM_ENF_PLN_VALORA') , ',')))
            BEGIN
                SELECT @CANTIDAD = CASE WHEN ALFANUMERICO IS NULL OR LTRIM(RTRIM(ALFANUMERICO)) = '' THEN 0 ELSE TRY_CAST(ALFANUMERICO AS INT) END 
                FROM HCAD WHERE CONSECUTIVO = @CONSECUTIVO AND CAMPO = '12_TOT_HER'
            
                IF EXISTS (SELECT IDSERVICIO, MINDOSIS, MAXDOSIS FROM SER WHERE @CANTIDAD BETWEEN MINDOSIS AND MAXDOSIS)
                BEGIN
                    EXEC SPK_GENCONSECUTIVO '01',@SEDE,'@HPREP',@NOPRESUPUESTO_NUEVO OUTPUT
                    SELECT @NOPRESUPUESTO_NUEVO = @SEDE + RIGHT('00000000'+CONVERT(VARCHAR(8),@NOPRESUPUESTO_NUEVO),8)
                    SELECT @MAX_NO_ITEM = 0

                    INSERT INTO HPREP (NOPRESUPUESTO, NOADMISION, FECHA, IDTERCEROCA, IDPLAN, IDSEDE, ESTADO, VALORTOTAL, VALORCOPAGO, VALOREXCEDENTE, CONSECUTIVOHCA, USUARIO, FACTURABLE, FACTURADA)
                    SELECT @NOPRESUPUESTO_NUEVO, @NOADMISION, DBO.FNK_GETDATE(), @IDTERCERO, @IDPLAN, @SEDE, 0, NULL, NULL, NULL, @CONSECUTIVO, @USUARIO, 1,0

                    INSERT INTO HPREPD (NOPRESUPUESTO,NO_ITEM,IDSERVICIO,CANTIDAD, USUARIO, ESPAQUETE, TIPO_GEN, ID_CITSITEDS)
                    SELECT @NOPRESUPUESTO_NUEVO,  @MAX_NO_ITEM + ROW_NUMBER() OVER (ORDER BY (SELECT NULL)), SER.IDSERVICIO, 1, @USUARIO, 1, 'Generado', @ID_CITSITEDS
                    FROM SER WHERE @CANTIDAD BETWEEN MINDOSIS AND MAXDOSIS

                    EXEC SPK_RELIQUIDA_PRESUPUESTO_PERU @NOPRESUPUESTO_NUEVO, 'NUEVO'
                END
            END
        END

		-- Generar incapacidad intramural cuando es alta médica (solo en creación, no en edición)
		IF @NUEVA_HCA = 1 AND @DAALTA = 1
		BEGIN
			DECLARE @DAALTA_MPL INT = 0
			
			SELECT @DAALTA_MPL = MPL.DAALTA
			FROM MPL INNER JOIN HCA ON HCA.CLASEPLANTILLA = MPL.CLASEPLANTILLA
			WHERE HCA.CONSECUTIVO = @CONSECUTIVO
			
			IF @DAALTA_MPL = 1 AND DBO.FNK_VALORVARIABLE('HCALTA_GENERAIME_INT') = 'SI'
			BEGIN
				DECLARE @VIAINGRESO_DESC VARCHAR(50)
				DECLARE @VIAINGRESO VARCHAR(2)
				DECLARE @ORIGEN_INC VARCHAR(7)

				SELECT @VIAINGRESO = COALESCE(VIAINGRESO, ''), @CAUSAEXTERNA = COALESCE(HTRIAGE.CAUSAEXT, HADM.CAUSAEXTERNA)
					,@FDESDE = HADM.FECHA
				FROM HADM LEFT JOIN HTRIAGE ON HTRIAGE.CNSTRIAGE = HADM.CNSTRIAGE
				WHERE HADM.NOADMISION = @NOADMISION

				IF COALESCE(@VIAINGRESO, '')='' AND @NIT = '830507718' -- SOLO MEDICAL
				BEGIN
					SELECT @VIAINGRESO = '03'
				END

				SELECT TOP 1 @VIAINGRESO_DESC = DESCRIPCION
				FROM	TGEN 
				WHERE	TABLA   = 'General' 
				AND		CAMPO	= 'VIADEINGRESO' 
				AND		CODIGO  = @VIAINGRESO

				IF @VIAINGRESO_DESC LIKE '%TRABAJO%' OR @VIAINGRESO_DESC LIKE '%LABORAL%'
				BEGIN
					SELECT @ORIGEN_INC = 'Laboral'
				END
				ELSE
				BEGIN
					SELECT @ORIGEN_INC = 'Comun'
				END

				PRINT @ORIGEN_INC
				
				SELECT TOP 1 @GSERVICIOS = CODIGO 
				FROM	TGEN 
				WHERE	TABLA = 'IME' 
				AND		CAMPO	= 'GSERVICIOS' 
				AND		COALESCE(CHECK1, 0) = 1
				
				SELECT TOP 1 @MODALIDAD = CODIGO 
				FROM	TGEN 
				WHERE	TABLA = 'IME' 
				AND		CAMPO	= 'MODALIDAD' 
				AND		COALESCE(CHECK1, 0) = 1
				
				SELECT TOP 1 @RETROACTIVA = CODIGO 
				FROM	TGEN 
				WHERE	TABLA = 'IME' 
				AND		CAMPO	= 'RETROACTIVA' 
				AND		COALESCE(CHECK1, 0) = 1
				
				SELECT TOP 1 @TIPOINCAPACIDAD = CODIGO 
				FROM	TGEN 
				WHERE	TABLA = 'IME' 
				AND		CAMPO	= 'TIPOINCAPACIDAD' 
				AND		COALESCE(CHECK1, 0) = 1
				
				SELECT @FHASTA = COALESCE(FECHAALTAMED, DBO.FNK_GETDATE())
				FROM HADM
				WHERE NOADMISION = @NOADMISION

				SELECT @DIASINCAPACIDAD = DATEDIFF(DAY, CAST(@FDESDE AS DATE), CAST(@FHASTA AS DATE))

				-- Mismo día ingreso/alta: mínimo 1 día completo de incapacidad
                SET @DIASINCAPACIDAD=ISNULL(@DIASINCAPACIDAD,0)+1
				
				-- Obtener los diagnósticos de la historia clínica
				DECLARE @MDX_JSON NVARCHAR(MAX) = '[]'
				
				SELECT @MDX_JSON = (
					SELECT HCADX.IDDX, MDX.DESCRIPCION
					FROM HCADX
					INNER JOIN MDX ON MDX.IDDX = HCADX.IDDX
					WHERE HCADX.CONSECUTIVO = @CONSECUTIVO
					FOR JSON PATH
				)
	
				-- Si no hay diagnósticos, usar array vacío
				IF @MDX_JSON IS NULL OR LEN(LTRIM(RTRIM(@MDX_JSON))) = 0
					SET @MDX_JSON = '[]'
				
				SELECT @JSON_IME = CONCAT('{"MODELO":"IME_COL","METODO":"REGISTRAR","PARAMETROS":{"SILENCIOSO":1,"IDAFILIADO":"', @IDAFILIADO, '","FECHA":"', CONVERT(VARCHAR(10), @FDESDE, 23), '","DIASINCAPACIDAD":', COALESCE(@DIASINCAPACIDAD, 0),',"CONTINGENCIA":"', @TIPOINCAPACIDAD,'","CAUSAEXTERNA":"', @CAUSAEXTERNA,'","DESCRIPCION":"","MDX":', @MDX_JSON, ',"NOADMISION":"', @NOADMISION, '","ESPRORROGA":0,"CNSWEB":"',@CNSWEB, '","GSERVICIOS":"', @GSERVICIOS, '","MODALIDAD":"', @MODALIDAD, '","RETROACTIVA":"',@RETROACTIVA, '","ORIGEN":"', @ORIGEN_INC, '", "IDDX": "', @DXINGRESO, '", "DX1": "', @DXEGRESO, '","DX2":"', @DXSALIDA1, '","CONSECUTIVOHCA":"', @CONSECUTIVO, '"},"USUARIO":"',@USUARIO,'"}')
				
				BEGIN TRY
					EXEC SPQ_JSON @JSON_IME
				END TRY
				BEGIN CATCH
					-- Fallo en generacion automatica de incapacidad (no critico, HCA ya confirmada)
					-- Limpiar transaccion huerfana que SPQ_JSON haya podido dejar abierta (error 266)
					IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION
					INSERT HCAW_LOG([JSON], USUARIO, ERROR) VALUES (@JSON_IME, @USUARIO, 1)
				END CATCH
			END
		END
		INSERT HCAW_LOG([JSON], USUARIO, ERROR) VALUES (@JSON, @USUARIO, 0)
	END
	ELSE
		EXEC SPQ_HCA_COL_V2 @JSON
END

